// Define a structure to represent a record
typedef struct {
    int key;
    long *offset;
} Record;

// Function to dynamically allocate memory for arrays and initialize them
void init_arrays(int num_records, int range_min, int range_max, long max_mem_usage) {
    // Validate input parameters
    if (num_records <= 0 || range_min < 0 || range_max < 0 || max_mem_usage <= 0) {
        printf("Invalid input parameters\n");
        return;
    }

    // Allocate memory for the offset and key arrays
    long *offsets = (long *)malloc(num_records * sizeof(long));
    int *keys = (int *)malloc(num_records * sizeof(int));
    Record *records = (Record *)malloc(num_records * sizeof(Record));

    // Initialize the offset and key arrays with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand() % (range_max - range_min + 1) + range_min;
        keys[i] = rand() % (range_max - range_min + 1) + range_min;
    }

    // Initialize the record structures with pointers to their corresponding offset and key values
    for (int i = 0; i < num_records; i++) {
        records[i].key = keys[i];
        records[i].offset = &offsets[i];
    }

    // Log memory usage and errors to a file
    FILE *log_file = fopen("memory_usage.log", "a");
    if (log_file == NULL) {
        printf("Error opening log file\n");
        return;
    }
    fprintf(log_file, "Memory usage: %ld bytes\n", num_records * sizeof(Record));
    fclose(log_file);

    // Handle potential edge cases such as invalid input parameters
    if (offsets == NULL || keys == NULL || records == NULL) {
        printf("Error allocating memory for arrays\n");
        return;
    }
}

// Function to deallocate memory for the arrays and record structures
void free_arrays(Record *records, int num_records) {
    // Validate input parameters
    if (records == NULL || num_records <= 0) {
        printf("Invalid input parameters\n");
        return;
    }

    // Deallocate memory for the offset and key arrays
    free(records[num_records - 1].offset);
    free(records[num_records - 1].key);
    free(records);
}
