#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <curl/curl.h>
#include <pthread.h>
#include <semaphore.h>

// Define the maximum number of concurrent DNS requests
#define MAX_CONCURRENT_REQUESTS 10

// Define the timeout for API request failures
#define TIMEOUT 5

// Define the cache size
#define CACHE_SIZE 1024

// Define the data structure to manage the cache
typedef struct {
    char *hostname;
    char *ip_address;
} CacheEntry;

// Define the thread-safe data structure for managing the cache
typedef struct {
    pthread_mutex_t mutex;
    CacheEntry *entries[CACHE_SIZE];
} Cache;

// Function to initialize the cache
void initCache(Cache *cache) {
    // Initialize the mutex for the cache
    pthread_mutex_init(&cache->mutex, NULL);

    // Initialize the entries in the cache
    for (int i = 0; i < CACHE_SIZE; i++) {
        cache->entries[i] = NULL;
    }
}

// Function to add an entry to the cache
void addCacheEntry(Cache *cache, char *hostname, char *ip_address) {
    // Acquire the mutex for the cache
    pthread_mutex_lock(&cache->mutex);

    // Check if there is space in the cache for a new entry
    int i;
    for (i = 0; i < CACHE_SIZE && cache->entries[i] != NULL; i++) {}

    // If there is no space, remove the oldest entry from the cache
    if (i == CACHE_SIZE) {
        CacheEntry *oldest_entry = NULL;
        for (int j = 0; j < CACHE_SIZE && oldest_entry == NULL; j++) {
            if (cache->entries[j] != NULL) {
                oldest_entry = cache->entries[j];
            }
        }
        free(oldest_entry);
    }

    // Add the new entry to the cache
    CacheEntry *new_entry = malloc(sizeof(CacheEntry));
    new_entry->hostname = hostname;
    new_entry->ip_address = ip_address;
    cache->entries[i] = new_entry;

    // Release the mutex for the cache
    pthread_mutex_unlock(&cache->mutex);
}

// Function to retrieve an entry from the cache
CacheEntry *getCacheEntry(Cache *cache, char *hostname) {
    // Acquire the mutex for the cache
    pthread_mutex_lock(&cache->mutex);

    // Check if the hostname is in the cache
    int i;
    for (i = 0; i < CACHE_SIZE && strcmp(cache->entries[i]->hostname, hostname) != 0; i++) {}

    // If the hostname is not in the cache, return NULL
    if (i == CACHE_SIZE) {
        CacheEntry *entry = NULL;
        pthread_mutex_unlock(&cache->mutex);
        return entry;
    }

    // Return the cached IP address
    CacheEntry *entry = cache->entries[i];
    pthread_mutex_unlock(&cache->mutex);
    return entry;
}

// Function to resolve a hostname using DNS resolution
char *resolveHostname(char *hostname) {
    // Initialize the curl handle
    CURL *curl = curl_easy_init();

    // Set the URL for the API request
    char url[1024];
    sprintf(url, "https://api.example.com/dns?hostname=%s", hostname);

    // Perform the API request and get the response
    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "API request failed: %s\n", curl_easy_strerror(res));
        return NULL;
    }

    // Get the response data
    char *data = malloc(1024);
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &res);
    if (res != 200) {
        fprintf(stderr, "API request failed with response code %d\n", res);
        return NULL;
    }
    curl_easy_getinfo(curl, CURLINFO_CONTENT_TYPE, &data);

    // Close the curl handle
    curl_easy_cleanup(curl);

    // Return the IP address from the response data
    char *ip_address = strtok(data, "\n");
    return ip_address;
}

// Function to process a line in the CSV file
void processLine(char *line) {
    // Split the line into fields using "," as the delimiter
    char **fields = malloc(1024);
    int num_fields = 0;
    for (int i = 0; i < strlen(line); i++) {
        if (line[i] == ',') {
            fields[num_fields++] = line + i + 1;
        }
    }

    // Get the hostname and IP address from the fields
    char *hostname = fields[0];
    char *ip_address = NULL;

    // Check if the hostname is in the cache
    CacheEntry *cache_entry = getCacheEntry(cache, hostname);
    if (cache_entry != NULL) {
        ip_address = cache_entry->ip_address;
    } else {
        // Resolve the hostname using DNS resolution
        ip_address = resolveHostname(hostname);

        // Add the hostname and IP address to the cache
        addCacheEntry(cache, hostname, ip_address);
    }

    // Calculate the average of the last two numeric fields
    int num1 = atoi(fields[num_fields - 2]);
    int num2 = atoi(fields[num_fields - 1]);
    int average = (num1 + num2) / 2;

    // Append the average to the output
    char *output = malloc(1024);
    sprintf(output, "%s,%d\n", hostname, average);
    printf("%s", output);
}

// Function to process a file of lines in parallel using threads
void processFileParallel(char *filename) {
    // Open the file for reading
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        perror("fopen");
        return;
    }

    // Initialize the cache
    Cache cache;
    initCache(&cache);

    // Create a semaphore to control access to the cache
    sem_t *sem = malloc(sizeof(sem_t));
    sem_init(sem, 0, MAX_CONCURRENT_REQUESTS);

    // Create a thread pool for processing lines in parallel
    pthread_t threads[MAX_CONCURRENT_REQUESTS];
    for (int i = 0; i < MAX_CONCURRENT_REQUESTS; i++) {
        pthread_create(&threads[i], NULL, processLine, file);
    }

    // Wait for all threads to finish
    for (int i = 0; i < MAX_CONCURRENT_REQUESTS; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up the cache and semaphore
    freeCache(&cache);
    sem_destroy(sem);
}

// Function to process a file of lines sequentially
void processFileSequential(char *filename) {
    // Open the file for reading
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        perror("fopen");
        return;
    }

    // Initialize the cache
    Cache cache;
    initCache(&cache);

    // Process each line in the file sequentially
    char *line = malloc(1024);
    while (fgets(line, 1024, file) != NULL) {
        processLine(line);
    }

    // Clean up the cache
    freeCache(&cache);
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return 1;
    }

    // Process the file in parallel or sequentially based on user input
    char *filename = argv[1];
    if (strcmp(argv[2], "-p") == 0) {
        processFileParallel(filename);
    } else {
        processFileSequential(filename);
    }

    return 0;
}
