async function readFiles(directory, fileExtension) {
  const files = await fs.promises.readdir(directory);
  const filteredFiles = files.filter((file) => file.endsWith(fileExtension));
  let contents = '';
  for (const file of filteredFiles) {
    try {
      const fileContents = await fs.promises.readFile(path.join(directory, file), 'utf8');
      contents += fileContents;
    } catch (error) {
      // Handle error gracefully by logging and continuing with the next file
      console.log(`Error reading file ${file}: ${error}`);
    }
  }
  return contents;
}
