import java.io.File;
import java.nio.file.Paths;
import java.time.Instant;
import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.TimeUnit;

public class DisjointPairs {
    public static int countDisjointPairs(int[] arr) {
        if (arr == null || arr.length < 2) return 0;

        // Initialize Union-Find data structure
        Map<Integer, Integer> parent = new HashMap<>();
        for (int i = 0; i < arr.length; i++) {
            parent.put(i, i);
        }

        int count = 0;
        for (int i = 0; i < arr.length - 1; i++) {
            // Find the root of the current element's tree
            int root1 = findRoot(parent, i);

            // Find the root of the next element's tree
            int root2 = findRoot(parent, i + 1);

            // If the roots are different, it means the elements are disjoint
            if (root1 != root2) {
                count++;

                // Union the two trees by setting the root of one tree to be the root of the other tree
                parent.put(root1, root2);
            }
        }

        return count;
    }

    private static int findRoot(Map<Integer, Integer> parent, int i) {
        // Find the root of the current element's tree by following the chain of parents until we reach the root
        int root = i;
        while (parent.get(root) != root) {
            root = parent.get(root);
        }

        return root;
    }

    public static String generateNewFilename(String filename, Instant timestamp) {
        // Extract the file extension from the original filename
        int index = filename.lastIndexOf('.');
        String extension = (index == -1) ? "" : filename.substring(index);

        // Generate a new filename by modifying the original filename's extension to include a timestamp-based identifier and a file type derived from character analysis of the original filename
        return Paths.get(filename).getFileName().toString() + "_" + timestamp.toEpochMilli() + "." + extension;
    }

    public static void logProcessingTime(long processingTime) {
        // Log the processing time in milliseconds for each element, ensuring that the log is formatted consistently across different platforms and file systems
        System.out.println("Processing time: " + TimeUnit.MILLISECONDS.toSeconds(processingTime) + " seconds");
    }
}
