<?php
function updateClinicStatus($clinicId, $status) {
    // Validate input parameters
    if (!is_numeric($clinicId) || !is_string($status)) {
        throw new InvalidArgumentException("Invalid arguments passed to updateClinicStatus");
    }

    // Connect to the health data API and retrieve the current status of the clinic
    $apiResponse = fetchHealthDataApi($clinicId);
    if ($apiResponse === false) {
        throw new RuntimeException("Failed to connect to health data API");
    }

    // Extract the current status from the API response
    $currentStatus = $apiResponse["status"];

    // Check if the current status is different from the requested status
    if ($currentStatus !== $status) {
        // Update the clinic's status in the database
        $updateQuery = "UPDATE clinics SET status = ?, last_modified_ip = ?, last_modified_date = NOW() WHERE id = ?";
        $stmt = $this->db->prepare($updateQuery);
        $stmt->bindValue(1, $status);
        $stmt->bindValue(2, $_SERVER["REMOTE_ADDR"]);
        $stmt->bindValue(3, $clinicId);
        if ($stmt->execute() === false) {
            throw new RuntimeException("Failed to update clinic status in database");
        }

        // Log the update event
        $logMessage = "Updated clinic status for clinic ID %d from '%s' to '%s'";
        $logArgs = array($clinicId, $currentStatus, $status);
        va_start(va_end, $logMessage, $logArgs);
    } else {
        // Log the no-op event
        $logMessage = "No update necessary for clinic ID %d (status '%s' is already '%s')";
        $logArgs = array($clinicId, $currentStatus, $status);
        va_start(va_end, $logMessage, $logArgs);
    }
}

function fetchHealthDataApi($clinicId) {
    // Connect to the health data API and retrieve the current status of the clinic
    $apiUrl = "https://example.com/health-data-api/clinics/$clinicId";
    $apiResponse = file_get_contents($apiUrl);
    if ($apiResponse === false) {
        return false;
    }

    // Decode the API response and extract the status
    $apiData = json_decode($apiResponse, true);
    if (!isset($apiData["status"])) {
        return false;
    }

    return $apiData["status"];
}
