<?php

// Define the session ID generation function
function generateSessionId() {
  // Generate a random string of characters using the base64_encode function
  $sessionId = base64_encode(random_bytes(32));

  // Return the generated session ID
  return $sessionId;
}

// Define the session invalidation function
function invalidateSession($sessionId) {
  // Check if the session ID is valid
  if (!isValidSessionId($sessionId)) {
    // If the session ID is not valid, return an error message
    return "Invalid session ID";
  }

  // Invalidate the session ID by setting it to null
  $sessionId = null;

  // Return a success message
  return "Session invalidated successfully";
}

// Define the session validation function
function isValidSessionId($sessionId) {
  // Check if the session ID is not null or empty
  if (empty($sessionId)) {
    // If the session ID is null or empty, return false
    return false;
  }

  // Check if the session ID is a valid UUID
  if (!preg_match('/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/', $sessionId)) {
    // If the session ID is not a valid UUID, return false
    return false;
  }

  // Check if the session ID is in the database
  $query = "SELECT COUNT(*) FROM sessions WHERE id = :id";
  $stmt = $pdo->prepare($query);
  $stmt->bindValue(':id', $sessionId, PDO::PARAM_STR);
  $stmt->execute();

  // Return true if the session ID is in the database, false otherwise
  return ($stmt->fetchColumn() > 0) ? true : false;
}

// Define the session creation function
function createSession($userId) {
  // Generate a unique session ID using the generateSessionId function
  $sessionId = generateSessionId();

  // Insert the new session into the database
  $query = "INSERT INTO sessions (id, user_id) VALUES (:id, :user_id)";
  $stmt = $pdo->prepare($query);
  $stmt->bindValue(':id', $sessionId, PDO::PARAM_STR);
  $stmt->bindValue(':user_id', $userId, PDO::PARAM_INT);
  $stmt->execute();

  // Return the generated session ID
  return $sessionId;
}

// Define the session retrieval function
function getSession($sessionId) {
  // Check if the session ID is valid
  if (!isValidSessionId($sessionId)) {
    // If the session ID is not valid, return an error message
    return "Invalid session ID";
  }

  // Retrieve the user ID associated with the session ID from the database
  $query = "SELECT user_id FROM sessions WHERE id = :id";
  $stmt = $pdo->prepare($query);
  $stmt->bindValue(':id', $sessionId, PDO::PARAM_STR);
  $stmt->execute();

  // Return the retrieved user ID
  return $stmt->fetchColumn();
}

// Define the session invalidation after inactivity period function
function invalidateSessionAfterInactivity($sessionId) {
  // Check if the session ID is valid
  if (!isValidSessionId($sessionId)) {
    // If the session ID is not valid, return an error message
    return "Invalid session ID";
  }

  // Retrieve the last activity time associated with the session ID from the database
  $query = "SELECT last_activity FROM sessions WHERE id = :id";
  $stmt = $pdo->prepare($query);
  $stmt->bindValue(':id', $sessionId, PDO::PARAM_STR);
  $stmt->execute();

  // Calculate the time remaining until invalidation based on the last activity time and the inactivity period
  $lastActivity = $stmt->fetchColumn();
  $timeRemaining = (strtotime($lastActivity) + 30*24*60*60) - time();

  // Return the calculated time remaining
  return $timeRemaining;
}

// Define the session invalidation after inactivity period function
function updateSessionLastActivity($sessionId) {
  // Check if the session ID is valid
  if (!isValidSessionId($sessionId)) {
    // If the session ID is not valid, return an error message
    return "Invalid session ID";
  }

  // Update the last activity time associated with the session ID in the database
  $query = "UPDATE sessions SET last_activity = :last_activity WHERE id = :id";
  $stmt = $pdo->prepare($query);
  $stmt->bindValue(':last_activity', date("Y-m-d H:i:s"), PDO::PARAM_STR);
  $stmt->bindValue(':id', $sessionId, PDO::PARAM_STR);
  $stmt->execute();

  // Return a success message
  return "Session last activity updated successfully";
}
