void updateUserProfile(char *username, char *password) {
    // Connect to the database
    MYSQL *conn = mysql_init(NULL);
    if (conn == NULL) {
        printf("Failed to initialize MySQL connection\n");
        return;
    }

    if (mysql_real_connect(conn, "localhost", "root", "", "mydatabase", 0, NULL, 0) == NULL) {
        printf("Failed to connect to database: %s\n", mysql_error(conn));
        mysql_close(conn);
        return;
    }

    // Prepare the query
    MYSQL_STMT *stmt = mysql_stmt_init(conn);
    if (stmt == NULL) {
        printf("Failed to initialize statement\n");
        mysql_close(conn);
        return;
    }

    const char *query = "UPDATE users SET password=? WHERE username=?";
    if (mysql_stmt_prepare(stmt, query, strlen(query)) != 0) {
        printf("Failed to prepare statement: %s\n", mysql_error(conn));
        mysql_close(conn);
        return;
    }

    // Bind the parameters
    MYSQL_BIND params[2];
    memset(params, 0, sizeof(params));

    params[0].buffer_type = MYSQL_TYPE_STRING;
    params[0].buffer = password;
    params[0].buffer_length = strlen(password);
    params[0].is_null = 0;

    params[1].buffer_type = MYSQL_TYPE_STRING;
    params[1].buffer = username;
    params[1].buffer_length = strlen(username);
    params[1].is_null = 0;

    if (mysql_stmt_bind_param(stmt, params) != 0) {
        printf("Failed to bind parameters: %s\n", mysql_error(conn));
        mysql_close(conn);
        return;
    }

    // Execute the query
    if (mysql_stmt_execute(stmt) != 0) {
        printf("Failed to execute statement: %s\n", mysql_error(conn));
        mysql_close(conn);
        return;
    }

    // Get the result
    MYSQL_RES *result = mysql_stmt_use_result(stmt);
    if (result == NULL) {
        printf("Failed to get result: %s\n", mysql_error(conn));
        mysql_close(conn);
        return;
    }

    // Check the number of rows affected
    unsigned long long affected_rows = mysql_stmt_affected_rows(stmt);
    if (affected_rows == 0) {
        printf("No rows were updated\n");
    } else {
        printf("%llu rows were updated\n", affected_rows);
    }

    // Close the statement and connection
    mysql_stmt_close(stmt);
    mysql_close(conn);
}
