using System;
using System.Numerics;
using System.Threading;

namespace DynamicValueGenerator
{
    public class RandomValueGenerator
    {
        private readonly int _minValue;
        private readonly int _maxValue;
        private readonly Random _random = new Random();

        public RandomValueGenerator(int minValue, int maxValue)
        {
            _minValue = minValue;
            _maxValue = maxValue;
        }

        public float GetRandomFloat()
        {
            return (float)(_random.NextDouble() * (_maxValue - _minValue)) + _minValue;
        }

        public int GetRandomInteger()
        {
            return _random.Next(_minValue, _maxValue);
        }

        public Vector3 GetRandomVector3(Vector3 minPoint, Vector3 maxPoint)
        {
            var x = (float)(_random.NextDouble() * (maxPoint.X - minPoint.X)) + minPoint.X;
            var y = (float)(_random.NextDouble() * (maxPoint.Y - minPoint.Y)) + minPoint.Y;
            var z = (float)(_random.NextDouble() * (maxPoint.Z - minPoint.Z)) + minPoint.Z;
            return new Vector3(x, y, z);
        }

        public Matrix4x4 GetRandomMatrix(int rows, int cols)
        {
            var matrix = new Matrix4x4();
            for (var i = 0; i < rows; i++)
            {
                for (var j = 0; j < cols; j++)
                {
                    var value = GetRandomFloat();
                    if (value >= _minValue && value <= _maxValue)
                    {
                        matrix[i, j] = value;
                    }
                }
            }
            return matrix;
        }

        public void Seed(int seed)
        {
            _random.Seed(seed);
        }

        public bool IsWithinBounds(float value)
        {
            return value >= _minValue && value <= _maxValue;
        }

        public override string ToString()
        {
            return $"{_minValue} - {_maxValue}";
        }
    }
}
