// Custom asyncReduce function for an array of numbers
async function asyncReduce(arr, initialValue, callback, config) {
  // Initialize variables
  let accumulator = initialValue;
  let currentIndex = 0;
  let isCancelled = false;

  // Create a promise chain to handle asynchronous operations
  const promiseChain = new Promise((resolve, reject) => {
    // Recursively call the callback function for each element in the array
    const next = (accumulator, currentValue) => {
      return new Promise((resolve, reject) => {
        try {
          // Perform asynchronous operations to determine the next state of the reduction
          callback(accumulator, currentValue).then(result => {
            // Update the accumulator and move on to the next element in the array
            accumulator = result;
            currentIndex++;
            if (currentIndex < arr.length) {
              resolve(next(accumulator, arr[currentIndex]));
            } else {
              resolve(accumulator);
            }
          }).catch(error => {
            // Handle errors within the asynchronous callback
            reject(error);
          });
        } catch (error) {
          // Handle errors outside of the asynchronous callback
          reject(error);
        }
      });
    };

    // Start the promise chain with the initial value and the first element in the array
    resolve(next(accumulator, arr[currentIndex]));
  });

  // Implement a mechanism to signal cancellation to all active asynchronous tasks within the reduction process
  const cancel = () => {
    isCancelled = true;
    promiseChain.cancel();
  };

  // Return the promise chain and the cancel function
  return {
    promise: promiseChain,
    cancel: cancel
  };
}

// Test cases for asyncReduce function
describe('asyncReduce', () => {
  it('should reduce an empty array to the initial value', () => {
    const arr = [];
    const initialValue = 0;
    const callback = (accumulator, currentValue) => accumulator + currentValue;
    const config = { timeout: 1000, retryAttempts: 3 };
    return asyncReduce(arr, initialValue, callback, config).promise.then(result => {
      expect(result).toBe(initialValue);
    });
  });

  it('should reduce a small array to the correct value', () => {
    const arr = [1, 2, 3];
    const initialValue = 0;
    const callback = (accumulator, currentValue) => accumulator + currentValue;
    const config = { timeout: 1000, retryAttempts: 3 };
    return asyncReduce(arr, initialValue, callback, config).promise.then(result => {
      expect(result).toBe(6);
    });
  });

  it('should reduce a large array to the correct value', () => {
    const arr = Array(10000).fill().map((_, i) => i + 1);
    const initialValue = 0;
    const callback = (accumulator, currentValue) => accumulator + currentValue;
    const config = { timeout: 1000, retryAttempts: 3 };
    return asyncReduce(arr, initialValue, callback, config).promise.then(result => {
      expect(result).toBe(50005000);
    });
  });

  it('should handle service disruptions', () => {
    const arr = [1, 2, 3];
    const initialValue = 0;
    const callback = (accumulator, currentValue) => {
      // Simulate a service disruption by throwing an error after the first element
      if (currentIndex === 0) {
        throw new Error('Service disrupted');
      } else {
        return accumulator + currentValue;
      }
    };
    const config = { timeout: 1000, retryAttempts: 3 };
    return asyncReduce(arr, initialValue, callback, config).promise.then(result => {
      expect(result).toBe(6);
    });
  });

  it('should handle timeouts', () => {
    const arr = [1, 2, 3];
    const initialValue = 0;
    const callback = (accumulator, currentValue) => {
      // Simulate a timeout by taking longer than the specified timeout
      return new Promise((resolve, reject) => {
        setTimeout(() => {
          resolve(accumulator + currentValue);
        }, 2000);
      });
    };
    const config = { timeout: 1000, retryAttempts: 3 };
    return asyncReduce(arr, initialValue, callback, config).promise.then(result => {
      expect(result).toBe(6);
    });
  });
});
