char* append_dir_separator(const char* path, size_t bufsize) {
    // Check if the buffer is large enough to hold a directory separator
    if (bufsize <= 1) {
        return NULL;
    }

    // Get the length of the input path
    size_t len = strlen(path);

    // Allocate memory for the output path
    char* out = malloc(len + 2);
    if (!out) {
        return NULL;
    }

    // Copy the input path to the output path
    memcpy(out, path, len);

    // Append a directory separator to the output path
    out[len] = '/';
    out[len + 1] = '\0';

    return out;
}
