// Define the CSS selector to match elements in the DOM tree
const char *selector = "div.my-class";

// Define the function to extract numerical values from a string
int extract_number(char *str) {
  int num;
  sscanf(str, "%d", &num);
  return num;
}

// Define the function to compute the average of two numbers
double average(int x, int y) {
  return (x + y) / 2.0;
}

// Define the function to recursively traverse the DOM tree and extract elements matching the CSS selector
void traverse_dom(struct dom_node *node) {
  // Check if the current node matches the specified CSS selector
  if (strcmp(node->name, selector) == 0) {
    // Extract the numerical values from the last two child elements
    int x = extract_number(node->children[node->child_count - 2]->content);
    int y = extract_number(node->children[node->child_count - 1]->content);

    // Compute the average of the extracted values
    double avg = average(x, y);

    // Print the average value to the console
    printf("Average: %f\n", avg);
  }

  // Recursively traverse the child nodes
  for (int i = 0; i < node->child_count; i++) {
    traverse_dom(node->children[i]);
  }
}

