#include <limits.h>
#include <math.h>
#include <assert.h>

// Define the maximum number of bits per sample supported by the function
#define MAX_BITS_PER_SAMPLE 16

// Define the default values for the image information
#define DEFAULT_BITS_PER_SAMPLE 8
#define DEFAULT_SAMPLES_PER_PIXEL 3
#define DEFAULT_EXTRA_SAMPLES 0

// Define the cache size for the theme bitmaps
#define THEME_CACHE_SIZE 1024

// Define the directory for the default theme
#define DEFAULT_THEME_DIRECTORY "/path/to/default/theme"

// Define the structure to hold the image information
typedef struct {
    int bitsPerSample;
    int samplesPerPixel;
    int extraSamples;
} ImageInfo;

// Define the function to handle TIFF and PNG images
void handleImage(const char* filePath) {
    // Check if the file is a TIFF or PNG image
    if (strcmp(filePath, ".tif") == 0 || strcmp(filePath, ".png") == 0) {
        // Open the file and read its header
        FILE* file = fopen(filePath, "rb");
        if (!file) {
            printf("Error: unable to open file %s\n", filePath);
            return;
        }

        // Read the image information from the header
        ImageInfo info;
        info.bitsPerSample = DEFAULT_BITS_PER_SAMPLE;
        info.samplesPerPixel = DEFAULT_SAMPLES_PER_PIXEL;
        info.extraSamples = DEFAULT_EXTRA_SAMPLES;

        // Check if the file is a TIFF image and read its bits per sample
        if (strcmp(filePath, ".tif") == 0) {
            // Read the bits per sample from the header
            fseek(file, 16, SEEK_SET);
            int bitsPerSample = fgetc(file);
            if (bitsPerSample > MAX_BITS_PER_SAMPLE) {
                printf("Warning: unsupported bits per sample %d\n", bitsPerSample);
                info.bitsPerSample = DEFAULT_BITS_PER_SAMPLE;
            } else {
                info.bitsPerSample = bitsPerSample;
            }
        }

        // Check if the file is a PNG image and read its samples per pixel
        if (strcmp(filePath, ".png") == 0) {
            // Read the samples per pixel from the header
            fseek(file, 16, SEEK_SET);
            int samplesPerPixel = fgetc(file);
            info.samplesPerPixel = samplesPerPixel;
        }

        // Check if the file has extra samples and read them
        if (info.extraSamples > 0) {
            // Read the extra samples from the header
            fseek(file, 16, SEEK_SET);
            int extraSamples = fgetc(file);
            info.extraSamples = extraSamples;
        }

        // Close the file and return the image information
        fclose(file);
        return info;
    } else {
        printf("Error: unsupported file format %s\n", filePath);
        return;
    }
}

// Define the function to integrate with an existing theme caching mechanism
void cacheThemeBitmap(const char* filePath) {
    // Check if the theme bitmap is already cached
    if (themeCache[filePath] != NULL) {
        // If the theme bitmap is already cached, return it
        return;
    } else {
        // If the theme bitmap is not cached, clear the cache and set the new bitmap to null
        for (int i = 0; i < THEME_CACHE_SIZE; i++) {
            if (themeCache[i] != NULL) {
                free(themeCache[i]);
                themeCache[i] = NULL;
            }
        }
        themeCache[filePath] = NULL;
    }
}

// Define the function to manage configuration for a default theme directory
void configureDefaultThemeDirectory() {
    // Check if the default theme directory is currently set
    if (strcmp(defaultThemeDirectory, DEFAULT_THEME_DIRECTORY) == 0) {
        // If the default theme directory is already set, return it
        return;
    } else {
        // If the default theme directory is not set, interact with an external configuration service to get the new directory
        char* newDirectory = getDefaultThemeDirectory();
        if (newDirectory != NULL) {
            strcpy(defaultThemeDirectory, newDirectory);
        }
    }
}

// Define the function to handle concurrent access from multiple threads and ensure thread-safety
void handleConcurrentAccess() {
    // Use a mutex to lock the theme cache and configuration for the default theme directory
    pthread_mutex_lock(&themeCacheMutex);
    pthread_mutex_lock(&defaultThemeDirectoryMutex);

    // Handle the image information and caching of the theme bitmap
    handleImage(filePath);
    cacheThemeBitmap(filePath);

    // Unlock the mutexes to allow other threads to access the theme cache and configuration for the default theme directory
    pthread_mutex_unlock(&themeCacheMutex);
    pthread_mutex_unlock(&defaultThemeDirectoryMutex);
}

// Define the function to optimize memory usage while maintaining clarity and readability
void optimizeMemoryUsage() {
    // Use a cache for the theme bitmaps to minimize redundant file reads
    char* themeCache[THEME_CACHE_SIZE];
    for (int i = 0; i < THEME_CACHE_SIZE; i++) {
        themeCache[i] = NULL;
    }

    // Use a mutex to lock the theme cache and configuration for the default theme directory
    pthread_mutex_t themeCacheMutex;
    pthread_mutex_init(&themeCacheMutex, NULL);
    pthread_mutex_t defaultThemeDirectoryMutex;
    pthread_mutex_init(&defaultThemeDirectoryMutex, NULL);
}
```
