// Define a list of allowed file extensions
const char* allowed_extensions[] = {".txt", ".pdf", ".docx"};

// Function to generate a unique file name with enhanced metadata
char* generateDynamicFileName(const char* original_file_path) {
  // Check if the input path is valid
  if (original_file_path == NULL || strlen(original_file_path) == 0) {
    return NULL;
  }

  // Get the directory and file name from the original path
  const char* directory = dirname(original_file_path);
  const char* filename = basename(original_file_path);

  // Extract the file extension from the original file name
  const char* extension = strrchr(filename, '.');
  if (extension == NULL) {
    return NULL;
  }

  // Check if the file extension is allowed
  int i;
  for (i = 0; i < sizeof(allowed_extensions) / sizeof(char*); i++) {
    if (strcmp(extension, allowed_extensions[i]) == 0) {
      break;
    }
  }
  if (i == sizeof(allowed_extensions) / sizeof(char*)) {
    return NULL;
  }

  // Generate a SHA-256 hash of the original file name
  unsigned char hash[SHA256_DIGEST_LENGTH];
  SHA256((unsigned char*)filename, strlen(filename), hash);

  // Get the current Unix timestamp
  time_t timestamp = time(NULL);

  // Generate a sequence of digits based on the first 10 characters of the original file name
  const char* seq = filename + 10;
  int seq_len = strlen(seq);
  if (seq_len > 8) {
    seq_len = 8;
  }
  char sequence[9];
  memset(sequence, 0, sizeof(sequence));
  for (i = 0; i < seq_len; i++) {
    sequence[i] = seq[i];
  }

  // Build the new file name with enhanced metadata
  char* new_filename = malloc(strlen(directory) + strlen(filename) + SHA256_DIGEST_LENGTH + 10 + 1);
  sprintf(new_filename, "%s/%s.%s.%lu-%s.%s", directory, filename, hash, timestamp, sequence, extension);

  return new_filename;
}
```
