        // Use OpenSSL backend
    } else {
        // Use custom backend
    }
}

void init_digests() {
    for (int i = 0; i < MAX_DIGEST_ALGORITHMS; i++) {
        EVP_add_digest(digest_algorithms[i].digest);
        EVP_add_digest_alias(digest_algorithms[i].name, digest_algorithms[i].digest);
    }
}

void init_cipher_suites() {
    for (int i = 0; i < MAX_CIPHER_SUITES; i++) {
        EVP_add_cipher(cipher_suites[i].cipher);
        EVP_add_digest(cipher_suites[i].digest);
    }
}

