// Define the type of object to deserialize
typedef struct {
    int id;
    char name[10];
} Object;

int execute_command(char *cmd, int timeout) {
    // Fork a child process to run the command
    pid_t pid = fork();
    if (pid == 0) {
        // Child process: run the command and exit
        execl("/bin/sh", "sh", "-c", cmd, NULL);
        exit(1);
    } else if (pid > 0) {
        // Parent process: wait for the child to finish or timeout
        int status;
        struct timespec ts = {timeout, 0};
        while (waitpid(pid, &status, WNOHANG) == 0) {
            nanosleep(&ts, NULL);
        }
        if (WIFEXITED(status)) {
            // Command finished successfully
            return 1;
        } else {
            // Command timed out or failed
            kill(pid, SIGKILL);
            waitpid(pid, &status, 0);
            return 0;
        }
    } else {
        // Error forking the process
        perror("fork");
        return 0;
    }
}

