        return 1;
    }

    // Set up a socket for receiving the serialized object
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock == -1) {
        perror("socket");
        return 1;
    }

    struct sockaddr_in serv_addr;
    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(8080);
    if (inet_pton(AF_INET, "127.0.0.1", &serv_addr.sin_addr) <= 0) {
        perror("inet_pton");
        return 1;
    }

    // Connect to the socket and send the command
    if (connect(sock, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        perror("connect");
        return 1;
    }

    char *cmd = argv[1];
    int timeout = atoi(argv[2]);
    size_t len = strlen(cmd);
    send(sock, cmd, len, 0);

    // Receive the serialized object from the socket
    char buffer[1024];
    recv(sock, buffer, sizeof(buffer), 0);

    // Deserialize the object and verify its integrity
    Object obj;
    if (deserialize_object(buffer, len, &obj) == 1) {
        printf("Object ID: %d\n", obj.id);
        printf("Object Name: %s\n", obj.name);
    } else {
        fprintf(stderr, "Error deserializing object\n");
        return 0;
    }

    // Close the socket and exit
    close(sock);
    return 1;
}
