public class CloudStorageHelper
{
    private readonly HttpClient _httpClient;
    private readonly CloudStorageAccount _storageAccount;
    private readonly CloudBlobContainer _blobContainer;

    public CloudStorageHelper(string storageConnectionString, string containerName)
    {
        _httpClient = new HttpClient();
        _storageAccount = CloudStorageAccount.Parse(storageConnectionString);
        _blobContainer = _storageAccount.CreateCloudBlobClient().GetContainerReference(containerName);
    }

    public async Task<BlobReference> UploadFileAsync(byte[] fileBytes, string fileName, AccessLevel accessLevel)
    {
        var blob = await _blobContainer.GetBlockBlobReferenceAsync(fileName).ConfigureAwait(false);
        blob.Properties.ContentType = "application/octet-stream";

        // Compress the file using a lossless compression algorithm
        var compressedBytes = CompressFile(fileBytes);

        // Upload the compressed file to the cloud storage service
        await blob.UploadFromByteArrayAsync(compressedBytes, 0, compressedBytes.Length).ConfigureAwait(false);

        // Set the access level of the uploaded file
        blob.Properties.SetBlobTier(accessLevel == AccessLevel.Public ? BlobTier.Hot : BlobTier.Cool);

        return new BlobReference(blob, fileName, compressedBytes.Length);
    }

    private byte[] CompressFile(byte[] fileBytes)
    {
        // Implement a lossless compression algorithm here
        // For example, you can use the GZipStream class from System.IO.Compression
        using (var memoryStream = new MemoryStream())
        {
            using (var gzipStream = new GZipStream(memoryStream, CompressionMode.Compress))
            {
                gzipStream.Write(fileBytes, 0, fileBytes.Length);
            }

            return memoryStream.ToArray();
        }
    }
}

public class BlobReference
{
    public CloudBlockBlob Blob { get; }
    public string FileName { get; }
    public long CompressedSize { get; }

    public BlobReference(CloudBlockBlob blob, string fileName, long compressedSize)
    {
        Blob = blob;
        FileName = fileName;
        CompressedSize = compressedSize;
    }
}

public enum AccessLevel
{
    Public,
    Private,
    ReadOnly
}
