using System;
using System.Security.Cryptography;
using System.Text;

public static string HashStrings(params string[] inputs) {
    if (inputs == null || inputs.Length == 0) {
        return null;
    }

    // Create a new SHA-256 hash object
    var sha = SHA256.Create();

    // Initialize the hash with an empty byte array
    var hash = new byte[sha.HashSize / 8];

    // Iterate over each input string and update the hash
    foreach (var input in inputs) {
        if (input == null || input.Length > 1024) {
            continue;
        }

        var bytes = Encoding.UTF8.GetBytes(input);
        sha.TransformBlock(bytes, 0, bytes.Length, hash, 0);
    }

    // Complete the hash and return the result in hexadecimal format
    sha.TransformFinalBlock(new byte[0], 0, 0);
    var result = BitConverter.ToString(hash).Replace("-", "");
    return result;
}
```
