using System;
using System.IO;
using System.Threading;
using System.Runtime.Serialization.Formatters.Binary;

public class DataLoader
{
    private const int MAX_FILE_SIZE = 1024 * 1024 * 1024; // 1GB
    private static readonly object _lockObject = new object();

    public static void LoadData(string filePath, out CustomDataStructure data)
    {
        using (var stream = File.OpenRead(filePath))
        {
            if (stream.Length > MAX_FILE_SIZE)
            {
                throw new Exception("File size exceeds maximum allowed size.");
            }

            var formatter = new BinaryFormatter();
            data = (CustomDataStructure)formatter.Deserialize(stream);
        }
    }

    public static void LoadDataAsync(string filePath, Action<CustomDataStructure> callback)
    {
        ThreadPool.QueueUserWorkItem(_ =>
        {
            CustomDataStructure data;
            try
            {
                LoadData(filePath, out data);
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Failed to load data from file '{filePath}': {ex.Message}");
                return;
            }

            callback(data);
        });
    }
}
```
