function uploadFile(file, url) {
  // Generate a unique identifier for the file
  const id = generateId();

  // Get the file type and size
  const fileType = file.type;
  const fileSize = file.size;

  // Get the current timestamp
  const timestamp = Date.now();

  // Create a new XMLHttpRequest object
  const xhr = new XMLHttpRequest();

  // Set up the request headers
  xhr.setRequestHeader("Content-Type", fileType);
  xhr.setRequestHeader("X-File-Size", fileSize);
  xhr.setRequestHeader("X-Upload-Timestamp", timestamp);

  // Set up the progress callback
  xhr.upload.onprogress = function(event) {
    if (event.lengthComputable) {
      const percentComplete = event.loaded / event.total * 100;
      console.log(`Uploading ${file.name}... ${percentComplete}% complete`);
    } else {
      console.log(`Uploading ${file.name}...`);
    }
  };

  // Set up the error callback
  xhr.onerror = function(event) {
    console.log("Error uploading file:", event);
  };

  // Set up the load callback
  xhr.onload = function() {
    if (xhr.status === 200) {
      console.log(`File uploaded successfully: ${file.name}`);
    } else {
      console.log("Error uploading file:", xhr.responseText);
    }
  };

  // Set up the retry logic
  const MAX_RETRIES = 3;
  let retries = 0;
  while (retries < MAX_RETRIES) {
    try {
      xhr.open("POST", url, true);
      xhr.send(file);
      break;
    } catch (error) {
      console.log(`Error uploading file: ${error}`);
      retries++;
      if (retries === MAX_RETRIES) {
        throw error;
      }
    }
  }

  // Store the metadata in a database or cache
  const metadata = {
    id,
    fileType,
    fileSize,
    timestamp,
  };
  storeMetadata(metadata);
}

function generateId() {
  return Math.random().toString(36).substr(2, 9);
}

function storeMetadata(metadata) {
  // Implement your own metadata storage mechanism here
}
