// C function to initialize and populate an array of NFAPI_RX_FRAME_PDU_T structures for processing up to 100 concurrent user equipment (UE) signals
void initAndPopulateNfapiRxFramePduArray(int numUes, NFAPI_RX_FRAME_PDU_T* nfapiRxFramePduArray) {
  // Initialize the array of NFAPI_RX_FRAME_PDU_T structures
  for (int i = 0; i < numUes; i++) {
