    nfapiRxFramePduArray[i].rx_frame_info.rnti = i + 1; // RNTI starts at 1
    nfapiRxFramePduArray[i].rx_frame_info.cqi = calculateCqi(i);
    nfapiRxFramePduArray[i].rx_frame_info.rsrp = calculateRsrp(i);
  }
}

