use std::env;
use std::fs;
use std::path::PathBuf;
use std::process::Command;

fn initialize_project_directory(name: &str) -> Result<(), String> {
    // Verify if the project directory is already set in the environment
    let project_dir = env::var("PROJECT_DIR").ok();

    // If the directory is not set, create a new directory with the specified name
    if project_dir.is_none() {
        let mut path = PathBuf::from(name);
        path.push("project");

        match fs::create_dir(&path) {
            Ok(_) => (),
            Err(e) => return Err(format!("Failed to create project directory: {}", e)),
        }

        // Initialize subdirectories and environment variables
        let mut subdirs = vec!["src", "target"];
        for dir in &subdirs {
            path.push(dir);
            match fs::create_dir(&path) {
                Ok(_) => (),
                Err(e) => return Err(format!("Failed to create subdirectory: {}", e)),
            }
            path.pop();
        }

        env::set_var("PROJECT_DIR", &path);
    } else {
        // Update environment variables with the correct paths and configurations
        let project_dir = project_dir.unwrap();
        env::set_var("PROJECT_DIR", &project_dir);
    }

    // Manage external dependencies, such as network services or third-party tools
    match Command::new("npm").arg("install").current_dir(&env::var("PROJECT_DIR")).status() {
        Ok(_) => (),
        Err(e) => return Err(format!("Failed to install external dependencies: {}", e)),
    }

    // Log any discrepancies using the `log_info` function
    log_info("Project directory initialized");

    Ok(())
}
