// Function to populate the list of CRC indications
void populate_crc_indications(size_t num_elements) {
    // Initialize the list with the number of elements requested
    crc_indications = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_indications) {
        printf("Error: Failed to allocate memory for CRC indications\n");
        return;
    }

    // Set the number of elements in the list
    num_crc_indications = num_elements;

    // Generate random values for the RNTI and CRCFLAG fields
    srand(time(NULL));
    for (size_t i = 0; i < num_crc_indications; i++) {
        crc_indications[i].rx_ue_information_tag = rand() % 1000;
        crc_indications[i].rnti = rand() % 1000000;
        crc_indications[i].crc_indication_rel8_tag = rand() % 256;
        crc_indications[i].crcflag = (rand() % 2) ? true : false;
    }

    // Check for duplicate RNTIs and handle them appropriately
    size_t num_duplicates = 0;
    for (size_t i = 0; i < num_crc_indications - 1; i++) {
        for (size_t j = i + 1; j < num_crc_indications; j++) {
            if (crc_indications[i].rnti == crc_indications[j].rnti) {
                // Duplicate RNTI found, increment the duplicate count and remove the duplicate entry
                num_duplicates++;
                memmove(&crc_indications[j], &crc_indications[j + 1], (num_crc_indications - j) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
                num_crc_indications--;
            }
        }
    }

    // Print statistics on successful and failed attempts to add RNTIs
    printf("Added %zu CRC indications, with %zu duplicates\n", num_crc_indications, num_duplicates);
}
