['```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

// Define the structure of a record
typedef struct {
    int value;
} Record;

// Define the hash table data structure
typedef struct {
    int size; // Size of the hash table
    int capacity; // Capacity of the hash table
    int *keys; // Array of keys
    Record **records; // Array of records
    pthread_mutex_t mutex; // Mutex for synchronization
} HashTable;

// Define a function to initialize the hash table
void initHashTable(HashTable *ht, int size) {
    ht->size = 0;
    ht->capacity = size;
    ht->keys = (int *)malloc(sizeof(int) * size);
    ht->records = (Record **)malloc(sizeof(Record *) * size);
    pthread_mutex_init(&ht->mutex, NULL);
}

// Define a function to insert a key-value pair into the hash table
void insertHashTable(HashTable *ht, int key, Record *record) {
    // Acquire the mutex lock
    pthread_mutex_lock(&ht->mutex);

    // Check if the key already exists in the hash table
    for (int i = 0; i < ht->size; i++) {
        if (ht->keys[i] == key) {
            // If the key already exists, update the record
            ht->records[i] = record;
            pthread_mutex_unlock(&ht->mutex);
            return;
        }
    }

    // If the key does not exist, insert a new entry
    if (ht->size == ht->capacity) {
        // If the hash table is full, resize it
        int newSize = ht->capacity * 2;
        ht->keys = (int *)realloc(ht->keys, sizeof(int) * newSize);
        ht->records = (Record **)realloc(ht->records, sizeof(Record *) * newSize);
        ht->capacity = newSize;
    }

    // Insert the key-value pair into the hash table
    ht->keys[ht->size] = key;
    ht->records[ht->size] = record;
    ht->size++;

    // Release the mutex lock
    pthread_mutex_unlock(&ht->mutex);
}

// Define a function to lookup a value in the hash table
Record *lookupHashTable(HashTable *ht, int key) {
    // Acquire the mutex lock
    pthread_mutex_lock(&ht->mutex);

    // Search for the key in the hash table
    for (int i = 0; i < ht->size; i++) {
        if (ht->keys[i] == key) {
            Record *record = ht->records[i];
            pthread_mutex_unlock(&ht->mutex);
            return record;
        }
    }

    // If the key is not found, return NULL
    pthread_mutex_unlock(&ht->mutex);
    return NULL;
}

// Define a function to delete a key-value pair from the hash table
void deleteHashTable(HashTable *ht, int key) {
    // Acquire the mutex lock
    pthread_mutex_lock(&ht->mutex);

    // Search for the key in the hash table
    for (int i = 0; i < ht->size; i++) {
        if (ht->keys[i] == key) {
            // If the key is found, delete it
            ht->size--;
            ht->keys[i] = ht->keys[ht->size];
            ht->records[i] = ht->records[ht->size];
            break;
        }
    }

    // Release the mutex lock
    pthread_mutex_unlock(&ht->mutex);
}

// Define a function to monitor memory usage statistics
void monitorMemoryUsage(HashTable *ht) {
    // Acquire the mutex lock
    pthread_mutex_lock(&ht->mutex);

    // Calculate the total memory used by the hash table
    int totalMemory = sizeof(int) * ht->capacity + sizeof(Record *) * ht->capacity;

    // Print the memory usage statistics
    printf("Total memory used: %d bytes\n", totalMemory);

    // Release the mutex lock
    pthread_mutex_unlock(&ht->mutex);
}

// Define a function to allocate memory for the hash table
void *allocateHashTable(int size) {
    HashTable *ht = (HashTable *)malloc(sizeof(HashTable));
    initHashTable(ht, size);
    return ht;
}

// Define a function to deallocate memory for the hash table
void deallocateHashTable(HashTable *ht) {
    free(ht->keys);
    free(ht->records);
    pthread_mutex_destroy(&ht->mutex);
    free(ht);
}
```
