    {"SHA-256", EVP_sha256, 0},
    {"SHA-384", EVP_sha384, 0},
    {"SHA-512", EVP_sha512, 0},
    {"AES-128-CBC", EVP_aes_128_cbc, 0},
    {"AES-256-CBC", EVP_aes_256_cbc, 0}
};

// Define a function to dynamically retrieve and return a list of available cryptographic hash functions and block ciphers
HashCipher *get_hash_ciphers(void) {
    // Initialize the array of available hash functions and block ciphers
    HashCipher *hash_ciphers = malloc(sizeof(HashCipher) * (sizeof(hash_ciphers) / sizeof(HashCipher)));
    if (!hash_ciphers) {
        return NULL;
    }

    // Retrieve the list of available hash functions and block ciphers from OpenSSL
    int num_hash_ciphers = EVP_get_digestbyname_all(NULL, 0);
    if (num_hash_ciphers < 0) {
        free(hash_ciphers);
        return NULL;
    }

    // Iterate over the list of available hash functions and block ciphers and populate the array
    for (int i = 0; i < num_hash_ciphers; i++) {
        const EVP_MD *md = EVP_get_digestbyname(EVP_get_digestbyname_all(NULL, i));
        if (!md) {
            continue;
        }
        hash_ciphers[i].name = md->name;
        hash_ciphers[i].impl = md->md_ctrl;
        hash_ciphers[i].params = md->md_size;
    }

    // Retrieve the list of available block ciphers from OpenSSL
    int num_block_ciphers = EVP_get_cipherbyname_all(NULL, 0);
    if (num_block_ciphers < 0) {
        free(hash_ciphers);
        return NULL;
    }

    // Iterate over the list of available block ciphers and populate the array
    for (int i = 0; i < num_block_ciphers; i++) {
        const EVP_CIPHER *cipher = EVP_get_cipherbyname(EVP_get_cipherbyname_all(NULL, i));
        if (!cipher) {
            continue;
        }
        hash_ciphers[i + num_hash_ciphers].name = cipher->name;
        hash_ciphers[i + num_hash_ciphers].impl = cipher->cipher_ctrl;
        hash_ciphers[i + num_hash_ciphers].params = cipher->key_len;
    }

    // Return the array of available hash functions and block ciphers
    return hash_ciphers;
}

