    snprintf(url, sizeof(url), "https://api.example.com/version/%s", name);

    // Set the HTTP headers for the API call
    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Accept: application/json");
    headers = curl_slist_append(headers, "Content-Type: application/json");

    // Set the HTTP options for the API call
    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_SSL_VERIFYPEER, 0L);
    curl_easy_setopt(curl, CURLOPT_SSL_VERIFYHOST, 0L);

    // Perform the API call and retrieve the response
    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        return;
    }

    // Extract the version information from the response
    long http_code = 0;
    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
    if (http_code != 200) {
        return;
    }
    struct curl_slist *header_list = NULL;
    curl_easy_getinfo(curl, CURLINFO_HEADER_LIST, &header_list);
    char *version = NULL;
    for (struct curl_slist *header = header_list; header; header = header->next) {
        if (!strncmp("X-Version", header->data, 8)) {
            version = strdup(header->data + 9);
            break;
        }
    }
    if (!version) {
        return;
    }

    // Parse the version information and store it in the output parameters
    char *delim = strchr(version, '.');
    if (delim) {
        *major = atoi(version);
        *minor = atoi(delim + 1);
    } else {
        *major = atoi(version);
        *minor = 0;
    }

    // Clean up the HTTP client and return
    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
}

// Define a function to fetch additional metadata from external APIs for each supported cipher or hash function
