namespace CustomRandomGenerator
{
    public class RandomNumberGenerator : IRandomNumberGenerator
    {
        private readonly Random _random = new Random();

        public RandomNumberGenerator(int seed)
        {
            this._random = new Random(seed);
        }

        public int NextInt(int minValue, int maxValue)
        {
            return this._random.Next(minValue, maxValue + 1);
        }

        public float NextFloat(float minValue, float maxValue, int decimalPlaces = 0)
        {
            if (decimalPlaces == 0)
            {
                return (float)(this._random.NextDouble() * (maxValue - minValue)) + minValue;
            }
            else
            {
                double randomNumber = this._random.NextDouble();
                int power = Math.Pow(10, decimalPlaces);
                return (float)Math.Round((randomNumber * (maxValue - minValue)) + minValue, decimalPlaces);
            }
        }

        public long NextLong(long minValue, long maxValue)
        {
            if (minValue > maxValue)
            {
                throw new ArgumentException("Min value cannot be greater than max value");
            }

            long range = maxValue - minValue;
            long randomNumber = this._random.NextLong(range);
            return randomNumber + minValue;
        }

        public double NextDouble(double minValue, double maxValue)
        {
            if (minValue > maxValue)
            {
                throw new ArgumentException("Min value cannot be greater than max value");
            }

            double range = maxValue - minValue;
            double randomNumber = this._random.NextDouble() * range;
            return randomNumber + minValue;
        }

        public bool NextBool(double probability)
        {
            if (probability < 0 || probability > 1)
            {
                throw new ArgumentException("Probability must be between 0 and 1");
            }

            return this._random.NextDouble() <= probability;
        }
    }
}
