#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>
#include <dirent.h>
#include <errno.h>

// Configuration structure for file extension modification rules
typedef struct {
    int num_digits; // Number of digits to keep in the filename
    char* file_type; // File type to modify (e.g., "jpg", "png")
    char** additional_patterns; // Additional patterns to match against the filename for extension modification
} config_t;

// Function to dynamically rename files within a specified directory, modifying their extensions based on specific criteria
void rename_files(const char* dir_path, const char* filename, config_t* config) {
    // Check if the directory exists and is accessible
    struct stat st = {0};
    if (stat(dir_path, &st) == -1) {
        perror("stat");
        return;
    }

    // Open the directory for reading
    DIR* dir = opendir(dir_path);
    if (!dir) {
        fprintf(stderr, "Failed to open directory: %s\n", strerror(errno));
        return;
    }

    // Iterate over the files in the directory
    struct dirent* entry = NULL;
    while ((entry = readdir(dir)) != NULL) {
        // Skip hidden files and directories
        if (entry->d_name[0] == '.') continue;

        // Get the full file path
        char* file_path = malloc(strlen(dir_path) + strlen(filename) + 2);
        sprintf(file_path, "%s/%s", dir_path, entry->d_name);

        // Check if the file exists and is accessible
        struct stat st = {0};
        if (stat(file_path, &st) == -1) {
            perror("stat");
            free(file_path);
            continue;
        }

        // Get the file extension
        char* ext = strrchr(entry->d_name, '.');
        if (!ext) {
            fprintf(stderr, "Failed to get file extension: %s\n", entry->d_name);
            free(file_path);
            continue;
        }

        // Check if the file extension matches the configured file type
        if (strcmp(ext + 1, config->file_type) != 0) {
            free(file_path);
            continue;
        }

        // Modify the file extension based on the configuration rules
        char* new_ext = modify_extension(entry->d_name, config);
        if (!new_ext) {
            fprintf(stderr, "Failed to modify file extension: %s\n", entry->d_name);
            free(file_path);
            continue;
        }

        // Rename the file
        char* new_file_path = malloc(strlen(dir_path) + strlen(filename) + 2 + strlen(new_ext));
        sprintf(new_file_path, "%s/%s.%s", dir_path, filename, new_ext);
        if (rename(file_path, new_file_path) == -1) {
            perror("rename");
            free(file_path);
            free(new_file_path);
            continue;
        }

        // Free memory
        free(file_path);
        free(new_file_path);
    }

    // Close the directory
    closedir(dir);
}

// Function to modify a file extension based on specific criteria
char* modify_extension(const char* filename, config_t* config) {
    // Get the file extension
    char* ext = strrchr(filename, '.');
    if (!ext) return NULL;

    // Check if the file extension matches the configured file type
    if (strcmp(ext + 1, config->file_type) != 0) return NULL;

    // Modify the file extension based on the configuration rules
    char* new_ext = malloc(config->num_digits + strlen(config->file_type) + 1);
    sprintf(new_ext, "%.*s.%s", config->num_digits, filename, config->file_type);

    // Check if the modified extension matches any of the additional patterns
    for (int i = 0; i < config->num_additional_patterns; i++) {
        if (strcmp(new_ext, config->additional_patterns[i]) == 0) return new_ext;
    }

    // Free memory and return NULL if the modified extension does not match any of the additional patterns
    free(new_ext);
    return NULL;
}
