void process_input(int *arr, size_t arr_len) {
    // Find the largest integer in the array
    int max = INT_MIN;
    for (size_t i = 0; i < arr_len; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    // Print the largest integer to standard output
