}

// Define the function to populate the list of NFAPI_CRC_INDICATION_PDU_T structures
void processRNTICRCIndications(NFAPI_CRC_INDICATION_PDU_T *list, size_t list_size) {
    // Initialize a random seed for generating unique RNTIs
    srand(time(NULL));

    // Iterate over the list of NFAPI_CRC_INDICATION_PDU_T structures
    for (size_t i = 0; i < list_size; i++) {
        // Generate a random RNTI value between 1 and 65535
        uint32_t rnti = rand() % 65535 + 1;

        // Check if the generated RNTI is already in the list
        bool duplicate = false;
        for (size_t j = 0; j < i; j++) {
            if (list[j].RNTI == rnti) {
                duplicate = true;
                break;
