#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdbool.h>

// Define a structure to represent an NFAPI_CRC_INDICATION_PDU_T element in the list
typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a structure to represent the list of NFAPI_CRC_INDICATION_PDU_T elements
typedef struct {
    size_t capacity; // The maximum number of elements that can be stored in the list
    size_t count; // The current number of elements in the list
    NFAPI_CRC_INDICATION_PDU_T* elements; // An array of pointers to the NFAPI_CRC_INDICATION_PDU_T structures
} NFAPI_CRC_INDICATION_LIST_T;

// Define a function to create a new list with a given capacity
NFAPI_CRC_INDICATION_LIST_T* nfapi_crc_indication_list_create(size_t capacity) {
    NFAPI_CRC_INDICATION_LIST_T* list = malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    if (list == NULL) {
        return NULL;
    }
    list->capacity = capacity;
    list->count = 0;
    list->elements = calloc(capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (list->elements == NULL) {
        free(list);
        return NULL;
    }
    return list;
}

// Define a function to destroy an existing list
void nfapi_crc_indication_list_destroy(NFAPI_CRC_INDICATION_LIST_T* list) {
    if (list == NULL) {
        return;
    }
    free(list->elements);
    free(list);
}

// Define a function to insert an element at the end of the list
bool nfapi_crc_indication_list_insert(NFAPI_CRC_INDICATION_LIST_T* list, RX_UE_INFORMATION_TAG rx_ue_information, RNTI rnti, CRC_INDICATION_REL8_TAG crc_indication_rel8) {
    if (list == NULL || list->count >= list->capacity) {
        return false;
    }
    NFAPI_CRC_INDICATION_PDU_T* element = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (element == NULL) {
        return false;
    }
    element->rx_ue_information = rx_ue_information;
    element->rnti = rnti;
    element->crc_indication_rel8 = crc_indication_rel8;
    list->elements[list->count++] = element;
    return true;
}

// Define a function to remove an element from the end of the list
bool nfapi_crc_indication_list_remove(NFAPI_CRC_INDICATION_LIST_T* list) {
    if (list == NULL || list->count <= 0) {
        return false;
    }
    free(list->elements[--list->count]);
    return true;
}

// Define a function to iterate over the elements of the list safely without causing buffer overflows
void nfapi_crc_indication_list_iterate(NFAPI_CRC_INDICATION_LIST_T* list, void (*callback)(RX_UE_INFORMATION_TAG rx_ue_information, RNTI rnti, CRC_INDICATION_REL8_TAG crc_indication_rel8)) {
    if (list == NULL || callback == NULL) {
        return;
    }
    for (size_t i = 0; i < list->count; i++) {
        NFAPI_CRC_INDICATION_PDU_T* element = list->elements[i];
        callback(element->rx_ue_information, element->rnti, element->crc_indication_rel8);
    }
}

// Define a function to validate the RNTI values in the list and initialize the CRCFLAG for each element
bool nfapi_crc_indication_list_validate(NFAPI_CRC_INDICATION_LIST_T* list) {
    if (list == NULL) {
        return false;
    }
    for (size_t i = 0; i < list->count; i++) {
        NFAPI_CRC_INDICATION_PDU_T* element = list->elements[i];
        if (!validate_rnti(element->rnti)) {
            return false;
        }
        element->crc_indication_rel8.CRCFLAG = generate_random_crcflag();
    }
    return true;
}
