    return 1;
}

// Function to disable the cipher context
int disableCipher(CipherContext *ctx) {
    // Disable the cipher context
    ctx->enabled = 0;

    return 1;
}

// Function to encrypt data using the cipher context
int encryptData(CipherContext *ctx, const unsigned char *data, size_t data_len, unsigned char *encrypted_data) {
