        fprintf(stderr, "Error: Cipher context not enabled\n");
        return 0;
    }

    // Encrypt the data using AES-256-CBC
    int ret = AES_cbc_encrypt(data, encrypted_data, data_len, &ctx->key, ctx->iv, AES_ENCRYPT);
    if (ret <= 0) {
        fprintf(stderr, "Error: Failed to encrypt data\n");
        return 0;
    }

    // Return the encrypted data
    return ret;
}

// Function to decrypt data using the cipher context
int decryptData(CipherContext *ctx, const unsigned char *encrypted_data, size_t encrypted_data_len, unsigned char *decrypted_data) {
    // Check if the cipher context is enabled
    if (!ctx->enabled) {
        fprintf(stderr, "Error: Cipher context not enabled\n");
        return 0;
    }

    // Decrypt the data using AES-256-CBC
    int ret = AES_cbc_decrypt(encrypted_data, decrypted_data, encrypted_data_len, &ctx->key, ctx->iv, AES_DECRYPT);
    if (ret <= 0) {
        fprintf(stderr, "Error: Failed to decrypt data\n");
        return 0;
    }

    // Return the decrypted data
    return ret;
}

// Function to clean up the cipher context
int cleanupCipher(CipherContext *ctx) {
    // Clean up the encryption key and IV
    AES_clear_key(&ctx->key);
    memset(ctx->iv, 0, AES_BLOCK_SIZE);

    return 1;
}
