// Define the function to validate the integrity of a CRC indication tag
bool validateCrcIndicationTag(CRC_INDICATION_REL8_TAG crcIndicationRel8) {
    // Check if the CRCFLAG is set and if it's within the expected range
    if (crcIndicationRel8.CRCFLAG == 0 || crcIndicationRel8.CRCFLAG > 1) {
