#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure for network configuration
typedef struct {
    MAC_FRAME macFrame;
    VLAN_TAG vlanTag;
    time_t timestamp;
} NetworkConfig;

// Define the list data structure
typedef struct {
    NetworkConfig *configs;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} ConfigList;

// Initialize a new list with a given capacity
void configListInit(ConfigList *list, size_t capacity) {
    list->configs = (NetworkConfig *)malloc(capacity * sizeof(NetworkConfig));
    list->capacity = capacity;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

// Insert a new configuration at the end of the list
void configListInsert(ConfigList *list, NetworkConfig config) {
    // Acquire lock to prevent race conditions
    pthread_mutex_lock(&list->mutex);

    // Check if the list is full and needs to be resized
    if (list->count == list->capacity) {
        size_t newCapacity = list->capacity * 2;
        NetworkConfig *newConfigs = (NetworkConfig *)realloc(list->configs, newCapacity * sizeof(NetworkConfig));
        if (!newConfigs) {
            // Reallocation failed, log error and return
            pthread_mutex_unlock(&list->mutex);
            printf("Failed to reallocate memory for config list\n");
            return;
        }
        list->configs = newConfigs;
        list->capacity = newCapacity;
    }

    // Insert the new configuration at the end of the list
    list->configs[list->count] = config;
    list->count++;

    // Release lock and return
    pthread_mutex_unlock(&list->mutex);
}

// Delete a configuration from the list by its index
void configListDelete(ConfigList *list, size_t index) {
    // Acquire lock to prevent race conditions
    pthread_mutex_lock(&list->mutex);

    // Check if the index is valid and the list is not empty
    if (index < 0 || index >= list->count) {
        printf("Invalid index for config deletion\n");
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    // Shift all configurations after the deleted one to fill the gap
    for (size_t i = index + 1; i < list->count; i++) {
        list->configs[i - 1] = list->configs[i];
    }

    // Decrement the count and release lock
    list->count--;
    pthread_mutex_unlock(&list->mutex);
}

// Iterate over all configurations in the list
void configListIterate(ConfigList *list, void (*callback)(NetworkConfig *config)) {
    // Acquire lock to prevent race conditions
    pthread_mutex_lock(&list->mutex);

    // Iterate over all configurations and call the callback function for each one
    for (size_t i = 0; i < list->count; i++) {
        NetworkConfig *config = &list->configs[i];
        callback(config);
    }

    // Release lock and return
    pthread_mutex_unlock(&list->mutex);
}

// Validate a MAC_FRAME structure for proper initialization
int validateMACFrame(MAC_FRAME *macFrame) {
    if (!macFrame || !macFrame->srcMac || !macFrame->dstMac) {
        return -1;
    }
    return 0;
}

// Validate a VLAN tag for proper initialization and range
int validateVLANTag(VLAN_TAG *vlanTag, int minVLANId, int maxVLANId) {
    if (!vlanTag || vlanTag->vlanId < minVLANId || vlanTag->vlanId > maxVLANId) {
        return -1;
    }
    return 0;
}

// Insert a new configuration into the list, validating MAC_FRAME and VLAN tag
void insertConfig(ConfigList *list, NetworkConfig config) {
    // Validate the MAC_FRAME structure for proper initialization
    if (validateMACFrame(&config.macFrame)) {
        printf("Invalid MAC_FRAME structure\n");
        return;
    }

    // Validate the VLAN tag for proper initialization and range
    if (validateVLANTag(&config.vlanTag, minVLANId, maxVLANId)) {
        printf("Invalid VLAN tag\n");
        return;
    }

    // Insert the new configuration into the list
    configListInsert(list, config);
}

// Delete a configuration from the list by its index, validating MAC_FRAME and VLAN tag
void deleteConfig(ConfigList *list, size_t index) {
    // Validate the index for proper deletion
    if (index < 0 || index >= list->count) {
        printf("Invalid index for config deletion\n");
        return;
    }

    // Acquire lock to prevent race conditions
    pthread_mutex_lock(&list->mutex);

    // Validate the MAC_FRAME structure for proper initialization
    NetworkConfig *config = &list->configs[index];
    if (validateMACFrame(&config.macFrame)) {
        printf("Invalid MAC_FRAME structure\n");
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    // Validate the VLAN tag for proper initialization and range
    if (validateVLANTag(&config.vlanTag, minVLANId, maxVLANId)) {
        printf("Invalid VLAN tag\n");
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    // Delete the configuration from the list
    configListDelete(list, index);

    // Release lock and return
    pthread_mutex_unlock(&list->mutex);
}
