// Define the list structure for the NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
} NFAPI_CRC_INDICATION_LIST_T;

// Define the function to manage the dynamic list of NFAPI_CRC_INDICATION_PDU_T structures
void manage_crc_indication_list(NFAPI_CRC_INDICATION_LIST_T *list) {
    // Check if the list is NULL or empty
    if (list == NULL || list->size == 0) {
        return;
    }

    // Define a lock for thread safety
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Define a condition variable to signal when the list is full or empty
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

    // Define a flag to indicate if the list is full or empty
    bool is_full = false;

    // Define a flag to indicate if the list is being iterated over
    bool is_iterating = false;

    // Define a function to add an element to the list
    void add_element(NFAPI_CRC_INDICATION_PDU_T *element) {
        // Lock the mutex before modifying the list
        pthread_mutex_lock(&mutex);

        // Check if the list is full or empty
        if (is_full || list->size == 0) {
            // If the list is full, wait for it to become empty
            while (is_full) {
                pthread_cond_wait(&cond, &mutex);
            }
        }

        // Add the element to the list
        list->data = realloc(list->data, (list->size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        memcpy(&list->data[list->size], element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        list->size++;

        // Unlock the mutex after modifying the list
        pthread_mutex_unlock(&mutex);
    }

    // Define a function to remove an element from the list
    void remove_element(NFAPI_CRC_INDICATION_PDU_T *element) {
        // Lock the mutex before modifying the list
        pthread_mutex_lock(&mutex);

        // Check if the list is empty or if the element to be removed is not in the list
        if (list->size == 0 || !memcmp(element, &list->data[list->size], sizeof(NFAPI_CRC_INDICATION_PDU_T))) {
            // If the list is empty or the element to be removed is not in the list, return
            pthread_mutex_unlock(&mutex);
            return;
        }

        // Find the index of the element to be removed
        size_t index = 0;
        while (index < list->size && memcmp(element, &list->data[index], sizeof(NFAPI_CRC_INDICATION_PDU_T))) {
            index++;
        }

        // Remove the element from the list
        if (index < list->size) {
            memmove(&list->data[index], &list->data[index + 1], (list->size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            list->size--;
        }

        // Unlock the mutex after modifying the list
        pthread_mutex_unlock(&mutex);
    }

    // Define a function to iterate over the elements of the list safely
    void iterate_elements(void (*callback)(NFAPI_CRC_INDICATION_PDU_T *)) {
        // Lock the mutex before iterating over the list
        pthread_mutex_lock(&mutex);

        // Check if the list is empty or if it is being iterated over
        if (list->size == 0 || is_iterating) {
            // If the list is empty or it is being iterated over, return
            pthread_mutex_unlock(&mutex);
            return;
        }

        // Set the flag to indicate that the list is being iterated over
        is_iterating = true;

        // Iterate over the elements of the list
        for (size_t i = 0; i < list->size; i++) {
            callback(&list->data[i]);
        }

        // Unset the flag to indicate that the list is no longer being iterated over
        is_iterating = false;

        // Unlock the mutex after iterating over the list
        pthread_mutex_unlock(&mutex);
    }
}
