Here is a possible implementation of the function in C:
```c
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

// Structure to represent a state in the FSA
typedef struct {
    int id;
    char* name;
} State;

// Function to dynamically allocate memory for a list of states from an FSA
State** create_state_list(int* states, int num_states, FSA* fsa, int last_state) {
    // Validate input parameters
    if (states == NULL || num_states <= 0 || fsa == NULL || last_state < 0) {
        return NULL;
    }

    // Allocate memory for the state list
    State** state_list = malloc(sizeof(State*) * num_states);
    if (state_list == NULL) {
        return NULL;
    }

    // Initialize the state list with the states from the FSA
    int i, j;
    for (i = 0; i < num_states; i++) {
        State* state = malloc(sizeof(State));
        if (state == NULL) {
            free(state_list);
            return NULL;
        }
        state->id = states[i];
        state->name = fsa->states[i].name;
        state_list[i] = state;
    }

    // Update the 'next' pointer of the last state in the list to point to the newly created state list
    State* last_state_ptr = &(state_list[last_state]);
    if (last_state_ptr->next != NULL) {
        free(last_state_ptr->next);
    }
    last_state_ptr->next = state_list;

    // Return the newly created state list
    return state_list;
}
```
This function takes in an integer array of states, a number of states, a pointer to an FSA, and a last state index. It dynamically allocates memory for a list of states from the given FSA, initializes the state list with the states from the FSA, updates the 'next' pointer of the last state in the list to point to the newly created state list, and returns the newly created state list.

The function first validates the input parameters to ensure that they are not null or invalid. If any of the input parameters are invalid, it returns NULL.

Next, it allocates memory for the state list using `malloc()`. It then initializes each state in the list with the corresponding state from the FSA and sets the 'next' pointer of the last state in the list to point to the newly created state list.

Finally, it returns the newly created state list.

Here is an example usage of the function:
```c
int main() {
    // Define a finite state automaton with 3 states
    FSA fsa = {
        .num_states = 3,
        .states = {
            {"q0", "q1"},
            {"q1", "q2"},
            {"q2", "q0"}
        }
    };

    // Define a list of states from the FSA
    int* states = malloc(sizeof(int) * fsa.num_states);
    for (int i = 0; i < fsa.num_states; i++) {
        states[i] = i;
    }

    // Create a state list from the FSA and last state index
    State** state_list = create_state_list(states, fsa.num_states, &fsa, 2);

    // Print the state list
    for (int i = 0; i < fsa.num_states; i++) {
        printf("%d: %s\n", state_list[i]->id, state_list[i]->name);
    }

    return 0;
}
