// Function to dynamically allocate memory for and initialize multiple arrays
void init_records(int num_records, int range_min, int range_max, long max_mem_usage) {
    // Check if the input parameters are valid
    if (num_records <= 0 || range_min < 0 || range_max < 0 || max_mem_usage <= 0) {
        fprintf(stderr, "Invalid input parameters\n");
        return;
    }

    // Allocate memory for the offset and key arrays
    long *offsets = (long *)malloc(num_records * sizeof(long));
    int *keys = (int *)malloc(num_records * sizeof(int));

    // Initialize the offset and key arrays with random values within the specified range
    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand() % (range_max - range_min + 1) + range_min;
        keys[i] = rand() % (range_max - range_min + 1) + range_min;
    }

    // Allocate memory for the record structures and initialize them with pointers to the offset and key arrays
    Record *records = (Record *)malloc(num_records * sizeof(Record));
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % (range_max - range_min + 1) + range_min;
        records[i].offset = &offsets[i];
        records[i].key = &keys[i];
    }

    // Free the memory allocated for the offset and key arrays if the maximum memory usage threshold is exceeded
    if (max_mem_usage > 0 && get_memory_usage() > max_mem_usage) {
        free(offsets);
        free(keys);
        records = NULL;
    }
}

// Function to get the current memory usage in bytes
long get_memory_usage() {
    return (long)malloc_usable_size(NULL);
}
