    public static void main(String[] args) throws IOException {
        // Initialize a logger to log memory usage and errors
        Logger logger = new Logger();

        // Execute the command using Runtime.getRuntime().exec()
        String command = "ls -l";
        Process process = Runtime.getRuntime().exec(command);

        // Capture both the standard output and error streams of the command
        BufferedReader stdout = new BufferedReader(new InputStreamReader(process.getInputStream()));
        BufferedReader stderr = new BufferedReader(new InputStreamReader(process.getErrorStream()));

        // Log the memory usage before executing the command
        logger.logMemoryUsage();

        // Execute the command and capture its output
        String line;
        while ((line = stdout.readLine()) != null) {
            System.out.println(line);
        }

        // Log any errors that occurred during execution
        while ((line = stderr.readLine()) != null) {
            logger.logError(line);
        }

        // Delete the log file if it exists before executing the command again
        File logFile = new File(LOG_FILE);
