void processFileAndRetrieveData(const char* filename, int supervisor_id, const char* db_username, const char* db_password) {
    // Modify the filename
    char new_filename[256];
    strcpy(new_filename, filename);
    size_t len = strlen(filename);
    if (len > 0 && filename[len - 1] != '.') {
        strcat(new_filename, ".");
    }
    for (int i = 0; i < len; i++) {
        new_filename[i + len] = filename[i] + '0';
    }
    char* file_type = ".txt";
    strcat(new_filename, file_type);
    MD5_CTX ctx;
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5_Init(&ctx);
    MD5_Update(&ctx, filename, len);
    MD5_Final(digest, &ctx);
    char md5_hash[33];
    for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
        sprintf(md5_hash + (i * 2), "%02x", digest[i]);
    }
    strcat(new_filename, "-");
    strcat(new_filename, md5_hash);

    // Retrieve employee data
    sqlite3* db;
    char* errmsg = NULL;
    int rc = sqlite3_open("employees.db", &db);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Error opening database: %s\n", sqlite3_errmsg(db));
        return;
    }
    char* sql = "SELECT name, city, address FROM Employees WHERE supervisor_id=?";
    sqlite3_stmt* stmt;
    rc = sqlite3_prepare_v2(db, sql, -1, &stmt, NULL);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Error preparing statement: %s\n", sqlite3_errmsg(db));
        return;
    }
    rc = sqlite3_bind_int(stmt, 1, supervisor_id);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Error binding parameter: %s\n", sqlite3_errmsg(db));
        return;
    }
    rc = sqlite3_step(stmt);
    if (rc == SQLITE_ROW) {
        char* name = (char*)sqlite3_column_text(stmt, 0);
        char* city = (char*)sqlite3_column_text(stmt, 1);
        char* address = (char*)sqlite3_column_text(stmt, 2);
        printf("Employee data:\n");
        printf("Name: %s\n", name);
        printf("City: %s\n", city);
        printf("Address: %s\n", address);
    } else {
        fprintf(stderr, "Error retrieving employee data: %s\n", sqlite3_errmsg(db));
    }
    rc = sqlite3_finalize(stmt);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Error finalizing statement: %s\n", sqlite3_errmsg(db));
    }
    rc = sqlite3_close(db);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Error closing database: %s\n", sqlite3_errmsg(db));
    }
}
