            $stmt = $conn->prepare("UPDATE users SET record_array = :recordArray WHERE id = :userId");
            $stmt->bindParam(':recordArray', $recordArray, PDO::PARAM_INT);
            $stmt->bindParam(':userId', $userId, PDO::PARAM_INT);
            $stmt->execute();
        } catch (PDOException $e) {
            throw new Exception("Failed to update user profile in the database");
        }

        // Close the database connection
        $conn = null;
    }
}
