  // Allocate and initialize memory for the arrays of long, int, and record structures
  long* offsetArray = malloc(sizeof(long) * MAX_RECORDS);
  if (!offsetArray) {
    printf("Error: Could not allocate memory for offset array\n");
    return 1;
  }
  int* keyArray = malloc(sizeof(int) * MAX_RECORDS);
  if (!keyArray) {
    printf("Error: Could not allocate memory for key array\n");
    free(offsetArray);
    return 1;
  }
  record* recordArray = malloc(sizeof(record) * MAX_RECORDS);
  if (!recordArray) {
    printf("Error: Could not allocate memory for record array\n");
    free(offsetArray);
    free(keyArray);
    return 1;
  }

  // Set the value of each record's int field to a random value within the provided range
  srand(time(NULL));
  for (int i = 0; i < MAX_RECORDS; i++) {
    offsetArray[i] = rand() % (maxValue - minValue + 1) + minValue;
    keyArray[i] = i;
    recordArray[i].value = offsetArray[i];
  }

  // Periodically check the system's available memory and disk space during the allocation and initialization phases
  while (true) {
    struct rusage usage;
    getrusage(RUSAGE_SELF, &usage);
    if (usage.ru_maxrss > MAX_MEMORY || usage.ru_idrss > MAX_DISK_SPACE) {
      printf("Warning: Insufficient memory or disk space resources\n");
      sleep(10);
    } else {
      break;
    }
  }

  // Return 0 if the conversion to PDF completes successfully within the specified timeout, otherwise return 1
  struct timeval startTime, endTime;
  gettimeofday(&startTime, NULL);
  while (true) {
    if (access(outputFilePath, F_OK) != -1) {
      break;
    } else {
      sleep(1);
    }
    struct timeval currentTime;
    gettimeofday(&currentTime, NULL);
    long elapsedTime = (currentTime.tv_sec - startTime.tv_sec) * 1000 + (currentTime.tv_usec - startTime.tv_usec) / 1000;
    if (elapsedTime > timeout) {
      printf("Error: Conversion timed out\n");
      return 1;
    }
  }
  return 0;
}
