// Define data structures for the distributed cache system
typedef struct {
    long offset;
} record_t;

typedef struct {
    int key;
    record_t *record;
} hash_entry_t;

typedef struct {
    hash_entry_t **entries;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} hash_table_t;

// Define functions for managing memory pools and hash tables
void *allocate_memory(size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory\n");
        exit(1);
    }
    return ptr;
}

void deallocate_memory(void *ptr) {
    free(ptr);
}

hash_table_t *create_hash_table(size_t capacity) {
    hash_table_t *ht = allocate_memory(sizeof(hash_table_t));
    ht->entries = allocate_memory(capacity * sizeof(hash_entry_t*));
    memset(ht->entries, 0, capacity * sizeof(hash_entry_t*));
    ht->capacity = capacity;
    ht->size = 0;
    pthread_mutex_init(&ht->lock, NULL);
    return ht;
}

void destroy_hash_table(hash_table_t *ht) {
    for (int i = 0; i < ht->capacity; ++i) {
        if (ht->entries[i] != NULL) {
            deallocate_memory(ht->entries[i]);
        }
    }
    deallocate_memory(ht->entries);
    pthread_mutex_destroy(&ht->lock);
    deallocate_memory(ht);
}

void insert_into_hash_table(hash_table_t *ht, int key, record_t *record) {
    // Calculate the hash value for the given key
    size_t hash = key % ht->capacity;

    // Check if there is an existing entry for the given key
    while (ht->entries[hash] != NULL && ht->entries[hash]->key != key) {
        // If there is a collision, recalculate the hash value and try again
        hash = (hash + 1) % ht->capacity;
    }

    // If there is no existing entry for the given key, create one
    if (ht->entries[hash] == NULL) {
        ht->entries[hash] = allocate_memory(sizeof(hash_entry_t));
        ht->entries[hash]->key = key;
        ht->entries[hash]->record = record;
        ++ht->size;
    } else {
        // If there is an existing entry for the given key, update it with the new record
        ht->entries[hash]->record = record;
    }
}

void *lookup_in_hash_table(hash_table_t *ht, int key) {
    // Calculate the hash value for the given key
    size_t hash = key % ht->capacity;

    // Check if there is an existing entry for the given key
    while (ht->entries[hash] != NULL && ht->entries[hash]->key != key) {
        // If there is a collision, recalculate the hash value and try again
        hash = (hash + 1) % ht->capacity;
    }

    // Return the record associated with the given key, or NULL if it does not exist
    return ht->entries[hash] != NULL ? ht->entries[hash]->record : NULL;
}

void delete_from_hash_table(hash_table_t *ht, int key) {
    // Calculate the hash value for the given key
    size_t hash = key % ht->capacity;

    // Check if there is an existing entry for the given key
    while (ht->entries[hash] != NULL && ht->entries[hash]->key != key) {
        // If there is a collision, recalculate the hash value and try again
        hash = (hash + 1) % ht->capacity;
    }

    // If there is an existing entry for the given key, delete it
    if (ht->entries[hash] != NULL) {
        deallocate_memory(ht->entries[hash]);
        --ht->size;
    }
}

