typedef struct {
    int key;
    long offset;
    void* record;
} Record;

// Define the metadata array structure
typedef struct {
    int size;
    void* data[];
} MetadataArray;

// Define the memory pool interface
typedef struct {
    void* (*alloc)(size_t);
    void (*free)(void*);
} MemoryPool;

// Define the function to dynamically manage memory for a flexible record storage system
void dynamicRecordStorage(int type, int key, long offset, void* record, MetadataArray* metadata, MemoryPool* pool) {
    // Check input validation
    if (type < 0 || key < 0 || offset < 0 || record == NULL || metadata == NULL || pool == NULL) {
        return;
    }

    // Allocate memory for the record and metadata array
    Record* newRecord = (Record*)pool->alloc(sizeof(Record));
    MetadataArray* newMetadata = (MetadataArray*)pool->alloc(sizeof(MetadataArray) + sizeof(void*) * metadata->size);

    // Initialize the record and metadata array
    newRecord->key = key;
    newRecord->offset = offset;
    newRecord->record = record;
    memcpy(newMetadata, metadata, sizeof(MetadataArray) + sizeof(void*) * metadata->size);

    // Add the record to the memory pool
    pthread_mutex_lock(&pool->mutex);
    pool->used += sizeof(Record) + sizeof(MetadataArray) + sizeof(void*) * newMetadata->size;
    if (pool->used > pool->maxSize) {
        pool->maxSize = pool->used;
    }
    pthread_mutex_unlock(&pool->mutex);

    // Update the record and metadata array in the memory pool
    Record** records = (Record**)pool->data;
    records[type] = newRecord;
    MetadataArray** metadataArrays = (MetadataArray**)(records + type + 1);
    metadataArrays[type] = newMetadata;

    // Log the memory usage and record update
    printf("Memory usage: %lu bytes\n", pool->used);
    printf("Record updated: key=%d, offset=%ld, record=0x%p, metadataSize=%d\n", key, offset, record, newMetadata->size);
}
