} NR_CSI_Report;

// Function to add new context and update existing ones based on random SNR values
void simulate_csi_reports(int num_contexts, int num_slots) {
    // Initialize array of NRUEContext structures
    NRUEContext *contexts = (NRUEContext *)malloc(num_contexts * sizeof(NRUEContext));
    if (!contexts) {
        printf("Memory allocation failed\n");
        return;
    }

    // Initialize array of NR_CSI_Report structures
    NR_CSI_Report *reports = (NR_CSI_Report *)malloc(num_slots * sizeof(NR_CSI_Report));
    if (!reports) {
        printf("Memory allocation failed\n");
        free(contexts);
        return;
    }

    // Initialize random seed for SNR generation
    srand(time(NULL));

    // Simulate CSI reports for each context
    for (int i = 0; i < num_contexts; i++) {
        NRUEContext *context = &contexts[i];
        NR_CSI_Report *report = &reports[i];

        // Generate random SNR values for each slot
        for (int j = 0; j < num_slots; j++) {
            report->slots[j].SNR = rand() % 100 + 1;
        }

        // Update existing contexts and add new ones as needed
        if (i < num_contexts - 1) {
            NRUEContext *next_context = &contexts[i + 1];
            NR_CSI_Report *next_report = &reports[i + 1];

            // Update existing context and report structures
            for (int j = 0; j < num_slots; j++) {
                next_context->report.slots[j].SNR = report->slots[j].SNR;
                next_report->slots[j].timestamp = report->slots[j].timestamp;
            }
        } else {
            // Add new context and report structures
            NRUEContext *new_context = &contexts[i + 1];
            NR_CSI_Report *new_report = &reports[i + 1];

            // Initialize new context and report structures
            new_context->NRUEIdentifier = i + 1;
            new_context->RNTI = i + 1;
            new_report->num_slots = num_slots;

            for (int j = 0; j < num_slots; j++) {
                new_report->slots[j].SNR = rand() % 100 + 1;
                new_report->slots[j].timestamp = time(NULL);
            }
        }
    }

    // Periodically clean up unused slots to prevent excessive memory consumption
    for (int i = 0; i < num_contexts; i++) {
        NRUEContext *context = &contexts[i];
        NR_CSI_Report *report = &reports[i];

        // Check if any slots are unused and delete them
        for (int j = 0; j < num_slots; j++) {
            if (report->slots[j].SNR == -1) {
                report->num_slots--;
                memmove(&report->slots[j], &report->slots[j + 1], sizeof(NR_CSI_Report_Slot) * (num_slots - j));
            }
        }
    }

    // Free memory for contexts and reports
    free(contexts);
    free(reports);
}
