void manageFrames(NFAPI_RX_FRAME_T** frames, int numFrames) {
    // Initialize the frame index and slot index variables
    int frameIndex = 0;
    int slotIndex = 0;

    // Loop through each frame in the list
    for (int i = 0; i < numFrames; i++) {
        NFAPI_RX_FRAME_T* frame = frames[i];

        // Loop through each slot in the current frame
        for (int j = 0; j < frame->numSlots; j++) {
            NFAPI_RX_SLOT_T* slot = &frame->slots[j];

            // Check if the slot is unused
            if (!slot->rawDataBuffer) {
                continue;
            }

            // Check if the slot is older than a certain age (e.g., 10 seconds)
            uint64_t currentTime = getCurrentTimestamp();
            if ((currentTime - slot->timestamp) > 10 * 1000000) {
                free(slot->rawDataBuffer);
                slot->rawDataBuffer = NULL;
            }
        }
    }
}

