#define RESOURCE_KEY_INT "int"
#define RESOURCE_VALUE_INT 1234567890

// Define the HTTP headers and status codes used by the API
#define HEADER_CONTENT_TYPE "Content-Type"
#define HEADER_ACCEPT "Accept"
#define STATUS_CODE_OK 200
#define STATUS_CODE_BAD_REQUEST 400
#define STATUS_CODE_NOT_FOUND 404
#define STATUS_CODE_METHOD_NOT_ALLOWED 405
#define STATUS_CODE_INTERNAL_SERVER_ERROR 500

// Define the API endpoint and port number
#define ENDPOINT "localhost"
#define PORT 8080

// Function to handle HTTP requests and responses
void handle_request(int sock, char *method, char *resource) {
    // Check if the method is supported by the API
    if (strcmp(method, "GET") == 0 || strcmp(method, "POST") == 0 || strcmp(method, "PUT") == 0 || strcmp(method, "DELETE") == 0) {
        // Check if the resource is valid and supported by the API
        if (strcmp(resource, RESOURCE_KEY_STRING) == 0 || strcmp(resource, RESOURCE_KEY_INT) == 0) {
            // Handle the HTTP request based on the method
            if (strcmp(method, "GET") == 0) {
                // Return the resource value for GET requests
                char *response = malloc(sizeof(char) * 1024);
                sprintf(response, "%s: %d\n", RESOURCE_KEY_INT, RESOURCE_VALUE_INT);
                send(sock, response, strlen(response), 0);
                free(response);
            } else if (strcmp(method, "POST") == 0) {
                // Update the resource value for POST requests
                char *data = malloc(sizeof(char) * 1024);
                recv(sock, data, 1024, 0);
                int new_value = atoi(data);
                free(data);
                if (new_value != RESOURCE_VALUE_INT) {
                    // Update the resource value and return a success message
                    RESOURCE_VALUE_INT = new_value;
                    char *response = malloc(sizeof(char) * 1024);
                    sprintf(response, "%s: %d\n", RESOURCE_KEY_INT, RESOURCE_VALUE_INT);
                    send(sock, response, strlen(response), 0);
                    free(response);
                } else {
                    // Return an error message if the resource value is not updated
                    char *response = malloc(sizeof(char) * 1024);
                    sprintf(response, "Error: Resource value not updated\n");
                    send(sock, response, strlen(response), 0);
                    free(response);
                }
            } else if (strcmp(method, "PUT") == 0) {
                // Replace the resource with a new one for PUT requests
                char *data = malloc(sizeof(char) * 1024);
                recv(sock, data, 1024, 0);
                int new_value = atoi(data);
                free(data);
                if (new_value != RESOURCE_VALUE_INT) {
                    // Replace the resource with a new one and return a success message
                    RESOURCE_VALUE_INT = new_value;
                    char *response = malloc(sizeof(char) * 1024);
                    sprintf(response, "%s: %d\n", RESOURCE_KEY_INT, RESOURCE_VALUE_INT);
                    send(sock, response, strlen(response), 0);
                    free(response);
                } else {
                    // Return an error message if the resource is not replaced
                    char *response = malloc(sizeof(char) * 1024);
                    sprintf(response, "Error: Resource not replaced\n");
                    send(sock, response, strlen(response), 0);
                    free(response);
                }
            } else if (strcmp(method, "DELETE") == 0) {
                // Delete the resource for DELETE requests
                RESOURCE_VALUE_INT = 0;
                char *response = malloc(sizeof(char) * 1024);
                sprintf(response, "%s: %d\n", RESOURCE_KEY_INT, RESOURCE_VALUE_INT);
                send(sock, response, strlen(response), 0);
                free(response);
            } else {
                // Return an error message if the method is not supported
                char *response = malloc(sizeof(char) * 1024);
                sprintf(response, "Error: Method not supported\n");
                send(sock, response, strlen(response), 0);
                free(response);
            }
        } else {
            // Return an error message if the resource is not valid or supported
            char *response = malloc(sizeof(char) * 1024);
            sprintf(response, "Error: Resource not found\n");
            send(sock, response, strlen(response), 0);
            free(response);
        }
    } else {
        // Return an error message if the method is not supported
        char *response = malloc(sizeof(char) * 1024);
        sprintf(response, "Error: Method not supported\n");
        send(sock, response, strlen(response), 0);
        free(response);
    }
}

