// Main function to handle HTTP requests and responses
int main() {
    // Create a socket for the API endpoint
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("socket failed");
        return 1;
    }

    // Set up the API endpoint and port number
    struct sockaddr_in server_address;
    memset(&server_address, 0, sizeof(server_address));
    server_address.sin_family = AF_INET;
    server_address.sin_port = htons(80);
    server_address.sin_addr.s_addr = INADDR_ANY;

    // Bind the socket to the API endpoint and port number
    if (bind(sock, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        perror("bind failed");
        return 1;
    }

    // Listen for incoming connections on the socket
    if (listen(sock, 3) < 0) {
        perror("listen failed");
        return 1;
    }

    printf("Server listening on port %d...\n", PORT);

    while (1) {
        // Accept an incoming connection request
        int client_sock = accept(sock, NULL, NULL);
        if (client_sock < 0) {
            perror("accept failed");
            return 1;
        }

        // Handle the HTTP request and response for the client
        handle_request(client_sock);

        // Close the connection with the client
        close(client_sock);
    }

    return 0;
}']

