#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>

// Custom data structures for linked list, binary tree, and hash table
struct custom_node {
    float value;
    struct custom_node* next;
};

struct binary_tree_node {
    char* key;
    struct custom_node* left;
    struct custom_node* right;
};

struct hash_table_entry {
    char* key;
    struct custom_node* value;
};

// Memory pool for managing memory allocations
struct memory_pool {
    void* base_address;
    size_t capacity;
    size_t used_memory;
    pthread_mutex_t mutex;
};

// Function to initialize the memory pool and allocate memory for data structures
void* init_memory_pool(size_t capacity) {
    struct memory_pool* pool = malloc(sizeof(struct memory_pool));
    if (!pool) {
        return NULL;
    }
    pool->base_address = malloc(capacity);
    if (!pool->base_address) {
        free(pool);
        return NULL;
    }
    pool->capacity = capacity;
    pool->used_memory = 0;
    pthread_mutex_init(&pool->mutex, NULL);
    return pool;
}

// Function to allocate memory for a data structure within the memory pool
void* allocate_memory(struct memory_pool* pool, size_t size) {
    void* memory = malloc(size);
    if (!memory) {
        return NULL;
    }
    pthread_mutex_lock(&pool->mutex);
    if (pool->used_memory + size > pool->capacity) {
        // Reallocate the memory pool if the initial capacity is exceeded
        void* new_base_address = realloc(pool->base_address, pool->capacity * 2);
        if (!new_base_address) {
            free(memory);
            pthread_mutex_unlock(&pool->mutex);
            return NULL;
        }
        pool->base_address = new_base_address;
        pool->capacity *= 2;
    }
    memcpy(memory, pool->base_address + pool->used_memory, size);
    pool->used_memory += size;
    pthread_mutex_unlock(&pool->mutex);
    return memory;
}

// Function to deallocate memory for a data structure within the memory pool
void deallocate_memory(struct memory_pool* pool, void* memory) {
    pthread_mutex_lock(&pool->mutex);
    size_t offset = (char*)memory - (char*)pool->base_address;
    if (offset < pool->used_memory) {
