// Function to dynamically manage and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
void populateList(int numStructures) {
    // Check if the list is already allocated
    if (list != NULL) {
        // Free the existing list
        free(list);
    }

    // Allocate memory for the new list
    list = malloc(numStructures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list == NULL) {
        printf("Error: Out of memory\n");
        return;
    }

    // Initialize the list with random values for RX_UE_INFORMATION_TAG, RNTI, and CRCFLAG
    srand(time(NULL));
    for (int i = 0; i < numStructures; i++) {
        list[i].RX_UE_INFORMATION_TAG = rand() % 10000;
        list[i].RNTI = rand() % 10000;
        list[i].CRCFLAG = rand() % 2;
    }
}

// Function to check if two structures share the same RNTI value
bool isDuplicate(NFAPI_CRC_INDICATION_PDU_T *p1, NFAPI_CRC_INDICATION_PDU_T *p2) {
    return p1->RNTI == p2->RNTI;
}

// Function to add a new structure to the list and check for duplicates
void addStructure(NFAPI_CRC_INDICATION_PDU_T *newStruct) {
    // Check if the list is already allocated
    if (list == NULL) {
        populateList(1);
