    // Check if the new structure has a duplicate RNTI value
    for (int i = 0; i < numStructures; i++) {
        if (isDuplicate(newStruct, &list[i])) {
            printf("Error: Duplicate RNTI value detected\n");
            return;
        }
    }

    // Add the new structure to the list
    list = realloc(list, (numStructures + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list == NULL) {
        printf("Error: Out of memory\n");
        return;
    }
    list[numStructures] = *newStruct;
    numStructures++;
}

// Function to handle a maximum input size of N structures efficiently
void handleMaxInputSize(int maxInputSize) {
    // Check if the list is already allocated
    if (list == NULL) {
        populateList(maxInputSize);
    } else {
        // Check if the current list size exceeds the maximum input size
        if (numStructures > maxInputSize) {
            // Free the excess structures in the list
            for (int i = maxInputSize; i < numStructures; i++) {
