    if (argc != 3) {
        printf("Usage: %s <offset_array_size> <key_array_size>\n", argv[0]);
        return 1;
    }

    // Parse command-line arguments
    int offset_array_size = atoi(argv[1]);
    int key_array_size = atoi(argv[2]);

    // Allocate memory for offset and key arrays
    long *offsets = malloc(offset_array_size * sizeof(long));
    int *keys = malloc(key_array_size * sizeof(int));

    // Initialize offset and key arrays with random values within a specified range
    srand(time(NULL));
    for (int i = 0; i < offset_array_size; i++) {
        offsets[i] = rand() % 1000000;
    }
    for (int i = 0; i < key_array_size; i++) {
        keys[i] = rand() % 1000000;
    }

    // Allocate memory for record array
    Record *records = malloc(sizeof(Record) * offset_array_size);

    // Initialize record array with random values within a specified range
    srand(time(NULL));
    for (int i = 0; i < offset_array_size; i++) {
        records[i].key = rand() % 1000000;
    }

    // Free memory allocated for offset and key arrays
    free(offsets);
    free(keys);

    return 0;
}
