    int variant; // The DES variant (56, 112, or 168)
    int mode; // The encryption mode (ECB, EDE, EDE3, or CFB)
    unsigned char key[KEY_SIZE_MAX]; // The encryption key
} des_ctx;

// Define the function to initialize the encryption context
void des_init(des_ctx *ctx, int variant, int mode, const unsigned char *key) {
    ctx->variant = variant;
    ctx->mode = mode;
    memcpy(ctx->key, key, KEY_SIZE_MAX);
}

// Define the function to encrypt a block of data using DES
void des_encrypt(des_ctx *ctx, const unsigned char *input, unsigned char *output) {
    switch (ctx->variant) {
        case DES_56:
            DES_ecb_encrypt(input, output, ctx->key, ctx->mode);
            break;
        case DES_112:
            DES_ede_encrypt(input, output, ctx->key, ctx->mode);
