            break;
        case DES_112:
            DES_ede_decrypt(input, output, ctx->key, ctx->mode);
            break;
        case DES_168:
            DES_ede3_decrypt(input, output, ctx->key, ctx->mode);
            break;
    }
}

// Define the function to encrypt a block of data using CFB mode
void des_cfb_encrypt(des_ctx *ctx, const unsigned char *input, unsigned char *output) {
    switch (ctx->variant) {
        case DES_56:
            DES_ecb_encrypt(input, output, ctx->key, ECB);
            break;
        case DES_112:
            DES_ede_encrypt(input, output, ctx->key, EDE);
            break;
        case DES_168:
            DES_ede3_encrypt(input, output, ctx->key, EDE3);
            break;
    }
}

// Define the function to decrypt a block of data using CFB mode
void des_cfb_decrypt(des_ctx *ctx, const unsigned char *input, unsigned char *output) {
    switch (ctx->variant) {
        case DES_56:
            DES_ecb_decrypt(input, output, ctx->key, ECB);
            break;
        case DES_112:
            DES_ede_decrypt(input, output, ctx->key, EDE);
            break;
        case DES_168:
            DES_ede3_decrypt(input, output, ctx->key, EDE3);
            break;
    }
}
