#include <pthread.h>
#include <semaphore.h>
#include <stdlib.h>
#include <string.h>

// Define the maximum number of threads that can be used for concurrent access to the library
#define MAX_THREADS 10

// Define the semaphore for synchronizing access to the library
sem_t *sem;

// Define the mutex for protecting the shared data structures
pthread_mutex_t mutex;

// Define the shared data structure for storing the cryptographic contexts
struct crypt_context {
    AES_KEY aes_key;
    CAMELLIA_KEY camellia_key;
    MD5_CTX md5_ctx;
    SHA_CTX sha_ctx;
    RSA_KEY rsa_key;
};

// Define the shared data structure for storing the cryptographic contexts
struct crypt_context *crypt_contexts[MAX_THREADS];

// Initialize the semaphore and mutex
void init_semaphore() {
    sem = sem_open("crypt_sem", O_CREAT, 0644, MAX_THREADS);
    pthread_mutex_init(&mutex, NULL);
}

// Clean up the semaphore and mutex
void cleanup_semaphore() {
    sem_close(sem);
    pthread_mutex_destroy(&mutex);
}

// Acquire a cryptographic context for the current thread
struct crypt_context *acquire_crypt_context() {
    // Wait for the semaphore to be available
    sem_wait(sem);

    // Lock the mutex to protect the shared data structure
    pthread_mutex_lock(&mutex);

    // Find an unused cryptographic context and assign it to the current thread
    int i;
    for (i = 0; i < MAX_THREADS; i++) {
        if (crypt_contexts[i] == NULL) {
            break;
        }
    }
    if (i == MAX_THREADS) {
        // No unused cryptographic context found, create a new one
        struct crypt_context *new_ctx = malloc(sizeof(struct crypt_context));
        AES_set_encrypt_key(&new_ctx->aes_key, 128, NULL);
        CAMELLIA_set_encrypt_key(&new_ctx->camellia_key, 128, NULL);
        MD5_Init(&new_ctx->md5_ctx);
        SHA_Init(&new_ctx->sha_ctx);
        RSA_generate_key(new_ctx->rsa_key, 1024, 65537, NULL);
        crypt_contexts[i] = new_ctx;
    } else {
        // Reuse an existing cryptographic context
        struct crypt_context *old_ctx = crypt_contexts[i];
        crypt_contexts[i] = NULL;
        return old_ctx;
    }

    // Unlock the mutex and return the acquired cryptographic context
    pthread_mutex_unlock(&mutex);
    return crypt_contexts[i];
}

// Release a cryptographic context for the current thread
void release_crypt_context(struct crypt_context *ctx) {
    // Lock the mutex to protect the shared data structure
    pthread_mutex_lock(&mutex);

    // Find the index of the released cryptographic context in the shared data structure
    int i;
    for (i = 0; i < MAX_THREADS; i++) {
        if (crypt_contexts[i] == ctx) {
            break;
        }
    }
    if (i == MAX_THREADS) {
        // The released cryptographic context was not found in the shared data structure, ignore it
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Mark the released cryptographic context as available for reuse
    crypt_contexts[i] = NULL;

    // Unlock the mutex and signal the semaphore to release a waiting thread
    pthread_mutex_unlock(&mutex);
    sem_post(sem);
}

// Encrypt data using AES in CBC mode with PKCS#7 padding
void encrypt_aes_cbc(const unsigned char *plaintext, size_t plaintext_len, unsigned char *ciphertext) {
    // Acquire a cryptographic context for the current thread
    struct crypt_context *ctx = acquire_crypt_context();

    // Initialize the AES encryption context with the shared key
    AES_KEY_CTX ctx;
    AES_set_encrypt_key(&ctx, &ctx->aes_key);

    // Encrypt the plaintext using AES in CBC mode with PKCS#7 padding
    size_t ciphertext_len = 0;
    unsigned char iv[AES_BLOCK_SIZE];
    RAND_bytes(iv, AES_BLOCK_SIZE);
    AES_cbc_encrypt(plaintext, ciphertext, plaintext_len, &ctx, iv, &ciphertext_len);

    // Release the cryptographic context for the current thread
    release_crypt_context(ctx);
}

// Decrypt data using AES in CBC mode with PKCS#7 padding
void decrypt_aes_cbc(const unsigned char *ciphertext, size_t ciphertext_len, unsigned char *plaintext) {
    // Acquire a cryptographic context for the current thread
    struct crypt_context *ctx = acquire_crypt_context();

    // Initialize the AES decryption context with the shared key
    AES_KEY_CTX ctx;
    AES_set_decrypt_key(&ctx, &ctx->aes_key);

    // Decrypt the ciphertext using AES in CBC mode with PKCS#7 padding
    size_t plaintext_len = 0;
    unsigned char iv[AES_BLOCK_SIZE];
    memcpy(iv, ciphertext, AES_BLOCK_SIZE);
    AES_cbc_decrypt(ciphertext + AES_BLOCK_SIZE, plaintext, ciphertext_len - AES_BLOCK_SIZE, &ctx, iv, &plaintext_len);

    // Release the cryptographic context for the current thread
    release_crypt_context(ctx);
}

// Encrypt data using Camellia in CBC mode with PKCS#7 padding
void encrypt_camellia_cbc(const unsigned char *plaintext, size_t plaintext_len, unsigned char *ciphertext) {
    // Acquire a cryptographic context for the current thread
    struct crypt_context *ctx = acquire_crypt_context();

    // Initialize the Camellia encryption context with the shared key
    CAMELLIA_KEY_CTX ctx;
    CAMELLIA_set_encrypt_key(&ctx, &ctx->camellia_key);

    // Encrypt the plaintext using Camellia in CBC mode with PKCS#7 padding
    size_t ciphertext_len = 0;
    unsigned char iv[CAMELLIA_BLOCK_SIZE];
    RAND_bytes(iv, CAMELLIA_BLOCK_SIZE);
    CAMELLIA_cbc_encrypt(plaintext, ciphertext, plaintext_len, &ctx, iv, &ciphertext_len);

    // Release the cryptographic context for the current thread
    release_crypt_context(ctx);
}

// Decrypt data using Camellia in CBC mode with PKCS#7 padding
void decrypt_camellia_cbc(const unsigned char *ciphertext, size_t ciphertext_len, unsigned char *plaintext) {
    // Acquire a cryptographic context for the current thread
    struct crypt_context *ctx = acquire_crypt_context();

    // Initialize the Camellia decryption context with the shared key
    CAMELLIA_KEY_CTX ctx;
    CAMELLIA_set_decrypt_key(&ctx, &ctx->camellia_key);

    // Decrypt the ciphertext using Camellia in CBC mode with PKCS#7 padding
    size_t plaintext_len = 0;
    unsigned char iv[CAMELLIA_BLOCK_SIZE];
    memcpy(iv, ciphertext, CAMELLIA_BLOCK_SIZE);
    CAMELLIA_cbc_decrypt(ciphertext + CAMELLIA_BLOCK_SIZE, plaintext, ciphertext_len - CAMELLIA_BLOCK_SIZE, &ctx, iv, &plaintext_len);

    // Release the cryptographic context for the current thread
    release_crypt_context(ctx);
}

// Compute the MD5 hash of a message
void md5(const unsigned char *message, size_t message_len, unsigned char *hash) {
    // Acquire a cryptographic context for the current thread
    struct crypt_context *ctx = acquire_crypt_context();

    // Initialize the MD5 hash context with the shared key
    MD5_CTX ctx;
    MD5_Init(&ctx);

    // Compute the MD5 hash of the message using the shared context
    MD5_Update(&ctx, message, message_len);
    MD5_Final(hash, &ctx);

    // Release the cryptographic context for the current thread
    release_crypt_context(ctx);
}

// Compute the SHA hash of a message
void sha(const unsigned char *message, size_t message_len, unsigned char *hash) {
    // Acquire a cryptographic context for the current thread
    struct crypt_context *ctx = acquire_crypt_context();

    // Initialize the SHA hash context with the shared key
    SHA_CTX ctx;
    SHA_Init(&ctx);

    // Compute the SHA hash of the message using the shared context
    SHA_Update(&ctx, message, message_len);
    SHA_Final(hash, &ctx);

    // Release the cryptographic context for the current thread
    release_crypt_context(ctx);
}

// Generate a RSA key pair
void rsa_generate_key(unsigned char *modulus, size_t modulus_len, unsigned char *exponent, size_t exponent_len) {
    // Acquire a cryptographic context for the current thread
    struct crypt_context *ctx = acquire_crypt_context();

    // Initialize the RSA key generation context with the shared key
    RSA_KEY_CTX ctx;
    RSA_generate_key(modulus, modulus_len, exponent, exponent_len, &ctx);

    // Release the cryptographic context for the current thread
    release_crypt_context(ctx);
}

// Encrypt a message using RSA with SHA1
void rsa_sha1_encrypt(const unsigned char *message, size_t message_len, unsigned char *ciphertext) {
    // Acquire a cryptographic context for the current thread
    struct crypt_context *ctx = acquire_crypt_context();

    // Initialize the RSA encryption context with the shared key
    RSA_KEY_CTX ctx;
    RSA_set_encrypt_key(&ctx, &ctx->rsa_key);

    // Encrypt the message using RSA with SHA1
    size_t ciphertext_len = 0;
    unsigned char sha1[SHA_DIGEST_LENGTH];
    SHA1(message, message_len, sha1);
    RSA_encrypt(sha1, sizeof(sha1), ciphertext, &ciphertext_len, &ctx);

    // Release the cryptographic context for the current thread
    release_crypt_context(ctx);
}
