// Define a structure to represent a transport channel
typedef struct LTEPHY_TransportChannelInfo {
    int channel_id;
    float throughput;
} LTEPHY_TransportChannelInfo_t;

// Define a dynamic array to store the transport channels
LTEPHY_TransportChannelInfo_t* transport_channels = NULL;
size_t num_transport_channels = 0;

// Function to add a new transport channel to the array
void add_transport_channel(int channel_id, float throughput) {
    // Check if the array is already full
    if (num_transport_channels >= SIZE_MAX / sizeof(LTEPHY_TransportChannelInfo_t)) {
        fprintf(stderr, "Error: transport channel array is full\n");
        return;
    }

    // Allocate memory for the new transport channel
    LTEPHY_TransportChannelInfo_t* new_channel = malloc(sizeof(LTEPHY_TransportChannelInfo_t));
    if (new_channel == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for new transport channel\n");
        return;
    }

    // Initialize the new transport channel
    new_channel->channel_id = channel_id;
    new_channel->throughput = throughput;

    // Add the new transport channel to the array
    transport_channels[num_transport_channels++] = new_channel;
}

// Function to update an existing transport channel in the array
void update_transport_channel(int channel_id, float throughput) {
    // Find the index of the transport channel with the given ID
    size_t i;
    for (i = 0; i < num_transport_channels; ++i) {
        if (transport_channels[i]->channel_id == channel_id) {
            break;
        }
    }

    // Check if the transport channel was found
    if (i == num_transport_channels) {
        fprintf(stderr, "Error: transport channel with ID %d not found\n", channel_id);
        return;
    }

    // Update the throughput of the transport channel
    transport_channels[i]->throughput = throughput;
}

// Function to iterate over all transport channels in the array
void iterate_transport_channels(void (*callback)(LTEPHY_TransportChannelInfo_t*)) {
    // Iterate over all transport channels and call the callback function for each one
    size_t i;
    for (i = 0; i < num_transport_channels; ++i) {
        callback(transport_channels[i]);
    }
}

// Function to calculate the total throughput of all transport channels in the array
float calculate_total_throughput() {
    float total_throughput = 0.0f;

    // Iterate over all transport channels and add their throughputs together
    iterate_transport_channels((LTEPHY_TransportChannelInfo_t* channel) {
        total_throughput += channel->throughput;
    });

    return total_throughput;
}
