    size_t record_size = sizeof(record);
    size_t num_records = 3;
    *records = (vector<record>*)aligned_alloc(CACHE_LINE_SIZE, record_size * num_records);
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        return -3;
    }

    // Set the values of each record's integer field to a random value within a specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; ++i) {
