    int padding_option; // The current padding option (none, PKCS5, or PKCS7)
    int cipher_algorithm; // The current cipher algorithm (DES or AES)
} library_config;

// Define the library's context structure
typedef struct {
    library_config config; // The current configuration of the library
    void *context; // The OpenSSL context for the current cipher mode and key length
} library_context;

// Initialize the library with a given configuration
int library_init(library_config *config) {
    if (config == NULL) {
        return -1;
    }

    // Validate the configuration
    if (config->cipher_mode < CIPHER_MODE_ECB || config->cipher_mode > CIPHER_MODE_NULL) {
        return -2;
    }
    if (config->key_length < KEY_SIZE_56 || config->key_length > MAX_KEY_LENGTH) {
        return -3;
    }
    if (config->padding_option < PADDING_NONE || config->padding_option > PADDING_PKCS7) {
        return -4;
    }
    if (config->cipher_algorithm < CIPHER_ALGORITHM_DES || config->cipher_algorithm > CIPHER_ALGORITHM_AES) {
        return -5;
    }

    // Initialize the OpenSSL context for the current cipher mode and key length
    library_context *ctx = (library_context *)malloc(sizeof(library_context));
    ctx->config = *config;
    ctx->context = NULL;

    switch (config->cipher_mode) {
        case CIPHER_MODE_ECB:
            ctx->context = EVP_CIPHER_CTX_new();
            break;
        case CIPHER_MODE_EDE:
            ctx->context = EVP_CIPHER_CTX_new();
            break;
        case CIPHER_MODE_EDE3:
            ctx->context = EVP_CIPHER_CTX_new();
            break;
        case CIPHER_MODE_CFB:
            ctx->context = EVP_CIPHER_CTX_new();
            break;
        case CIPHER_MODE_NULL:
            ctx->context = NULL;
            break;
    }

    // Set the key length and padding option for the current cipher mode and key length
    switch (config->cipher_mode) {
        case CIPHER_MODE_ECB:
            EVP_CIPHER_CTX_set_key_length(ctx->context, config->key_length);
            EVP_CIPHER_CTX_set_padding(ctx->context, config->padding_option);
            break;
        case CIPHER_MODE_EDE:
            EVP_CIPHER_CTX_set_key_length(ctx->context, config->key_length);
