            EVP_CIPHER_CTX_set_padding(ctx->context, config->padding_option);
            break;
        case CIPHER_MODE_NULL:
            // No key length or padding option needed for NULL encryption
            break;
    }

    return 0;
}

// Encrypt a block of data using the current cipher mode and key length
int library_encrypt(library_context *ctx, unsigned char *plaintext, int plaintext_len, unsigned char *ciphertext) {
    if (ctx == NULL || plaintext == NULL || plaintext_len <= 0 || ciphertext == NULL) {
        return -1;
    }

    // Encrypt the block of data using the current cipher mode and key length
    int ciphertext_len = 0;
    switch (ctx->config.cipher_mode) {
