            break;
        case CIPHER_MODE_CFB:
            ciphertext_len = EVP_EncryptUpdate(ctx->context, ciphertext, plaintext_len);
            break;
        case CIPHER_MODE_NULL:
            // No encryption needed for NULL encryption
            ciphertext_len = plaintext_len;
            memcpy(ciphertext, plaintext, plaintext_len);
            break;
    }

    return ciphertext_len;
}

// Decrypt a block of data using the current cipher mode and key length
int library_decrypt(library_context *ctx, unsigned char *ciphertext, int ciphertext_len, unsigned char *plaintext) {
    if (ctx == NULL || ciphertext == NULL || ciphertext_len <= 0 || plaintext == NULL) {
        return -1;
    }

    // Decrypt the block of data using the current cipher mode and key length
    int plaintext_len = 0;
    switch (ctx->config.cipher_mode) {
        case CIPHER_MODE_ECB:
            plaintext_len = EVP_DecryptUpdate(ctx->context, plaintext, ciphertext_len);
            break;
        case CIPHER_MODE_EDE:
            plaintext_len = EVP_DecryptUpdate(ctx->context, plaintext, ciphertext_len);
            break;
        case CIPHER_MODE_EDE3:
            plaintext_len = EVP_DecryptUpdate(ctx->context, plaintext, ciphertext_len);
            break;
        case CIPHER_MODE_CFB:
            plaintext_len = EVP_DecryptUpdate(ctx->context, plaintext, ciphertext_len);
            break;
        case CIPHER_MODE_NULL:
            // No decryption needed for NULL encryption
            plaintext_len = ciphertext_len;
            memcpy(plaintext, ciphertext, ciphertext_len);
            break;
    }

    return plaintext_len;
}

// Free the library's context structure
void library_free(library_context *ctx) {
    if (ctx == NULL) {
        return;
    }

    // Free the OpenSSL context for the current cipher mode and key length
    switch (ctx->config.cipher_mode) {
        case CIPHER_MODE_ECB:
            EVP_CIPHER_CTX_free(ctx->context);
            break;
        case CIPHER_MODE_EDE:
            EVP_CIPHER_CTX_free(ctx->context);
            break;
        case CIPHER_MODE_EDE3:
            EVP_CIPHER_CTX_free(ctx->context);
            break;
        case CIPHER_MODE_CFB:
            EVP_CIPHER_CTX_free(ctx->context);
            break;
        case CIPHER_MODE_NULL:
            // No OpenSSL context needed for NULL encryption
            break;
    }

    free(ctx);
}
