char* generateDynamicRecordFileName(const char* path) {
    // Check if the path is valid and has the correct format
    if (!path || strchr(path, '/') == NULL || strrchr(path, '.') == NULL) {
        return NULL;
    }

    // Get the directory and file name from the path
    char* directory = strtok((char*)path, "/");
    char* fileName = strtok(NULL, "/");

    // Check if the directory exists and is a directory
    struct stat sb;
    if (stat(directory, &sb) == -1 || !S_ISDIR(sb.st_mode)) {
        return NULL;
    }

    // Get the file extension from the path
    char* extension = strrchr(path, '.');

    // Check if the file extension is supported
    if (!extension || strcmp(extension, ".txt") && strcmp(extension, ".csv")) {
        return NULL;
    }

    // Generate a random number within the specified range for the record key
    int key = rand() % 1000 + 1;

    // Create an array of records with one element
    Record* records = malloc(sizeof(Record));
    records[0].key = key;

    // Generate a SHA-256 hash of the file name
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256((unsigned char*)fileName, strlen(fileName), hash);

    // Get the current Unix timestamp
    time_t timestamp = time(NULL);

    // Generate a sequence of digits based on the first 10 alphanumeric characters of the file name
    char* sequence = malloc(sizeof(char) * 10);
    for (int i = 0; i < 10; i++) {
        sequence[i] = fileName[i];
    }

    // Create a new file name according to the specific rules
    char* newFileName = malloc(sizeof(char) * 256);
    sprintf(newFileName, "%s/%s.%08x.%ld-%s.%s", directory, fileName, hash, timestamp, sequence, extension);

    // Free the memory allocated for the records and return the new file name
    free(records);
    free(sequence);
    return newFileName;
}
