    int i, j;

    // Loop through each PUSCH symbol in the bulk and calculate its SNR using the process_pusch_symbol function
    for (i = 0; i < M; i++) {
        process_pusch_symbol(pusch_symbols[i]);
    }

    // Add the new RX PDU to the cache using the manage_rx_pdu_list function
    manage_rx_pdu_list(&rx_pdu, M);

    // Loop through each entry in the cache and process its corresponding bulk of PUSCH symbols using the process_bulk_pusch_symbols function
    for (i = 0; i < cache_size; i++) {
        process_bulk_pusch_symbols(cache[i]->rx_pdu, cache[i]->pusch_symbols_count);
