// Define data structures for the hash table and metadata
typedef struct {
    long offset;
    int key;
    record_t record;
} record_t;

typedef struct {
    int status;
    int usage;
} metadata_t;

// Define a custom hash table with efficient insertion, lookup, and deletion operations
struct hash_table {
    // Array of records in the hash table
    record_t* records;

    // Array of metadata for each record
    metadata_t* metadata;

    // Number of records in the hash table
    int num_records;

    // Size of the hash table
    int size;
};

// Define a function to dynamically manage memory within a specified memory pool
void* allocate_memory(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Error: failed to allocate memory\n");
        exit(1);
    }
    return ptr;
}

// Define a function to initialize a record with a unique random value within a given range
void init_record(record_t* record, int min, int max) {
    record->offset = (long)(min + (rand() % (max - min)));
    record->key = 0;
    record->record.value = 0;
}

// Define a function to resolve collisions by rehashing until an empty slot is found
void rehash(struct hash_table* table, int index) {
    // Rehash the record at the specified index
    record_t* record = &table->records[index];
    metadata_t* metadata = &table->metadata[index];

    // Generate a new random offset for the record
    long new_offset = (long)(min + (rand() % (max - min)));

    // Update the record and metadata with the new offset
    record->offset = new_offset;
    metadata->status = 0;
    metadata->usage = 0;
}

// Define a function to insert a record into the hash table
void insert(struct hash_table* table, int key, record_t* record) {
    // Calculate the index for the new record
    int index = key % table->size;

    // Check if the index is already occupied by another record
    while (table->metadata[index].status == 1) {
        // Rehash the record at the specified index
        rehash(table, index);

        // Update the index to the new location
        index = key % table->size;
    }

    // Insert the record into the hash table
    table->records[index] = *record;
    table->metadata[index].status = 1;
}

// Define a function to lookup a record in the hash table
void* lookup(struct hash_table* table, int key) {
    // Calculate the index for the specified key
    int index = key % table->size;

    // Check if the index is occupied by a record
    while (table->metadata[index].status == 1) {
        // Check if the record at the specified index matches the specified key
        if (table->records[index].key == key) {
            // Return the record
            return &table->records[index];
        } else {
            // Rehash the record at the specified index
            rehash(table, index);

            // Update the index to the new location
            index = key % table->size;
        }
    }

    // Return NULL if no matching record is found
    return NULL;
}

// Define a function to delete a record from the hash table
void delete(struct hash_table* table, int key) {
    // Calculate the index for the specified key
    int index = key % table->size;

    // Check if the index is occupied by a record
    while (table->metadata[index].status == 1) {
        // Check if the record at the specified index matches the specified key
        if (table->records[index].key == key) {
            // Mark the record as deleted
            table->metadata[index].status = -1;

            // Return the record
            return &table->records[index];
        } else {
            // Rehash the record at the specified index
            rehash(table, index);

            // Update the index to the new location
            index = key % table->size;
        }
    }

    // Return NULL if no matching record is found
    return NULL;
}

// Define a function to expire records older than a specified threshold
void expire(struct hash_table* table, int threshold) {
    // Iterate over the metadata array
    for (int i = 0; i < table->size; i++) {
        // Check if the record is marked as deleted or has not been accessed recently enough
        if (table->metadata[i].status == -1 || table->metadata[i].usage < threshold) {
            // Delete the record from the hash table
            delete(table, table->records[i].key);
        }
    }
}

// Define a function to query the total number of active records in the hash table
int num_active_records(struct hash_table* table) {
    // Initialize a counter for the number of active records
    int count = 0;

    // Iterate over the metadata array
    for (int i = 0; i < table->size; i++) {
        // Check if the record is marked as deleted or has not been accessed recently enough
        if (table->metadata[i].status == 1) {
            // Increment the counter for each active record
            count++;
        }
    }

    // Return the number of active records
    return count;
}

// Define a function to query the average age of the records in the hash table
double avg_age(struct hash_table* table) {
    // Initialize a counter for the total age of all records
    long total_age = 0;

    // Iterate over the metadata array
    for (int i = 0; i < table->size; i++) {
        // Check if the record is marked as deleted or has not been accessed recently enough
        if (table->metadata[i].status == 1) {
            // Increment the counter for each active record
            total_age += table->records[i].offset;
        }
    }

    // Return the average age of all records
    return (double)total_age / num_active_records(table);
}

// Define a function to query the percentage of recently accessed records in the hash table
double recent_accesses(struct hash_table* table) {
    // Initialize a counter for the number of recently accessed records
    int count = 0;

