void* initMemory(size_t size, size_t count, int randomValueRange) {
    void* ptr = allocateMemory(size, count);
    if (ptr != NULL) {
        // Initialize the offset array
        long* offsets = (long*)ptr;
        for (int i = 0; i < count; i++) {
            offsets[i] = i * size;
        }

        // Initialize the key array
        int* keys = (int*)(offsets + count);
        for (int i = 0; i < count; i++) {
            keys[i] = i;
