    // Define the function to handle concurrent access to the arrays
    void *concurrent_access(void *args) {
        int thread_id = (int)(long)args;
        while (1) {
            pthread_mutex_lock(&mutex);
            if (num_keys == 0) {
                // If there are no more keys to process, exit the thread
                break;
            }
            int key = keys[--num_keys];
            long offset = offsets[key];
            pthread_mutex_unlock(&mutex);

