// Define data structures and types
typedef uint64_t offset_t;
typedef uint32_t key_t;
typedef struct {
    offset_t offset;
    key_t key;
    int value;
} record_t;

// Define memory pool for allocations
#define MEMORY_POOL_SIZE 1024 * 1024 * 16 // 16 MB
static char memory_pool[MEMORY_POOL_SIZE];
static size_t memory_pool_used = 0;

// Define mutex for synchronizing access to shared resources
pthread_mutex_t memory_pool_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to allocate memory for an array of offset_t type and initialize it with increasing values starting from 0
offset_t* allocate_offset_array(size_t size) {
    // Check if the requested size is within the bounds of the memory pool
    if (size > MEMORY_POOL_SIZE - memory_pool_used) {
        return NULL;
    }

    // Lock the mutex to prevent concurrent access to shared resources
    pthread_mutex_lock(&memory_pool_mutex);

    // Allocate memory for the array and initialize it with increasing values starting from 0
    offset_t* arr = (offset_t*)&memory_pool[memory_pool_used];
    size_t i;
    for (i = 0; i < size; i++) {
        arr[i] = i * sizeof(offset_t);
    }

    // Update the memory pool usage counter
    memory_pool_used += size * sizeof(offset_t);

    // Unlock the mutex to allow other threads to access shared resources
    pthread_mutex_unlock(&memory_pool_mutex);

    return arr;
}

// Function to allocate memory for an array of key_t type and initialize it with sequential integers starting from 1
key_t* allocate_key_array(size_t size) {
    // Check if the requested size is within the bounds of the memory pool
    if (size > MEMORY_POOL_SIZE - memory_pool_used) {
        return NULL;
    }

    // Lock the mutex to prevent concurrent access to shared resources
    pthread_mutex_lock(&memory_pool_mutex);

    // Allocate memory for the array and initialize it with sequential integers starting from 1
    key_t* arr = (key_t*)&memory_pool[memory_pool_used];
    size_t i;
    for (i = 0; i < size; i++) {
        arr[i] = i + 1;
    }

    // Update the memory pool usage counter
    memory_pool_used += size * sizeof(key_t);

    // Unlock the mutex to allow other threads to access shared resources
    pthread_mutex_unlock(&memory_pool_mutex);

    return arr;
}

// Function to allocate memory for an array of record_t structures and initialize it with random values within a given range [min, max]
record_t* allocate_record_array(size_t size, int min, int max) {
    // Check if the requested size is within the bounds of the memory pool
    if (size > MEMORY_POOL_SIZE - memory_pool_used) {
        return NULL;
    }

    // Lock the mutex to prevent concurrent access to shared resources
    pthread_mutex_lock(&memory_pool_mutex);

    // Allocate memory for the array and initialize it with random values within a given range [min, max]
    record_t* arr = (record_t*)&memory_pool[memory_pool_used];
    size_t i;
    for (i = 0; i < size; i++) {
        arr[i].offset = rand() % (max - min + 1) + min;
        arr[i].key = rand() % (max - min + 1) + min;
        arr[i].value = rand() % (max - min + 1) + min;
    }

    // Update the memory pool usage counter
    memory_pool_used += size * sizeof(record_t);

    // Unlock the mutex to allow other threads to access shared resources
    pthread_mutex_unlock(&memory_pool_mutex);

    return arr;
}

// Function to free all previously allocated memory and exit gracefully if any allocation fails
void free_all_allocations() {
    // Lock the mutex to prevent concurrent access to shared resources
    pthread_mutex_lock(&memory_pool_mutex);

    // Free all previously allocated memory
    memory_pool_used = 0;

    // Unlock the mutex to allow other threads to access shared resources
    pthread_mutex_unlock(&memory_pool_mutex);
}

// Function to verify the integrity of the data after each operation, ensuring that no records are corrupted or duplicated
void check_data_integrity(record_t* arr, size_t size) {
    // Check if the array is NULL or empty
    if (arr == NULL || size == 0) {
        return;
    }

    // Calculate the sum of all offsets and keys in the array
    offset_t sum_offsets = 0;
    key_t sum_keys = 0;
    size_t i;
    for (i = 0; i < size; i++) {
        sum_offsets += arr[i].offset;
        sum_keys += arr[i].key;
    }

    // Calculate the checksum of all values in the array
    uint32_t checksum = 0;
    for (i = 0; i < size; i++) {
        checksum += arr[i].value;
    }

    // Verify that the sum of offsets, keys, and values matches the expected value
    if (sum_offsets != size * sizeof(offset_t) || sum_keys != size * sizeof(key_t) || checksum != size * sizeof(int)) {
        printf("Data integrity issue detected!\n");
        free_all_allocations();
        exit(1);
    }
}

