#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

// Define the structure for an NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the linked list structure for managing the NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    int size;
    int capacity;
} NFAPI_CRC_INDICATION_LIST_T;

// Define the maximum number of structures that can be stored in the linked list
#define MAX_STRUCTS 1000

// Define the synchronization mechanism for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new structure to the linked list
void add_structure(NFAPI_CRC_INDICATION_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *new_struct) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&mutex);

    // Check if the linked list is full
    if (list->size == list->capacity) {
        // If the linked list is full, dynamically resize it to accommodate more elements
        list->data = realloc(list->data, (list->capacity + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!list->data) {
            // If the memory allocation fails, log an error and return
            printf("Error: Failed to allocate memory for linked list\n");
            pthread_mutex_unlock(&mutex);
            return;
        }
        list->capacity++;
    }

    // Add the new structure to the end of the linked list
    list->data[list->size++] = *new_struct;

    // Release the lock on the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to remove a structure from the linked list
void remove_structure(NFAPI_CRC_INDICATION_LIST_T *list, int index) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&mutex);

    // Check if the index is valid
    if (index < 0 || index >= list->size) {
        // If the index is invalid, log an error and return
        printf("Error: Invalid index for removing structure from linked list\n");
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Remove the structure at the specified index from the linked list
    NFAPI_CRC_INDICATION_PDU_T *removed_struct = &list->data[index];
    for (int i = index; i < list->size - 1; i++) {
        list->data[i] = list->data[i + 1];
    }
    list->size--;

    // Release the lock on the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to serialize the linked list state to a file
void serialize(NFAPI_CRC_INDICATION_LIST_T *list, FILE *file) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&mutex);

    // Write the metadata about the structure count and timestamps for each node to the file
    fprintf(file, "Structure Count: %d\n", list->size);
    for (int i = 0; i < list->size; i++) {
        NFAPI_CRC_INDICATION_PDU_T *struct_ptr = &list->data[i];
        fprintf(file, "Structure %d: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=%d, CRCFLAG=%d\n", i, struct_ptr->RX_UE_INFORMATION_TAG, struct_ptr->RNTI, struct_ptr->CRC_INDICATION_REL8_TAG, struct_ptr->CRCFLAG);
    }

    // Release the lock on the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to deserialize the linked list state from a file
void deserialize(NFAPI_CRC_INDICATION_LIST_T *list, FILE *file) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&mutex);

    // Read the metadata about the structure count and timestamps for each node from the file
    int struct_count;
    fscanf(file, "Structure Count: %d\n", &struct_count);
    list->size = 0;
    for (int i = 0; i < struct_count; i++) {
        NFAPI_CRC_INDICATION_PDU_T new_struct;
        fscanf(file, "Structure %d: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=%d, CRCFLAG=%d\n", &new_struct.RX_UE_INFORMATION_TAG, &new_struct.RNTI, &new_struct.CRC_INDICATION_REL8_TAG, &new_struct.CRCFLAG);
        add_structure(list, &new_struct);
    }

    // Release the lock on the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to clean up unused memory in the linked list
void cleanup(NFAPI_CRC_INDICATION_LIST_T *list) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&mutex);

    // Check if the linked list is empty
    if (list->size == 0) {
        // If the linked list is empty, release all memory allocated for it
        free(list->data);
        list->data = NULL;
        list->capacity = 0;
    } else {
        // If the linked list is not empty, dynamically resize it to accommodate only the number of elements that are currently in use
        list->data = realloc(list->data, list->size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!list->data) {
            // If the memory allocation fails, log an error and return
            printf("Error: Failed to allocate memory for linked list\n");
            pthread_mutex_unlock(&mutex);
            return;
        }
        list->capacity = list->size;
    }

    // Release the lock on the mutex
    pthread_mutex_unlock(&mutex);
