struct mempool {
    size_t capacity; // total capacity of the pool
    size_t used; // amount of memory currently in use
    void* blocks[]; // array of memory blocks
};

// Function to initialize the memory pool
void init_mempool(struct mempool* pool, size_t capacity) {
    pool->capacity = capacity;
    pool->used = 0;
}

// Function to allocate memory from the memory pool
void* alloc_mempool(struct mempool* pool, size_t size) {
    if (pool->used + size > pool->capacity) {
        // Memory limit exceeded, return NULL
        return NULL;
    }
    void* block = &pool->blocks[pool->used];
    pool->used += size;
    return block;
}

// Function to free memory from the memory pool
void free_mempool(struct mempool* pool, void* block) {
    // Find the index of the block in the pool
    int i = (char*)block - (char*)pool->blocks;
    if (i < 0 || i >= pool->used) {
        // Block not found, return
        return;
    }
    // Move the last block to the freed block's position
    void* last_block = &pool->blocks[pool->used - 1];
    memcpy(block, last_block, pool->capacity - i);
    pool->used--;
}

