namespace RandomNumberService {
    class MersenneTwister {
        private:
            std::uint64_t seed;
            std::vector<std::uint64_t> state;
            std::mutex mutex;
            std::atomic<bool> initialized;

        public:
            MersenneTwister(std::uint64_t seed);
            ~MersenneTwister();

            void init();
            void reset();

            std::uint64_t generateInteger(std::uint64_t min, std::uint64_t max);
            float generateFloat(float min, float max);
