```
// RandomNumberService.cpp
#include "RandomNumberService.h"

namespace RandomNumberService {
    MersenneTwister::MersenneTwister(std::uint64_t seed) : seed(seed), initialized(false) {}

    MersenneTwister::~MersenneTwister() {
        if (initialized) {
            reset();
        }
    }

    void MersenneTwister::init() {
        // Initialize the state vector with a seed value
        state.resize(624);
        for (std::uint64_t i = 0; i < 624; ++i) {
            state[i] = seed + i;
        }

        // Perform the initialization steps
        std::uint64_t mti = 0;
        while (mti < 623) {
            std::uint64_t y = (state[mti] & 0x8000000000000000UL) | (state[mti + 1] & 0x7fffffffffffffffUL);
            state[mti] = y >> 1;
            if (y % 2 == 0) {
                state[mti + 1] = y << 1;
            } else {
                state[mti + 1] = y << 1 | 1;
            }
            mti += 2;
        }

        initialized = true;
    }

    void MersenneTwister::reset() {
        if (initialized) {
            std::uint64_t seed = this->seed;
            init();
            this->seed = seed;
        }
    }

    std::uint64_t MersenneTwister::generateInteger(std::uint64_t min, std::uint64_t max) {
        // Generate a random integer between the specified range
        if (!initialized) {
            init();
        }

        std::lock_guard<std::mutex> lock(mutex);
        std::uint64_t result = 0;
        for (int i = 0; i < 623; ++i) {
            std::uint64_t y = (state[i] & 0x8000000000000000UL) | (state[i + 1] & 0x7fffffffffffffffUL);
            state[i] = y >> 1;
            if (y % 2 == 0) {
                state[i + 1] = y << 1;
            } else {
                state[i + 1] = y << 1 | 1;
            }
            result = (result << 31) | (y & 0x7fffffff);
        }

        std::uint64_t t = state[623];
        state[623] = t >> 1;
        if (t % 2 == 0) {
            state[0] = t << 1;
        } else {
            state[0] = t << 1 | 1;
        }

        result &= 0x7fffffffffffffffUL;
        return min + (result % (max - min + 1));
    }

    float MersenneTwister::generateFloat(float min, float max) {
        // Generate a random floating-point number between the specified range
        if (!initialized) {
            init();
        }

        std::lock_guard<std::mutex> lock(mutex);
        std::uint64_t result = 0;
        for (int i = 0; i < 623; ++i) {
            std::uint64_t y = (state[i] & 0x8000000000000000UL) | (state[i + 1] & 0x7fffffffffffffffUL);
            state[i] = y >> 1;
            if (y % 2 == 0) {
                state[i + 1] = y << 1;
            } else {
                state[i + 1] = y << 1 | 1;
            }
            result = (result << 31) | (y & 0x7fffffff);
        }

        std::uint64_t t = state[623];
        state[623] = t >> 1;
        if (t % 2 == 0) {
            state[0] = t << 1;
        } else {
            state[0] = t << 1 | 1;
        }

        result &= 0x7fffffffffffffffUL;
        return min + (result / static_cast<float>(0x7fffffffffffffff)) * (max - min);
    }
}
