#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>

// Define a structure to hold the CRC indication data
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a dynamic array to hold the CRC indication data
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t size;
} NFAPI_CRC_INDICATION_ARRAY_T;

// Define a mutex to protect the shared state between threads
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Define a variable to hold the running total of CRC errors detected
static uint32_t crc_errors = 0;

// Function to dynamically manage an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_ARRAY_T* nfapi_crc_indication_array_create(size_t capacity) {
    // Allocate memory for the array and its elements
    NFAPI_CRC_INDICATION_ARRAY_T* array = malloc(sizeof(NFAPI_CRC_INDICATION_ARRAY_T));
    array->data = calloc(capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    array->capacity = capacity;
    array->size = 0;

    // Initialize the mutex for thread-safe access to the shared state
    pthread_mutex_init(&mutex, NULL);

    return array;
}

// Function to add a new CRC indication structure to the array
void nfapi_crc_indication_array_add(NFAPI_CRC_INDICATION_ARRAY_T* array, uint16_t RX_UE_INFORMATION_TAG, uint32_t RNTI) {
    // Acquire the mutex to protect the shared state between threads
    pthread_mutex_lock(&mutex);

    // Check if the array needs to be resized
    if (array->size == array->capacity) {
        // Reallocate memory for the array and its elements
        size_t new_capacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_data == NULL) {
            // Handle memory allocation failure
            pthread_mutex_unlock(&mutex);
            return;
        }
        array->data = new_data;
        array->capacity = new_capacity;
    }

    // Generate a random CRC flag for the new structure
    uint8_t CRCFLAG = rand() % 2;

    // Add the new structure to the array
    array->data[array->size].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    array->data[array->size].RNTI = RNTI;
    array->data[array->size].CRCFLAG = CRCFLAG;
    array->size++;

    // Update the running total of CRC errors detected atomically
    crc_errors += CRCFLAG;

    pthread_mutex_unlock(&mutex);
}

// Function to reset the running total of CRC errors detected
void nfapi_crc_indication_array_reset(NFAPI_CRC_INDICATION_ARRAY_T* array) {
    // Acquire the mutex to protect the shared state between threads
    pthread_mutex_lock(&mutex);

    // Reset the running total of CRC errors detected
    crc_errors = 0;

    pthread_mutex_unlock(&mutex);
}

// Function to get the current value of the running total of CRC errors detected
uint32_t nfapi_crc_indication_array_get_crc_errors(NFAPI_CRC_INDICATION_ARRAY_T* array) {
    // Acquire the mutex to protect the shared state between threads
    pthread_mutex_lock(&mutex);

    // Get the current value of the running total of CRC errors detected
    uint32_t crc_errors = array->crc_errors;

    pthread_mutex_unlock(&mutex);

    return crc_errors;
}
