// Function to resolve DNS hostname and return IP address in u_char array
u_char* dnsResolve(const char* hostname) {
    struct addrinfo hints, *res;
    int err;

    // Set up hints for DNS resolution
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    // Resolve hostname and get IP address in u_char array
    if ((err = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(err));
        return NULL;
    }

    // Return IP address in u_char array
    u_char* ip = (u_char*) malloc(sizeof(struct in_addr));
    memcpy(ip, res->ai_addr, sizeof(struct in_addr));
    freeaddrinfo(res);
    return ip;
}

