void processLine(char* line) {
    // Split line into tokens using comma delimiter
    char* tokens[3];
    int numTokens = 0;
    for (int i = 0; i < strlen(line); i++) {
        if (line[i] == ',') {
            tokens[numTokens++] = line + i + 1;
        }
    }

    // Calculate average of last two numeric fields
    int num1 = atoi(tokens[numTokens - 2]);
    int num2 = atoi(tokens[numTokens - 1]);
    int avg = (num1 + num2) / 2;

    // Append average as final field in output
    char* output = malloc(strlen(line) + 3);
    sprintf(output, "%s,%d", line, avg);
    printf("%s\n", output);
}

