// Define a dynamic array to store the NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T **array;
    int size;
} DYNAMIC_ARRAY;

// Define a mutex to protect the dynamic array from concurrent access
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new element to the dynamic array
void addElement(DYNAMIC_ARRAY *array, NFAPI_CRC_INDICATION_PDU_T *element) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Check if the array is full and needs to be resized
    if (array->size == 0 || array->size % 10 == 0) {
        int newSize = array->size + 10;
        NFAPI_CRC_INDICATION_PDU_T **newArray = realloc(array->array, sizeof(NFAPI_CRC_INDICATION_PDU_T *) * newSize);
        if (newArray == NULL) {
            // Handle memory allocation failure gracefully
            pthread_mutex_unlock(&mutex);
            return;
        }
        array->array = newArray;
        array->size = newSize;
    }

    // Add the new element to the end of the array
    array->array[array->size - 1] = element;
    array->size++;

    // Unlock the mutex and return
    pthread_mutex_unlock(&mutex);
}

