// Define a struct to represent a task
typedef struct Task {
    int priority;
    int deadline;
    char* description;
} Task;

// Define a struct to represent the dynamic collection of tasks
typedef struct TaskCollection {
    Task** tasks;
    size_t capacity;
    size_t count;
} TaskCollection;

// Initialize a new task collection with a given capacity
TaskCollection* initTaskCollection(size_t capacity) {
    TaskCollection* collection = malloc(sizeof(TaskCollection));
    if (!collection) {
        // Handle memory allocation failure gracefully
        return NULL;
    }
    collection->tasks = malloc(capacity * sizeof(Task*));
    if (!collection->tasks) {
        free(collection);
        return NULL;
    }
    collection->capacity = capacity;
    collection->count = 0;
    return collection;
}

// Add a new task to the collection
void addTask(TaskCollection* collection, int priority, int deadline, char* description) {
    if (collection->count == collection->capacity) {
        // Handle capacity overflow gracefully
        return;
    }
    Task* task = malloc(sizeof(Task));
    if (!task) {
        // Handle memory allocation failure gracefully
        return;
    }
    task->priority = priority;
    task->deadline = deadline;
    task->description = strdup(description);
    collection->tasks[collection->count++] = task;
}

// Remove a task from the collection by its index
void removeTask(TaskCollection* collection, size_t index) {
    if (index >= collection->count) {
        // Handle invalid index gracefully
        return;
    }
    Task* task = collection->tasks[index];
    free(task->description);
    free(task);
    --collection->count;
    memmove(&collection->tasks[index], &collection->tasks[index + 1], (collection->count - index) * sizeof(Task*));
}

// Update a task in the collection by its index
void updateTask(TaskCollection* collection, size_t index, int priority, int deadline, char* description) {
    if (index >= collection->count) {
        // Handle invalid index gracefully
        return;
    }
    Task* task = collection->tasks[index];
    task->priority = priority;
    task->deadline = deadline;
    free(task->description);
    task->description = strdup(description);
}

// Get the number of tasks in the collection
size_t getTaskCount(TaskCollection* collection) {
    return collection->count;
}

// Get a task from the collection by its index
Task* getTask(TaskCollection* collection, size_t index) {
    if (index >= collection->count) {
        // Handle invalid index gracefully
        return NULL;
    }
    return collection->tasks[index];
}

// Free the memory used by the task collection
void freeTaskCollection(TaskCollection* collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        Task* task = collection->tasks[i];
        free(task->description);
        free(task);
    }
    free(collection->tasks);
    free(collection);
}
