#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <math.h>

// Define the record structure
typedef struct {
    long offset;
    int key;
} Record;

// Define the collection structure
typedef struct {
    size_t capacity; // Maximum number of records in the collection
    size_t count; // Current number of records in the collection
    Record* records; // Array of record structures
} Collection;

// Initialize a new collection with the given capacity and random key range
Collection* init_collection(size_t capacity, int min_key, int max_key) {
    Collection* collection = (Collection*)malloc(sizeof(Collection));
    if (!collection) {
        fprintf(stderr, "Failed to allocate memory for the collection\n");
        return NULL;
    }

    // Initialize the capacity and count fields
    collection->capacity = capacity;
    collection->count = 0;

    // Allocate memory for the record array
    collection->records = (Record*)malloc(sizeof(Record) * capacity);
    if (!collection->records) {
        fprintf(stderr, "Failed to allocate memory for the record array\n");
        free(collection);
        return NULL;
    }

    // Initialize each record's key with a random value within the specified range
    srand(time(NULL));
    for (size_t i = 0; i < capacity; i++) {
        collection->records[i].key = rand() % (max_key - min_key + 1) + min_key;
    }

    return collection;
}

// Add a new record to the collection with the given offset and key
int add_record(Collection* collection, long offset, int key) {
    if (!collection || collection->count >= collection->capacity) {
        fprintf(stderr, "Failed to add record: collection is full\n");
        return -1;
    }

    // Allocate memory for the new record
    Record* new_record = (Record*)malloc(sizeof(Record));
    if (!new_record) {
        fprintf(stderr, "Failed to allocate memory for the new record\n");
        return -1;
    }

    // Initialize the new record's offset and key
    new_record->offset = offset;
    new_record->key = key;

    // Add the new record to the collection
    collection->records[collection->count++] = *new_record;

    return 0;
}

// Remove a record from the collection with the given index
int remove_record(Collection* collection, size_t index) {
    if (!collection || index >= collection->count) {
        fprintf(stderr, "Failed to remove record: invalid index\n");
        return -1;
    }

    // Free the memory allocated for the removed record
    free(collection->records[index]);

    // Shift all records after the removed record one position to the left
    for (size_t i = index + 1; i < collection->count; i++) {
        collection->records[i - 1] = collection->records[i];
    }

    // Decrement the count of records in the collection
    collection->count--;

    return 0;
}

// Find a record in the collection with the given key
Record* find_record(Collection* collection, int key) {
    if (!collection || collection->count == 0) {
        fprintf(stderr, "Failed to find record: collection is empty\n");
        return NULL;
    }

    // Iterate over the records in the collection and compare their keys with the given key
    for (size_t i = 0; i < collection->count; i++) {
        if (collection->records[i].key == key) {
            return &collection->records[i];
        }
    }

    // Return NULL if no record with the given key is found
    return NULL;
}

// Free the memory allocated for the collection and its records
void free_collection(Collection* collection) {
    if (!collection) {
        fprintf(stderr, "Failed to free collection: invalid pointer\n");
        return;
    }

    // Free the memory allocated for each record in the collection
    for (size_t i = 0; i < collection->count; i++) {
        free(collection->records[i]);
    }

    // Free the memory allocated for the record array
    free(collection->records);

    // Free the memory allocated for the collection structure itself
    free(collection);
}
