#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a struct to represent an event
typedef struct {
    time_t timestamp;
    char* identifier;
    int status;
} Event;

// Define a struct to represent the collection of events
typedef struct {
    Event** events; // An array of pointers to Event structures
    size_t capacity; // The current capacity of the array
    size_t count; // The number of elements in the array
    pthread_mutex_t mutex; // A mutex for thread-safe access
} EventCollection;

// Initialize an empty event collection with a given initial capacity
EventCollection* init_event_collection(size_t initial_capacity) {
    EventCollection* collection = malloc(sizeof(EventCollection));
    if (!collection) {
        return NULL;
    }
    collection->events = calloc(initial_capacity, sizeof(Event*));
    if (!collection->events) {
        free(collection);
        return NULL;
    }
    collection->capacity = initial_capacity;
    collection->count = 0;
    pthread_mutex_init(&collection->mutex, NULL);
    return collection;
}

// Add an event to the collection
void add_event(EventCollection* collection, Event* event) {
    // Acquire the mutex before modifying the array
    pthread_mutex_lock(&collection->mutex);
    if (collection->count == collection->capacity) {
        // Resize the array if it's full
        size_t new_capacity = collection->capacity * 2;
        Event** new_events = realloc(collection->events, new_capacity * sizeof(Event*));
        if (!new_events) {
            pthread_mutex_unlock(&collection->mutex);
            return;
        }
        collection->events = new_events;
        collection->capacity = new_capacity;
    }
    // Add the event to the array
    collection->events[collection->count++] = event;
    pthread_mutex_unlock(&collection->mutex);
}

// Remove an event from the collection by its index
void remove_event(EventCollection* collection, size_t index) {
    // Acquire the mutex before modifying the array
    pthread_mutex_lock(&collection->mutex);
    if (index >= collection->count) {
        pthread_mutex_unlock(&collection->mutex);
        return;
    }
    // Shift all events after the removed event to fill the gap
    for (size_t i = index + 1; i < collection->count; i++) {
        collection->events[i - 1] = collection->events[i];
    }
    // Decrement the count and free the last element
    collection->count--;
    free(collection->events[collection->count]);
    pthread_mutex_unlock(&collection->mutex);
}

// Clear all events from the collection without leaking memory
void clear_events(EventCollection* collection) {
    // Acquire the mutex before modifying the array
    pthread_mutex_lock(&collection->mutex);
    for (size_t i = 0; i < collection->count; i++) {
        free(collection->events[i]);
    }
    collection->count = 0;
    pthread_mutex_unlock(&collection->mutex);
}

// Free the memory allocated for the event collection
void free_event_collection(EventCollection* collection) {
    // Acquire the mutex before modifying the array
    pthread_mutex_lock(&collection->mutex);
    for (size_t i = 0; i < collection->count; i++) {
        free(collection->events[i]);
    }
    free(collection->events);
    pthread_mutex_unlock(&collection->mutex);
    pthread_mutex_destroy(&collection->mutex);
    free(collection);
}
```
This code defines a struct `Event` to represent an event with a timestamp, identifier, and status flag. It also defines a struct `EventCollection` to represent a collection of events, which includes an array of pointers to `Event` structures, the current capacity of the array, and a mutex for thread-safe access.

The `init_event_collection()` function initializes an empty event collection with a given initial capacity. It allocates memory for the array of pointers to `Event` structures using `calloc()`, and sets the count to 0. It also initializes the mutex using `pthread_mutex_init()`.

The `add_event()` function adds an event to the collection by first acquiring the mutex, then checking if the array is full. If it's full, it resizes the array by doubling its capacity and reallocating memory for the new array using `realloc()`. It then adds the event to the end of the array and increments the count. Finally, it releases the mutex.

The `remove_event()` function removes an event from the collection by first acquiring the mutex, then checking if the index is valid. If it's not valid, it releases the mutex and returns. Otherwise, it shifts all events after the removed event to fill the gap, decrements the count, and frees the last element using `free()`. Finally, it releases the mutex.

The `clear_events()` function clears all events from the collection without leaking memory by first acquiring the mutex, then freeing each event in the array using `free()`. It sets the count to 0 and releases the mutex.

The `free_event_collection()` function frees the memory allocated for the event collection by first acquiring the mutex, then freeing each event in the array using `free()`, then freeing the array of pointers using `free()`, then destroying the mutex using `pthread_mutex_destroy()`, and finally freeing the entire struct using `free()`."]

