void* allocator_thread(void *arg) {
    // Retry allocation up to RETRY_MAX_ATTEMPTS times if any allocation fails
    for (int i = 0; i < RETRY_MAX_ATTEMPTS; i++) {
        // Allocate memory for offsets, keys, and records
        OffsetArray *offsets = allocate_offsets(num_offsets);
        KeyArray *keys = allocate_keys(num_keys);
        RecordArray *records = allocate_records(num_records, 1, MAX_SUM_RANDOM_VALUES);

