        if (offsets == NULL || keys == NULL || records == NULL) {
            // Free previously allocated memory and reset partially allocated structures
            free_memory(offsets);
            free_memory(keys);
            free_memory(records);

            // Sleep for a short period to avoid busy-waiting
            usleep(LOCK_TIMEOUT);
        } else {
            // Allocation succeeded, exit the retry loop
            break;
        }
    }

    return NULL;
}
