  const chapters = text.split(/[^\w\s]+\d+[\w\s]+/g);

  // Iterate over each chapter
  for (const chapter of chapters) {
    // Check if the chapter is from the Old Testament
    if (!isOldTestamentChapter(chapter)) continue;

    // Split the chapter into individual verses
    const versesInChapter = chapter.split(/[\n\r]+/g);

    // Iterate over each verse in the chapter
    for (const verse of versesInChapter) {
      // Check if the verse is a duplicate or irrelevant
      if (!isRelevantVerse(verse)) continue;

