    for (int i = 0; i < array.size(); i++) {
        for (int j = i + 1; j < array.size(); j++) {
            if (array[i].NFAPI_RX_FRAME_RX_UE_INFORMATION_TAG != array[j].NFAPI_RX_FRAME_RX_UE_INFORMATION_TAG) {
                count++;
            }
        }
    }
    return count;
}

