// Define the record structure
typedef struct {
    int id;
    int offset;
    char key[10];
} Record;

// Define the cache structure
typedef struct {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} Cache;

// Initialize the cache with a given capacity
void initCache(Cache *cache, size_t capacity) {
    cache->capacity = capacity;
    cache->count = 0;
    cache->records = (Record *)malloc(sizeof(Record) * capacity);
    pthread_mutex_init(&cache->mutex, NULL);
}

// Add a record to the cache
void addToCache(Cache *cache, Record *record) {
    // Check if the cache is full
    if (cache->count == cache->capacity) {
        // Flush the cache to disk
        flushCache(cache);
    }

    // Add the record to the cache
    pthread_mutex_lock(&cache->mutex);
    cache->records[cache->count++] = *record;
    pthread_mutex_unlock(&cache->mutex);
}

// Flush the cache to disk
void flushCache(Cache *cache) {
    // Write the records to disk
    for (size_t i = 0; i < cache->count; i++) {
        Record *record = &cache->records[i];
        // Write record to disk
    }

    // Reset the count and clear the mutex
    pthread_mutex_lock(&cache->mutex);
    cache->count = 0;
    pthread_mutex_unlock(&cache->mutex);
}

// Get a record from the cache
Record *getFromCache(Cache *cache, int id) {
    // Check if the cache is empty
    if (cache->count == 0) {
        return NULL;
    }

    // Search for the record in the cache
    pthread_mutex_lock(&cache->mutex);
    for (size_t i = 0; i < cache->count; i++) {
        Record *record = &cache->records[i];
        if (record->id == id) {
            // Return the record
            pthread_mutex_unlock(&cache->mutex);
            return record;
        }
    }
    pthread_mutex_unlock(&cache->mutex);

    // If the record is not found, return NULL
    return NULL;
}

// Clean up the cache and free the memory
void cleanupCache(Cache *cache) {
    // Free the records
    for (size_t i = 0; i < cache->count; i++) {
        Record *record = &cache->records[i];
        free(record);
    }

    // Free the mutex
    pthread_mutex_destroy(&cache->mutex);
}
