const copyBytes = (dataChunks, startByte, endByte) => {
  // Validate input parameters
  if (!Array.isArray(dataChunks) || dataChunks.length === 0) {
    throw new Error("Invalid data chunks");
  }
  if (typeof startByte !== "number" || typeof endByte !== "number") {
    throw new Error("Invalid byte range");
  }
  if (startByte < 0 || endByte > dataChunks[dataChunks.length - 1].byteLength) {
    throw new Error("Out of bounds");
  }

  // Initialize output buffer and copy bytes from input chunks
  const outputBuffer = Buffer.alloc(endByte - startByte + 1);
  let currentOffset = 0;
  for (const chunk of dataChunks) {
    if (currentOffset >= endByte) break;
    const chunkStart = Math.max(startByte, currentOffset);
    const chunkEnd = Math.min(endByte, currentOffset + chunk.byteLength - 1);
    outputBuffer.set(chunk.slice(chunkStart, chunkEnd), currentOffset - startByte);
    currentOffset += chunkEnd - chunkStart + 1;
  }

  // Return copied data in a new buffer
  return outputBuffer.slice(0, endByte - startByte + 1);
};
```
This function takes an array of `dataChunks` as input, each representing a portion of the original data stream. It also takes two integer parameters `startByte` and `endByte`, specifying the range of bytes to be copied from the input chunks. The function returns a new buffer containing the copied data.

The function first validates the input parameters to ensure that they are correct and do not exceed the bounds of the input data. It then initializes an output buffer with the appropriate size, based on the range of bytes specified by `startByte` and `endByte`.

