#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a structure to represent a network interface configuration
typedef struct NetworkInterfaceConfig {
    char* ip_address;
    char* subnet_mask;
    PortConfiguration port_config;
} NetworkInterfaceConfig;

// Define a structure to represent a collection of network interface configurations
typedef struct NetworkInterfaceCollection {
    NetworkInterfaceConfig** configs;
    size_t num_configs;
    pthread_mutex_t mutex; // Mutex for thread-safe access to the collection
} NetworkInterfaceCollection;

// Define a function to initialize and manage a dynamically allocated collection of network interface configurations in a multi-threaded environment
NetworkInterfaceCollection* init_network_interface_collection() {
    NetworkInterfaceCollection* collection = malloc(sizeof(NetworkInterfaceCollection));
    if (!collection) {
        return NULL;
    }

    // Initialize the mutex for thread-safe access to the collection
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);
    pthread_mutex_init(&collection->mutex, &attr);

    // Initialize the collection with an empty array of network interface configurations
    collection->configs = malloc(sizeof(NetworkInterfaceConfig*) * 10);
    if (!collection->configs) {
        free(collection);
        return NULL;
    }
    collection->num_configs = 0;

    return collection;
}

// Define a function to add a new network interface configuration to the collection
int add_network_interface_config(NetworkInterfaceCollection* collection, const char* ip_address, const char* subnet_mask) {
    if (!collection || !ip_address || !subnet_mask) {
        return -1;
    }

    // Acquire the mutex for thread-safe access to the collection
    pthread_mutex_lock(&collection->mutex);

    // Check if the IP address is already in use
    for (size_t i = 0; i < collection->num_configs; ++i) {
        if (!strcmp(ip_address, collection->configs[i]->ip_address)) {
            pthread_mutex_unlock(&collection->mutex);
            return -1;
        }
    }

    // Create a new network interface configuration structure and add it to the collection
    NetworkInterfaceConfig* config = malloc(sizeof(NetworkInterfaceConfig));
    if (!config) {
        pthread_mutex_unlock(&collection->mutex);
        return -1;
    }
    config->ip_address = strdup(ip_address);
    config->subnet_mask = strdup(subnet_mask);
    config->port_config.bandwidth = rand() % 100 + 100; // Randomly select a bandwidth between 100 and 200 Mbps
    config->port_config.latency = rand() % 50 + 10; // Randomly select a latency between 10 and 60 ms
    collection->configs[collection->num_configs++] = config;

    pthread_mutex_unlock(&collection->mutex);

    return 0;
}

// Define a function to retrieve a network interface configuration from the collection by IP address
NetworkInterfaceConfig* get_network_interface_config(NetworkInterfaceCollection* collection, const char* ip_address) {
    if (!collection || !ip_address) {
        return NULL;
    }

    // Acquire the mutex for thread-safe access to the collection
    pthread_mutex_lock(&collection->mutex);

    // Search for the network interface configuration with the specified IP address
    for (size_t i = 0; i < collection->num_configs; ++i) {
        if (!strcmp(ip_address, collection->configs[i]->ip_address)) {
            pthread_mutex_unlock(&collection->mutex);
            return collection->configs[i];
        }
    }

    pthread_mutex_unlock(&collection->mutex);

    return NULL;
}

// Define a function to modify the bandwidth and/or latency of a network interface configuration in the collection
int update_network_interface_config(NetworkInterfaceCollection* collection, const char* ip_address, int bandwidth, int latency) {
    if (!collection || !ip_address) {
        return -1;
    }

    // Acquire the mutex for thread-safe access to the collection
    pthread_mutex_lock(&collection->mutex);

    // Search for the network interface configuration with the specified IP address
    for (size_t i = 0; i < collection->num_configs; ++i) {
        if (!strcmp(ip_address, collection->configs[i]->ip_address)) {
            // Update the bandwidth and/or latency of the network interface configuration
            if (bandwidth > 0) {
                collection->configs[i]->port_config.bandwidth = bandwidth;
            }
            if (latency > 0) {
                collection->configs[i]->port_config.latency = latency;
            }
            break;
        }
    }

    pthread_mutex_unlock(&collection->mutex);

    return 0;
}

// Define a function to release the memory allocated for the network interface collection
void free_network_interface_collection(NetworkInterfaceCollection* collection) {
    if (!collection) {
        return;
    }

    // Acquire the mutex for thread-safe access to the collection
    pthread_mutex_lock(&collection->mutex);

    // Release the memory allocated for each network interface configuration structure
    for (size_t i = 0; i < collection->num_configs; ++i) {
        free(collection->configs[i]->ip_address);
        free(collection->configs[i]->subnet_mask);
        free(collection->configs[i]);
    }

    // Release the memory allocated for the array of network interface configuration structures
    free(collection->configs);

    // Release the mutex and free the collection structure itself
    pthread_mutex_unlock(&collection->mutex);
    free(collection);
}
```
This code defines a function `init_network_interface_collection` to initialize and manage a dynamically allocated collection of network interface configurations in a multi-threaded environment. The function creates an empty array of network interface configuration structures, initializes the mutex for thread-safe access to the collection, and returns a pointer to the collection structure.

The `add_network_interface_config` function adds a new network interface configuration to the collection by creating a new structure and adding it to the end of the array. The function checks if the IP address is already in use before adding the new configuration. If the IP address is already in use, the function returns an error code.

The `get_network_interface_config` function retrieves a network interface configuration from the collection by searching for the specified IP address. The function acquires the mutex for thread-safe access to the collection before searching for the configuration and releases the mutex after the search is complete. If the IP address is not found, the function returns `NULL`.

The `update_network_interface_config` function modifies the bandwidth and/or latency of a network interface configuration in the collection by updating the corresponding fields in the structure. The function acquires the mutex for thread-safe access to the collection before searching for the configuration and updates the fields if found. If the IP address is not found, the function returns an error code.

The `free_network_interface_collection` function releases the memory allocated for the network interface collection by releasing the memory allocated for each network interface configuration structure and the array of structures. The function also releases the mutex and frees the collection structure itself.']

