const fs = require('fs');
const path = require('path');
const { promisify } = require('util');
const readFileAsync = promisify(fs.readFile);
const writeFileAsync = promisify(fs.writeFile);
const log = console.log;

async function processDirectory(directoryPath) {
  const directoryContents = await fs.promises.readdir(directoryPath, { withFileTypes: true });
  const fileTypeCounts = {};
  const totalLines = 0;
  for (const file of directoryContents) {
    if (!file.isDirectory()) {
      const filePath = path.join(directoryPath, file.name);
      try {
        const fileContent = await readFileAsync(filePath, 'utf8');
        const lines = fileContent.split('\n').length;
        totalLines += lines;
        if (lines > 0) {
          fileTypeCounts[path.extname(filePath)] = (fileTypeCounts[path.extname(filePath)] || 0) + lines;
        }
      } catch (error) {
        log(`Error reading file ${filePath}: ${error}`);
      }
    }
  }
  return { totalLines, fileTypeCounts };
}

async function main() {
  const directoryPath = 'path/to/directory';
  const startTime = Date.now();
  try {
    const summary = await processDirectory(directoryPath);
    log(`Processed ${summary.totalLines} lines in ${Date.now() - startTime} ms`);
    log(JSON.stringify(summary, null, 2));
  } catch (error) {
    log(`Error processing directory: ${error}`);
  }
}

main();
```
