```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the record structure
typedef struct {
    int value;
    long *offset;
    int *key;
} record_t;

// Define the cache structure
typedef struct {
    record_t **records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} cache_t;

// Function to initialize the cache
void init_cache(cache_t *cache) {
    // Allocate memory for the records array
    cache->records = (record_t **)malloc(sizeof(record_t *) * 10);
    if (!cache->records) {
        perror("Failed to allocate memory for records");
        exit(EXIT_FAILURE);
    }

    // Initialize the capacity and size of the cache
    cache->capacity = 10;
    cache->size = 0;

    // Initialize the mutex for protecting the cache
    pthread_mutex_init(&cache->mutex, NULL);
}

// Function to add a record to the cache
void add_record(cache_t *cache, int value, long offset, int key) {
    // Lock the cache mutex
    pthread_mutex_lock(&cache->mutex);

    // Check if the cache is full
    if (cache->size == cache->capacity) {
        // If the cache is full, double its capacity
        cache->capacity *= 2;
        cache->records = (record_t **)realloc(cache->records, sizeof(record_t *) * cache->capacity);
        if (!cache->records) {
            perror("Failed to reallocate memory for records");
            exit(EXIT_FAILURE);
        }
    }

    // Allocate memory for the new record
    cache->records[cache->size] = (record_t *)malloc(sizeof(record_t));
    if (!cache->records[cache->size]) {
        perror("Failed to allocate memory for record");
        exit(EXIT_FAILURE);
    }

    // Initialize the new record
    cache->records[cache->size]->value = value;
    cache->records[cache->size]->offset = offset;
    cache->records[cache->size]->key = key;

    // Increment the size of the cache
    cache->size++;

    // Unlock the cache mutex
    pthread_mutex_unlock(&cache->mutex);
}

// Function to retrieve a record from the cache
record_t *get_record(cache_t *cache, int key) {
    // Lock the cache mutex
    pthread_mutex_lock(&cache->mutex);

    // Search for the record in the cache
    for (size_t i = 0; i < cache->size; i++) {
        if (cache->records[i]->key == key) {
            // If the record is found, return it
            pthread_mutex_unlock(&cache->mutex);
            return cache->records[i];
        }
    }

    // If the record is not found, return NULL
    pthread_mutex_unlock(&cache->mutex);
    return NULL;
}

// Function to free the memory allocated for the cache
void free_cache(cache_t *cache) {
    // Lock the cache mutex
    pthread_mutex_lock(&cache->mutex);

    // Free the records array
    free(cache->records);

    // Reset the capacity and size of the cache
    cache->capacity = 0;
    cache->size = 0;

    // Unlock the cache mutex
    pthread_mutex_unlock(&cache->mutex);
}
```
