#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

// Function to read a list of floating-point numbers from a file
float* read_file(const char* filename) {
    // Open the file for reading
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error: File not found\n");
        return NULL;
    }

    // Get the number of lines in the file
    int num_lines = 0;
    char line[1024];
    while (fgets(line, sizeof(line), fp) != NULL) {
        num_lines++;
    }

    // Allocate memory for the array of floats
    float* arr = malloc(num_lines * sizeof(float));
    if (arr == NULL) {
        printf("Error: Memory allocation failed\n");
        fclose(fp);
        return NULL;
    }

    // Read the numbers from the file and store them in the array
    rewind(fp);
    for (int i = 0; i < num_lines; i++) {
        float val;
        if (fscanf(fp, "%f", &val) != 1) {
            printf("Error: Invalid file format\n");
            free(arr);
            fclose(fp);
            return NULL;
        }
        arr[i] = val;
    }

    // Close the file
    fclose(fp);

    // Calculate the mean and standard deviation of the numbers
    float sum = 0.0f;
    for (int i = 0; i < num_lines; i++) {
        sum += arr[i];
    }
    float mean = sum / num_lines;

    float variance = 0.0f;
    for (int i = 0; i < num_lines; i++) {
        variance += pow(arr[i] - mean, 2);
    }
    variance /= num_lines - 1;
    float stddev = sqrt(variance);

    // Print the results
    printf("Mean: %f\n", mean);
    printf("Standard deviation: %f\n", stddev);

    return arr;
}
```
