// Define the service manager class
class ServiceManager {
 public:
  // Constructor
  ServiceManager() : running_(false) {}

  // Start the service with a random delay
  void startService(int delay) {
    std::this_thread::sleep_for(std::chrono::seconds(delay));
    running_ = true;
  }

  // Stop the service and log details
  void stopService() {
    running_ = false;
    std::cout << "Service stopped" << std::endl;
  }

  // Check if the service is running
  bool isRunning() { return running_; }

 private:
  bool running_;
};

// Define the wireless frame data manager class
class WirelessFrameDataManager {
 public:
  // Constructor
  WirelessFrameDataManager(int maxSize) : maxSize_(maxSize), size_(0) {}

  // Initialize and populate an array of NFAPI_RX_FRAME_PDU_T structures with valid elements
  void initializeArray() {
    for (int i = 0; i < maxSize_; ++i) {
      NFAPI_RX_FRAME_PDU_T pdu;
      pdu.rnti = generateRandomRNTI();
      pdu.cqi = calculateCQI(pdu.rsrp);
      pdu.rsrp = generateRandomRSRP();
      array_.push_back(pdu);
    }
  }

  // Get the size of the array
  int getSize() { return size_; }

  // Add a new element to the array and handle out-of-memory scenarios gracefully
  void addElement(NFAPI_RX_FRAME_PDU_T pdu) {
    if (size_ < maxSize_) {
      array_.push_back(pdu);
      ++size_;
    } else {
      std::cout << "Out of memory, retrying with backoff strategy" << std::endl;
      std::this_thread::sleep_for(std::chrono::seconds(1));
      addElement(pdu);
    }
  }

  // Remove an element from the array and handle allocation failures gracefully
  void removeElement(int index) {
    if (index < size_) {
      array_.erase(array_.begin() + index);
      --size_;
    } else {
      std::cout << "Allocation failure, retrying with backoff strategy" << std::endl;
      std::this_thread::sleep_for(std::chrono::seconds(1));
      removeElement(index);
    }
  }

 private:
  // Generate a random RNTI value
  uint16_t generateRandomRNTI() {
    return rand() % 1000;
  }

  // Calculate the CQI value based on the RSRP value
  uint8_t calculateCQI(int16_t rsrp) {
    if (rsrp < -75) {
      return 0;
    } else if (rsrp >= -75 && rsrp < -25) {
      return 1;
    } else if (rsrp >= -25 && rsrp < 0) {
      return 2;
    } else if (rsrp >= 0 && rsrp < 30) {
      return 3;
    } else if (rsrp >= 30 && rsrp < 45) {
      return 4;
    } else if (rsrp >= 45 && rsrp < 60) {
      return 5;
    } else if (rsrp >= 60 && rsrp < 75) {
      return 6;
    } else if (rsrp >= 75) {
      return 7;
    }
  }

  // Generate a random RSRP value
  int16_t generateRandomRSRP() {
    return rand() % 100 - 50;
  }

  // The maximum size of the array
  int maxSize_;

  // The current size of the array
  int size_;

  // The array of NFAPI_RX_FRAME_PDU_T structures
  std::vector<NFAPI_RX_FRAME_PDU_T> array_;
};

// Define the external data source class
class ExternalDataSource {
 public:
  // Constructor
  ExternalDataSource() : running_(false) {}

  // Start the service with a random delay
  void startService(int delay) {
    std::this_thread::sleep_for(std::chrono::seconds(delay));
    running_ = true;
  }

  // Stop the service and log details
  void stopService() {
    running_ = false;
    std::cout << "External data source stopped" << std::endl;
  }

  // Check if the service is running
  bool isRunning() { return running_; }

 private:
  bool running_;
};

// Define the notification manager class
class NotificationManager {
 public:
  // Constructor
  NotificationManager(int maxSize) : maxSize_(maxSize), size_(0) {}

  // Add a new notification to the queue and handle allocation failures gracefully
  void addNotification(std::string notification) {
    if (size_ < maxSize_) {
      notifications_.push(notification);
      ++size_;
    } else {
      std::cout << "Allocation failure, retrying with backoff strategy" << std::endl;
      std::this_thread::sleep_for(std::chrono::seconds(1));
      addNotification(notification);
    }
  }

  // Remove a notification from the queue and handle underflow gracefully
  void removeNotification() {
    if (!notifications_.empty()) {
      notifications_.pop();
      --size_;
    } else {
      std::cout << "Underflow, retrying with backoff strategy" << std::endl;
      std::this_thread::sleep_for(std::chrono::seconds(1));
      removeNotification();
    }
  }

 private:
  // The maximum size of the queue
  int maxSize_;

  // The current size of the queue
  int size_;

  // The queue of notifications
  std::queue<std::string> notifications_;
};

// Define the main function
int main() {
  // Initialize the wireless frame data manager and external data source
  WirelessFrameDataManager wfdm(1000);
  ExternalDataSource eds;

  // Start the service manager and external data source with random delays
  ServiceManager sm;
  std::thread t1(&ServiceManager::startService, &sm, rand() % 5 + 1);
  std::thread t2(&ExternalDataSource::startService, &eds, rand() % 5 + 1);

  // Initialize the notification manager and start the service manager with a random delay
  NotificationManager nm(1000);
  std::thread t3(&NotificationManager::addNotification, &nm, "Service started");
  std::this_thread::sleep_for(std::chrono::seconds(rand() % 5 + 1));

  // Start the main loop
  while (true) {
    // Check if the service manager and external data source are running
    if (!sm.isRunning() || !eds.isRunning()) {
      break;
    }

    // Fetch and validate CRC indications from the external data source
    std::string crcIndication = eds.fetchCRCIndication();
    if (crcIndication != "") {
      nm.addNotification(crcIndication);
    }

    // Add a new element to the wireless frame data manager array and handle out-of-memory scenarios gracefully
    NFAPI_RX_FRAME_PDU_T pdu;
    pdu.rnti = generateRandomRNTI();
    pdu.cqi = calculateCQI(pdu.rsrp);
    pdu.rsrp = generateRandomRSRP();
    wfdm.addElement(pdu);

    // Remove an element from the wireless frame data manager array and handle allocation failures gracefully
    wfdm.removeElement(rand() % 1000);

    // Log detailed operation details for each state change and send notifications to the external monitoring system
    std::cout << "Wireless frame data manager size: " << wfdm.getSize() << std::endl;
    std::cout << "External data source running: " << eds.isRunning() << std::endl;
    std::cout << "Notification manager size: " << nm.size_ << std::endl;
  }

  // Stop the service manager and external data source with random delays
  t1.join();
  std::this_thread::sleep_for(std::chrono::seconds(rand() % 5 + 1));
  sm.stopService();
  t2.join();
  std::this_thread::sleep_for(std::chrono::seconds(rand() % 5 + 1));
  eds.stopService();

  // Log detailed operation details for each state change and send notifications to the external monitoring system
  std::cout << "Wireless frame data manager size: " << wfdm.getSize() << std::endl;
  std::cout << "External data source running: " << eds.isRunning() << std::endl;
  std::cout << "Notification manager size: " << nm.size_ << std::endl;

  return 0;
}
