int dns_resolution(const char* hostname, u_char* ip_address) {
    // Attempt DNS resolution for the given hostname
    struct addrinfo hints, *res;
    int ret;

    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    if ((ret = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo failed: %s\n", gai_strerror(ret));
        return -1;
    }

    // Check if the IP address is valid and belongs to the desired network segment
    struct in_addr ip_addr;
    memcpy(&ip_addr, res->ai_addr, sizeof(struct sockaddr_in));
    char* ip_str = inet_ntoa(ip_addr);
    if (!inet_pton(AF_INET, ip_str, &ip_addr)) {
        fprintf(stderr, "Invalid IP address: %s\n", ip_str);
        return -1;
    }

    // Log an appropriate message and retry the resolution up to three times before returning an error code
    int i = 0;
    while (i < 3) {
        if ((ret = getaddrinfo(hostname, NULL, &hints, &res)) == 0) {
