    char* ip_str = inet_ntoa(ip_addr);
    if (!inet_pton(AF_INET, ip_str, &ip_addr)) {
        fprintf(stderr, "Invalid IP address: %s\n", ip_str);
        return -1;
    }

    // Log an appropriate message and retry the resolution up to three times before returning an error code
    int i = 0;
    while (i < 3) {
        if ((ret = getaddrinfo(hostname, NULL, &hints, &res)) == 0) {
            break;
        } else {
            fprintf(stderr, "getaddrinfo failed: %s\n", gai_strerror(ret));
            i++;
            sleep(1); // delay for one second before retrying
        }
    }
    if (i == 3) {
        fprintf(stderr, "Failed to resolve hostname after three retries\n");
        return -1;
