};

// Define the function to generate and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
void generateAndPopulateList(list<NFAPI_CRC_INDICATION_PDU_T> &pduList) {
  // Set the random seed for generating random values
  std::random_device rd;
  std::mt19937 gen(rd());

  // Generate a list of NFAPI_CRC_INDICATION_PDU_T structures with randomly set CRCFLAG
