// Define a linked list to store the dynamic list of NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t count;
} NFAPI_CRC_INDICATION_LIST;

// Define a function to add a new structure to the linked list
void nfapi_crc_indication_list_add(NFAPI_CRC_INDICATION_LIST *list, int RX_UE_INFORMATION_TAG, int RNTI, bool CRCFLAG) {
    // Allocate memory for the new structure
    NFAPI_CRC_INDICATION_PDU_T *new_data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_data) {
        printf("Error: Failed to allocate memory for new NFAPI_CRC_INDICATION_PDU_T structure\n");
        return;
    }

    // Initialize the new structure with the given values
    new_data->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_data->RNTI = RNTI;
    new_data->CRCFLAG = CRCFLAG;

    // Add the new structure to the linked list
    if (list->count == 0) {
        list->data = new_data;
    } else {
        NFAPI_CRC_INDICATION_PDU_T *last_data = list->data + (list->count - 1);
        last_data->next = new_data;
    }

    // Increment the count of elements in the linked list
