// Define data structures for storing records and keys
typedef struct {
    int value;
} record_t;

typedef struct {
    long offset;
} key_t;

// Define a custom hash table to map keys to records
typedef struct {
    key_t *keys;
    record_t **records;
    int size;
    int capacity;
    pthread_mutex_t mutex;
} hash_table_t;

// Define a function to initialize the hash table with a specified capacity
void init_hash_table(hash_table_t *ht, int capacity) {
    ht->keys = (key_t *)malloc(sizeof(key_t) * capacity);
    ht->records = (record_t **)malloc(sizeof(record_t *) * capacity);
    ht->size = 0;
    ht->capacity = capacity;
    pthread_mutex_init(&ht->mutex, NULL);
}

// Define a function to insert a new record into the hash table
void insert(hash_table_t *ht, key_t key, record_t *record) {
    // Acquire lock on mutex
    pthread_mutex_lock(&ht->mutex);

    // Check if there is enough space in the hash table to store the new record
    if (ht->size >= ht->capacity) {
        // If not, resize the hash table by doubling its capacity
        int new_capacity = ht->capacity * 2;
        key_t *new_keys = (key_t *)realloc(ht->keys, sizeof(key_t) * new_capacity);
        record_t **new_records = (record_t **)realloc(ht->records, sizeof(record_t *) * new_capacity);
        ht->keys = new_keys;
        ht->records = new_records;
        ht->capacity = new_capacity;
    }

    // Insert the new record into the hash table
    int index = key % ht->capacity;
    while (ht->keys[index].offset != -1) {
        index = (index + 1) % ht->capacity;
    }
    ht->keys[index] = key;
    ht->records[index] = record;
    ht->size++;

    // Release lock on mutex
    pthread_mutex_unlock(&ht->mutex);
}

// Define a function to lookup a record in the hash table by its key
record_t *lookup(hash_table_t *ht, key_t key) {
    // Acquire lock on mutex
    pthread_mutex_lock(&ht->mutex);

    // Find the index of the record with the specified key in the hash table
    int index = key % ht->capacity;
    while (index != -1 && ht->keys[index].offset != key.offset) {
        index = (index + 1) % ht->capacity;
    }

    // If the record was found, return it
    if (index != -1) {
        pthread_mutex_unlock(&ht->mutex);
        return ht->records[index];
    }

    // Otherwise, return NULL
    pthread_mutex_unlock(&ht->mutex);
    return NULL;
}

// Define a function to delete a record from the hash table by its key
void delete(hash_table_t *ht, key_t key) {
    // Acquire lock on mutex
    pthread_mutex_lock(&ht->mutex);

    // Find the index of the record with the specified key in the hash table
    int index = key % ht->capacity;
    while (index != -1 && ht->keys[index].offset != key.offset) {
        index = (index + 1) % ht->capacity;
    }

    // If the record was found, delete it from the hash table
    if (index != -1) {
        ht->keys[index] = ht->keys[ht->size - 1];
        ht->records[index] = ht->records[ht->size - 1];
        ht->size--;
    }

    // Release lock on mutex
    pthread_mutex_unlock(&ht->mutex);
}

// Define a function to query the total number of records stored in the hash table
int get_num_records(hash_table_t *ht) {
    return ht->size;
}

// Define a function to iterate over all records in the hash table
void iterate(hash_table_t *ht, void (*callback)(key_t key, record_t *record)) {
    // Acquire lock on mutex
    pthread_mutex_lock(&ht->mutex);

    // Iterate over all records in the hash table and call the callback function for each one
    int index = 0;
    while (index < ht->size) {
        key_t key = ht->keys[index];
        record_t *record = ht->records[index];
        callback(key, record);
        index++;
    }

    // Release lock on mutex
    pthread_mutex_unlock(&ht->mutex);
}

// Define a function to release all allocated resources for the hash table
void free_hash_table(hash_table_t *ht) {
    // Acquire lock on mutex
    pthread_mutex_lock(&ht->mutex);

    // Release memory for keys and records
    free(ht->keys);
    free(ht->records);

    // Release mutex
    pthread_mutex_unlock(&ht->mutex);
}
