    if (input_file == NULL) {
        printf("Error: unable to open input file\n");
        return;
    }
    while (num_frames < MAX_FRAMES && !feof(input_file)) {
        NFAPI_RX_FRAME_PDU_T *frame = &frames[num_frames];
        fread(frame, sizeof(NFAPI_RX_FRAME_PDU_T), 1, input_file);
        process_frame(frame);
        num_frames++;
    }
    fclose(input_file);

    // Print maximum RSRP value and corresponding RNTI
    float max_rsrp = -INFINITY;
    int max_rnti = 0;
    for (int i = 0; i < num_frames; i++) {
        if (frames[i].rsrp > max_rsrp) {
            max_rsrp = frames[i].rsrp;
            max_rnti = frames[i].rnti;
        }
    }
    printf("Maximum RSRP value: %f\n", max_rsrp);
    printf("Corresponding RNTI: %d\n", max_rnti);
