// Define the main function to handle concurrent calls from multiple threads
int main(int argc, char *argv[]) {
    // Initialize and populate frame array
    NFAPI_RX_FRAME_PDU_T frames[MAX_FRAMES];
    int num_frames = 0;

    // Read input file and populate frame array
    FILE *input_file = fopen("input.bin", "rb");
    if (input_file == NULL) {
        printf("Error: unable to open input file\n");
        return -1;
    }
    while (num_frames < MAX_FRAMES && !feof(input_file)) {
        NFAPI_RX_FRAME_PDU_T *frame = &frames[num_frames];
