void init_data_structure(DataStructure* ds, size_t num_records, int seed) {
    // Allocate memory for the record array
    ds->records = (Record*)malloc(num_records * sizeof(Record));
    if (!ds->records) {
        printf("Error: failed to allocate memory for record array\n");
        exit(1);
    }

    // Initialize the random number generator with the seed value
    srand(seed);

    // Generate a random offset and key for each record
    for (size_t i = 0; i < num_records; i++) {
        ds->records[i].offset = rand() % 100;
        ds->records[i].key = rand() % 100;
    }

    // Set the number of records and capacity to the specified value
    ds->num_records = num_records;
    ds->capacity = num_records;
}

// Add a new record to the data structure, growing the array if necessary
void add_record(DataStructure* ds, int offset, int key) {
    // Check if the capacity of the data structure needs to be increased
    if (ds->num_records == ds->capacity) {
        // Double the capacity of the data structure
        size_t new_capacity = ds->capacity * 2;
        Record* new_records = (Record*)realloc(ds->records, new_capacity * sizeof(Record));
        if (!new_records) {
            printf("Error: failed to reallocate memory for record array\n");
            exit(1);
        }

        // Update the data structure with the new records and capacity
        ds->records = new_records;
        ds->capacity = new_capacity;
    }

    // Add the new record to the end of the array
    ds->records[ds->num_records].offset = offset;
    ds->records[ds->num_records].key = key;
    ds->num_records++;
}

// Remove a record from the data structure, shrinking the array if necessary
void remove_record(DataStructure* ds, int index) {
    // Check if the number of records needs to be decreased
    if (ds->num_records > 0 && index < ds->num_records - 1) {
        // Move the last record to the position of the removed record
        ds->records[index] = ds->records[ds->num_records - 1];
    }

    // Decrease the number of records and capacity if necessary
    ds->num_records--;
    if (ds->capacity > ds->num_records) {
        size_t new_capacity = ds->capacity / 2;
        Record* new_records = (Record*)realloc(ds->records, new_capacity * sizeof(Record));
        if (!new_records) {
            printf("Error: failed to reallocate memory for record array\n");
            exit(1);
        }

        // Update the data structure with the new records and capacity
        ds->records = new_records;
        ds->capacity = new_capacity;
    }
}

// Find a record in the data structure by its offset or key
int find_record(DataStructure* ds, int offset, int key) {
    // Iterate through the records and check if the offset or key matches
    for (size_t i = 0; i < ds->num_records; i++) {
        if (ds->records[i].offset == offset || ds->records[i].key == key) {
            return i;
        }
    }

    // Return -1 if the record is not found
    return -1;
}

// Update a record in the data structure by its index
void update_record(DataStructure* ds, int index, int offset, int key) {
    // Check if the index is valid
    if (index < 0 || index >= ds->num_records) {
        printf("Error: invalid record index\n");
        exit(1);
    }

    // Update the offset and key of the record at the specified index
