#include <string.h>
#include <assert.h>

// Custom memory pool allocator
struct MemoryPool {
    void* data;
    size_t size;
};

void initMemoryPool(struct MemoryPool* pool, size_t size) {
    pool->data = malloc(size);
    pool->size = size;
}

void freeMemoryPool(struct MemoryPool* pool) {
    free(pool->data);
}

void* allocateFromPool(struct MemoryPool* pool, size_t size) {
    if (pool->size < size) {
        return NULL;
    }
    void* data = pool->data;
    pool->data += size;
    pool->size -= size;
    return data;
}
