```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <assert.h>
#include <pthread.h>
#include <semaphore.h>

// RecordSet data structure
struct RecordSet {
    int* data;
    size_t capacity;
    size_t size;
};

void initRecordSet(struct RecordSet* set, size_t capacity) {
    set->data = malloc(capacity * sizeof(int));
    set->capacity = capacity;
    set->size = 0;
}

void freeRecordSet(struct RecordSet* set) {
    free(set->data);
}

// Producer-consumer pattern using condition variables and mutexes
void produceData(struct RecordSet* set, int start, int end) {
    pthread_mutex_lock(&set->mutex);
    while (set->size >= set->capacity) {
        sem_wait(&set->semaphore);
    }
    for (int i = start; i <= end; i++) {
        set->data[set->size++] = i;
    }
    pthread_mutex_unlock(&set->mutex);
}

void consumeData(struct RecordSet* set) {
    pthread_mutex_lock(&set->mutex);
    while (set->size == 0) {
        sem_wait(&set->semaphore);
    }
    int data = set->data[--set->size];
    pthread_mutex_unlock(&set->mutex);
}
```
