    NFAPI_RX_FRAME_RSRP_TAG;
} NFAPI_RX_FRAME_PDU_T;

void init_rx_frame(NFAPI_RX_FRAME_PDU_T *pdu, size_t n) {
    for (size_t i = 0; i < n; i++) {
        pdu[i].NFAPI_RX_FRAME_RX_UE_INFORMATION_TAG = NFAPI_RX_FRAME_RX_UE_INFORMATION_TAG_INIT;
        pdu[i].RNTI = 0;
        pdu[i].NFAPI_RX_FRAME_CQI_TAG = NFAPI_RX_FRAME_CQI_TAG_INIT;
        pdu[i].NFAPI_RX_FRAME_RSRP_TAG = NFAPI_RX_FRAME_RSRP_TAG_INIT;
    }
}

void populate_rx_frame(NFAPI_RX_FRAME_PDU_T *pdu, size_t n) {
    for (size_t i = 0; i < n; i++) {
        // Calculate CQI and RSRP values based on predefined algorithm
        pdu[i].NFAPI_RX_FRAME_CQI_TAG.cqi = calculate_cqi(pdu[i].RNTI);
        pdu[i].NFAPI_RX_FRAME_RSRP_TAG.rsrp = calculate_rsrp(pdu[i].RNTI);
    }
}

void free_rx_frame(NFAPI_RX_FRAME_PDU_T *pdu, size_t n) {
    for (size_t i = 0; i < n; i++) {
        // Free memory allocated for each structure
        free(pdu[i].NFAPI_RX_FRAME_CQI_TAG.cqi);
        free(pdu[i].NFAPI_RX_FRAME_RSRP_TAG.rsrp);
    }
}

void handle_out_of_memory(size_t n) {
    // Log error and fallback strategy
    printf("Out of memory! Reducing frame size to accommodate available memory.\n");
    for (size_t i = 0; i < n; i++) {
        pdu[i].NFAPI_RX_FRAME_CQI_TAG.cqi = NULL;
        pdu[i].NFAPI_RX_FRAME_RSRP_TAG.rsrp = NULL;
    }
}

void process_rx_frame(NFAPI_RX_FRAME_PDU_T *pdu, size_t n) {
    // Initialize and populate the array of NFAPI_RX_FRAME_PDU_T structures
    init_rx_frame(pdu, n);
    populate_rx_frame(pdu, n);

    // Free memory allocated for each structure if necessary
    free_rx_frame(pdu, n);
}
