static int thread_count = 0;

void generateNfademo(int num_crcs) {
    // Initialize the NFAPI interface
    nfapi_init();

    // Create a list of NFAPI CRC indications
    NFAPI_CRC_INDICATION_PDU_T *crc_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_crcs * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Populate the list with random data
    for (int i = 0; i < num_crcs; i++) {
        crc_list[i].rx_ue_information.tag = RX_UE_INFORMATION_TAG;
        crc_list[i].rx_ue_information.rnti = rand() % 10000;
        crc_list[i].crc_indication_rel8.tag = CRC_INDICATION_REL8_TAG;
        crc_list[i].crc_indication_rel8.crcFlag = rand() % 2;
    }

    // Generate the NFAPI CRC indications asynchronously using a thread pool
    for (int i = 0; i < num_crcs; i++) {
        pthread_create(&thread_pool[i], NULL, nfapi_generate_crc_indication, &crc_list[i]);
    }
}

// C# function: handlePageUpdate()
using System;
using System.Collections.Generic;
using System.Linq;
using System.Web;
using System.Data;
using System.Data.SqlClient;
using System.Threading.Tasks;

public class PageHandler {
    public async Task<string> handlePageUpdate(int pageSectionId, int elementId, string htmlContent) {
        // Validate input data for correctness and consistency
        if (pageSectionId < 0 || elementId < 0 || String.IsNullOrEmpty(htmlContent)) {
            return "Invalid input data";
        }

        // Update the HTML content using a service class
        var service = new PageService();
        bool success = await service.updatePageElementAsync(pageSectionId, elementId, htmlContent);

        if (success) {
            return "Page updated successfully";
        } else {
            return "Error updating page";
        }
    }
}

// Service class: PageService
using System;
using System.Collections.Generic;
using System.Linq;
using System.Web;
using System.Data;
using System.Data.SqlClient;
using System.Threading.Tasks;

public class PageService {
    public async Task<bool> updatePageElementAsync(int pageSectionId, int elementId, string htmlContent) {
        // Connect to the database and execute an SQL query
        using (var connection = new SqlConnection("Server=myServerAddress;Database=myDataBase;User Id=myUsername;Password=myPassword;")) {
            await connection.OpenAsync();
            var command = new SqlCommand("UPDATE PageElements SET HtmlContent = @HtmlContent WHERE PageSectionId = @PageSectionId AND ElementId = @ElementId", connection);
            command.Parameters.AddWithValue("@HtmlContent", htmlContent);
            command.Parameters.AddWithValue("@PageSectionId", pageSectionId);
            command.Parameters.AddWithValue("@ElementId", elementId);
            int rowsAffected = await command.ExecuteNonQueryAsync();

            // Check if the update was successful
            return rowsAffected > 0;
        }
    }
}']

