typedef struct {
    uint32_t *RNTIs;
    size_t count;
    pthread_mutex_t mutex;
} RNTI_DATA_STRUCTURE;

// Function to dynamically generate and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T *generate_crc_indication_pdu(size_t num_elements) {
    // Allocate memory for the list of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T *list = malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list == NULL) {
        printf("Error: Failed to allocate memory for the list of NFAPI_CRC_INDICATION_PDU_T structures\n");
        return NULL;
    }

    // Initialize the RNTI data structure
    RNTI_DATA_STRUCTURE *rnti_data = malloc(sizeof(RNTI_DATA_STRUCTURE));
    if (rnti_data == NULL) {
        printf("Error: Failed to allocate memory for the RNTI data structure\n");
        free(list);
        return NULL;
    }
    rnti_data->RNTIs = malloc(num_elements * sizeof(uint32_t));
    if (rnti_data->RNTIs == NULL) {
        printf("Error: Failed to allocate memory for the RNTI data structure\n");
        free(list);
        free(rnti_data);
        return NULL;
    }
    rnti_data->count = 0;
    pthread_mutex_init(&rnti_data->mutex, NULL);

    // Populate the list of NFAPI_CRC_INDICATION_PDU_T structures with random values
    for (size_t i = 0; i < num_elements; i++) {
        // Generate a random RNTI value
        uint32_t rnti = rand() % 1000000000 + 1;

        // Check if the RNTI value is already in the list
        bool duplicate = false;
        pthread_mutex_lock(&rnti_data->mutex);
        for (size_t j = 0; j < rnti_data->count; j++) {
            if (rnti == rnti_data->RNTIs[j]) {
                duplicate = true;
                break;
            }
        }
        pthread_mutex_unlock(&rnti_data->mutex);

        // If the RNTI value is a duplicate, generate a new one and try again
        if (duplicate) {
            i--;
            continue;
        }

        // Add the RNTI value to the list of RNTIs
        pthread_mutex_lock(&rnti_data->mutex);
        rnti_data->RNTIs[rnti_data->count++] = rnti;
        pthread_mutex_unlock(&rnti_data->mutex);

        // Populate the NFAPI_CRC_INDICATION_PDU_T structure with the random values
        list[i].RX_UE_INFORMATION_TAG = rand() % 1000 + 1;
        list[i].RNTI = rnti;
        list[i].CRC_INDICATION_REL8_TAG = rand() % 1000 + 1;
        list[i].CRCFLAG = (rand() % 2 == 0) ? true : false;
    }

    // Free the RNTI data structure if it is empty
    pthread_mutex_lock(&rnti_data->mutex);
    if (rnti_data->count == 0) {
        free(rnti_data->RNTIs);
        rnti_data->RNTIs = NULL;
        pthread_mutex_unlock(&rnti_data->mutex);
        free(rnti_data);
    } else {
        pthread_mutex_unlock(&rnti_data->mutex);
    }

    return list;
}

// Function to add a new RNTI value to the list of NFAPI_CRC_INDICATION_PDU_T structures
bool add_new_rnti(NFAPI_CRC_INDICATION_PDU_T *list, size_t num_elements, uint32_t rnti) {
    // Check if the RNTI value is already in the list
    bool duplicate = false;
    pthread_mutex_lock(&rnti_data->mutex);
    for (size_t i = 0; i < num_elements; i++) {
        if (rnti == list[i].RNTI) {
            duplicate = true;
            break;
        }
    }
    pthread_mutex_unlock(&rnti_data->mutex);

    // If the RNTI value is a duplicate, return false
    if (duplicate) {
        return false;
    }

    // Add the RNTI value to the list of RNTIs
    pthread_mutex_lock(&rnti_data->mutex);
    rnti_data->RNTIs[rnti_data->count++] = rnti;
    pthread_mutex_unlock(&rnti_data->mutex);

    return true;
}

// Function to remove an RNTI value from the list of NFAPI_CRC_INDICATION_PDU_T structures
bool remove_rnti(NFAPI_CRC_INDICATION_PDU_T *list, size_t num_elements, uint32_t rnti) {
    // Check if the RNTI value is in the list
    bool found = false;
    pthread_mutex_lock(&rnti_data->mutex);
    for (size_t i = 0; i < num_elements; i++) {
        if (rnti == list[i].RNTI) {
            found = true;
            break;
        }
    }
    pthread_mutex_unlock(&rnti_data->mutex);

    // If the RNTI value is not in the list, return false
    if (!found) {
        return false;
    }

    // Remove the RNTI value from the list of RNTIs
    pthread_mutex_lock(&rnti_data->mutex);
    for (size_t i = 0; i < rnti_data->count; i++) {
        if (rnti == rnti_data->RNTIs[i]) {
            rnti_data->RNTIs[i] = rnti_data->RNTIs[--rnti_data->count];
            break;
        }
    }
    pthread_mutex_unlock(&rnti_data->mutex);

    return true;
}
