```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_FRAMES 100
#define BUFFER_SIZE 1024 * 1024 * 10  // 10 MB buffer size

typedef struct {
    int rnti;
    int cqi;
    int rsrp;
} NFAPI_RX_FRAME_TAG;

typedef struct {
    NFAPI_RX_FRAME_TAG rx_ue_information;
    int cqi_tag;
    int rsrp_tag;
} NFAPI_RX_FRAME_PDU_T;

void initializeFrames(NFAPI_RX_FRAME_PDU_T *frames, int num_frames, FILE *data_source) {
    if (!frames || num_frames <= 0 || num_frames > MAX_FRAMES || !data_source) {
        fprintf(stderr, "Invalid input parameters\n");
        return;
    }

    int total_memory = sizeof(NFAPI_RX_FRAME_PDU_T) * num_frames;
    char *buffer = malloc(BUFFER_SIZE);
    if (!buffer) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    NFAPI_RX_FRAME_PDU_T *current_frame = (NFAPI_RX_FRAME_PDU_T *)buffer;
    for (int i = 0; i < num_frames; ++i) {
        if (fread(&current_frame->rx_ue_information, sizeof(NFAPI_RX_FRAME_TAG), 1, data_source) != 1) {
            fprintf(stderr, "Failed to read data from source\n");
            free(buffer);
            return;
        }
        current_frame->cqi_tag = calculateCQI(i);
        current_frame->rsrp_tag = calculateRSRP(i);
        current_frame++;
    }

    free(buffer);
}

int calculateCQI(int frame_index) {
    return frame_index % 16;
}

int calculateRSRP(int frame_index) {
    return frame_index * 2 - 100;
}

int findMaxRsrp(const NFAPI_RX_FRAME_PDU_T *frames, int num_frames) {
    if (!frames || num_frames <= 0) {
        return -1;
    }

    int max_rsrp = frames->rx_ue_information.rsrp;
    for (int i = 1; i < num_frames; ++i) {
        if (frames[i].rx_ue_information.rsrp > max_rsrp) {
            max_rsrp = frames[i].rx_ue_information.rsrp;
        }
    }

    return max_rsrp;
}
