#include <json-c/json.h>

// Define the structure for the resource bundle
typedef struct {
    char *name;
    int age;
} ResourceBundle;

// Function to load a resource bundle from a file path
int loadResourceBundle(const char *file_path) {
    // Open the file and check for errors
    int fd = open(file_path, O_RDONLY);
    if (fd == -1) {
        perror("Error opening resource bundle file");
        return errno;
    }

    // Read the contents of the file into a buffer
    char *buffer = malloc(sizeof(char) * 4096);
    ssize_t bytes_read = read(fd, buffer, 4096);
    if (bytes_read == -1) {
        perror("Error reading resource bundle file");
        return errno;
    }

    // Parse the JSON data in the buffer using json-c library
    json_object *root = json_tokener_parse(buffer);
    if (!root) {
        fprintf(stderr, "Error parsing JSON data\n");
        return -1;
    }

    // Get the number of items in the bundle
    int num_items = json_object_array_length(root);

    // Allocate memory for the resource bundle and populate it with the parsed data
    ResourceBundle *bundle = malloc(sizeof(ResourceBundle) * num_items);
    for (int i = 0; i < num_items; i++) {
        json_object *item = json_object_array_get_idx(root, i);
        bundle[i].name = json_object_get_string(json_object_object_get(item, "name"));
        bundle[i].age = json_object_get_int(json_object_object_get(item, "age"));
    }

    // Close the file and return the number of items in the bundle
    close(fd);
    return num_items;
}
```
This function takes a file path as an argument and loads the resource bundle from that file. It uses the `json-c` library to parse the JSON data in the file, and it allocates memory for the resource bundle based on the number of items in the bundle. The function returns the number of items in the bundle if successful, or a negative value if an error occurs.

Here is an example usage of the `loadResourceBundle` function:
```c
