    // Load the resource bundle from a file
    int num_items = loadResourceBundle("resource_bundle.json");
    if (num_items < 0) {
        fprintf(stderr, "Error loading resource bundle\n");
        return -1;
    }

    // Print the number of items in the bundle
    printf("Number of items in the bundle: %d\n", num_items);

    // Clean up memory
    free(bundle);
    close(fd);
    return 0;
}
```
