void addLTEPHY_TransportChannel(LTEPHY_TransportChannelList_t* list, int channel_id, float throughput) {
    // Check if the list is full
    if (list->size == list->capacity) {
        // Reallocate memory for the list container to increase its capacity by 10%
        size_t new_capacity = list->capacity + (list->capacity / 10);
        LTEPHY_TransportChannelInfo_t* new_data = (LTEPHY_TransportChannelInfo_t*)realloc(list->data, sizeof(LTEPHY_TransportChannelInfo_t) * new_capacity);
