        // Update the list container with the new memory and capacity
        list->data = new_data;
        list->capacity = new_capacity;
    }
    // Add a new entry to the list
    list->data[list->size].channel_id = channel_id;
    list->data[list->size].throughput = throughput;
    list->size++;
}

