// Add a DataPacket to the array, allocating memory for the payload content if necessary
void addDataPacket(uint32_t SourceIP, uint32_t DestinationIP, size_t PayloadLength, char* PayloadContent) {
    // Check if the array needs to be resized
    if (data_packets_count == data_packets_capacity) {
        data_packets_capacity *= 2;
        data_packets = (DataPacket*)realloc(data_packets, sizeof(DataPacket) * data_packets_capacity);
    }

    // Add the DataPacket to the array
    data_packets[data_packets_count].SourceIP = SourceIP;
    data_packets[data_packets_count].DestinationIP = DestinationIP;
    data_packets[data_packets_count].PayloadLength = PayloadLength;
    if (PayloadContent != NULL) {
        data_packets[data_packets_count].PayloadContent = (char*)malloc(sizeof(char) * PayloadLength);
        memcpy(data_packets[data_packets_count].PayloadContent, PayloadContent, PayloadLength);
    } else {
        data_packets[data_packets_count].PayloadContent = NULL;
    }
    data_packets_count++;
}

// Fetch IP geolocation data for the given DataPacket and add it to the cache
void fetchGeoLocationDataForDataPacket(DataPacket* packet) {
    // Check if the entry is already in the cache
    if (isInCache(packet->SourceIP)) {
        return;
    }

    // Fetch the geolocation data from the API
    char* GeoLocationData = NULL;
    int status_code = fetchGeoLocationDataFromAPI(packet->SourceIP, &GeoLocationData);

    // Check if the API request was successful
    if (status_code == 200) {
        addToCache(packet->SourceIP, GeoLocationData);
    } else {
        free(GeoLocationData);
    }
}

// Fetch IP geolocation data for the given DataPacket using a thread-safe mechanism
void* fetchGeoLocationDataForDataPacketThreadSafe(void* packet) {
    DataPacket* packet = (DataPacket*)packet;
    pthread_mutex_lock(&cache_mutex);
    if (!isInCache(packet->SourceIP)) {
        fetchGeoLocationDataForDataPacket(packet);
    }
    pthread_mutex_unlock(&cache_mutex);
}

// Initialize the cache and array of DataPackets with the given capacity
void init(size_t capacity) {
    initCache();
    initDataPackets(capacity);
}

// Add a DataPacket to the array, allocating memory for the payload content if necessary
void add(uint32_t SourceIP, uint32_t DestinationIP, size_t PayloadLength, char* PayloadContent) {
    // Check if the API request is valid
    if (SourceIP == 0 || DestinationIP == 0 || PayloadLength == 0) {
        return;
    }

    // Fetch IP geolocation data for the given DataPacket using a thread-safe mechanism
    pthread_t thread;
    pthread_create(&thread, NULL, fetchGeoLocationDataForDataPacketThreadSafe, packet);

    // Add the DataPacket to the array
    addDataPacket(SourceIP, DestinationIP, PayloadLength, PayloadContent);
}

// Fetch IP geolocation data for all DataPackets in the array using a thread-safe mechanism
void fetchGeoLocationDataForAllDataPacketsThreadSafe() {
    pthread_t threads[MAX_CONCURRENT_REQUESTS];
    for (int i = 0; i < data_packets_count; i++) {
        DataPacket* packet = &data_packets[i];
        if (!isInCache(packet->SourceIP)) {
            pthread_create(&threads[i], NULL, fetchGeoLocationDataForDataPacketThreadSafe, packet);
        }
    }
}

// Fetch IP geolocation data for all DataPackets in the array
void fetchGeoLocationDataForAllDataPackets() {
    // Check if the API request is valid
    if (data_packets_count == 0) {
        return;
    }

    // Fetch IP geolocation data for all DataPackets in the array using a thread-safe mechanism
    fetchGeoLocationDataForAllDataPacketsThreadSafe();
}

// Free memory allocated for the payload content of each DataPacket in the array
void freeDataPackets() {
    for (int i = 0; i < data_packets_count; i++) {
        if (data_packets[i].PayloadContent != NULL) {
            free(data_packets[i].PayloadContent);
        }
    }
}

// Free memory allocated for the cache and the array of DataPackets
void free() {
    freeDataPackets();
    free(cache);
    free(data_packets);
}
