// Define the array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T *crc_indication_array = NULL;
size_t crc_indication_array_size = 0;
pthread_mutex_t crc_indication_array_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new element to the array
void add_element(NFAPI_CRC_INDICATION_PDU_T *new_element) {
    pthread_mutex_lock(&crc_indication_array_lock);
    if (crc_indication_array == NULL) {
        crc_indication_array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        memcpy(crc_indication_array, new_element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    } else {
        crc_indication_array = realloc(crc_indication_array, (crc_indication_array_size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        memcpy(&crc_indication_array[crc_indication_array_size], new_element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    crc_indication_array_size++;
    pthread_mutex_unlock(&crc_indication_array_lock);
}

// Function to remove an element from the array based on RNTI value
void remove_element(uint16_t rnti) {
    pthread_mutex_lock(&crc_indication_array_lock);
    for (size_t i = 0; i < crc_indication_array_size; i++) {
        if (crc_indication_array[i].RNTI == rnti) {
            memmove(&crc_indication_array[i], &crc_indication_array[i + 1], (crc_indication_array_size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            crc_indication_array_size--;
            break;
        }
    }
    pthread_mutex_unlock(&crc_indication_array_lock);
}

// Function to update an element in the array based on RNTI value
void update_element(uint16_t rnti, uint8_t crcflag) {
    pthread_mutex_lock(&crc_indication_array_lock);
    for (size_t i = 0; i < crc_indication_array_size; i++) {
        if (crc_indication_array[i].RNTI == rnti) {
            crc_indication_array[i].CRCFLAG = crcflag;
            break;
        }
    }
    pthread_mutex_unlock(&crc_indication_array_lock);
}

// Function to iterate over the array in forward order
void iterate_forward(void (*callback)(NFAPI_CRC_INDICATION_PDU_T *)) {
    pthread_mutex_lock(&crc_indication_array_lock);
    for (size_t i = 0; i < crc_indication_array_size; i++) {
        callback(&crc_indication_array[i]);
    }
    pthread_mutex_unlock(&crc_indication_array_lock);
}

// Function to iterate over the array in reverse order
void iterate_reverse(void (*callback)(NFAPI_CRC_INDICATION_PDU_T *)) {
    pthread_mutex_lock(&crc_indication_array_lock);
    for (size_t i = crc_indication_array_size; i > 0; i--) {
        callback(&crc_indication_array[i - 1]);
    }
    pthread_mutex_unlock(&crc_indication_array_lock);
}
