// Function to generate a unique file name with enhanced metadata
void generateUniqueNficFile(char* original_file_path, char* new_extension) {
  // Validate the input parameters
  if (original_file_path == NULL || new_extension == NULL) {
    printf("Invalid input parameters\n");
    return;
  }

  // Get the directory and file name from the original file path
  char* directory = strtok(original_file_path, "/");
  char* filename = strrchr(directory, '/') + 1;

  // Generate a SHA-256 hash of the original file name
  unsigned char hash[SHA256_DIGEST_LENGTH];
  SHA256((unsigned char*)filename, strlen(filename), hash);

  // Get the current Unix timestamp
  time_t timestamp = time(NULL);

  // Derive a sequence of digits from the first 10 alphanumeric characters of the original file name
  char* sequence = filename + 10;
  while (*sequence != '\0' && !isalnum(*sequence)) {
    sequence++;
  }

  // Generate the new file name with enhanced metadata
  char* new_filename = malloc(strlen(directory) + strlen(filename) + SHA256_DIGEST_LENGTH + 10 + strlen(new_extension));
  sprintf(new_filename, "%s/%s.%s-%s.%s", directory, filename, hash, sequence, new_extension);

  // Check if the new file name is unique within the specified directory
  struct stat st;
  while (stat(new_filename, &st) == 0) {
    // If not unique, generate a new sequence of digits and try again
    char* new_sequence = malloc(10);
    sprintf(new_sequence, "%d", rand() % 100000000);
    free(new_filename);
    new_filename = malloc(strlen(directory) + strlen(filename) + SHA256_DIGEST_LENGTH + 10 + strlen(new_extension));
    sprintf(new_filename, "%s/%s.%s-%s.%s", directory, filename, hash, new_sequence, new_extension);
    free(new_sequence);
  }

  // Create the new file with the generated name and extension
  FILE* fp = fopen(new_filename, "wb");
  if (fp == NULL) {
    printf("Failed to create new file\n");
    return;
  }
  fclose(fp);

  // Free memory allocated for the new file name and extension
  free(new_filename);
}
```
