    void startService() {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(0, 10);
        int delay = dis(gen);
        std::this_thread::sleep_for(std::chrono::seconds(delay));
        std::cout << "Starting processing service with a random delay of " << delay << " seconds" << std::endl;
    }

    // Stop the processing service with a random delay
    void stopService() {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(0, 10);
        int delay = dis(gen);
        std::this_thread::sleep_for(std::chrono::seconds(delay));
        std::cout << "Stopping processing service with a random delay of " << delay << " seconds" << std::endl;
    }
};

// Define a persistent queue to buffer notifications and retry sending them in case of transient failures
class NotificationQueue {
public:
    // Add a notification to the queue
    void addNotification(const std::string& notification) {
        std::lock_guard<std::mutex> lock(m_mutex);
        m_queue.push_back(notification);
    }

    // Retrieve and remove the oldest notification from the queue
    std::string getNotification() {
        std::lock_guard<std::mutex> lock(m_mutex);
        if (m_queue.empty()) {
            return "";
        } else {
            std::string notification = m_queue.front();
            m_queue.pop_front();
            return notification;
        }
    }

private:
    // Mutex to protect the queue from concurrent access
    std::mutex m_mutex;

    // Queue of notifications
    std::deque<std::string> m_queue;
};

