// Define the function to dynamically allocate memory for a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* allocate_crc_indication_pdu_list(size_t n) {
    // Check if the input is valid
    if (n == 0) {
        return NULL;
    }

    // Calculate the size of the memory block to be allocated
    size_t size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * n;

    // Allocate the memory block
    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(size);
    if (list == NULL) {
        fprintf(stderr, "Failed to allocate memory for the CRC indication PDU list\n");
        return NULL;
    }

    // Initialize the elements of the list
    for (size_t i = 0; i < n; i++) {
        list[i].rx_ue_information_tag = 0x1234;
        list[i].rnti = 0x5678;
        list[i].crc_indication_rel8_tag = 0x9ABC;
        list[i].crcflag = true;
    }

    // Return a pointer to the first element of the list
    return list;
}

// Define the function to free the memory allocated for the list of NFAPI_CRC_INDICATION_PDU_T structures
void free_crc_indication_pdu_list(NFAPI_CRC_INDICATION_PDU_T* list) {
    // Check if the input is valid
    if (list == NULL) {
        return;
    }

    // Free the memory block allocated for the list
    free(list);
}
