#include <stdlib.h>
#include <pthread.h>
#include <stdio.h>

// Define a structure to represent an NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a dynamic array to store the structures
NFAPI_CRC_INDICATION_PDU_T *array = NULL;
size_t array_size = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to allocate memory for the dynamic array
void allocate_memory(size_t size) {
    pthread_mutex_lock(&mutex);
    if (array == NULL || array_size < size) {
        free(array);
        array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * size);
        array_size = size;
    }
    pthread_mutex_unlock(&mutex);
}

// Function to deallocate memory for the dynamic array
void deallocate_memory() {
    pthread_mutex_lock(&mutex);
    free(array);
    array = NULL;
    array_size = 0;
    pthread_mutex_unlock(&mutex);
}

// Function to add a new structure to the dynamic array
void add_structure(NFAPI_CRC_INDICATION_PDU_T *structure) {
    pthread_mutex_lock(&mutex);
    if (array == NULL || array_size >= MAX_ARRAY_SIZE) {
        allocate_memory(array_size + 1);
    }
    array[array_size++] = *structure;
    pthread_mutex_unlock(&mutex);
}

// Function to iterate over the structures in the dynamic array
void iterate_structures() {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < array_size; i++) {
        // Process each structure here
    }
    pthread_mutex_unlock(&mutex);
}

// Function to clear the entire dynamic array
void clear_array() {
    pthread_mutex_lock(&mutex);
    deallocate_memory();
    pthread_mutex_unlock(&mutex);
}

// Function to prevent duplicate RNTI values from being added
bool is_duplicate(RNTI rnti) {
    bool is_duplicate = false;
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < array_size; i++) {
        if (array[i].rnti == rnti) {
            is_duplicate = true;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
    return is_duplicate;
}

// Function to update the dynamic array with new data from an external source
void update_array(NFAPI_CRC_INDICATION_PDU_T *new_data) {
    pthread_mutex_lock(&mutex);
    if (!is_duplicate(new_data->rnti)) {
        add_structure(new_data);
    }
    pthread_mutex_unlock(&mutex);
}

// Function to expose statistics for monitoring and debugging purposes
void get_statistics() {
    pthread_mutex_lock(&mutex);
    printf("Number of unique RNTIs: %d\n", array_size);
    printf("Total number of structures in the array: %d\n", array_size);
    printf("Average duration of operations like insertion and iteration: %.2f ms\n", average_duration);
    pthread_mutex_unlock(&mutex);
}
