class UserSession {
public:
    // Constructor and destructor
    UserSession(int uid, std::string username) : uid_(uid), username_(username) {}
    ~UserSession() = default;

    // Getters and setters for UID and username
    int getUID() const { return uid_; }
    void setUID(int uid) { uid_ = uid; }
    std::string getUsername() const { return username_; }
    void setUsername(std::string username) { username_ = username; }

private:
    int uid_;
    std::string username_;
};

class SessionManager {
public:
    // Constructor and destructor
    SessionManager() : sessions_(), mutex_(), cv_() {}
    ~SessionManager() = default;

    // Add a new session to the collection
    void addSession(int uid, std::string username) {
        std::lock_guard<std::mutex> lock(mutex_);
        sessions_.push_back(UserSession(uid, username));
    }

    // Remove a session from the collection
    void removeSession(int uid) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto it = sessions_.begin(); it != sessions_.end(); ++it) {
            if ((*it).getUID() == uid) {
                sessions_.erase(it);
                break;
            }
        }
    }

    // Update a session in the collection
    void updateSession(int uid, std::string username) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto it = sessions_.begin(); it != sessions_.end(); ++it) {
            if ((*it).getUID() == uid) {
                (*it).setUsername(username);
                break;
            }
        }
    }

    // Get a session from the collection by UID
    UserSession getSessionByUID(int uid) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto it = sessions_.begin(); it != sessions_.end(); ++it) {
            if ((*it).getUID() == uid) {
                return *it;
            }
        }
        return UserSession(-1, "");
    }

    // Get a session from the collection by username
    UserSession getSessionByUsername(std::string username) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto it = sessions_.begin(); it != sessions_.end(); ++it) {
            if ((*it).getUsername() == username) {
                return *it;
            }
        }
        return UserSession(-1, "");
    }

    // Get all sessions from the collection
    std::vector<UserSession> getAllSessions() {
        std::lock_guard<std::mutex> lock(mutex_);
        return sessions_;
    }

private:
    // Vector of UserSession objects
    std::vector<UserSession> sessions_;

    // Mutex for thread-safe access to the vector
    std::mutex mutex_;

    // Condition variable for waiting on a session update
    std::condition_variable cv_;
};
```
