// Define the structure for the record
typedef struct {
    int value;
} record;

// Define the hash table for mapping keys to records
typedef struct {
    int *keys;
    record **records;
    int size;
    int capacity;
} hash_table;

// Define the function for initializing the memory pool
void init_memory_pool(hash_table *ht, int initial_capacity) {
    ht->size = 0;
    ht->capacity = initial_capacity;
    ht->keys = (int *)malloc(sizeof(int) * ht->capacity);
    ht->records = (record **)malloc(sizeof(record *) * ht->capacity);
}

// Define the function for inserting a new record into the hash table
void insert_record(hash_table *ht, int key, record *value) {
    // Check if the key already exists in the hash table
    if (lookup_key(ht, key)) {
        printf("Duplicate RNTI detected. Ignoring new record.\n");
        return;
    }

    // If the key does not exist, insert a new record into the hash table
    int index = ht->size++;
    ht->keys[index] = key;
    ht->records[index] = value;
}

// Define the function for looking up a record in the hash table by key
record *lookup_key(hash_table *ht, int key) {
    // Iterate through the hash table to find the corresponding record
    for (int i = 0; i < ht->size; i++) {
        if (ht->keys[i] == key) {
            return ht->records[i];
        }
    }

    // If no matching record is found, return NULL
    return NULL;
}

// Define the function for deleting a record from the hash table by key
void delete_key(hash_table *ht, int key) {
    // Iterate through the hash table to find the corresponding record
    for (int i = 0; i < ht->size; i++) {
        if (ht->keys[i] == key) {
            // Shift all subsequent records to fill the gap
            for (int j = i + 1; j < ht->size; j++) {
                ht->keys[j - 1] = ht->keys[j];
                ht->records[j - 1] = ht->records[j];
            }

            // Decrement the size of the hash table
            ht->size--;
            return;
        }
    }
}

// Define the function for updating a record in the hash table by key
void update_record(hash_table *ht, int key, record *value) {
    // Look up the corresponding record in the hash table
    record *rec = lookup_key(ht, key);

    // If no matching record is found, insert a new one
    if (rec == NULL) {
        insert_record(ht, key, value);
        return;
    }

    // Update the existing record with the new value
    rec->value = value->value;
}

// Define the function for monitoring and reporting memory usage statistics
void monitor_memory_usage(hash_table *ht) {
    int total_size = 0;
    int max_size = 0;
    int num_records = 0;

    // Iterate through the hash table to calculate the total size and maximum size
    for (int i = 0; i < ht->capacity; i++) {
        if (ht->keys[i] != NULL) {
            total_size += sizeof(record);
            max_size = MAX(max_size, total_size);
            num_records++;
        }
    }

    // Print the memory usage statistics
    printf("Memory usage: %d bytes (%d records)\n", max_size, num_records);
}

