        nfapi_crc_indication_pdu_array[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        nfapi_crc_indication_pdu_array[i].RNTI = rand() % 1000;
        nfapi_crc_indication_pdu_array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    }

    // Insert the records into the hash table
    for (int i = 0; i < 4; i++) {
        insert_record(&ht, key_array[i], record_array[i]);
    }

    // Update the records in the hash table
    for (int i = 0; i < 4; i++) {
        update_record(&ht, key_array[i], record_array[i]);
    }

    // Delete the records from the hash table
    for (int i = 0; i < 4; i++) {
