// Define constants for DNS query limits and log size
#define MAX_QUERIES 100
#define LOG_SIZE 1024

// Define a struct to store DNS query information
struct dns_query {
    char *hostname;
    time_t timestamp;
};

// Define a linked list to store DNS queries
struct dns_query_list {
    struct dns_query *head;
    struct dns_query *tail;
};

// Define a function to add a DNS query to the linked list
void add_dns_query(struct dns_query_list *list, char *hostname) {
    // Allocate memory for the new DNS query
    struct dns_query *new_query = malloc(sizeof(struct dns_query));
    if (new_query == NULL) {
        perror("malloc");
        exit(1);
    }

    // Set the hostname and timestamp for the new DNS query
    new_query->hostname = strdup(hostname);
    new_query->timestamp = time(NULL);

    // Add the new DNS query to the linked list
    if (list->head == NULL) {
        list->head = new_query;
        list->tail = new_query;
    } else {
        list->tail->next = new_query;
        list->tail = new_query;
    }
}

// Define a function to remove the oldest DNS query from the linked list
void remove_oldest_dns_query(struct dns_query_list *list) {
    // If there are no queries in the linked list, return
    if (list->head == NULL) {
        return;
    }

    // Remove the oldest query from the linked list
    struct dns_query *oldest_query = list->head;
    list->head = list->head->next;
    free(oldest_query);
}

// Define a function to log DNS queries
void log_dns_query(struct dns_query_list *list, char *hostname) {
    // If the linked list is full, remove the oldest query
    if (list->tail == NULL || list->tail->next != NULL) {
        remove_oldest_dns_query(list);
    }

    // Add the new DNS query to the linked list
    add_dns_query(list, hostname);
}

// Define a function to perform DNS resolution
int dns_resolve(char *hostname) {
    // Initialize variables for DNS resolution
    struct addrinfo hints;
    struct addrinfo *result = NULL;
    int status;

    // Set up the hints for DNS resolution
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_flags = AI_PASSIVE;

    // Perform DNS resolution
    status = getaddrinfo(hostname, NULL, &hints, &result);
    if (status != 0) {
        fprintf(stderr, "getaddrinfo failed: %s\n", gai_strerror(status));
        return -1;
    }

    // Free the memory allocated by getaddrinfo
    freeaddrinfo(result);

    // Return success
    return 0;
}

// Define a function to handle DNS resolution errors
void dns_resolve_error(char *hostname) {
    // Log the DNS resolution error
    log_dns_query(&list, hostname);

    // Print an error message
    fprintf(stderr, "DNS resolution failed for %s\n", hostname);
}

