} TX_PDU;

// Define the array of TX_PDU structures
TX_PDU *tx_pdu_array = NULL;
size_t tx_pdu_array_size = 0;

// Function to add a new element to the array
void add_element(TX_PDU *new_element) {
    // Check if the array is full
    if (tx_pdu_array_size == SIZE_MAX) {
        fprintf(stderr, "Error: Array is full\n");
        return;
    }

    // Allocate memory for the new element
    TX_PDU *new_element = malloc(sizeof(TX_PDU));
    if (new_element == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory\n");
        return;
    }

    // Copy the contents of the new element into the array
    memcpy(new_element, new_element, sizeof(TX_PDU));

    // Increment the size of the array
    tx_pdu_array_size++;
}

// Function to remove an existing element from the array based on a specific criterion
void remove_element(TX_PDU *element) {
    // Check if the array is empty
    if (tx_pdu_array_size == 0) {
        fprintf(stderr, "Error: Array is empty\n");
        return;
    }

    // Find the index of the element to remove
    size_t index = 0;
    while (index < tx_pdu_array_size && &tx_pdu_array[index] != element) {
        index++;
    }

    // Check if the element was found
    if (index == tx_pdu_array_size) {
        fprintf(stderr, "Error: Element not found\n");
        return;
    }

    // Remove the element from the array
    memmove(&tx_pdu_array[index], &tx_pdu_array[index + 1], (tx_pdu_array_size - index) * sizeof(TX_PDU));
    tx_pdu_array_size--;
}

// Function to update the contents of an element in the array
void update_element(TX_PDU *element, TX_MESSAGE new_message) {
    // Check if the array is empty
    if (tx_pdu_array_size == 0) {
        fprintf(stderr, "Error: Array is empty\n");
        return;
    }

    // Find the index of the element to update
    size_t index = 0;
    while (index < tx_pdu_array_size && &tx_pdu_array[index] != element) {
        index++;
    }

    // Check if the element was found
    if (index == tx_pdu_array_size) {
        fprintf(stderr, "Error: Element not found\n");
        return;
    }

    // Update the contents of the element
    memcpy(&tx_pdu_array[index].message, &new_message, sizeof(TX_MESSAGE));
}

// Function to serialize the array to a file
void serialize_array(FILE *file) {
    // Check if the array is empty
    if (tx_pdu_array_size == 0) {
        fprintf(stderr, "Error: Array is empty\n");
        return;
    }

    // Write the size of the array to the file
    fwrite(&tx_pdu_array_size, sizeof(size_t), 1, file);

    // Write each element of the array to the file
    for (size_t i = 0; i < tx_pdu_array_size; i++) {
        TX_PDU *element = &tx_pdu_array[i];
        fwrite(element, sizeof(TX_PDU), 1, file);
    }
}

// Function to deserialize the array from a file
void deserialize_array(FILE *file) {
    // Check if the file is empty
    if (ftell(file) == 0) {
        fprintf(stderr, "Error: File is empty\n");
        return;
    }

    // Read the size of the array from the file
    size_t size = 0;
    fread(&size, sizeof(size_t), 1, file);

    // Allocate memory for the array
    tx_pdu_array = malloc(sizeof(TX_PDU) * size);
    if (tx_pdu_array == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory\n");
        return;
    }

    // Read each element of the array from the file
    for (size_t i = 0; i < size; i++) {
        TX_PDU *element = &tx_pdu_array[i];
        fread(element, sizeof(TX_PDU), 1, file);
    }
}
