    NFAPI_CRC_INDICATION_PDU_T *entries; // Pointer to the array of NFAPI_CRC_INDICATION_PDU_T structures
} NFAPI_CRC_INDICATION_LIST_T;

// Define a function to dynamically allocate memory for a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_LIST_T *allocate_crc_indication_list(int capacity) {
    // Allocate memory for the list structure and initialize its fields
    NFAPI_CRC_INDICATION_LIST_T *list = (NFAPI_CRC_INDICATION_LIST_T *)malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    if (!list) {
        // Log an error message if memory allocation fails
        printf("Error: Failed to allocate memory for CRC indication list\n");
        return NULL;
    }
    list->count = 0;
    list->capacity = capacity;
    list->entries = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * capacity);
    if (!list->entries) {
        // Log an error message if memory allocation fails
        printf("Error: Failed to allocate memory for CRC indication list entries\n");
        free(list);
        return NULL;
    }
    return list;
}

// Define a function to add a new entry to the list of NFAPI_CRC_INDICATION_PDU_T structures
int add_crc_indication_entry(NFAPI_CRC_INDICATION_LIST_T *list, RX_UE_INFORMATION_TAG rx_ue_information_tag, RNTI rnti, CRC_INDICATION_REL8_TAG crc_indication_rel8_tag) {
    // Check if the list is full and needs to be resized
    if (list->count == list->capacity) {
        // Double the capacity of the list
        int new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_entries = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->entries, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
        if (!new_entries) {
            // Log an error message if memory reallocation fails
            printf("Error: Failed to resize CRC indication list\n");
            return -1;
        }
        list->entries = new_entries;
        list->capacity = new_capacity;
    }
    // Add the new entry to the list
    NFAPI_CRC_INDICATION_PDU_T *entry = &list->entries[list->count++];
    entry->rx_ue_information_tag = rx_ue_information_tag;
    entry->rnti = rnti;
    entry->crc_indication_rel8_tag = crc_indication_rel8_tag;
    return 0;
}

// Define a function to release all allocated memory for the list of NFAPI_CRC_INDICATION_PDU_T structures
void free_crc_indication_list(NFAPI_CRC_INDICATION_LIST_T *list) {
    // Release the memory for the list structure and its entries
    free(list->entries);
    free(list);
}

// Define a function to traverse the list of NFAPI_CRC_INDICATION_PDU_T structures in reverse order
void traverse_crc_indication_list_reverse(NFAPI_CRC_INDICATION_LIST_T *list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T *)) {
    // Iterate over the list in reverse order and call the callback function for each entry
    for (int i = list->count - 1; i >= 0; i--) {
        NFAPI_CRC_INDICATION_PDU_T *entry = &list->entries[i];
        callback(entry);
