#include <semaphore.h>
#include <unistd.h>

// Define the record structure
typedef struct {
    int value;
    long *offset;
    int *key;
    char **metadata;
} Record;

// Define the metadata array structure
typedef struct {
    int size;
    char data[];
} Metadata;

// Define the function to dynamically allocate memory for and initialize multiple arrays of varying data types
void init_arrays(int type, long offset, int key, char *metadata) {
    // Check if the maximum allowed size of the records and metadata array has been exceeded
    if (type > MAX_RECORD_TYPE || offset > MAX_OFFSET || key > MAX_KEY || metadata > MAX_METADATA) {
        printf("Error: Maximum allowed size of the record and metadata array has been exceeded\n");
        return;
    }

    // Allocate memory for the arrays
    Record *records = (Record *)malloc(sizeof(Record) * type);
    long *offsets = (long *)malloc(sizeof(long) * offset);
    int *keys = (int *)malloc(sizeof(int) * key);
    char **metadata_arrays = (char **)malloc(sizeof(char *) * metadata);

    // Initialize the arrays
    for (int i = 0; i < type; i++) {
        records[i].value = 0;
        records[i].offset = &offsets[i];
        records[i].key = &keys[i];
        records[i].metadata = &metadata_arrays[i];
    }

    // Initialize the offset and key arrays
    for (int i = 0; i < offset; i++) {
        offsets[i] = 0;
    }
    for (int i = 0; i < key; i++) {
        keys[i] = 0;
    }

    // Initialize the metadata arrays
    for (int i = 0; i < metadata; i++) {
        metadata_arrays[i] = (char *)malloc(sizeof(char) * METADATA_SIZE);
        memset(metadata_arrays[i], '\0', METADATA_SIZE);
    }

    // Synchronize access to the arrays using a semaphore
    sem_t *sem = sem_open("array_sem", O_CREAT, 0644, 1);
    if (sem == SEM_FAILED) {
        printf("Error: Failed to create semaphore\n");
        return;
    }
    pthread_mutex_t *mutex = (pthread_mutex_t *)malloc(sizeof(pthread_mutex_t));
    if (mutex == NULL) {
        printf("Error: Failed to allocate memory for mutex\n");
        return;
    }
    pthread_mutex_init(mutex, NULL);
    sem_wait(sem);

    // Update the shared resources with the new arrays
    shared_records = records;
    shared_offsets = offsets;
    shared_keys = keys;
    shared_metadata_arrays = metadata_arrays;

    // Release the semaphore
    sem_post(sem);
}

// Define a function to generate random strings of specified lengths using a given character set
char *generate_random_string(int length, char *charset) {
    char *str = (char *)malloc(sizeof(char) * length);
    for (int i = 0; i < length; i++) {
        str[i] = charset[rand() % strlen(charset)];
    }
    return str;
}

