    int salt_length = 16;
    char salt[salt_length];
    for (int i = 0; i < salt_length; i++) {
        salt[i] = generate_random_string(1, "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789")[0];
    }
    char *hashed_password = (char *)malloc(sizeof(char) * 64);
    int hash_length = 64;
    for (int i = 0; i < hash_length; i++) {
        hashed_password[i] = generate_random_string(1, "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789")[0];
    }
