    offset_t *offsets;
    key_t *keys;
    size_t capacity;
    size_t count;
} cache_t;

// Define a custom hash table for caching offsets and keys
typedef struct {
    cache_t *cache;
    size_t size;
} hash_table_t;

// Define a function to generate random integers within a specified range using the Mersenne Twister algorithm
uint32_t mersenne_twister(uint32_t min, uint32_t max) {
    // Initialize the Mersenne Twister with a seed value
    srand(time(NULL));

    // Generate random integers within the specified range using the Mersenne Twister algorithm
    while (true) {
        int r = rand();
        if (r >= min && r <= max) {
            return r;
        }
    }
}

// Define a function to populate the record structure with random integers within a specified range
void populate_record(record_t *record, uint32_t min, uint32_t max) {
    // Generate a random integer within the specified range using the Mersenne Twister algorithm
    record->record = mersenne_twister(min, max);
}

// Define a function to allocate memory for the cache structure and initialize it with default values
cache_t *init_cache() {
    // Allocate memory for the cache structure
    cache_t *cache = malloc(sizeof(cache_t));
    if (cache == NULL) {
        printf("Error: Failed to allocate memory for cache\n");
        return NULL;
    }

    // Initialize the cache structure with default values
    cache->offsets = NULL;
    cache->keys = NULL;
    cache->capacity = 0;
    cache->count = 0;

    return cache;
}

// Define a function to allocate memory for the hash table and initialize it with default values
hash_table_t *init_hash_table() {
    // Allocate memory for the hash table structure
    hash_table_t *hash_table = malloc(sizeof(hash_table_t));
    if (hash_table == NULL) {
        printf("Error: Failed to allocate memory for hash table\n");
        return NULL;
    }

    // Initialize the hash table structure with default values
    hash_table->cache = init_cache();
    hash_table->size = 0;

    return hash_table;
}

// Define a function to add an offset and key to the cache
void add_to_cache(cache_t *cache, offset_t offset, key_t key) {
    // Check if the cache is full
    if (cache->count == cache->capacity) {
        // If the cache is full, evict the least recently used entry
        evict_from_cache(cache);
    }

    // Add the offset and key to the cache
    cache->offsets[cache->count] = offset;
    cache->keys[cache->count] = key;
    cache->count++;
}

// Define a function to evict an entry from the cache
void evict_from_cache(cache_t *cache) {
    // Find the least recently used entry in the cache
    size_t lru_index = 0;
    for (size_t i = 1; i < cache->count; i++) {
        if (cache->offsets[i].offset < cache->offsets[lru_index].offset) {
            lru_index = i;
        }
    }

    // Remove the least recently used entry from the cache
    free(cache->offsets[lru_index]);
    free(cache->keys[lru_index]);
    cache->count--;
}

// Define a function to search for an offset and key in the cache
bool search_in_cache(cache_t *cache, offset_t offset, key_t key) {
    // Check if the cache is empty
    if (cache->count == 0) {
        return false;
    }

    // Search for the offset and key in the cache
    for (size_t i = 0; i < cache->count; i++) {
        if (cache->offsets[i].offset == offset && cache->keys[i].key == key) {
            return true;
        }
    }

    return false;
}

// Define a function to add an entry to the hash table
void add_to_hash_table(hash_table_t *hash_table, offset_t offset, key_t key) {
    // Check if the hash table is full
    if (hash_table->size == 0) {
        // If the hash table is empty, allocate memory for it and initialize it with default values
        hash_table->cache = init_cache();
        hash_table->size = 1;
    } else if (hash_table->size == hash_table->capacity) {
        // If the hash table is full, double its size and rehash all entries
        hash_table->capacity *= 2;
        for (size_t i = 0; i < hash_table->size; i++) {
            add_to_cache(hash_table->cache, hash_table->offsets[i], hash_table->keys[i]);
        }
    }

    // Add the offset and key to the hash table
    hash_table->offsets[hash_table->size] = offset;
    hash_table->keys[hash_table->size] = key;
    hash_table->size++;
}

// Define a function to search for an entry in the hash table
bool search_in_hash_table(hash_table_t *hash_table, offset_t offset, key_t key) {
    // Check if the hash table is empty
    if (hash_table->size == 0) {
        return false;
    }

    // Search for the offset and key in the hash table
    size_t index = hash(offset, key);
    while (true) {
        if (hash_table->offsets[index].offset == offset && hash_table->keys[index].key == key) {
            return true;
        } else if (index == 0) {
            break;
        }
        index--;
    }

    return false;
}

// Define a function to free the memory allocated for the cache and hash table
void free_cache(cache_t *cache) {
    // Free the memory allocated for the cache structure
    free(cache->offsets);
    free(cache->keys);
    free(cache);
}

// Define a function to free the memory allocated for the hash table
void free_hash_table(hash_table_t *hash_table) {
    // Free the memory allocated for the hash table structure
    free(hash_table->offsets);
    free(hash_table->keys);
    free(hash_table);
}
