void add_frame(int FRAME_TYPE, int TX_POWER_LEVEL, int SRS_CONFIG) {
    // Acquire the lock on the mutex before modifying the array
    pthread_mutex_lock(&frame_lock);

    // Generate a random SRS_INDEX for the new frame
    int SRS_INDEX = rand() % 10;

    // Add the new frame to the array
    frames[SRS_INDEX].FRAME_TYPE = FRAME_TYPE;
    frames[SRS_INDEX].TX_POWER_LEVEL = TX_POWER_LEVEL;
    frames[SRS_INDEX].SRS_CONFIG = SRS_CONFIG;

    // Release the lock on the mutex after modifying the array
    pthread_mutex_unlock(&frame_lock);
}

