void remove_frame(int SRS_INDEX) {
    // Acquire the lock on the mutex before modifying the array
    pthread_mutex_lock(&frame_lock);

    // Remove the frame from the array
    frames[SRS_INDEX].FRAME_TYPE = 0;
    frames[SRS_INDEX].TX_POWER_LEVEL = 0;
    frames[SRS_INDEX].SRS_CONFIG = 0;

    // Release the lock on the mutex after modifying the array
    pthread_mutex_unlock(&frame_lock);
}

// Function to retrieve a frame from the array
LTE_PHY_FRAME_INFO get_frame(int SRS_INDEX) {
    // Acquire the lock on the mutex before accessing the array
    pthread_mutex_lock(&frame_lock);

    // Retrieve the frame from the array
    LTE_PHY_FRAME_INFO frame = frames[SRS_INDEX];

    // Release the lock on the mutex after accessing the array
    pthread_mutex_unlock(&frame_lock);

    return frame;
}

// Function to check if a frame exists in the array
int frame_exists(int SRS_INDEX) {
    // Acquire the lock on the mutex before accessing the array
    pthread_mutex_lock(&frame_lock);

    // Check if the frame exists in the array
    int exists = (frames[SRS_INDEX].FRAME_TYPE != 0);

    // Release the lock on the mutex after accessing the array
    pthread_mutex_unlock(&frame_lock);

    return exists;
}
