    uint32_t rx_ue_information_tag;
    uint32_t rnti;
    uint8_t crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the function to dynamically manage memory for the list of CRC indications
NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_list(uint32_t n) {
    // Validate that N does not exceed the maximum limit
    if (n > MAX_N) {
        printf("Error: Provided value of N (%d) exceeds the maximum limit (%d)\n", n, MAX_N);
        return NULL;
    }

    // Allocate memory for the list of CRC indications
    NFAPI_CRC_INDICATION_PDU_T* crc_indication_list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * n);
    if (crc_indication_list == NULL) {
        printf("Error: Failed to allocate memory for the list of CRC indications\n");
        return NULL;
    }

    // Initialize the seed value for random number generation
    srand(time(NULL));

    // Iterate over each element in the list and initialize it with a valid RX_UE_INFORMATION_TAG, RNTI, and CRCFLAG
    for (uint32_t i = 0; i < n; i++) {
        crc_indication_list[i].rx_ue_information_tag = rand() % 1000000;
        crc_indication_list[i].rnti = rand() % 65536;
        crc_indication_list[i].crc_indication_rel8_tag = rand() % 256;
    }

    // Integrate with an external logging framework to log the creation of each NFAPI_CRC_INDICATION_PDU_T structure
    printf("Log: Created a list of %d CRC indications\n", n);

    // Return the pointer to the allocated memory
    return crc_indication_list;
}

// Define the function to free all allocated memory for the list of CRC indications
void destroy_crc_indication_list(NFAPI_CRC_INDICATION_PDU_T* crc_indication_list) {
    // Free all allocated memory for the list of CRC indications
    free(crc_indication_list);
}

// Define the function to dynamically manage memory for a single CRC indication structure
