    // Allocate memory for a single CRC indication structure
    NFAPI_CRC_INDICATION_PDU_T* crc_indication = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (crc_indication == NULL) {
        printf("Error: Failed to allocate memory for a single CRC indication structure\n");
        return NULL;
    }

    // Initialize the seed value for random number generation
    srand(time(NULL));

    // Initialize the RX_UE_INFORMATION_TAG, RNTI, and CRCFLAG with a randomly set value
    crc_indication->rx_ue_information_tag = rand() % 1000000;
    crc_indication->rnti = rand() % 65536;
    crc_indication->crc_indication_rel8_tag = rand() % 256;

    // Integrate with an external logging framework to log the creation of a single CRC indication structure
    printf("Log: Created a single CRC indication structure\n");

    // Return the pointer to the allocated memory
    return crc_indication;
}

// Define the function to free all allocated memory for a single CRC indication structure
void destroy_crc_indication(NFAPI_CRC_INDICATION_PDU_T* crc_indication) {
    // Free all allocated memory for a single CRC indication structure
    free(crc_indication);
}
