    ue_contexts[num_ues].RNTI = rnti;
    ue_contexts[num_ues].CRCIndication = (rand() % 2) ? true : false;
    num_ues++;
}

// Define a function to remove an existing UE context from the array, handling potential errors gracefully
void remove_ue_context(int ue_id) {
    // Find the index of the UE context in the array
