    int key;
} KeyValue;

typedef struct {
    int value;
} Record;

// Function to dynamically allocate memory for arrays and initialize them with data from multiple sources
void initData(OffsetValue** offsetValues, KeyValue** keys, Record** records) {
    // Load configuration file and environment variable
    FILE* configFile = fopen("config.txt", "r");
    char* envVar = getenv("ENV_VAR");

    // Initialize arrays with data from configuration file and environment variable
    *offsetValues = (OffsetValue*)malloc(sizeof(OffsetValue) * 10);
    *keys = (KeyValue*)malloc(sizeof(KeyValue) * 5);
    *records = (Record*)malloc(sizeof(Record) * 10);

    // Load data from configuration file and environment variable into arrays
    for (int i = 0; i < 10; i++) {
        fscanf(configFile, "%ld", &(*offsetValues)[i].offset);
    }
    for (int i = 0; i < 5; i++) {
        (*keys)[i].key = atoi(envVar + i * 2);
    }
    srand(time(NULL));
    for (int i = 0; i < 10; i++) {
        (*records)[i].value = rand() % 100;
    }

    // Free memory allocated for arrays and records
    free(*offsetValues);
    free(*keys);
    free(*records);
}

// Function to log operations with timestamps and context information
void logOperation(char* operation, char* context) {
    time_t t = time(NULL);
    struct tm* now = localtime(&t);
    printf("%s: %d-%02d-%02d %02d:%02d:%02d (%s)\n", operation, now->tm_year + 1900, now->tm_mon + 1, now->tm_mday, now->tm_hour, now->tm_min, now->tm_sec, context);
}

// Function to handle potential errors during file loading and memory allocation
void errorHandler(char* message) {
    printf("Error: %s\n", message);
}

int main() {
    OffsetValue* offsetValues;
    KeyValue* keys;
    Record* records;

    // Initialize arrays with data from multiple sources
    initData(&offsetValues, &keys, &records);

    // Log initialization of arrays and records
    logOperation("Initialization", "Arrays and Records");

    // Free memory allocated for arrays and records
    free(offsetValues);
    free(keys);
    free(records);

    return 0;
}
