#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_LINE_LENGTH 1024
#define MAX_CHUNK_SIZE 1024 * 1024 // 1 MB
#define MEMORY_THRESHOLD 0.8 // 80% of total memory

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void *process_chunk(void *arg) {
    char *file = (char *)arg;
    FILE *fp = fopen(file, "r");
    if (!fp) {
        perror("fopen");
        return NULL;
    }

    // Create a dynamic array to manage the list of structures
    NFAPI_CRC_INDICATION_PDU_T **array = (NFAPI_CRC_INDICATION_PDU_T **)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T *) * MAX_CHUNK_SIZE);
    if (!array) {
        perror("malloc");
        fclose(fp);
        return NULL;
    }

    // Read and process the file in chunks
    char line[MAX_LINE_LENGTH];
    int i = 0;
    while (fgets(line, MAX_LINE_LENGTH, fp)) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            perror("malloc");
            fclose(fp);
            return NULL;
        }

        // Populate the structure with random values
        pdu->RX_UE_INFORMATION_TAG = rand();
        pdu->RNTI = rand();
        pdu->CRC_INDICATION_REL8_TAG = rand();

        array[i++] = pdu;
    }

    // Flush the structures to a temporary file when memory usage exceeds threshold
    if (i > 0 && ((double)i / MAX_CHUNK_SIZE) >= MEMORY_THRESHOLD) {
        char temp_file[256];
        sprintf(temp_file, "tmp.%d", getpid());
        FILE *tfp = fopen(temp_file, "w");
        if (!tfp) {
            perror("fopen");
            fclose(fp);
            return NULL;
        }

        for (int j = 0; j < i; j++) {
            NFAPI_CRC_INDICATION_PDU_T *pdu = array[j];
            fwrite(pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, tfp);
        }

        fclose(tfp);
    }

    // Clean up the dynamic array and close the file
    free(array);
    fclose(fp);

    return NULL;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        printf("Usage: %s <input_file>\n", argv[0]);
        exit(1);
    }

    // Create a semaphore to synchronize access to the temporary file
    sem_t *sem = sem_open("/tmp/sem", O_CREAT, 0644, 1);
    if (!sem) {
        perror("sem_open");
        exit(1);
    }

    // Create a thread to process the input file in chunks
    pthread_t tid;
    int ret = pthread_create(&tid, NULL, process_chunk, argv[1]);
    if (ret != 0) {
        perror("pthread_create");
        exit(1);
    }

    // Wait for the thread to finish and close the semaphore
    pthread_join(tid, NULL);
    sem_close(sem);

    return 0;
}
```
