} NFAPI_CRC_INDICATION_PDU_T;

// Define a list data structure to store the NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
} NFAPI_CRC_INDICATION_LIST_T;

// Define a mutex to protect the list data structure from concurrent access
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to dynamically generate and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_LIST_T *generate_crc_indication_list(size_t num_elements) {
    // Allocate memory for the list data structure
    NFAPI_CRC_INDICATION_LIST_T *list = malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    if (!list) {
        printf("Error: Failed to allocate memory for CRC indication list\n");
        return NULL;
    }

    // Initialize the list size and data pointer
    list->size = 0;
    list->data = NULL;

    // Generate and populate the list of NFAPI_CRC_INDICATION_PDU_T structures
    for (size_t i = 0; i < num_elements; i++) {
        // Allocate memory for a new NFAPI_CRC_INDICATION_PDU_T structure
        NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            printf("Error: Failed to allocate memory for CRC indication PDU\n");
            free(list);
            return NULL;
        }

        // Set the RX_UE_INFORMATION_TAG, RNTI, and CRCFLAG fields randomly
        pdu->RX_UE_INFORMATION_TAG = rand() % 10000;
        pdu->RNTI = rand() % 100000000;
        pdu->CRCFLAG = rand() % 2;

        // Add the new NFAPI_CRC_INDICATION_PDU_T structure to the list
        if (list->size == 0) {
            list->data = pdu;
        } else {
            NFAPI_CRC_INDICATION_PDU_T *prev = list->data;
            while (prev->next != NULL) {
                prev = prev->next;
            }
            prev->next = pdu;
        }

        // Increment the list size
        list->size++;
    }

    return list;
}

// Function to add a new NFAPI_CRC_INDICATION_PDU_T structure to the list, ensuring unique RNTI values and robust error handling
void add_crc_indication(NFAPI_CRC_INDICATION_LIST_T *list, uint32_t rnti) {
    // Acquire the mutex to protect the list data structure from concurrent access
    pthread_mutex_lock(&list_mutex);

    // Check if the RNTI value is already present in the list
    NFAPI_CRC_INDICATION_PDU_T *pdu = list->data;
    while (pdu != NULL) {
        if (pdu->RNTI == rnti) {
            // Release the mutex and return early if a duplicate RNTI value is detected
            pthread_mutex_unlock(&list_mutex);
            printf("Error: Duplicate RNTI value detected\n");
            return;
        }
        pdu = pdu->next;
    }

    // Allocate memory for a new NFAPI_CRC_INDICATION_PDU_T structure
    NFAPI_CRC_INDICATION_PDU_T *new_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_pdu) {
        printf("Error: Failed to allocate memory for CRC indication PDU\n");
        pthread_mutex_unlock(&list_mutex);
        return;
    }

    // Set the RX_UE_INFORMATION_TAG, RNTI, and CRCFLAG fields randomly
    new_pdu->RX_UE_INFORMATION_TAG = rand() % 10000;
    new_pdu->RNTI = rnti;
    new_pdu->CRCFLAG = rand() % 2;

    // Add the new NFAPI_CRC_INDICATION_PDU_T structure to the list
    if (list->size == 0) {
        list->data = new_pdu;
    } else {
        NFAPI_CRC_INDICATION_PDU_T *prev = list->data;
        while (prev->next != NULL) {
            prev = prev->next;
        }
        prev->next = new_pdu;
    }

    // Increment the list size and release the mutex
    list->size++;
    pthread_mutex_unlock(&list_mutex);
}

// Function to remove a NFAPI_CRC_INDICATION_PDU_T structure from the list by RNTI value, ensuring thread-safe access and modification
void remove_crc_indication(NFAPI_CRC_INDICATION_LIST_T *list, uint32_t rnti) {
    // Acquire the mutex to protect the list data structure from concurrent access
    pthread_mutex_lock(&list_mutex);

    // Find the NFAPI_CRC_INDICATION_PDU_T structure with the specified RNTI value and remove it from the list
    NFAPI_CRC_INDICATION_PDU_T *pdu = list->data;
    while (pdu != NULL) {
        if (pdu->RNTI == rnti) {
            // Remove the current PDU from the list and update the next pointer of the previous PDU
            NFAPI_CRC_INDICATION_PDU_T *prev = pdu;
            pdu = pdu->next;
            prev->next = pdu->next;

            // Free the memory allocated for the removed PDU
            free(pdu);

            // Decrement the list size and release the mutex
            list->size--;
            pthread_mutex_unlock(&list_mutex);
            return;
        }
        pdu = pdu->next;
    }

    // Release the mutex if no matching RNTI value was found in the list
    pthread_mutex_unlock(&list_mutex);
}

// Function to periodically verify the integrity of the CRC_INDICATION_REL8_TAG against a predefined reference value for each entry
void verify_crc_indication(NFAPI_CRC_INDICATION_LIST_T *list) {
    // Acquire the mutex to protect the list data structure from concurrent access
    pthread_mutex_lock(&list_mutex);

    // Iterate over each NFAPI_CRC_INDICATION_PDU_T structure in the list and verify the CRC_INDICATION_REL8_TAG against a predefined reference value
    NFAPI_CRC_INDICATION_PDU_T *pdu = list->data;
    while (pdu != NULL) {
        // Check if the CRC_INDICATION_REL8_TAG matches the predefined reference value
        if (pdu->CRCFLAG != 0x1234) {
            printf("Error: Discrepancy detected in CRC indication PDU\n");
            // Log the issue and implement a recovery algorithm to correct the problem
            pthread_mutex_unlock(&list_mutex);
            return;
        }
        pdu = pdu->next;
    }

    // Release the mutex if no discrepancies were detected in the list
    pthread_mutex_unlock(&list_mutex);
}
