    // Parse the command line arguments
    for (int i = 1; i < argc; i++) {
        if (!strcmp(argv[i], "-c")) {
            count = atoi(argv[++i]);
        } else if (!strcmp(argv[i], "-o")) {
            output_file = fopen(argv[++i], "w");
            if (!output_file) {
                perror("Failed to open output file");
                exit(EXIT_FAILURE);
            }
        } else if (!strcmp(argv[i], "-m")) {
            verbose = true;
        }
    }

    // Check for valid input file and count
    if (count <= 0) {
        printf("Usage: %s -c <count> [-o <output_file>] [-m]\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    // Initialize the configuration structure
    config->offset[0] = 0;
    config->key[0] = 1;

    // Read the input file and process its contents
    FILE *input_file = fopen(argv[i], "r");
    if (!input_file) {
        perror("Failed to open input file");
        exit(EXIT_FAILURE);
    }
    process_input_file(input_file, config);
    fclose(input_file);

    // Allocate memory for the array of records
    record_t *records = allocate_records(count);

    // Initialize each record with a random value within the specified range
    for (int i = 0; i < count; i++) {
        init_record(&records[i], 1, 100);
    }

    // Write the records to the output file
    if (output_file) {
        for (int i = 0; i < count; i++) {
            fprintf(output_file, "%d\n", records[i].value);
        }
        fclose(output_file);
    }

    // Clean up memory
    free(records);
}

