  return pow(10, (rssi - snr) / 10);
}

// Define the function to populate and initialize the array of RX frame structures
void populateRxFrames(NFAPI_RX_FRAME_PDU_T *rxFrames, int numFrames) {
  // Initialize the count of successfully initialized structures
  int initCount = 0;

  // Loop through each frame and initialize the structure
  for (int i = 0; i < numFrames; i++) {
    rxFrames[i].rnti = i + 1;
    rxFrames[i].cqi = calculateSignalCondition(rxFrames[i].rsrp, rxFrames[i].rsrq);
