    int newCapacity = initCount * 2;
    NFAPI_RX_FRAME_PDU_T *newArray = realloc(rxFrames, sizeof(NFAPI_RX_FRAME_PDU_T) * newCapacity);
    if (newArray == NULL) {
      // Handle out-of-memory scenario gracefully by implementing a custom error management mechanism
      printf("Error: Out of memory\n");
      return;
    } else {
      rxFrames = newArray;
    }
  }

  // Check if the total number of structures exceeds the predefined threshold and trigger logging or notification mechanisms if necessary
  if (initCount > TRIGGER_THRESHOLD) {
    printf("Warning: Total number of structures exceeds %d\n", TRIGGER_THRESHOLD);
  }
}

