// Define the function to generate random frame parameters
void generateRandomFrameParams(LTE_DL_FRAMEINFO *frameInfo) {
    // Generate a random frame number between 1 and MAX_NUM_FRAMES
    frameInfo->frameNumber = rand() % (MAX_NUM_FRAMES + 1);

    // Generate a random slot duration between 20 and 50 ms
    frameInfo->slotDuration = 20 + ((double)rand() / RAND_MAX) * 30;

    // Generate a random cyclic prefix type (A or B)
    frameInfo->cyclicPrefixType = (char)(rand() % 2 + 'A');
}

// Define the function to validate frame parameters against LTE standards
int validateFrameParams(LTE_DL_FRAMEINFO *frameInfo) {
    // Check if the slot duration is within the allowed range of 20-50 ms
    if (frameInfo->slotDuration < 20 || frameInfo->slotDuration > 50) {
        return 0;
    }

    // Check if the cyclic prefix type is valid (A or B)
    if (frameInfo->cyclicPrefixType != 'A' && frameInfo->cyclicPrefixType != 'B') {
        return 0;
    }

    // If all checks pass, return 1 to indicate validity
    return 1;
}

// Define the function to manage the dynamically allocated array of LTE_DL_FRAMEINFO structures
