        generateRandomFrameParams(frameInfo);

        // Validate the frame parameters against LTE standards
        if (validateFrameParams(frameInfo)) {
            frames[i] = frameInfo;
        } else {
            free(frameInfo);
        }
    }

    // Integrate with existing network management tools to handle varying levels of support for different LTE versions
    integrateWithTools(frames, numFrames);
}

// Define the function to integrate with existing network management tools
void integrateWithTools(LTE_DL_FRAMEINFO **frames, int numFrames) {
    // Loop through each frame and check if it is supported by the existing tools
    for (int i = 0; i < numFrames; i++) {
        LTE_DL_FRAMEINFO *frameInfo = frames[i];

        // Check if the frame is supported by the existing tools
        if (!isFrameSupported(frameInfo)) {
            // If not, free the memory allocated for the frame and remove it from the array
            free(frames[i]);
            frames[i] = NULL;
        }
    }
}

// Define the function to check if a frame is supported by existing network management tools
int isFrameSupported(LTE_DL_FRAMEINFO *frameInfo) {
    // Check if the frame's slot duration and cyclic prefix type are within the allowed range for the existing tools
    return (frameInfo->slotDuration >= 20 && frameInfo->slotDuration <= 50 && frameInfo->cyclicPrefixType == 'A' || frameInfo->cyclicPrefixType == 'B');
}
