void get_crc_indication_summary(int *num_crc_indications, int *rnti) {
    // Iterate through the linked list and count the number of CRC indications for each RNTI
    node_t *current = head;
    while (current != NULL) {
        if (current->data->crc_indication->CRC_INDICATION_REL8_TAG == 1) {
            (*num_crc_indications)++;
        }
        current = current->next;
    }

    // Return the RNTI with the highest number of CRC indications
    int max_rnti = -1;
    int max_num_crc_indications = 0;
    current = head;
    while (current != NULL) {
        if (current->data->crc_indication->CRC_INDICATION_REL8_TAG == 1 && (*num_crc_indications) > max_num_crc_indications) {
            max_rnti = current->data->rnti;
            max_num_crc_indications = *num_crc_indications;
        }
        current = current->next;
    }

    // Return the RNTI with the highest number of CRC indications
    *rnti = max_rnti;
}
