// Define the allowed extensions for the new file name
const char* allowed_extensions[] = {"jpg", "png", "gif"};

// Define the structure to hold the NFAPI_CRC_INDICATION_PDU_T data
typedef struct {
    int rx_ue_information_tag;
    int rnti;
    int crc_indication_rel8_tag;
    int crcflag;
} nfapi_crc_indication_pdu_t;

// Define the function to generate a unique file name
char* generateDynamicFileName(const char* original_file_path, const char* new_extension) {
    // Check if the input path is valid and has a directory component
    if (!original_file_path || !strchr(original_file_path, '/')) {
        return NULL;
    }

    // Get the directory and file name components of the original path
    char* directory = strdup(original_file_path);
    char* filename = basename(directory);

    // Check if the new extension is valid and allowed
    if (!new_extension || !strchr(allowed_extensions, new_extension)) {
        return NULL;
    }

    // Generate a SHA-256 hash of the original file name
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256((unsigned char*)filename, strlen(filename), hash);

    // Get the current Unix timestamp
    time_t timestamp = time(NULL);

    // Generate a sequence of digits based on the first 10 characters of the original file name
    int sequence[8];
    for (int i = 0; i < 8; i++) {
        sequence[i] = filename[i] - '0';
    }

    // Create a new file name with the format: <directory>/<original_name>.<hash>.<timestamp>-<sequence_of_digits>.<new_extension>
    char* new_file_name = malloc(strlen(directory) + strlen(filename) + SHA256_DIGEST_LENGTH * 2 + 10 + strlen(new_extension));
    sprintf(new_file_name, "%s/%s.%s.%lu-%d.%s", directory, filename, hash, timestamp, sequence[0], new_extension);

    // Check if the new file name is unique within the specified directory
    struct stat st;
    if (stat(new_file_name, &st) == 0) {
        free(directory);
        free(new_file_name);
        return NULL;
    }

    // Create a list of NFAPI_CRC_INDICATION_PDU_T structures with the generated file name and extension
    nfapi_crc_indication_pdu_t* pdu = malloc(sizeof(nfapi_crc_indication_pdu_t));
    pdu->rx_ue_information_tag = 0;
    pdu->rnti = 0;
    pdu->crc_indication_rel8_tag = 0;
    pdu->crcflag = 1;
    strcpy(pdu->filename, new_file_name);

    // Return the list of NFAPI_CRC_INDICATION_PDU_T structures
    return pdu;
}
