    for (int i = 0; i < numContexts; i++) {
        (*contexts)[i].rachRequest = NULL;
        (*contexts)[i].nasMessage = NULL;
    }
}

// Define the function to add a new UE context
void addNewUEContext(NRUEContext **contexts, int numContexts, NR_RACH_REQUEST_T *rachRequest, NAS_MESSAGE *nasMessage) {
    // Check if there is enough memory for a new context
    if (numContexts >= MAX_NUM_CONTEXTS) {
        printf("Error: Maximum number of UE contexts reached\n");
        return;
    }

    // Allocate memory for the new context
    (*contexts)[numContexts].rachRequest = rachRequest;
    (*contexts)[numContexts].nasMessage = nasMessage;

    // Increment the number of contexts
    numContexts++;
}

// Define the function to retrieve a UE context by its index
NRUEContext *getUEContext(NRUEContext **contexts, int index) {
    if (index < 0 || index >= numContexts) {
        printf("Error: Invalid index for UE context\n");
        return NULL;
    }

    return &(*contexts)[index];
}

// Define the function to free the memory of a UE context
void freeUEContext(NRUEContext **contexts, int index) {
    if (index < 0 || index >= numContexts) {
        printf("Error: Invalid index for UE context\n");
        return;
    }

    // Free the memory of the NAS message
    free((*contexts)[index].nasMessage);

    // Decrement the number of contexts
    numContexts--;
}
```
