    unsigned short macsdu_length; // Length of the MACSDU
    unsigned char *macsdu; // Pointer to the MACSDU
} MAC_PDU;

// Define the function to allocate memory for a list of MAC PDUs
MAC_PDU* alloc_mac_pdu(int N) {
    // Check if the input value is valid
    if (N <= 0) {
        printf("Error: Invalid input value for N\n");
        return NULL;
    }

    // Allocate memory for the list of MAC PDUs
    MAC_PDU *mac_pdu_list = malloc(sizeof(MAC_PDU) * N);
    if (mac_pdu_list == NULL) {
        printf("Error: Failed to allocate memory for the list of MAC PDUs\n");
        return NULL;
    }

    // Initialize the MAC control field and MACSDU length for each structure
    for (int i = 0; i < N; i++) {
        mac_pdu_list[i].mac_control = rand() % 256; // Randomly generate a value between 0 and 255
        mac_pdu_list[i].macsdu_length = rand() % 100 + 100; // Randomly generate a value between 100 and 255
        mac_pdu_list[i].macsdu = malloc(mac_pdu_list[i].macsdu_length);
        if (mac_pdu_list[i].macsdu == NULL) {
            printf("Error: Failed to allocate memory for the MACSDU\n");
            return NULL;
        }
    }

    // Return the list of MAC PDUs
    return mac_pdu_list;
}

// Define a helper function to free the allocated memory
void free_mac_pdu(MAC_PDU *mac_pdu_list) {
    if (mac_pdu_list == NULL) {
        return;
    }

    // Free the memory for each structure in the list
    for (int i = 0; i < N; i++) {
        free(mac_pdu_list[i].macsdu);
    }

    // Free the memory for the list of structures
    free(mac_pdu_list);
}
