// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the list of NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    int size;
    int capacity;
    NFAPI_CRC_INDICATION_PDU_T* data;
} NFAPI_CRC_INDICATION_LIST_T;

// Initialize the list with a given capacity
void nfapi_crc_indication_list_init(NFAPI_CRC_INDICATION_LIST_T* list, int capacity) {
    list->size = 0;
    list->capacity = capacity;
    list->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * capacity);
}

// Add a new element to the list
void nfapi_crc_indication_list_add(NFAPI_CRC_INDICATION_LIST_T* list, RX_UE_INFORMATION_TAG rx_ue_information_tag, RNTI rnti) {
    // Check if the list is full
    if (list->size == list->capacity) {
        // Double the capacity of the list
        int new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
        if (new_data == NULL) {
            // Reallocation failed, exit the function
            return;
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }

    // Generate a random CRC flag for the new element
    bool crc_flag = rand() % 2 == 0;

    // Add the new element to the list
    list->data[list->size].rx_ue_information_tag = rx_ue_information_tag;
    list->data[list->size].rnti = rnti;
    list->data[list->size].crc_indication_rel8_tag.crcflag = crc_flag;
    list->size++;
}

// Remove an element from the list by its index
void nfapi_crc_indication_list_remove(NFAPI_CRC_INDICATION_LIST_T* list, int index) {
    // Check if the index is valid
    if (index < 0 || index >= list->size) {
        return;
    }

    // Shift all elements after the removed element to the left
    for (int i = index + 1; i < list->size; i++) {
        list->data[i - 1] = list->data[i];
    }

    // Decrease the size of the list by one
    list->size--;
}

// Sort the list in ascending order based on RNTI
void nfapi_crc_indication_list_sort(NFAPI_CRC_INDICATION_LIST_T* list) {
    // Bubble sort the list
    for (int i = 0; i < list->size - 1; i++) {
        for (int j = i + 1; j < list->size; j++) {
            if (list->data[i].rnti > list->data[j].rnti) {
                NFAPI_CRC_INDICATION_PDU_T temp = list->data[i];
                list->data[i] = list->data[j];
                list->data[j] = temp;
            }
        }
    }
}

// Check if two consecutive elements in the list share the same RNTI value
bool nfapi_crc_indication_list_has_duplicates(NFAPI_CRC_INDICATION_LIST_T* list) {
    for (int i = 0; i < list->size - 1; i++) {
        if (list->data[i].rnti == list->data[i + 1].rnti) {
            return true;
        }
    }
    return false;
}

// Free the memory allocated for the list
void nfapi_crc_indication_list_free(NFAPI_CRC_INDICATION_LIST_T* list) {
    free(list->data);
}
```
