public class UserAccountManager : IdentityUserManager<IdentityUser>
{
    private readonly ILogger _logger;
    private readonly IPasswordHasher<IdentityUser> _passwordHasher;
    private readonly IUserStore<IdentityUser> _userStore;
    private readonly IOptions<IdentityOptions> _options;

    public UserAccountManager(ILogger<UserAccountManager> logger, IPasswordHasher<IdentityUser> passwordHasher, IUserStore<IdentityUser> userStore, IOptions<IdentityOptions> options) : base(userStore, passwordHasher, options)
    {
        _logger = logger;
        _passwordHasher = passwordHasher;
        _userStore = userStore;
        _options = options;
    }

    public async Task<bool> ValidateCredentialsAsync(string username, string password)
    {
        var user = await _userStore.FindByNameAsync(username);
        if (user == null)
        {
            return false;
        }

        var result = await _passwordHasher.VerifyHashedPasswordAsync(user, user.PasswordHash, password);
        if (result != PasswordVerificationResult.Success)
        {
            return false;
        }

        return true;
    }

    public async Task<IdentityUser> FindByNameAsync(string username)
    {
        var user = await _userStore.FindByNameAsync(username);
        if (user == null)
        {
            throw new InvalidOperationException($"Unable to find user with name '{username}'.");
        }

        return user;
    }

    public async Task<IdentityUser> FindByIdAsync(string id)
    {
        var user = await _userStore.FindByIdAsync(id);
        if (user == null)
        {
            throw new InvalidOperationException($"Unable to find user with ID '{id}'.");
        }

        return user;
    }

    public async Task<IdentityUser> CreateAsync(string username, string password)
    {
        var user = await _userStore.CreateAsync(new IdentityUser() { UserName = username }, password);
        if (user == null)
        {
            throw new InvalidOperationException($"Unable to create user with name '{username}'.");
        }

        return user;
    }

    public async Task<IdentityUser> UpdateAsync(string id, string username, string password)
    {
        var user = await _userStore.UpdateAsync(new IdentityUser() { UserName = username }, password);
        if (user == null)
        {
            throw new InvalidOperationException($"Unable to update user with ID '{id}'.");
        }

        return user;
    }

    public async Task<IdentityUser> DeleteAsync(string id)
    {
        var user = await _userStore.DeleteAsync(new IdentityUser() { UserName = username });
        if (user == null)
        {
            throw new InvalidOperationException($"Unable to delete user with ID '{id}'.");
        }

        return user;
    }
}
