#include <errno.h>

// Define the structure for a MAC transaction
typedef struct {
    MAC_PDU *mac_pdu;
    SAP sap;
    PDCP_PDU pdcp_pdu;
} MAC_TRANSACTION_T;

// Define the queue data structure
typedef struct {
    MAC_TRANSACTION_T *transactions[50000];
    int head, tail;
    sem_t mutex;
    int retransmissions;
} QUEUE_T;

// Function to initialize the queue
void init_queue(QUEUE_T *queue) {
    // Initialize the head and tail pointers
    queue->head = 0;
    queue->tail = 0;

    // Initialize the mutex for synchronizing access to the queue
    sem_init(&queue->mutex, 0, 1);

    // Initialize the retransmission counter
    queue->retransmissions = 0;
}

// Function to add a transaction to the queue
void enqueue(QUEUE_T *queue, MAC_TRANSACTION_T *transaction) {
    // Acquire the mutex for synchronizing access to the queue
    sem_wait(&queue->mutex);

    // Check if the queue is full
    if (queue->tail == 50000) {
        // If the queue is full, discard the oldest transaction
        free(queue->transactions[queue->head]);
        queue->head = (queue->head + 1) % 50000;
    }

    // Add the new transaction to the end of the queue
    queue->transactions[queue->tail] = transaction;
    queue->tail = (queue->tail + 1) % 50000;

    // Increment the retransmission counter if necessary
    if (transaction->mac_pdu->retransmissions > 0) {
        queue->retransmissions++;
    }

    // Release the mutex for synchronizing access to the queue
    sem_post(&queue->mutex);
}

// Function to remove a transaction from the queue
MAC_TRANSACTION_T *dequeue(QUEUE_T *queue) {
    MAC_TRANSACTION_T *transaction;

    // Acquire the mutex for synchronizing access to the queue
    sem_wait(&queue->mutex);

    // Check if the queue is empty
    if (queue->head == queue->tail) {
        transaction = NULL;
    } else {
        // Remove the oldest transaction from the queue
        transaction = queue->transactions[queue->head];
        queue->head = (queue->head + 1) % 50000;

        // Decrement the retransmission counter if necessary
        if (transaction->mac_pdu->retransmissions > 0) {
            queue->retransmissions--;
        }
    }

    // Release the mutex for synchronizing access to the queue
    sem_post(&queue->mutex);

    return transaction;
}

// Function to reset the retransmission counter
void reset_retransmissions(QUEUE_T *queue) {
    // Acquire the mutex for synchronizing access to the queue
    sem_wait(&queue->mutex);

    // Reset the retransmission counter
    queue->retransmissions = 0;

    // Release the mutex for synchronizing access to the queue
    sem_post(&queue->mutex);
}

// Function to get the current value of the retransmission counter
int get_retransmissions(QUEUE_T *queue) {
    int retransmissions;

    // Acquire the mutex for synchronizing access to the queue
    sem_wait(&queue->mutex);

    // Get the current value of the retransmission counter
    retransmissions = queue->retransmissions;

    // Release the mutex for synchronizing access to the queue
    sem_post(&queue->mutex);

    return retransmissions;
}
```
