        // Validate the RX_UE_INFORMATION_TAG and RNTI before adding them to the list
        if (rx_ue_information_tag > 0 && rnti > 0) {
            list[i].rx_ue_information_tag = rx_ue_information_tag;
            list[i].rnti = rnti;
            list[i].crc_indication_rel8_tag = crc_indication_rel8_tag;
        } else {
            // Handle invalid inputs gracefully by skipping the current element and continuing with the next one
            continue;
        }
    }

