    for (int i = 0; i < num_network_interfaces; i++) {
        if (i + 1 > num_essential_interfaces) {
            // TODO: Replace this with actual code to purge the inactive interfaces
            network_interfaces[i].id = -1;
        }
    }
}

// Function to balance the trade-off between memory usage and data freshness, possibly by setting configurable thresholds for data age and activity levels
void balance_memory_usage() {
    // TODO: Replace this with actual code to determine which interfaces are stale and need to be purged
    int num_stale_interfaces = 0;
    for (int i = 0; i < num_network_interfaces; i++) {
        if (network_interfaces[i].latency > 10.0) {
            // TODO: Replace this with actual code to purge the stale interfaces
            network_interfaces[i].id = -1;
            num_stale_interfaces++;
        }
    }
}

// Function to handle potential memory allocation failures gracefully and includes bounds checking to prevent out-of-bounds access
void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        printf("Error: Failed to allocate memory\n");
        return NULL;
    }
    return ptr;
}

// Function to handle potential memory allocation failures gracefully and includes bounds checking to prevent out-of-bounds access
void safe_free(void* ptr) {
    if (ptr) {
        free(ptr);
    }
}
