int processAndFilterTransactions(LTE_RRC_UECONTEXT *transactions, int num_transactions) {
    // Initialize metrics for tracking transaction processing time and weighted sum
    long total_processing_time = 0;
    double total_weighted_sum = 0.0;

    // Iterate over each transaction and filter based on age, frequency, and priority
    for (int i = 0; i < num_transactions; i++) {
        LTE_RRC_UECONTEXT *transaction = &transactions[i];

        // Calculate the weighted sum of the transaction's SIB tags based on their priority levels
        double weighted_sum = 0.0;
        for (int j = 0; j < MAX_NUM_OF_SIBS; j++) {
            if (transaction->sibs[j].priority_level > 0) {
                weighted_sum += transaction->sibs[j].priority_level * (double)(time(NULL) - transaction->sibs[j].timestamp);
            }
        }

        // Update metrics and select the most relevant transaction based on its weighted sum
        total_processing_time += time(NULL) - transaction->timestamp;
        total_weighted_sum += weighted_sum;
        if (weighted_sum > 0.0 && weighted_sum > total_weighted_sum) {
            return i;
        }
    }

    // If no relevant transactions were found, return -1
    return -1;
}

int main() {
