            transactions[i].sibs[j].integrity_check_value[INTEGRITY_CHECK_VALUE_SIZE - 1] = rand() % 256;
            transactions[i].sibs[j].priority_level = rand() % PRIORITY_LEVELS + MIN_PRIORITY;
        }
    }

    // Process and filter the transactions
