#include <stdlib.h>
#include <string.h>
#include <stdio.h>

// Define the structure to hold the CRC indication data
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the dynamic array to hold the list of CRC indications
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t count;
} NFAPI_CRC_INDICATION_LIST_T;

// Define the slab allocator to manage memory for the dynamic array
typedef struct {
    void* slabs[1024]; // 1024 slabs of 64KB each
    size_t used;      // number of bytes used in the slabs
} NFAPI_CRC_INDICATION_SLAB_ALLOCATOR_T;

// Define the pool allocator to manage memory for the dynamic array
typedef struct {
    void* pools[1024]; // 1024 pools of 64KB each
    size_t used;      // number of bytes used in the pools
} NFAPI_CRC_INDICATION_POOL_ALLOCATOR_T;

// Define the logging mechanism to record all operations
typedef struct {
    FILE* logfile;
    char* buffer;
    size_t capacity;
    size_t count;
} NFAPI_CRC_INDICATION_LOGGING_T;

// Function to initialize the dynamic array and slab allocator
void nfapi_crc_indication_init(NFAPI_CRC_INDICATION_LIST_T* list, size_t capacity) {
    // Initialize the dynamic array with a null pointer and zero count
    list->data = NULL;
    list->count = 0;

    // Initialize the slab allocator with a null pointer and zero used bytes
    NFAPI_CRC_INDICATION_SLAB_ALLOCATOR_T* allocator = (NFAPI_CRC_INDICATION_SLAB_ALLOCATOR_T*)malloc(sizeof(NFAPI_CRC_INDICATION_SLAB_ALLOCATOR_T));
    allocator->slabs[0] = NULL;
    allocator->used = 0;
}

// Function to add a new CRC indication to the dynamic array
void nfapi_crc_indication_add(NFAPI_CRC_INDICATION_LIST_T* list, uint16_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    // Check if the dynamic array needs to be resized
    if (list->count == list->capacity) {
        // Resize the dynamic array by 50%
        size_t new_capacity = list->capacity * 1.5;
        NFAPI_CRC_INDICATION_PDU_T* new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_data == NULL) {
            // Handle memory allocation failure
            return;
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }

    // Calculate the CRC flag based on the RX_UE_INFORMATION_TAG and RNTI
    uint8_t CRC_INDICATION_REL8_TAG = calculate_crc(RX_UE_INFORMATION_TAG, RNTI);

    // Add a new element to the dynamic array
    list->data[list->count].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    list->data[list->count].RNTI = RNTI;
    list->data[list->count].CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    list->count++;
}

// Function to calculate the CRC flag based on the RX_UE_INFORMATION_TAG and RNTI
uint8_t calculate_crc(uint16_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    // Calculate the checksum over the fields of the RX_UE_INFORMATION_TAG structure
    uint32_t checksum = 0;
    for (int i = 0; i < sizeof(RX_UE_INFORMATION_TAG); i++) {
        checksum += ((uint8_t*)&RX_UE_INFORMATION_TAG)[i];
    }

    // Calculate the checksum over the fields of the RNTI structure
    for (int i = 0; i < sizeof(RNTI); i++) {
        checksum += ((uint8_t*)&RNTI)[i];
    }

    // Set the CRC flag based on the checksum
    return checksum % 2 == 0 ? 1 : 0;
}

// Function to free the memory allocated for the dynamic array and slab allocator
void nfapi_crc_indication_free(NFAPI_CRC_INDICATION_LIST_T* list) {
    // Free the memory allocated for the dynamic array
    free(list->data);

    // Free the memory allocated for the slab allocator
    free(list->slabs);
}

// Function to log all operations performed on the dynamic array
void nfapi_crc_indication_log(NFAPI_CRC_INDICATION_LIST_T* list, NFAPI_CRC_INDICATION_LOGGING_T* logging) {
    // Check if the logging buffer is full
    if (logging->count == logging->capacity) {
        // Flush the logging buffer to disk
        fwrite(logging->buffer, sizeof(char), logging->count, logging->logfile);
        logging->count = 0;
    }

    // Log the operation type and timestamp
    char* log_entry = (char*)malloc(sizeof(char) * 128);
    sprintf(log_entry, "%s %lu\n", "CRC Indication", time(NULL));
    logging->buffer[logging->count++] = log_entry;
}
