    CACHE_ENTRY_T *entries;
    size_t count;
} CACHE_DATA_T;

// Define the mutex for synchronizing access to the list and cache
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Define the function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_LIST_T *create_crc_indication_list(size_t N) {
    // Allocate memory for the list
    NFAPI_CRC_INDICATION_LIST_T *list = malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    if (list == NULL) {
        return NULL;
    }

    // Initialize the count to zero
    list->count = 0;

    // Allocate memory for the PDUs
    list->pdu = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list->pdu == NULL) {
        free(list);
        return NULL;
    }

    // Initialize the cache data structure
    CACHE_DATA_T *cache = malloc(sizeof(CACHE_DATA_T));
    if (cache == NULL) {
        free(list->pdu);
        free(list);
        return NULL;
    }
    cache->count = 0;
    cache->entries = malloc(CACHE_SIZE * sizeof(CACHE_ENTRY_T));
    if (cache->entries == NULL) {
        free(cache);
        free(list->pdu);
        free(list);
        return NULL;
    }

    // Generate the RNTIs and CRCFLAGS for each PDU
    size_t i = 0;
    while (i < N) {
        // Generate a random RNTI within the specified range
        uint32_t rnti = rand() % (MAX_RNTI - MIN_RNTI + 1) + MIN_RNTI;

        // Check if the RNTI is already in the cache
        bool found = false;
        for (size_t j = 0; j < cache->count; j++) {
            if (cache->entries[j].RNTI == rnti) {
                found = true;
                break;
            }
        }

        // If the RNTI is not in the cache, generate a CRCFLAG based on the checksum algorithm
        uint8_t crcflag = 0;
        if (!found) {
            char *data = malloc(sizeof(uint16_t) + sizeof(uint32_t));
            memcpy(data, &list->pdu[i].RX_UE_INFORMATION_TAG, sizeof(uint16_t));
            memcpy(data + sizeof(uint16_t), &rnti, sizeof(uint32_t));
            crcflag = calculate_checksum(CHECKSUM_ALGORITHM, data, sizeof(uint16_t) + sizeof(uint32_t));
            free(data);
        } else {
            // If the RNTI is in the cache, retrieve the CRCFLAG from the cache
            crcflag = cache->entries[j].CRCFLAG;
        }

        // Add the PDU to the list and cache
        list->pdu[i].RX_UE_INFORMATION_TAG = rnti;
        list->pdu[i].RNTI = rnti;
        list->pdu[i].CRCFLAG = crcflag;
        cache->entries[cache->count++] = (CACHE_ENTRY_T) {rnti, crcflag};

        // Increment the count and check for edge cases
        i++;
    }

    return list;
}

// Define the function to calculate a checksum using the specified algorithm
uint8_t calculate_checksum(const char *algorithm, const void *data, size_t length) {
    // Check if the algorithm is supported
    if (strcmp(algorithm, "CRC-16") == 0) {
        return crc16(data, length);
    } else {
        printf("Unsupported checksum algorithm: %s\n", algorithm);
        return 0;
    }
}

// Define the function to generate a random RNTI within the specified range
uint32_t rand_rnti(void) {
    return rand() % (MAX_RNTI - MIN_RNTI + 1) + MIN_RNTI;
}

// Define the function to handle concurrent access from multiple threads safely
void *create_crc_indication_list_thread(void *arg) {
    // Lock the list mutex
    pthread_mutex_lock(&list_mutex);

    // Create the list of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_LIST_T *list = create_crc_indication_list(N);

    // Unlock the list mutex
    pthread_mutex_unlock(&list_mutex);

    return NULL;
}
