// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the maximum size of the list
#define MAX_LIST_SIZE 1000

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* create_and_populate_list(int num_ues) {
    // Allocate memory for the list
    NFAPI_CRC_INDICATION_PDU_T *list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_ues);
    if (!list) {
        printf("Error: Failed to allocate memory for the list\n");
        return NULL;
    }

    // Initialize the list size
    int list_size = 0;

    // Loop through each UE and populate the list
    for (int i = 0; i < num_ues; i++) {
        // Generate a random RX_UE_INFORMATION_TAG
        RX_UE_INFORMATION_TAG rx_ue_information = generate_rx_ue_information();

        // Generate a random RNTI
        RNTI rnti = generate_rnti();

        // Generate a random CRC_INDICATION_REL8_TAG with a randomly set CRCFLAG
        CRC_INDICATION_REL8_TAG crc_indication_rel8 = generate_crc_indication_rel8(rnti);

        // Validate the structure before adding it to the list
        if (validate_structure(rx_ue_information, rnti, crc_indication_rel8)) {
            // Add the structure to the list
            list[list_size].rx_ue_information = rx_ue_information;
            list[list_size].rnti = rnti;
            list[list_size].crc_indication_rel8 = crc_indication_rel8;
            list_size++;
        } else {
            // Skip this entry and continue populating the list
            printf("Skipping invalid structure\n");
        }
    }

    // Monitor the list size and ensure it does not exceed the maximum limit set by the user
    if (list_size > MAX_LIST_SIZE) {
        // Purge less critical entries to make room for recent data
        purge_entries(list, list_size - MAX_LIST_SIZE);
    }

    return list;
}

// Function to generate a random RX_UE_INFORMATION_TAG
RX_UE_INFORMATION_TAG generate_rx_ue_information() {
    // Generate a random RX_UE_INFORMATION_TAG with a randomly set RNTI and CRC_INDICATION_REL8_TAG
    RX_UE_INFORMATION_TAG rx_ue_information;
    rx_ue_information.rnti = generate_rnti();
    rx_ue_information.crc_indication_rel8 = generate_crc_indication_rel8(rx_ue_information.rnti);
    return rx_ue_information;
}

// Function to generate a random RNTI
RNTI generate_rnti() {
    // Generate a random RNTI with a randomly set value between 0 and 65535
    RNTI rnti = (RNTI)rand() % 65536;
    return rnti;
}

// Function to generate a random CRC_INDICATION_REL8_TAG with a randomly set CRCFLAG
CRC_INDICATION_REL8_TAG generate_crc_indication_rel8(RNTI rnti) {
    // Generate a random CRC_INDICATION_REL8_TAG with a randomly set CRCFLAG
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
    crc_indication_rel8.rnti = rnti;
    crc_indication_rel8.crc_flag = (bool)rand() % 2;
    return crc_indication_rel8;
}

// Function to validate the structure before adding it to the list
bool validate_structure(RX_UE_INFORMATION_TAG rx_ue_information, RNTI rnti, CRC_INDICATION_REL8_TAG crc_indication_rel8) {
    // Validate the structure by checking if the RNTI and CRCFLAG are valid
    return (rx_ue_information.rnti == rnti && crc_indication_rel8.crc_flag);
}

// Function to purge less critical entries from the list
void purge_entries(NFAPI_CRC_INDICATION_PDU_T *list, int num_entries) {
    // Loop through each entry and check if it is less critical than the others
    for (int i = 0; i < num_entries; i++) {
        // If the entry is less critical, remove it from the list
        if (is_less_critical(list[i])) {
            memmove(&list[i], &list[i + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (num_entries - i));
            num_entries--;
        }
    }
}

// Function to check if an entry is less critical than the others
bool is_less_critical(NFAPI_CRC_INDICATION_PDU_T entry) {
    // Check if the entry has a lower RNTI value or a higher CRCFLAG value
    return (entry.rnti < list[0].rnti || entry.crc_indication_rel8.crc_flag > list[0].crc_indication_rel8.crc_flag);
}
```
