// Function to resolve a given hostname to its IP address using standard library functions
int resolve_hostname(char *hostname, u_char ip[]) {
    // Initialize the DNS resolver
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    // Resolve the hostname to an IP address
    int status = getaddrinfo(hostname, NULL, &hints, &res);
    if (status != 0) {
        fprintf(stderr, "Failed to resolve hostname: %s\n", gai_strerror(status));
        return -1;
    }

    // Copy the IP address to the output parameter
    memcpy(ip, res->ai_addr, 4);

    // Free the memory allocated by getaddrinfo()
    freeaddrinfo(res);

    return 0;
}

