    pthread_mutex_lock(&cache->mutex);

    // Check if the IP address is already cached
    for (int i = 0; i < cache->size; i++) {
        if (strcmp(cache->pdu[i].hostname, hostname) == 0) {
            memcpy(ip, cache->pdu[i].ip, 4);
            break;
