        if (status == 0) {
            // Add the IP address to the cache
            NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pdu->hostname = hostname;
            memcpy(pdu->ip, ip, 4);
            cache->size++;
            cache->pdu = realloc(cache->pdu, cache->size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            cache->pdu[i] = pdu;
        } else {
            // Handle the error by returning an appropriate error code
            perror("Failed to resolve hostname");
            return NULL;
