// Function to handle API request failures, including retry mechanisms with exponential backoff and circuit breakers to prevent overloading the API under transient failures
void* handle_api_request(void *args) {
    // Cast the input argument to a pointer of type CACHE
    CACHE *cache = (CACHE*)args;

    // Initialize the retry mechanism with an exponential backoff and circuit breaker
    int retries = 0;
    while (retries < MAX_RETRIES) {
        // Make the API request
        int status = make_api_request(cache->pdu);
        if (status == 0) {
            // Handle the success case by returning the response
            return cache->pdu;
        } else {
            // Handle the error case by retrying with an exponential backoff and circuit breaker
            retries++;
            sleep(pow(2, retries));
            if (retries >= MAX_RETRIES) {
                perror("Failed to make API request");
                return NULL;
            }
        }
    }
}

