char* trimAndLimit(const char* str, int size_limit) {
    // Check for null pointer or empty string
    if (str == NULL || *str == '\0') {
        return NULL;
    }

    // Calculate the length of the input string
    int len = strlen(str);

    // Truncate the string to fit within the size limit
    char* trimmed_str = (char*)malloc(size_limit + 1);
    memcpy(trimmed_str, str, size_limit);
    trimmed_str[size_limit] = '\0';

    // Append a space instead of a null terminator if the string is exactly at the size limit
    if (len == size_limit) {
        trimmed_str[size_limit - 1] = ' ';
    }

    return trimmed_str;
}
