    // Allocate memory for the hash table and initialize it to NULL
    band_table_lock = (pthread_mutex_t *)malloc(sizeof(pthread_mutex_t) * num_bands);
    band_table = (band_info_t **)malloc(sizeof(band_info_t *) * num_bands);
    for (uint32_t i = 0; i < num_bands; i++) {
