// Add a new band to the library with a given ID and center frequency
void add_band(uint32_t band_id, float center_frequency) {
    // Acquire the lock for the hash table
    pthread_mutex_lock(&band_table_lock[band_id % num_bands]);

    // Check if a band with the given ID already exists
    if (band_table[band_id] != NULL) {
        printf("Band with ID %u already exists\n", band_id);
        pthread_mutex_unlock(&band_table_lock[band_id % num_bands]);
        return;
    }

    // Allocate memory for the new band information structure
    band_info_t *new_band = (band_info_t *)malloc(sizeof(band_info_t));
    if (new_band == NULL) {
        printf("Failed to allocate memory for new band\n");
        pthread_mutex_unlock(&band_table_lock[band_id % num_bands]);
        return;
    }

    // Initialize the new band information structure
    new_band->band_id = band_id;
    new_band->center_frequency = center_frequency;

    // Add the new band to the hash table
    band_table[band_id] = new_band;

    // Release the lock for the hash table
    pthread_mutex_unlock(&band_table_lock[band_id % num_bands]);
}

