    // Acquire the lock for the hash table
    pthread_mutex_lock(&band_table_lock[band_id % num_bands]);

    // Check if a band with the given ID exists
    if (band_table[band_id] == NULL) {
        printf("Band with ID %u does not exist\n", band_id);
        pthread_mutex_unlock(&band_table_lock[band_id % num_bands]);
        return;
    }

    // Free the memory for the band information structure
    free(band_table[band_id]);
    band_table[band_id] = NULL;

    // Release the lock for the hash table
    pthread_mutex_unlock(&band_table_lock[band_id % num_bands]);
}

