void process_file(char* filename, int max_records) {
    // Open the file in read mode
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return;
    }

    // Define an array of records with a maximum size of 10,000 elements
    Record *records = malloc(max_records * sizeof(Record));
    if (records == NULL) {
        printf("Error: unable to allocate memory for records\n");
        fclose(file);
        return;
    }

    // Initialize the array of records with random values within a specified range
    srand(time(NULL));
    for (int i = 0; i < max_records; i++) {
        records[i].integer_field = rand() % 100 + 1;
        records[i].offset_ptr = NULL;
    }

    // Process each line of the file, calculating the average of the last two numerical fields and inserting it into the final column
    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    while ((read = getline(&line, &len, file)) != -1) {
        // Split the line into columns using whitespace as a delimiter
        char **columns = strtok(line, " ");
        if (columns == NULL) {
            printf("Error: unable to split line %d\n", i);
            break;
        }

        // Calculate the average of the last two numerical fields
        int num1 = atoi(columns[i - 2]);
        int num2 = atoi(columns[i - 1]);
        float average = (num1 + num2) / 2.0;

        // Insert the average into the final column of the record
        records[i].integer_field = average;

        // Free the memory allocated for the previous offset pointer, if any
        if (records[i].offset_ptr != NULL) {
            free(records[i].offset_ptr);
        }

        // Allocate memory for the new offset pointer and assign it to the record
        records[i].offset_ptr = malloc(sizeof(long));
        if (records[i].offset_ptr == NULL) {
            printf("Error: unable to allocate memory for offset pointer\n");
            break;
        }
    }

    // Print the results and free the allocated memory
