        printf("%d %ld\n", records[i].integer_field, *(records[i].offset_ptr));
        if (records[i].offset_ptr != NULL) {
            free(records[i].offset_ptr);
        }
    }

    // Close the file and free the memory allocated for the line buffer
    fclose(file);
    free(line);
}

