// Add a data stream record to the queue
void addDataStreamRecord(QUEUE* queue, int streamId, int timestamp, float dataValue) {
    pthread_mutex_lock(&queue->mutex);
    while (queue->size == queue->capacity) {
        // Wait for space to become available in the queue
        pthread_cond_wait(&queue->cond, &queue->mutex);
    }
    queue->records[queue->size++] = (DATA_STREAM_RECORD){streamId, timestamp, dataValue};
    pthread_mutex_unlock(&queue->mutex);
}

// Remove a data stream record from the queue
void removeDataStreamRecord(QUEUE* queue) {
    pthread_mutex_lock(&queue->mutex);
    while (queue->size == 0) {
        // Wait for an element to become available in the queue
        pthread_cond_wait(&queue->cond, &queue->mutex);
    }
    DATA_STREAM_RECORD record = queue->records[--queue->size];
    pthread_mutex_unlock(&queue->mutex);
}

// Destroy the queue and free its resources
void destroyQueue(QUEUE* queue) {
    pthread_mutex_destroy(&queue->mutex);
    pthread_cond_destroy(&queue->cond);
    free(queue->records);
}
```
This implementation uses a thread-safe queue mechanism to facilitate efficient data processing under varying network conditions and hardware constraints. The `initQueue` function initializes the queue with a given capacity, while the `addDataStreamRecord` function adds a new record to the queue, waiting for space to become available if necessary. The `removeDataStreamRecord` function removes an element from the queue, waiting for an element to become available if necessary. Finally, the `destroyQueue` function destroys the queue and frees its resources.

