using System;
using System.Diagnostics;
using System.IO;
using System.Threading;

public static class WebsiteAdder
{
    private const int Timeout = 10 * 1000; // 10 seconds
    private const int RetryCount = 3;

    public static void AddWebsite(string directoryPath, string siteName)
    {
        if (!Directory.Exists(directoryPath))
        {
            throw new DirectoryNotFoundException($"The directory '{directoryPath}' does not exist.");
        }

        // Verify that a web.config file exists in the directory
        if (!File.Exists(Path.Combine(directoryPath, "web.config")))
        {
            throw new FileNotFoundException("A web.config file is required to add a website.", "web.config");
        }

        // Ensure that the directory has sufficient permissions for the operation
        if (!Directory.GetAccessControl(directoryPath).AreAccessRulesProtected)
        {
            throw new UnauthorizedAccessException("The directory does not have sufficient permissions to add a website.");
        }

        // Start the process and wait for it to complete or timeout
        var process = new Process();
        process.StartInfo.FileName = "cmd";
        process.StartInfo.Arguments = $"/c \"cd {directoryPath} && dotnet run --project {siteName}\"";
        process.StartInfo.UseShellExecute = false;
        process.StartInfo.RedirectStandardOutput = true;
        process.StartInfo.CreateNoWindow = true;

        var output = new StringBuilder();
        var error = new StringBuilder();

        using (var outputWaitHandle = new AutoResetEvent(false))
        using (var errorWaitHandle = new AutoResetEvent(false))
        {
            process.OutputDataReceived += (sender, e) =>
            {
                if (e.Data == null)
                {
                    outputWaitHandle.Set();
                }
                else
                {
                    output.AppendLine(e.Data);
                }
            };
            process.ErrorDataReceived += (sender, e) =>
            {
                if (e.Data == null)
                {
                    errorWaitHandle.Set();
                }
                else
                {
                    error.AppendLine(e.Data);
                }
            };

            process.Start();

            process.BeginOutputReadLine();
            process.BeginErrorReadLine();

            var exited = process.WaitForExit(Timeout);
            if (!exited)
            {
                process.Kill();
            }

            outputWaitHandle.WaitOne();
            errorWaitHandle.WaitOne();
        }

        // Log the operation details to a separate log file
        var logFilePath = Path.Combine(directoryPath, "website_addition.log");
        using (var writer = new StreamWriter(logFilePath))
        {
            writer.WriteLine($"Added website '{siteName}' to directory '{directoryPath}'.");
            writer.WriteLine("Output:");
            writer.Write(output.ToString());
            writer.WriteLine("Error:");
            writer.Write(error.ToString());
        }
    }
}
