// Initialize and manage a dynamic list of NFAPI_CRC_INDICATION_PDU_T structures within a network interface control point (NICP) module
void initializeAndManageNicpList(NICP_LIST* nicpList) {
    // Allocate memory for the list elements
    nicpList->elements = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * 10000);
    if (nicpList->elements == NULL) {
        // Handle allocation failure
        return;
    }

    // Initialize the list capacity and count
    nicpList->capacity = 10000;
    nicpList->count = 0;

    // Initialize the mutex for synchronizing access to the list
    pthread_mutex_init(&nicpListMutex, NULL);
}

// Add a new element to the list
void addElementToNicpList(NICP_LIST* nicpList, NFAPI_CRC_INDICATION_PDU_T* element) {
    // Acquire the mutex for synchronizing access to the list
    pthread_mutex_lock(&nicpListMutex);

