        // Handle invalid index condition
        return;
    }

    // Remove the element from the list
    NFAPI_CRC_INDICATION_PDU_T* removedElement = &nicpList->elements[index];
    memmove(&nicpList->elements[index], &nicpList->elements[index + 1], (nicpList->count - index) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    nicpList->count--;

    // Release the mutex for synchronizing access to the list
    pthread_mutex_unlock(&nicpListMutex);
}

// Get an element from the list by its index
NFAPI_CRC_INDICATION_PDU_T* getElementFromNicpList(NICP_LIST* nicpList, size_t index) {
    // Acquire the mutex for synchronizing access to the list
    pthread_mutex_lock(&nicpListMutex);

    // Check if the index is valid
    if (index >= nicpList->count) {
        // Handle invalid index condition
        return NULL;
    }

    // Get the element from the list
    NFAPI_CRC_INDICATION_PDU_T* element = &nicpList->elements[index];

    // Release the mutex for synchronizing access to the list
    pthread_mutex_unlock(&nicpListMutex);

    return element;
}

// Free the memory allocated for the list elements
void freeNicpList(NICP_LIST* nicpList) {
    // Acquire the mutex for synchronizing access to the list
    pthread_mutex_lock(&nicpListMutex);

