public class MessageProcessor
{
    private readonly string _key;
    private readonly string _iv;
    private readonly List<CustomObject> _decryptedMessages = new List<CustomObject>();

    public MessageProcessor(string key, string iv)
    {
        _key = key;
        _iv = iv;
    }

    public async Task ProcessMessageAsync(byte[] messageBytes)
    {
        try
        {
            // Decrypt the message using AES-GCM with the provided key and IV
            byte[] decryptedMessageBytes = await DecryptAsync(messageBytes, _key, _iv);

