            bool isValid = ValidateIntegrity(decryptedMessageBytes);

            if (isValid)
            {
                // Deserialize the decrypted message into a custom object
                CustomObject deserializedMessage = Deserialize(decryptedMessageBytes);

                // Add the deserialized message to the list of decrypted messages
                _decryptedMessages.Add(deserializedMessage);
            }
        }
        catch (Exception ex)
        {
            // Log the error and continue processing other messages
            Console.WriteLine($"Error processing message: {ex.Message}");
        }
    }

    private async Task<byte[]> DecryptAsync(byte[] encryptedBytes, string key, string iv)
    {
        try
        {
            // Use the third-party library to decrypt the message in chunks if necessary
            byte[] decryptedBytes = await ThirdPartyLibrary.DecryptAsync(encryptedBytes, key, iv);

            return decryptedBytes;
        }
        catch (Exception ex)
        {
            // Log the error and continue processing other messages
            Console.WriteLine($"Error decrypting message: {ex.Message}");

            return null;
        }
    }

    private bool ValidateIntegrity(byte[] decryptedBytes)
    {
        try
        {
            // Use the third-party library to validate the integrity of the decrypted message
            bool isValid = ThirdPartyLibrary.ValidateIntegrity(decryptedBytes);

            return isValid;
        }
        catch (Exception ex)
        {
            // Log the error and continue processing other messages
            Console.WriteLine($"Error validating integrity of decrypted message: {ex.Message}");

            return false;
        }
    }

    private CustomObject Deserialize(byte[] decryptedBytes)
    {
        try
        {
            // Use a JSON deserializer to deserialize the decrypted message into a custom object
            CustomObject deserializedMessage = JsonConvert.DeserializeObject<CustomObject>(decryptedBytes);

            return deserializedMessage;
        }
        catch (Exception ex)
        {
            // Log the error and continue processing other messages
            Console.WriteLine($"Error deserializing decrypted message: {ex.Message}");

            return null;
        }
    }

    public List<CustomObject> GetDecryptedMessages()
    {
        return _decryptedMessages;
    }
}
