// Define the structure for NetworkEvent
typedef struct {
    int EventTag;
    time_t Timestamp;
    void* DataBuffer;
} NetworkEvent;

// Function to initialize and populate an array of NetworkEvents
NetworkEvent* initAndPopulateNetworkEvents(int numEvents, size_t dataSize) {
    // Check if the input parameters are valid
    if (numEvents <= 0 || dataSize <= 0) {
        return NULL;
    }

    // Allocate memory for the array of NetworkEvents
    NetworkEvent* events = malloc(sizeof(NetworkEvent) * numEvents);
    if (!events) {
        return NULL;
    }

    // Initialize each NetworkEvent structure with a unique EventTag, Timestamp, and DataBuffer
    for (int i = 0; i < numEvents; i++) {
        events[i].EventTag = i + 1;
        events[i].Timestamp = time(NULL);
        events[i].DataBuffer = malloc(dataSize);
        if (!events[i].DataBuffer) {
            free(events);
            return NULL;
        }
    }

    // Populate the DataBuffer for each NetworkEvent with random data
    srand(time(NULL));
    for (int i = 0; i < numEvents; i++) {
        for (size_t j = 0; j < dataSize; j++) {
            events[i].DataBuffer[j] = rand() % 256;
        }
    }

    return events;
}
