#include <stdlib.h>
#include <string.h>
#include <stdio.h>

// Custom data structure for representing a network packet
typedef struct {
    uint32_t sourceIP;
    uint32_t destinationIP;
    uint8_t protocolType;
    uint16_t payloadLength;
} Packet;

// Dynamic array of packets
Packet* packets = NULL;
size_t numPackets = 0;

// Function to add a new packet to the dynamic array
void addPacket(Packet* packet) {
    // Reallocate memory for the dynamic array if necessary
    if (numPackets == 0 || numPackets >= packets->size) {
        size_t newSize = numPackets + 1;
        Packet* newPackets = realloc(packets, newSize * sizeof(Packet));
        if (!newPackets) {
            printf("Error: Failed to allocate memory for packet\n");
            return;
        }
        packets = newPackets;
    }

    // Copy the packet data into the dynamic array
    memcpy(&packets[numPackets], packet, sizeof(Packet));
    numPackets++;
}

// Function to remove a packet from the dynamic array by index
void removePacket(size_t index) {
    if (index >= numPackets) {
        printf("Error: Index out of bounds\n");
        return;
    }

    // Shift all packets after the specified index to the left
    for (size_t i = index + 1; i < numPackets; i++) {
        memcpy(&packets[i - 1], &packets[i], sizeof(Packet));
    }

    // Decrement the number of packets
    numPackets--;
}

// Function to update an existing packet in the dynamic array
void updatePacket(size_t index, Packet* newPacket) {
    if (index >= numPackets) {
        printf("Error: Index out of bounds\n");
        return;
    }

    // Copy the new packet data into the specified position in the dynamic array
    memcpy(&packets[index], newPacket, sizeof(Packet));
}

// Function to retrieve a packet from the dynamic array by index
Packet* getPacket(size_t index) {
    if (index >= numPackets) {
        printf("Error: Index out of bounds\n");
        return NULL;
    }

    // Return a pointer to the specified position in the dynamic array
    return &packets[index];
}

// Function to free all memory allocated for the dynamic array
void freePackets() {
    if (packets) {
        free(packets);
        packets = NULL;
    }
}
