import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.Logger;

public class DeserializationUtility {
    private static final Logger LOGGER = Logger.getLogger(DeserializationUtility.class.getName());
    private static final ConcurrentHashMap<Class<?>, ObjectInputStream> INPUT_STREAMS = new ConcurrentHashMap<>();

    public static <T> T deserialize(byte[] data, Class<T> clazz) {
        try (ByteArrayInputStream inputStream = new ByteArrayInputStream(data)) {
            ObjectInputStream objectInputStream = getObjectInputStream(clazz);
            return clazz.cast(objectInputStream.readObject());
        } catch (IOException | ClassNotFoundException e) {
            LOGGER.log(Level.SEVERE, "Error deserializing data", e);
            throw new RuntimeException("Error deserializing data: " + e.getMessage(), e);
        }
    }

    private static ObjectInputStream getObjectInputStream(Class<?> clazz) {
        return INPUT_STREAMS.computeIfAbsent(clazz, c -> {
            try {
                return new ObjectInputStream(new ByteArrayInputStream(new byte[0]));
            } catch (IOException e) {
                throw new RuntimeException("Error creating object input stream", e);
            }
        });
    }
}
```
