        if (!validate_mac_rx_buffer(&buffers[i])) {
            printf("Error: Failed to validate MAC RX buffer %d\n", i);
            free(buffers);
            return NULL;
        }
    }

    // Return the array of buffers to the caller
    return buffers;
}

// Function to generate a random MAC PDU header
MAC_PDU_HEADER_T generate_random_mac_pdu_header() {
    // Generate a random MAC address for the source and destination
    uint8_t src_addr[6];
    uint8_t dst_addr[6];
    for (int i = 0; i < 6; i++) {
        src_addr[i] = rand() % 256;
        dst_addr[i] = rand() % 256;
    }

    // Generate a random MAC PDU type and subtype
    uint8_t pdu_type = rand() % 256;
    uint8_t pdu_subtype = rand() % 256;

    // Create the MAC PDU header structure
    MAC_PDU_HEADER_T header;
    header.src_addr = src_addr;
    header.dst_addr = dst_addr;
    header.pdu_type = pdu_type;
    header.pdu_subtype = pdu_subtype;

    return header;
}

// Function to validate a MAC RX buffer
bool validate_mac_rx_buffer(MAC_RX_BUFFER_STRUCT* buffer) {
    // Check that the buffer is not NULL
    if (!buffer) {
        printf("Error: Buffer is NULL\n");
        return false;
    }

    // Check that the header is valid
    if (!validate_mac_pdu_header(&buffer->header)) {
        printf("Error: Invalid MAC PDU header in buffer\n");
        return false;
    }

    // Check that the buffer is not empty
    if (buffer->buffer.length == 0) {
        printf("Error: Buffer is empty\n");
        return false;
    }

    // Check that the buffer is properly aligned
    if ((uintptr_t)buffer->buffer.data % 4 != 0) {
        printf("Error: Buffer is not properly aligned\n");
        return false;
    }

    // Check that the buffer has a valid length
    if (buffer->buffer.length > MAX_MAC_PDU_LENGTH) {
        printf("Error: Buffer length exceeds maximum allowed value\n");
        return false;
    }

    // Check that the buffer is not corrupted
    for (int i = 0; i < buffer->buffer.length; i++) {
        if (buffer->buffer.data[i] == 0xFF) {
            printf("Error: Buffer is corrupted\n");
            return false;
        }
    }

    // If all checks pass, the buffer is valid
    return true;
}
