    for (int i = 0; i < numEvents; i++) {
        events[i].eventTag = EVENT_TAG_UNKNOWN;
        events[i].timestamp = 0;
        events[i].dataBuffer = NULL;
    }

    // Allocate memory for the DataBuffers
    int totalDataSize = 0;
    for (int i = 0; i < numEvents; i++) {
        int dataSize = rand() % maxDataSize + 1;
        if (totalDataSize + dataSize > OVERALL_LIMIT) {
            fprintf(stderr, "Total data size exceeds the limit\n");
            free(events);
            return NULL;
        }
        events[i].dataBuffer = malloc(dataSize);
        if (events[i].dataBuffer == NULL) {
            fprintf(stderr, "Failed to allocate memory for DataBuffer\n");
            free(events);
            return NULL;
        }
        totalDataSize += dataSize;
    }

    // Integrate with an external data source to fetch binary data for some events
