['Here is an example implementation of the command-line tool using Rust and Tokio:
```rust
use std::collections::HashMap;
use std::sync::Arc;
use tokio::task::JoinHandle;
use tokio::time::{Duration, Instant};

struct Operation {
    name: String,
    latency: Duration,
    resource_usage: ResourceUsage,
}

enum ResourceUsage {
    Low,
    Medium,
    High,
}

struct Command {
    name: String,
    args: Vec<String>,
}

impl Command {
    fn new(name: &str) -> Self {
        Self {
            name: name.to_string(),
            args: vec![],
        }
    }

    fn add_arg(&mut self, arg: String) {
        self.args.push(arg);
    }
}

struct OperationManager {
    operations: HashMap<String, JoinHandle>,
    current_operation: Option<JoinHandle>,
}

impl OperationManager {
    fn new() -> Self {
        Self {
            operations: HashMap::new(),
            current_operation: None,
        }
    }

    fn add_operation(&mut self, name: String, latency: Duration, resource_usage: ResourceUsage) {
        let handle = tokio::spawn(async move {
            // Implement the operation logic here
            println!("Operation {} started", name);
            let start = Instant::now();
            while start.elapsed() < latency {
                tokio::time::sleep(Duration::from_millis(10)).await;
            }
            println!("Operation {} completed", name);
        });
        self.operations.insert(name, handle);
    }

    fn list(&self) -> Vec<String> {
        self.operations.keys().cloned().collect()
    }

    fn info(&self, name: &str) -> Option<Operation> {
        let op = self.operations.get(name)?;
        Some(Operation {
            name: name.to_string(),
            latency: Duration::from_secs(10),
            resource_usage: ResourceUsage::Low,
        })
    }

    fn execute(&mut self, name: &str) -> Result<(), String> {
        let op = self.operations.get(name)?;
        if self.current_operation.is_some() {
            return Err("Another operation is already running".to_string());
        }
        self.current_operation = Some(op.clone());
        Ok(())
    }
}

fn main() -> Result<(), String> {
    let mut manager = OperationManager::new();
    manager.add_operation("ping".to_string(), Duration::from_secs(10), ResourceUsage::Low);
    manager.add_operation("fetch".to_string(), Duration::from_secs(20), ResourceUsage::Medium);
    manager.add_operation("transform".to_string(), Duration::from_secs(30), ResourceUsage::High);

    let mut command = Command::new("list");
    manager.execute(&command)?;

    command = Command::new("info ping");
    manager.execute(&command)?;

    command = Command::new("execute ping");
    manager.execute(&command)?;

    Ok(())
}
```
This implementation uses a `HashMap` to store the operations and their corresponding join handles, allowing for efficient lookup and execution of operations. The `OperationManager` struct also maintains a reference to the currently running operation, which is used to implement the `execute` method.

The `main` function demonstrates how to use the command-line tool by adding three operations, listing them, getting information about one of them, and executing it. It also handles errors gracefully by returning informative error messages when appropriate.

Note that this is just an example implementation and may need to be modified based on specific requirements and constraints.']

