// Define the function to dynamically allocate memory for an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* allocate_crc_indication_pdu(size_t n) {
    // Check if the input value is valid
    if (n <= 0) {
        fprintf(stderr, "Invalid input value for N\n");
        return NULL;
    }

    // Allocate memory for the array of structures
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * n);
    if (!pdu) {
        fprintf(stderr, "Failed to allocate memory for the array of structures\n");
        return NULL;
    }

    // Initialize each structure with a valid RX_UE_INFORMATION_TAG, RNTI, and CRCFLAG
    for (size_t i = 0; i < n; ++i) {
        pdu[i].RX_UE_INFORMATION_TAG = rand() % UINT16_MAX;
        pdu[i].RNTI = rand() % UINT32_MAX;
        pdu[i].CRCFLAG = rand() % 256;
    }

    // Sort the array by RNTI and then by CRCFLAG in ascending order
    qsort(pdu, n, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare_crc_indication_pdu);

    return pdu;
}

// Define the comparator function for sorting the array of NFAPI_CRC_INDICATION_PDU_T structures by RNTI and then by CRCFLAG
int compare_crc_indication_pdu(const void* a, const void* b) {
    const NFAPI_CRC_INDICATION_PDU_T* pa = (const NFAPI_CRC_INDICATION_PDU_T*)a;
    const NFAPI_CRC_INDICATION_PDU_T* pb = (const NFAPI_CRC_INDICATION_PDU_T*)b;

    // Sort by RNTI first
    if (pa->RNTI < pb->RNTI) {
        return -1;
    } else if (pa->RNTI > pb->RNTI) {
        return 1;
    }

    // If the RNTIs are equal, sort by CRCFLAG in ascending order
    if (pa->CRCFLAG < pb->CRCFLAG) {
        return -1;
    } else if (pa->CRCFLAG > pb->CRCFLAG) {
        return 1;
    }

    // If all other criteria are equal, the structures are considered equal
    return 0;
}

// Define the function to free the memory allocated for the array of NFAPI_CRC_INDICATION_PDU_T structures
void free_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdu) {
        free(pdu);
    }
}
