// Define a linked list node to store the PDUs
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdu;
    struct Node *next;
} Node;

// Define a global variable to keep track of the head and tail nodes of the linked list
Node *head = NULL, *tail = NULL;

// Define a mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to dynamically manage the collection of NFAPI_CRC_INDICATION_PDU_T structures
void manage_crc_indication_pdus(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Check if the input parameter is null
    if (pdu == NULL) {
        printf("Invalid input parameter: pdu is null\n");
        return;
    }

    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&mutex);

    // Check if the head node is null, indicating an empty linked list
    if (head == NULL) {
        // Allocate memory for the new PDU and set it as the head node
        head = malloc(sizeof(Node));
        head->pdu = pdu;
        head->next = NULL;
        tail = head;
    } else {
        // Allocate memory for a new node and set its next pointer to the current tail node
        Node *new_node = malloc(sizeof(Node));
        new_node->pdu = pdu;
        new_node->next = NULL;
        tail->next = new_node;
        tail = new_node;
    }

    // Unlock the mutex to allow other threads to access the linked list
    pthread_mutex_unlock(&mutex);
}

// Function to deallocate memory for a given PDU
void deallocate_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Check if the input parameter is null
    if (pdu == NULL) {
        printf("Invalid input parameter: pdu is null\n");
        return;
    }

    // Lock the mutex to prevent race conditions
    pthread_mutex_lock(&mutex);

    // Find the node containing the given PDU and set its next pointer to NULL
    Node *current = head;
    while (current != NULL) {
        if (current->pdu == pdu) {
            current->next = NULL;
            break;
        }
        current = current->next;
    }

    // Deallocate memory for the given PDU and set its pointer to NULL
    free(pdu);
    pdu = NULL;

    // Unlock the mutex to allow other threads to access the linked list
    pthread_mutex_unlock(&mutex);
}
