// Function to calculate MD5 hash of a file
char* md5HashFile(const char* filePath) {
    // Open the file and create a hashlib.md5() object
    FILE* fp = fopen(filePath, "rb");
    if (fp == NULL) {
        printf("Error: unable to open file %s\n", filePath);
        return NULL;
    }
    hashlib_md5_t md5 = hashlib_md5_new();
    if (md5 == NULL) {
        printf("Error: unable to create MD5 object\n");
        fclose(fp);
        return NULL;
    }

    // Read the file in chunks and update the hash
    char buffer[1024];
    size_t bytesRead = 0;
    while ((bytesRead = fread(buffer, 1, sizeof(buffer), fp)) > 0) {
        hashlib_md5_update(md5, buffer, bytesRead);
    }

    // Get the hexdigest of the hash and return it
    char* hexdigest = hashlib_md5_hexdigest(md5);
    fclose(fp);
    hashlib_md5_free(md5);
    return hexdigest;
}

// Function to create and populate a dynamic array of UserSession structures
UserSession* createUserSessions(int numSessions) {
    // Allocate memory for the array of UserSession structures
    UserSession* sessions = (UserSession*)malloc(numSessions * sizeof(UserSession));
    if (sessions == NULL) {
