    for (int i = 0; i < numSessions; i++) {
        sessions[i].RNTI = rnti++;
        sessions[i].CRC_INDICATION_REL8_TAG = crcFlag++;
        sessions[i].dataBuffer = NULL;
    }

    return sessions;
}

