    size_t chunkSize = 1024;
    size_t totalChunks = (size_t)ceil((float)fileSize / chunkSize);
    for (int i = 0; i < numSessions; i++) {
        requests[i].filePath = filePath;
        requests[i].chunkSize = chunkSize;
        requests[i].totalChunks = totalChunks;
        requests[i].currentChunk = 0;
        requests[i].isLastChunk = false;
    }

    return requests;
}

