    UserSession* sessions = createUserSessions(numSessions);
    DataTransferRequest* requests = createDataTransferRequests(numSessions);
    EncryptionKey* keys = createEncryptionKeys(numSessions);

    // Initialize the concurrent access and retries
    int numRetries = 0;
    bool isLastChunk = false;

    // Loop until all sessions have completed their data transfer requests
    while (true) {
        // Handle retries and backoff strategies in case of network outages
        retryOrBackoff(numRetries, maxRetries);

        // Update the current chunk for each session
        for (int i = 0; i < numSessions; i++) {
            requests[i].currentChunk++;
            if (requests[i].currentChunk == requests[i].totalChunks) {
                isLastChunk = true;
            }
        }

        // Calculate the MD5 hash of each file chunk and update the UserSession structure
        for (int i = 0; i < numSessions; i++) {
            char* hexdigest = md5HashFile(requests[i].filePath);
            if (hexdigest == NULL) {
                printf("Error: unable to calculate MD5 hash of file %s\n", requests[i].filePath);
                continue;
            }
            sessions[i].dataBuffer = hexdigest;
        }

        // Encrypt the data buffer for each session using the corresponding EncryptionKey structure
