            char* encryptedData = encrypt(sessions[i].dataBuffer, keys[i].key);
            if (encryptedData == NULL) {
                printf("Error: unable to encrypt data buffer\n");
                continue;
            }
            sessions[i].dataBuffer = encryptedData;
