        bool isAllCompleted = true;
        for (int i = 0; i < numSessions; i++) {
            if (!isLastChunk) {
                isAllCompleted = false;
                break;
            }
        }

        // If all sessions have completed their data transfer requests, exit the loop
        if (isAllCompleted) {
            break;
        }
    }

    // Free the memory allocated for the dynamic arrays of UserSession, DataTransferRequest, and EncryptionKey structures
    free(sessions);
    free(requests);
    free(keys);
