// Define a mutex to ensure thread safety when accessing the list
static pthread_mutex_t crc_indication_list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Define a function to generate a random RNTI
uint16_t generate_random_rnti() {
    return (uint16_t)((rand_r(&seed) % 65536) + 1);
