// Define a function to add an NFAPI_CRC_INDICATION_PDU_T structure to the list
void add_crc_indication(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Acquire the mutex to ensure thread safety when accessing the list
    pthread_mutex_lock(&crc_indication_list_mutex);

    // Check if the list is full and needs to be resized
    if (crc_indication_count >= MAX_CRC_INDICATION_COUNT) {
        // Resize the list by doubling its size
        crc_indication_list = realloc(crc_indication_list, 2 * MAX_CRC_INDICATION_COUNT * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (crc_indication_list == NULL) {
