    if (pdu->rnti == 0) {
        pdu->rnti = generate_random_rnti();
    }

    // Add the structure to the list
    crc_indication_list[crc_indication_count++] = *pdu;

    // Release the mutex
    pthread_mutex_unlock(&crc_indication_list_mutex);
}

// Define a function to remove an NFAPI_CRC_INDICATION_PDU_T structure from the list
void remove_crc_indication(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Acquire the mutex to ensure thread safety when accessing the list
    pthread_mutex_lock(&crc_indication_list_mutex);

    // Find the structure in the list and remove it
    for (size_t i = 0; i < crc_indication_count; i++) {
        if (crc_indication_list[i].rnti == pdu->rnti) {
            // Remove the structure from the list
            memmove(&crc_indication_list[i], &crc_indication_list[i + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (crc_indication_count - i));
            crc_indication_count--;
            break;
        }
    }

    // Release the mutex
    pthread_mutex_unlock(&crc_indication_list_mutex);
}

// Define a function to manage and clean up resources when the list exceeds predefined thresholds
void manage_resources() {
    // Acquire the mutex to ensure thread safety when accessing the list
    pthread_mutex_lock(&crc_indication_list_mutex);

    // Check if the list needs to be resized
    if (crc_indication_count > MAX_CRC_INDICATION_COUNT / 2) {
        // Resize the list by half its size
        crc_indication_list = realloc(crc_indication_list, MAX_CRC_INDICATION_COUNT * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (crc_indication_list == NULL) {
