#define RECORD_THRESHOLD 1000

// Function to initialize memory for multiple data structures
void init_memory(int num_large_offsets, int num_keys, int num_records) {
    // Allocate memory for the large offset array
    large_offsets = (long *)malloc(num_large_offsets * sizeof(long));
    if (!large_offsets) {
        printf("Error: Failed to allocate memory for large offsets\n");
        return;
    }

    // Initialize the large offset array with random values within a specified range
    srand(time(NULL));
    for (int i = 0; i < num_large_offsets; i++) {
        large_offsets[i] = rand() % 1000000;
    }

    // Allocate memory for the key array
    keys = (int *)malloc(num_keys * sizeof(int));
    if (!keys) {
        printf("Error: Failed to allocate memory for keys\n");
        return;
    }

    // Initialize the key array with random values within a specified range
    srand(time(NULL));
    for (int i = 0; i < num_keys; i++) {
        keys[i] = rand() % 1000000;
    }

    // Allocate memory for the record array
    records = (record_t *)malloc(num_records * sizeof(record_t));
    if (!records) {
        printf("Error: Failed to allocate memory for records\n");
        return;
    }

    // Initialize the record array with random values within a specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % 1000000;
    }
}

// Function to resize the record array if necessary
void resize_records(int new_size) {
    // Check if the new size is greater than the current size
    if (new_size > RECORD_THRESHOLD) {
        // Allocate a new, larger array for the records
        record_t *new_records = (record_t *)malloc(new_size * sizeof(record_t));
        if (!new_records) {
            printf("Error: Failed to allocate memory for new records\n");
            return;
        }

        // Copy over all existing record values from the old array
        memcpy(new_records, records, RECORD_THRESHOLD * sizeof(record_t));

        // Free the old array and update the pointer to the new array
        free(records);
        records = new_records;
    }
}

// Function to handle memory allocation failures gracefully
void handle_memory_failure() {
