// Define the structure to hold the NFAPI_CRC_INDICATION_PDU_T data
typedef struct {
    int id;
    char* name;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a linked list node to store the structures
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

// Define a function to dynamically manage the list of structures
void manageList(int N) {
    // Check for invalid input values
    if (N < 0) {
        printf("Invalid input value: N must be non-negative\n");
        return;
    }

    // Initialize the head node and current node pointers
    Node* head = NULL;
    Node* curr = NULL;

    // Loop until all structures have been allocated
    for (int i = 0; i < N; i++) {
        // Allocate memory for a new structure
        NFAPI_CRC_INDICATION_PDU_T* data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (data == NULL) {
            printf("Memory allocation failed\n");
            break;
        }

        // Initialize the structure fields
        data->id = i + 1;
        data->name = malloc(sizeof(char) * 20);
        sprintf(data->name, "Structure %d", i + 1);

        // Add the new structure to the list
        if (head == NULL) {
            head = curr = malloc(sizeof(Node));
        } else {
            curr->next = malloc(sizeof(Node));
            curr = curr->next;
        }
        curr->data = *data;
    }

    // Free the allocated memory when no longer needed
    if (head != NULL) {
        Node* temp = head;
        while (temp != NULL) {
            free(temp->data.name);
            free(temp);
            temp = temp->next;
        }
    }
}

// Define a helper function to free allocated memory
void freeList() {
    Node* temp = head;
    while (temp != NULL) {
        free(temp->data.name);
        free(temp);
        temp = temp->next;
    }
}
