```java
import java.io.BufferedReader;
import java.io.File;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;

public class CommandExecutor {
    public static void main(String[] args) throws IOException {
        // Define the command to execute
        String command = "ls -l";
        // Define the working directory for the command
        File workingDirectory = new File("/home/user");
        // Define the file to delete before executing the command
        File fileToDelete = new File("file.txt");
        // Check if the file exists and delete it if necessary
        if (fileToDelete.exists()) {
            fileToDelete.delete();
        }
        // Execute the command using Runtime.getRuntime().exec(String, String, File)
        Process process = Runtime.getRuntime().exec(command, null, workingDirectory);
        // Capture the standard output and error streams of the command
        BufferedReader stdOut = new BufferedReader(new InputStreamReader(process.getInputStream()));
        BufferedReader stdErr = new BufferedReader(new InputStreamReader(process.getErrorStream()));
        // Read the standard output and error streams of the command
        List<String> stdOutLines = new ArrayList<>();
        List<String> stdErrLines = new ArrayList<>();
        String line;
        while ((line = stdOut.readLine()) != null) {
            stdOutLines.add(line);
        }
        while ((line = stdErr.readLine()) != null) {
            stdErrLines.add(line);
        }
        // Close the standard output and error streams of the command
        stdOut.close();
        stdErr.close();
        // Print the standard output and error streams of the command
        System.out.println("Standard Output:");
        for (String line : stdOutLines) {
            System.out.println(line);
        }
        System.out.println("Standard Error:");
        for (String line : stdErrLines) {
            System.out.println(line);
        }
    }
}
