void handleMemoryAndDataProcessing(int limit) {
    // Declare variables for the arrays and the record structure
    int *offsets = NULL;
    int *keys = NULL;
    record *records = NULL;
    int size = 0;

    // Read the records from standard input
    while (1) {
        // Check if the current size is less than the maximum size
        if (size < MAX_RECORDS) {
            // Allocate memory for a new record structure
            record *new_record = malloc(sizeof(record));
            if (new_record == NULL) {
                // If the allocation fails, log an error and return
                printf("Error: Failed to allocate memory for record\n");
                break;
            } else {
                // Add the new record structure to the array
                records = realloc(records, (size + 1) * sizeof(record));
                if (records == NULL) {
                    // If the reallocation fails, log an error and return
                    printf("Error: Failed to allocate memory for records\n");
                    break;
                } else {
                    records[size] = new_record;
                    size++;
                }
            }
        } else {
            // If the current size is equal to the maximum size, grow the arrays
            growArray(&offsets, &size);
            growArray(&keys, &size);
            growArray(&records, &size);
        }

        // Read a new record from standard input
        scanf("%d", &(records[size - 1]->RNTI));

        // Check if the RNTI value is valid
        if (records[size - 1]->RNTI > limit) {
            // If the RNTI value is not valid, free the memory for the record structure
            free(records[size - 1]);
            records = realloc(records, size * sizeof(record));
            size--;
        } else {
            // If the RNTI value is valid, add it to the arrays
            offsets[size - 1] = size - 1;
            keys[size - 1] = records[size - 1]->RNTI;
        }
    }

    // Find and return the record with the highest valid RNTI value
    int max_key = INT_MIN;
    for (int i = 0; i < size; i++) {
        if (keys[i] > max_key) {
            max_key = keys[i];
        }
    }
    record *max_record = NULL;
    for (int i = 0; i < size; i++) {
        if (keys[i] == max_key) {
            max_record = records[i];
            break;
        }
    }
    return max_record;
}

// Test the function with a sample input
int main() {
    // Define the limit for the RNTI values
    int limit = 100;

    // Call the function to handle memory and data processing
    record *max_record = handleMemoryAndDataProcessing(limit);

    // Print the result
    if (max_record != NULL) {
        printf("The highest valid RNTI value is %d\n", max_record->RNTI);
    } else {
        printf("No valid records found\n");
    }

    return 0;
}
