    size_t size_;
};

// Define the function for dynamically generating and populating a list of NFAPI_CRC_INDICATION_PDU_T structures
void generateNFAPICrcIndicationList(const char* data, size_t length) {
    // Initialize the hash map for storing RNTIs
    RNTI_HASH_MAP_T rntiMap[1024];
    memset(rntiMap, 0, sizeof(rntiMap));

    // Initialize the memory pool allocator
    MEMORY_POOL_ALLOCATOR_T* allocator = (MEMORY_POOL_ALLOCATOR_T*)malloc(sizeof(MEMORY_POOL_ALLOCATOR_T));
    allocator->memory = malloc(length);
    allocator->size = length;

    // Initialize the list of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* pduList = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * 1024);
    memset(pduList, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T) * 1024);

    // Lock the list of NFAPI_CRC_INDICATION_PDU_T structures for concurrent access
    pthread_spinlock_t lock;
    pthread_spin_init(&lock, PTHREAD_PROCESS_PRIVATE);

    // Iterate over the incoming data streams and populate the list of NFAPI_CRC_INDICATION_PDU_T structures
    for (size_t i = 0; i < length; i++) {
        // Parse the current entry in the data stream
        const char* entry = &data[i];
        uint16_t rnti = *(uint16_t*)entry;
        uint8_t crcIndication = *(uint8_t*)(entry + 2);

        // Check if the RNTI is already present in the hash map
        bool found = false;
        for (size_t j = 0; j < 1024; j++) {
            if (rntiMap[j].key == rnti) {
                found = true;
                break;
            }
        }

        // If the RNTI is not present in the hash map, add it and allocate a new NFAPI_CRC_INDICATION_PDU_T structure
        if (!found) {
            pthread_spin_lock(&lock);
            for (size_t j = 0; j < 1024; j++) {
                if (rntiMap[j].key == 0) {
                    rntiMap[j].key = rnti;
                    rntiMap[j].value = true;
                    break;
                }
            }
            pthread_spin_unlock(&lock);

            // Allocate a new NFAPI_CRC_INDICATION_PDU_T structure using the memory pool allocator
            SmartPointer* pdu = (SmartPointer*)malloc(sizeof(SmartPointer));
            pdu->memory = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pdu->size = sizeof(NFAPI_CRC_INDICATION_PDU_T);

            // Initialize the new NFAPI_CRC_INDICATION_PDU_T structure
            NFAPI_CRC_INDICATION_PDU_T* newPdu = (NFAPI_CRC_INDICATION_PDU_T*)pdu->getMemory();
            newPdu->rnti = rnti;
            newPdu->crcIndication = crcIndication;

            // Add the new NFAPI_CRC_INDICATION_PDU_T structure to the list
            pthread_spin_lock(&lock);
            for (size_t j = 0; j < 1024; j++) {
                if (pduList[j].rnti == 0) {
                    pduList[j] = *newPdu;
                    break;
                }
            }
            pthread_spin_unlock(&lock);
        }
    }

    // Release the lock on the list of NFAPI_CRC_INDICATION_PDU_T structures
    pthread_spin_destroy(&lock);

    // Clean up the memory pool allocator and the hash map
    free(allocator->memory);
    free(rntiMap);

    // Return the list of NFAPI_CRC_INDICATION_PDU_T structures
    return pduList;
}
