function generateWidgets(widgetConfigs) {
  const container = document.createElement("div");
  container.classList.add("widget-container");

  // Initialize widgets as individual components within the container
  for (const config of widgetConfigs) {
    const widget = createWidget(config);
    container.appendChild(widget);
  }

  return container;
}

function createWidget(config) {
  const widgetType = config.type;
  const title = config.title;
  const dataSource = config.dataSource;
  const options = config.options;

  // Create a new widget instance based on the specified type
  let widget;
  if (widgetType === "chart") {
    widget = createChartWidget(dataSource, options);
  } else if (widgetType === "table") {
    widget = createTableWidget(dataSource, options);
  } else {
    throw new Error(`Unsupported widget type: ${widgetType}`);
  }

  // Initialize the widget with its specified data and options
  widget.initialize(title, dataSource, options);

  return widget;
}

function createChartWidget(dataSource, options) {
  const chart = document.createElement("canvas");
  chart.classList.add("chart-widget");

  // Initialize the chart with its specified data and options
  const ctx = chart.getContext("2d");
  const chartInstance = new Chart(ctx, {
    type: "line",
    data: {
      labels: [],
      datasets: []
    },
    options: {}
  });

  // Update the chart with new data from the specified data source
  function updateChart() {
    const data = fetchData(dataSource);
    chartInstance.data = data;
    chartInstance.update();
  }

  return {
    initialize: (title, dataSource, options) => {
      chart.title = title;
      chart.dataSource = dataSource;
      chart.options = options;
      updateChart();
    },
    update: () => {
      updateChart();
    }
  };
}

function createTableWidget(dataSource, options) {
  const table = document.createElement("table");
  table.classList.add("table-widget");

  // Initialize the table with its specified data and options
  function updateTable() {
    const data = fetchData(dataSource);
    const rows = [];
    for (const row of data) {
      const tr = document.createElement("tr");
      for (const cell of row) {
        const td = document.createElement("td");
        td.textContent = cell;
        tr.appendChild(td);
      }
      rows.push(tr);
    }
    table.innerHTML = "";
    for (const row of rows) {
      table.appendChild(row);
    }
  }

  return {
    initialize: (title, dataSource, options) => {
      table.title = title;
      table.dataSource = dataSource;
      table.options = options;
      updateTable();
    },
    update: () => {
      updateTable();
    }
  };
}

function fetchData(dataSource) {
  // Fetch data from the specified data source asynchronously
  return new Promise((resolve, reject) => {
    const xhr = new XMLHttpRequest();
    xhr.open("GET", dataSource);
    xhr.onload = () => {
      if (xhr.status === 200) {
        resolve(JSON.parse(xhr.responseText));
      } else {
        reject(new Error(`Failed to fetch data from ${dataSource}`));
      }
    };
    xhr.onerror = () => {
      reject(new Error(`Network error while fetching data from ${dataSource}`));
    };
    xhr.send();
  });
}
```
