```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

// Define the structure to hold a notification
typedef struct {
    int id; // Unique identifier for the notification
    time_t timestamp; // Timestamp of the notification
    char* metadata; // Metadata tags associated with the notification
} Notification;

// Define the dynamic array data structure
typedef struct {
    Notification** notifications; // Array of pointers to notifications
    int size; // Current size of the array
    int capacity; // Maximum capacity of the array
} DynamicArray;

// Function to create a new dynamic array
DynamicArray* create_dynamic_array(int initial_capacity) {
    DynamicArray* arr = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!arr) {
        return NULL;
    }
    arr->notifications = (Notification**)malloc(initial_capacity * sizeof(Notification*));
    if (!arr->notifications) {
        free(arr);
        return NULL;
    }
    arr->size = 0;
    arr->capacity = initial_capacity;
    return arr;
}

// Function to add a new notification to the dynamic array
int add_notification(DynamicArray* arr, int id, time_t timestamp, char* metadata) {
    if (!arr || !metadata) {
        return -1;
    }
    // Check if the array is full and needs to be resized
    if (arr->size == arr->capacity) {
        int new_capacity = arr->capacity * 2;
        Notification** new_notifications = (Notification**)realloc(arr->notifications, new_capacity * sizeof(Notification*));
        if (!new_notifications) {
            return -1;
        }
        arr->notifications = new_notifications;
        arr->capacity = new_capacity;
    }
    // Create a new notification and add it to the array
    Notification* new_notification = (Notification*)malloc(sizeof(Notification));
    if (!new_notification) {
        return -1;
    }
    new_notification->id = id;
    new_notification->timestamp = timestamp;
    new_notification->metadata = metadata;
    arr->notifications[arr->size++] = new_notification;
    return 0;
}

// Function to retrieve a notification from the dynamic array by its ID
Notification* get_notification(DynamicArray* arr, int id) {
    if (!arr) {
        return NULL;
    }
    for (int i = 0; i < arr->size; i++) {
        Notification* notification = arr->notifications[i];
        if (notification->id == id) {
            return notification;
        }
    }
    return NULL;
}

// Function to retrieve all notifications from the dynamic array within a given time range
Notification** get_notifications(DynamicArray* arr, time_t start_time, time_t end_time) {
    if (!arr) {
        return NULL;
    }
    int count = 0;
    for (int i = 0; i < arr->size; i++) {
        Notification* notification = arr->notifications[i];
        if (notification->timestamp >= start_time && notification->timestamp <= end_time) {
            count++;
        }
    }
    Notification** notifications = (Notification**)malloc(count * sizeof(Notification*));
    if (!notifications) {
        return NULL;
    }
    int index = 0;
    for (int i = 0; i < arr->size; i++) {
        Notification* notification = arr->notifications[i];
        if (notification->timestamp >= start_time && notification->timestamp <= end_time) {
            notifications[index++] = notification;
        }
    }
    return notifications;
}

// Function to filter notifications by event type and time range
Notification** filter_notifications(DynamicArray* arr, char* event_type, time_t start_time, time_t end_time) {
    if (!arr || !event_type) {
        return NULL;
    }
    int count = 0;
    for (int i = 0; i < arr->size; i++) {
        Notification* notification = arr->notifications[i];
        if (notification->metadata && strcmp(notification->metadata, event_type) == 0 && notification->timestamp >= start_time && notification->timestamp <= end_time) {
            count++;
        }
    }
    Notification** notifications = (Notification**)malloc(count * sizeof(Notification*));
    if (!notifications) {
        return NULL;
    }
    int index = 0;
    for (int i = 0; i < arr->size; i++) {
        Notification* notification = arr->notifications[i];
        if (notification->metadata && strcmp(notification->metadata, event_type) == 0 && notification->timestamp >= start_time && notification->timestamp <= end_time) {
            notifications[index++] = notification;
        }
    }
    return notifications;
}

// Function to free the memory allocated for a dynamic array
void free_dynamic_array(DynamicArray* arr) {
    if (!arr) {
        return;
    }
    for (int i = 0; i < arr->size; i++) {
        Notification* notification = arr->notifications[i];
        free(notification);
    }
    free(arr->notifications);
    free(arr);
}
```
