DiskIOPerfMetrics* init_disk_io_perf_metrics(size_t max_devices, size_t max_timestamps) {
    // Allocate memory for the array of Disk I/O Performance Metrics structures
    DiskIOPerfMetrics** metrics = (DiskIOPerfMetrics**)malloc(max_devices * sizeof(DiskIOPerfMetrics*));
    if (!metrics) {
        fprintf(stderr, "Failed to allocate memory for disk I/O performance metrics\n");
        return NULL;
    }

    // Initialize each structure in the array with a device path and LUN
    for (size_t i = 0; i < max_devices; ++i) {
        metrics[i] = (DiskIOPerfMetrics*)malloc(sizeof(DiskIOPerfMetrics));
        if (!metrics[i]) {
            fprintf(stderr, "Failed to allocate memory for disk I/O performance metrics\n");
            return NULL;
        }
        metrics[i]->device_path = (char*)malloc(256 * sizeof(char));
        if (!metrics[i]->device_path) {
            fprintf(stderr, "Failed to allocate memory for disk I/O performance metrics\n");
            return NULL;
        }
        metrics[i]->lun = -1;
        metrics[i]->timestamps = (long*)malloc(max_timestamps * sizeof(long));
        if (!metrics[i]->timestamps) {
            fprintf(stderr, "Failed to allocate memory for disk I/O performance metrics\n");
            return NULL;
        }
        metrics[i]->timestamp_count = 0;
        metrics[i]->average_latency = -1.0;
    }

    // Return the array of Disk I/O Performance Metrics structures
    return metrics;
}

// Define a function to add a new timestamp to a Disk I/O Performance Metrics structure
void add_timestamp(DiskIOPerfMetrics* metrics, long timestamp) {
    // Check if the structure has reached its maximum capacity for timestamps
    if (metrics->timestamp_count == max_timestamps) {
        fprintf(stderr, "Maximum number of timestamps exceeded\n");
        return;
    }

    // Add the new timestamp to the structure
    metrics->timestamps[metrics->timestamp_count++] = timestamp;
}

// Define a function to calculate and store the average latency for each device
void calculate_average_latency(DiskIOPerfMetrics* metrics) {
    // Calculate the average latency for each device
    for (size_t i = 0; i < max_devices; ++i) {
        long sum = 0;
        size_t count = 0;
        for (size_t j = 0; j < metrics[i]->timestamp_count; ++j) {
            // Filter out invalid or out-of-order timestamps to maintain data integrity
            if (metrics[i]->timestamps[j] > 0) {
                sum += metrics[i]->timestamps[j];
                count++;
            }
        }
        if (count > 0) {
            metrics[i]->average_latency = (double)sum / (double)count;
        } else {
            metrics[i]->average_latency = -1.0;
        }
    }
}

// Define a function to handle memory allocation safely and efficiently
void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Failed to allocate memory\n");
        return NULL;
    }
    return ptr;
}

// Define a function to handle memory deallocation safely and efficiently
void safe_free(void* ptr) {
    free(ptr);
}
