// Function to calculate and store the average packet size for each interface
void calculate_packet_size(nic_statistics_t *nic_stats, int num_interfaces) {
    // Calculate the average packet size for each interface
    for (int i = 0; i < num_interfaces; i++) {
        nic_stats[i].packet_size = nic_stats[i].num_packets ? nic_stats[i].total_packet_size / nic_stats[i].num_packets : 0;
    }
}

// Function to validate the integrity of each CRC indication rel8 tag
void validate_crc_indication(nic_statistics_t *nic_stats, int num_interfaces) {
    // Validate the integrity of each CRC indication rel8 tag
    for (int i = 0; i < num_interfaces; i++) {
        if (!strcmp((*nic_stats)[i].packet_stats[(*nic_stats)[i].num_packets - 1].crc_indication_rel8_tag, "CRC_INDICATION_REL8")) {
            // If the CRC indication rel8 tag is valid, update the statistics
            (*nic_stats)[i].num_packets++;
            (*nic_stats)[i].total_packet_size += (*nic_stats)[i].packet_stats[(*nic_stats)[i].num_packets - 1].packet_size;
        } else {
            // If the CRC indication rel8 tag is invalid, discard the packet and update the statistics
            (*nic_stats)[i].num_packets--;
            (*nic_stats)[i].total_packet_size -= (*nic_stats)[i].packet_stats[(*nic_stats)[i].num_packets - 1].packet_size;
        }
    }
}

