const modules = {
  module1: {
    url: 'https://example.com/module1',
    dependencies: ['module2'],
    timeout: 5000, // 5 seconds
  },
  module2: {
    url: 'https://example.com/module2',
    dependencies: [],
    timeout: 3000, // 3 seconds
  },
  module3: {
    url: 'https://example.com/module3',
    dependencies: ['module1'],
    timeout: 10000, // 10 seconds
  },
};

const loadModule = (url) => {
  return new Promise((resolve, reject) => {
    const xhr = new XMLHttpRequest();
    xhr.open('GET', url);
    xhr.onload = () => {
      if (xhr.status === 200) {
        resolve(xhr.responseText);
      } else {
        reject(`Failed to load module ${url}`);
      }
    };
    xhr.ontimeout = () => {
      reject(`Timed out while loading module ${url}`);
    };
    xhr.send();
  });
};

const executeModule = (module) => {
  return new Promise((resolve, reject) => {
    const script = document.createElement('script');
    script.textContent = module;
    document.body.appendChild(script);
    script.onload = () => {
      resolve();
    };
    script.onerror = (event) => {
      reject(`Failed to execute module ${module}`);
    };
  });
};

const loadModules = async (modules, timeout) => {
  const promises = [];
  for (const module of modules) {
    promises.push(loadModule(module.url));
  }
  return Promise.all(promises).then((results) => {
    const loadedModules = {};
    results.forEach((result, index) => {
      loadedModules[modules[index].name] = result;
    });
    return loadedModules;
  }).catch((error) => {
    console.log(error);
    return null;
  });
};

const executeModules = async (modules, timeout) => {
  const promises = [];
  for (const module of modules) {
    promises.push(executeModule(module));
  }
  return Promise.all(promises).then((results) => {
    const executedModules = {};
    results.forEach((result, index) => {
      executedModules[modules[index].name] = result;
    });
    return executedModules;
  }).catch((error) => {
    console.log(error);
    return null;
  });
};

const loadAndExecuteModules = async (modules, timeout) => {
  const loadedModules = await loadModules(modules, timeout);
  if (!loadedModules) {
    return null;
  }
  const executedModules = await executeModules(loadedModules, timeout);
  if (!executedModules) {
    return null;
  }
  return executedModules;
};

const main = async () => {
  try {
    const modules = [
      { name: 'module1', url: 'https://example.com/module1' },
      { name: 'module2', url: 'https://example.com/module2' },
      { name: 'module3', url: 'https://example.com/module3' },
    ];
    const timeout = 5000; // 5 seconds
    const executedModules = await loadAndExecuteModules(modules, timeout);
    if (!executedModules) {
      console.log('Failed to execute modules');
      return;
    }
    console.log(`Executed modules: ${Object.keys(executedModules).join(', ')}`);
  } catch (error) {
    console.log(error);
  }
};

main();
