    size_t num_messages;
    pthread_mutex_t mutex;
} message_list_t;

// Function to generate a new message and add it to the list
void generate_message(message_list_t *list) {
    // Allocate memory for the new message
    taipei_message_t *new_message = malloc(sizeof(taipei_message_t));
    if (new_message == NULL) {
        return;
    }

    // Generate a unique GTP_TEID and UE_ID for the new message
    uint32_t gtp_teid = generate_gtp_teid();
    uint64_t ue_id = generate_ue_id();

    // Fill in the NAS_MESSAGE field with a random string
    char nas_message[1024];
    for (int i = 0; i < 1024; i++) {
        nas_message[i] = 'a' + rand() % 26;
    }

    // Fill in the rest of the fields with random data
    new_message->gtp_teid = gtp_teid;
    new_message->ue_id = ue_id;
    strcpy(new_message->nas_message, nas_message);

    // Lock the mutex to prevent concurrent access to the list
    pthread_mutex_lock(&list->mutex);

    // Add the new message to the end of the list
    list->messages = realloc(list->messages, (list->num_messages + 1) * sizeof(taipei_message_t));
    if (list->messages == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return;
    }
    list->messages[list->num_messages++] = new_message;

    // Unlock the mutex and return
    pthread_mutex_unlock(&list->mutex);
}

// Function to retrieve a message from the list by GTP_TEID
taipei_message_t *get_message(message_list_t *list, uint32_t gtp_teid) {
    // Lock the mutex to prevent concurrent access to the list
    pthread_mutex_lock(&list->mutex);

    // Iterate through the messages and find the one with the matching GTP_TEID
    for (int i = 0; i < list->num_messages; i++) {
        if (list->messages[i]->gtp_teid == gtp_teid) {
            taipei_message_t *message = list->messages[i];
            pthread_mutex_unlock(&list->mutex);
            return message;
        }
    }

    // If no matching message is found, return NULL
    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

// Function to delete a message from the list by GTP_TEID
void delete_message(message_list_t *list, uint32_t gtp_teid) {
    // Lock the mutex to prevent concurrent access to the list
    pthread_mutex_lock(&list->mutex);

    // Iterate through the messages and find the one with the matching GTP_TEID
    for (int i = 0; i < list->num_messages; i++) {
        if (list->messages[i]->gtp_teid == gtp_teid) {
            taipei_message_t *message = list->messages[i];
            free(message);
            list->messages[i] = NULL;
            break;
        }
    }

    // Update the number of messages and reallocate memory if necessary
    list->num_messages--;
    list->messages = realloc(list->messages, list->num_messages * sizeof(taipei_message_t));

    // Unlock the mutex and return
    pthread_mutex_unlock(&list->mutex);
}
