// Define the function to insert an element into the tree-based data structure
TreeNode *insert(TreeNode *tree, NFAPI_CRC_INDICATION_PDU_T *element) {
    // If the tree is empty, create a new node and return it
    if (tree == NULL) {
        TreeNode *newNode = (TreeNode *)malloc(sizeof(TreeNode));
        newNode->data = element;
        newNode->left = NULL;
        newNode->right = NULL;
        return newNode;
    }

    // If the element is less than the root node, insert it in the left subtree
    if (element->RNTI < tree->data->RNTI) {
        tree->left = insert(tree->left, element);
    } else {
        tree->right = insert(tree->right, element);
    }

    return tree;
}

// Define the function to free memory for the tree-based data structure
void freeTree(TreeNode *tree) {
    // If the tree is empty, do nothing
    if (tree == NULL) {
        return;
    }

    // Recursively free memory for the left and right subtrees
    freeTree(tree->left);
    freeTree(tree->right);

    // Free the node itself
