<?php
function updateClinicStatus($clinicId, $status, $lastModifiedIp, $lastModifiedDate) {
    // Connect to the database
    $db = new PDO('mysql:host=localhost;dbname=mydatabase', 'username', 'password');

    // Prepare the SQL query for updating the clinic status
    $sql = "UPDATE clinics SET status = :status, last_modified_ip = :lastModifiedIp, last_modified_date = :lastModifiedDate WHERE id = :clinicId";
    $stmt = $db->prepare($sql);

    // Bind the parameters to the SQL query
    $stmt->bindParam(':status', $status);
    $stmt->bindParam(':lastModifiedIp', $lastModifiedIp);
    $stmt->bindParam(':lastModifiedDate', $lastModifiedDate);
    $stmt->bindParam(':clinicId', $clinicId);

    // Execute the SQL query and check for errors
    if ($stmt->execute()) {
        // If the update was successful, send a notification to relevant stakeholders (if enabled)
        if ($status === 'critical' && $notificationPreference === 'enabled') {
            // Send a notification to the relevant stakeholders using an external API
            $apiResponse = sendNotification($clinicId);

            // If the API call was successful, log the success message
            if ($apiResponse['success']) {
                $logMessage = "Successfully sent notification for clinic ID {$clinicId}";
                logToDatabase($logMessage);
            } else {
                $logMessage = "Failed to send notification for clinic ID {$clinicId}: {$apiResponse['error']}";
                logToDatabase($logMessage);
            }
        }

        // Return a success message if the update was successful
        return 'Successfully updated clinic status';
    } else {
        // If the update failed, log the error and return an error message
        $errorMessage = "Failed to update clinic status: {$stmt->errorInfo()}";
        logToDatabase($errorMessage);
        return $errorMessage;
    }
}

// Send a notification to relevant stakeholders using an external API
function sendNotification($clinicId) {
    // Connect to the external API
    $api = new ExternalAPI('https://example.com/api');

    // Prepare the API request with the clinic ID and notification preference
    $request = [
        'method' => 'POST',
        'url' => '/notifications',
        'headers' => ['Content-Type: application/json'],
        'body' => json_encode(['clinicId' => $clinicId, 'notificationPreference' => 'enabled'])
    ];

    // Send the API request and check for errors
    $response = $api->request($request);
    if ($response['success']) {
        return ['success' => true];
    } else {
        return ['success' => false, 'error' => $response['error']];
    }
}

// Log a message to the database
function logToDatabase($message) {
    // Connect to the database
    $db = new PDO('mysql:host=localhost;dbname=mydatabase', 'username', 'password');

    // Prepare the SQL query for logging the message
    $sql = "INSERT INTO logs (message) VALUES (:message)";
    $stmt = $db->prepare($sql);

    // Bind the parameters to the SQL query
    $stmt->bindParam(':message', $message);

    // Execute the SQL query and check for errors
    if ($stmt->execute()) {
        return true;
    } else {
        return false;
    }
}
