#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include "nfapi_rx_frame.h"

typedef struct {
    NFAPI_RX_FRAME_PDU_T *pdu;
    int index;
} PDU_LIST_ENTRY_T;

typedef struct {
    PDU_LIST_ENTRY_T *head;
    PDU_LIST_ENTRY_T *tail;
    size_t count;
    pthread_mutex_t mutex;
} PDU_LIST_T;

void init_pdu_list(PDU_LIST_T *list) {
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

void add_pdu_to_list(PDU_LIST_T *list, NFAPI_RX_FRAME_PDU_T *pdu) {
    PDU_LIST_ENTRY_T *entry = malloc(sizeof(PDU_LIST_ENTRY_T));
    entry->pdu = pdu;
    entry->index = list->count++;
    if (list->head == NULL) {
        list->head = entry;
        list->tail = entry;
    } else {
        list->tail->next = entry;
        list->tail = entry;
    }
}

void remove_pdu_from_list(PDU_LIST_T *list, int index) {
    PDU_LIST_ENTRY_T *entry = list->head;
    while (entry != NULL && entry->index != index) {
        entry = entry->next;
    }
    if (entry == NULL) {
        return;
    }
    if (entry == list->head) {
        list->head = entry->next;
    }
    if (entry == list->tail) {
        list->tail = entry->prev;
    }
    free(entry);
}

void clear_pdu_list(PDU_LIST_T *list) {
    PDU_LIST_ENTRY_T *entry = list->head;
    while (entry != NULL) {
        PDU_LIST_ENTRY_T *next = entry->next;
        free(entry);
        entry = next;
    }
}

void destroy_pdu_list(PDU_LIST_T *list) {
    clear_pdu_list(list);
    pthread_mutex_destroy(&list->mutex);
}

NFAPI_RX_FRAME_PDU_T* get_pdu_from_list(PDU_LIST_T *list, int index) {
    PDU_LIST_ENTRY_T *entry = list->head;
    while (entry != NULL && entry->index != index) {
        entry = entry->next;
    }
    if (entry == NULL) {
        return NULL;
    }
    return entry->pdu;
}

