#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define structure for storing record data
typedef struct {
    int long_value;
    int int_value;
    double double_value;
} Record;

int main(int argc, char **argv) {
    // Check command line arguments
    if (argc < 2) {
        printf("Usage: %s [options] input_file1 [input_file2 ...]\n", argv[0]);
        return 1;
    }

    // Initialize variables for tracking file offsets and bytes read
    long total_bytes = 0;
    int num_files = argc - 1;
    int current_file = 0;

    // Initialize arrays for storing record data
    Record *records[num_files];
    for (int i = 0; i < num_files; i++) {
        records[i] = malloc(sizeof(Record) * 1000);
    }

    // Process each input file
    while (current_file < num_files) {
        FILE *input_file = fopen(argv[current_file + 1], "r");
        if (!input_file) {
            printf("Error: unable to open file %s\n", argv[current_file + 1]);
            return 1;
        }

        // Read input file line by line and process each line
        char *line = NULL;
        size_t len = 0;
        ssize_t read;
        while ((read = getline(&line, &len, input_file)) != -1) {
            // Parse line and extract record data
            Record *record = malloc(sizeof(Record));
            record->long_value = atol(line);
            record->int_value = atoi(line + 10);
            record->double_value = atof(line + 20);

            // Add record to array of records
            records[current_file] = realloc(records[current_file], (num_files * sizeof(Record)));
            records[current_file][num_files - current_file - 1] = record;
        }

        // Update total bytes read from file and move to next input file
        fseek(input_file, 0, SEEK_END);
        long file_size = ftell(input_file);
        total_bytes += file_size;
        current_file++;
    }

    // Print output for each record in each input file
    for (int i = 0; i < num_files; i++) {
        printf("File %d:\n", i + 1);
        for (int j = 0; j < num_files - i - 1; j++) {
            Record *record = records[i][j];
            printf("%ld, %d, %.2f\n", record->long_value, record->int_value, record->double_value);
        }
    }

    // Free memory for arrays of records
    for (int i = 0; i < num_files; i++) {
        free(records[i]);
    }

    return 0;
}
