#include <stdlib.h>
#include <pthread.h>
#include <stdio.h>
#include <string.h>

// Define a structure for the dynamic linked list node
typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_information;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a mutex for thread-safe access to the linked list
pthread_mutex_t linked_list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Define a function to allocate memory for a new node in the linked list
NFAPI_CRC_INDICATION_PDU_T* allocate_node(RX_UE_INFORMATION_TAG rx_ue_information, RNTI rnti) {
    NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) {
        printf("Memory allocation failed\n");
        return NULL;
    }
    new_node->rx_ue_information = rx_ue_information;
    new_node->rnti = rnti;
    // Generate a random CRCFLAG value for the new node
    new_node->crc_indication_rel8.CRCFLAG = rand() % 1000;
    return new_node;
}

