    array->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(array->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

// Resize the dynamic array if necessary to accommodate up to 150 elements
void resize_array(NFAPI_CRC_INDICATION_ARRAY_T* array) {
    if (array->count >= 150) {
        // double the capacity of the array
        array->capacity *= 2;
        // reallocate memory for the array
        array->data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->data, array->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
