void manage_records(Record **records, size_t *num_records, size_t initial_size) {
    // Initialize the number of records to the initial size
    *num_records = initial_size;

    // Allocate memory for the records
    *records = (Record *)malloc(initial_size * sizeof(Record));
    if (*records == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for records\n");
        return;
    }

    // Fill the records with random values for key and status flag
    srand(time(NULL));
    for (size_t i = 0; i < initial_size; i++) {
        (*records)[i].key = rand() % 100;
        (*records)[i].status_flag = 'A' + (rand() % 26);
    }

    // Calculate the offset based on the index and step size
    long step_size = 50;
    for (size_t i = 0; i < initial_size; i++) {
        (*records)[i].offset = i * step_size;
    }

    // Dynamically resize the array if necessary
    while (1) {
        size_t new_size = *num_records + initial_size;
        Record *new_records = realloc(*records, new_size * sizeof(Record));
        if (new_records == NULL) {
            fprintf(stderr, "Error: Failed to resize records array\n");
            return;
        }
        *records = new_records;
        for (size_t i = *num_records; i < new_size; i++) {
            (*records)[i].key = rand() % 100;
            (*records)[i].status_flag = 'A' + (rand() % 26);
        }
        *num_records = new_size;
    }
}

