    char *SM_Context_Request;
} PDUSessionState;

// Define a global variable to store the list of UESessionStates
UESessionState *UESessions = NULL;

// Define a function to initialize and manage the list of UESessionStates
void init_UESessionManager(int num_ues) {
    // Allocate memory for the list of UESessionStates
    UESessions = (UESessionState *)malloc(num_ues * sizeof(UESessionState));
    if (!UESessions) {
        perror("Failed to allocate memory for UESessions");
        exit(1);
    }

    // Initialize each UESessionState structure with a unique UE_ID, RNTI, and empty list of PDUSessionStates
    for (int i = 0; i < num_ues; i++) {
        UESessions[i].UE_ID = i + 1;
        UESessions[i].RNTI = rand() % 10000;
        UESessions[i].PDUSessions = NULL;
    }
}

// Define a function to add a new PDUSessionState to the list of UESessionStates
void add_PDUSession(int UE_ID, char *PDU_SESSION_Establishment_Request, char *Allocation_and_Binding_Command, char *SM_Context_Request) {
    // Find the UESessionState structure for the given UE_ID
    int i;
    for (i = 0; i < num_ues; i++) {
        if (UESessions[i].UE_ID == UE_ID) {
            break;
        }
    }

    // If the UESessionState structure is not found, return an error
    if (i == num_ues) {
        printf("Error: Could not find UESessionState for UE_ID %d\n", UE_ID);
        return;
    }

    // Allocate memory for the new PDUSessionState structure
    PDUSessionState *new_PDUSession = (PDUSessionState *)malloc(sizeof(PDUSessionState));
    if (!new_PDUSession) {
        perror("Failed to allocate memory for new PDUSession");
        exit(1);
    }

    // Initialize the new PDUSessionState structure with the given parameters
    new_PDUSession->PDU_SESSION_Establishment_Request = PDU_SESSION_Establishment_Request;
    new_PDUSession->Allocation_and_Binding_Command = Allocation_and_Binding_Command;
    new_PDUSession->SM_Context_Request = SM_Context_Request;

    // Add the new PDUSessionState structure to the list of PDUSessions for the UESessionState structure
    if (UESessions[i].PDUSessions == NULL) {
        UESessions[i].PDUSessions = new_PDUSession;
    } else {
        // Add the new PDUSessionState structure to the end of the list
        PDUSessionState *current_PDUSession = UESessions[i].PDUSessions;
        while (current_PDUSession->next != NULL) {
            current_PDUSession = current_PDUSession->next;
        }
        current_PDUSession->next = new_PDUSession;
    }
}

// Define a function to remove a PDUSessionState from the list of UESessionStates
void remove_PDUSession(int UE_ID, char *PDU_SESSION_Establishment_Request) {
    // Find the UESessionState structure for the given UE_ID
    int i;
    for (i = 0; i < num_ues; i++) {
        if (UESessions[i].UE_ID == UE_ID) {
            break;
        }
    }

    // If the UESessionState structure is not found, return an error
    if (i == num_ues) {
        printf("Error: Could not find UESessionState for UE_ID %d\n", UE_ID);
        return;
    }

    // Find the PDUSessionState structure for the given PDU_SESSION_Establishment_Request
    PDUSessionState *current_PDUSession = UESessions[i].PDUSessions;
    while (current_PDUSession != NULL) {
        if (strcmp(current_PDUSession->PDU_SESSION_Establishment_Request, PDU_SESSION_Establishment_Request) == 0) {
            break;
        }
        current_PDUSession = current_PDUSession->next;
    }

    // If the PDUSessionState structure is not found, return an error
    if (current_PDUSession == NULL) {
        printf("Error: Could not find PDUSessionState for UE_ID %d and PDU_SESSION_Establishment_Request %s\n", UE_ID, PDU_SESSION_Establishment_Request);
        return;
    }

    // Remove the PDUSessionState structure from the list of PDUSessions for the UESessionState structure
    if (current_PDUSession == UESessions[i].PDUSessions) {
        UESessions[i].PDUSessions = current_PDUSession->next;
