    for (int i = 0; i < records->size; i++) {
        if (records[i].key == record->key) {
            return -1;
        }
    }

    // Add the record to the list
    records = realloc(records, sizeof(Record) * (records->size + 1));
    records[records->size++] = *record;

    // Log the operation
    if (LOGGING_LEVEL >= 3) {
        printf("Added record with key %d\n", record->key);
    }

    return 0;
}

// Function to update a record in the list
int update_record(Record *record) {
    // Check if the record exists in the list
    for (int i = 0; i < records->size; i++) {
        if (records[i].key == record->key) {
            records[i] = *record;
            return 0;
        }
    }

    // Log the operation
    if (LOGGING_LEVEL >= 3) {
        printf("Updated record with key %d\n", record->key);
    }

    return -1;
}

// Function to retrieve a record from the list
Record *get_record(int key) {
    // Check if the record exists in the list
    for (int i = 0; i < records->size; i++) {
        if (records[i].key == key) {
            return &records[i];
        }
    }

    // Log the operation
    if (LOGGING_LEVEL >= 3) {
        printf("Retrieved record with key %d\n", key);
    }

    return NULL;
}

// Function to resolve a hostname using DNS resolution
int resolve_hostname(const char *hostname, u_char **ip_address) {
    // Check if the hostname is valid
    if (!validate_hostname(hostname)) {
        return -1;
    }

    // Resolve the hostname using standard library functions
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;
    if (getaddrinfo(hostname, NULL, &hints, &res) != 0) {
        return -1;
    }

    // Get the IP address from the DNS resolution result
    *ip_address = res->ai_addr->sa_data;

    // Log the operation
    if (LOGGING_LEVEL >= 3) {
        printf("Resolved hostname %s to IP address %s\n", hostname, ip_address);
    }

    return 0;
}

// Function to validate a hostname
int validate_hostname(const char *hostname) {
    // Check if the hostname is valid
    if (!hostname || strlen(hostname) == 0) {
        return -1;
    }

    // Validate the IP address format
    struct sockaddr_in sa;
    if (inet_pton(AF_INET, hostname, &sa.sin_addr) <= 0) {
        return -1;
    }

    // Log the operation
    if (LOGGING_LEVEL >= 3) {
        printf("Validated hostname %s\n", hostname);
    }

    return 0;
}

