#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <assert.h>

// Define a struct to represent a state in the FSA
struct State {
    int id;
    char *name;
    struct State *next;
};

// Define a struct to represent the FSA
struct FSA {
    struct State *start;
    struct State *end;
    int num_states;
    int num_transitions;
};

// Define a struct to represent the list of states
struct StateList {
    struct State *head;
    struct State *tail;
    int size;
};

// Function to dynamically manage memory for a list of unique states from an FSA
void get_unique_states(int *state_array, int num_states, struct FSA *fsa, int last_state) {
    // Validate the FSA to ensure its integrity
    if (!validate_fsa(fsa)) {
        return;
    }

    // Initialize a list of states
    struct StateList *list = malloc(sizeof(struct StateList));
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;

    // Iterate over the FSA's transitions and add unique states to the list
    for (int i = 0; i < fsa->num_transitions; i++) {
        int state = state_array[i];
        if (state == last_state) {
            continue;
        }
        struct State *new_state = malloc(sizeof(struct State));
        new_state->id = state;
        new_state->name = get_state_name(fsa, state);
        new_state->next = NULL;
        if (list->head == NULL) {
            list->head = new_state;
            list->tail = new_state;
        } else {
            list->tail->next = new_state;
            list->tail = new_state;
        }
        list->size++;
    }

    // Update the 'next' pointer of the last state in the list to point to the newly created state list
    struct State *last_state_ptr = get_state(fsa, last_state);
    if (last_state_ptr != NULL) {
        last_state_ptr->next = list->head;
    }

    // Return the list of unique states
    return list;
}

// Function to validate an FSA
int validate_fsa(struct FSA *fsa) {
    // Check if the FSA has a valid start and end state
    if (fsa->start == NULL || fsa->end == NULL) {
        return 0;
    }

    // Check if the FSA has a valid number of states and transitions
    if (fsa->num_states <= 0 || fsa->num_transitions <= 0) {
        return 0;
    }

    // Check if all states in the FSA are reachable from the start state
    for (int i = 0; i < fsa->num_states; i++) {
        struct State *state = get_state(fsa, i);
        if (state == NULL) {
            return 0;
        }
    }

    // Check if all transitions in the FSA are valid
    for (int i = 0; i < fsa->num_transitions; i++) {
        int state1 = state_array[i];
        int state2 = state_array[i + 1];
        struct State *state1_ptr = get_state(fsa, state1);
        struct State *state2_ptr = get_state(fsa, state2);
        if (state1_ptr == NULL || state2_ptr == NULL) {
            return 0;
        }
    }

    // If all checks pass, the FSA is valid
    return 1;
}

// Function to get a state's name from an FSA
char *get_state_name(struct FSA *fsa, int id) {
    struct State *state = get_state(fsa, id);
    if (state == NULL) {
        return NULL;
    }
    return state->name;
}

// Function to get a state from an FSA
struct State *get_state(struct FSA *fsa, int id) {
    for (int i = 0; i < fsa->num_states; i++) {
        struct State *state = &fsa->start[i];
        if (state->id == id) {
            return state;
        }
    }
    return NULL;
}
