    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the structure for a linked list node
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct Node *next;
} Node;

// Define the structure for a hash table
typedef struct HashTable {
    int size;
    Node **table;
} HashTable;

// Define the function to create and populate an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T *createAndPopulateArray(int N) {
    // Initialize the array with NULL values
    NFAPI_CRC_INDICATION_PDU_T *array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);
    memset(array, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);

    // Initialize the hash table for storing RNTIs
    HashTable *hashTable = createHashTable(N);

    // Populate the array with random values and handle duplicates gracefully
    for (int i = 0; i < N; i++) {
        int rnti = rand() % INT_MAX;
        bool duplicate = false;

        // Check if the RNTI is already in the hash table
        Node *node = getNode(hashTable, rnti);
        while (node != NULL) {
            duplicate = true;
            break;
        }

        // If the RNTI is not a duplicate, add it to the hash table and populate the array
        if (!duplicate) {
            node = createNode(rnti);
            addNode(hashTable, rnti, node);
            array[i].RX_UE_INFORMATION_TAG = rand() % UINT16_MAX;
            array[i].RNTI = rnti;
            array[i].CRC_INDICATION_REL8_TAG = rand() % UINT8_MAX;
            array[i].CRCFLAG = (rand() % 2) ? true : false;
        } else {
            // If the RNTI is a duplicate, populate the array with the existing value
            int index = getIndex(hashTable, rnti);
            array[i] = *(array + index);
        }
    }

    // Free the hash table and return the populated array
    freeHashTable(hashTable);
    return array;
}

// Define the function to create a linked list node
Node *createNode(int data) {
    Node *node = malloc(sizeof(Node));
    node->data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    node->data->RX_UE_INFORMATION_TAG = rand() % UINT16_MAX;
    node->data->RNTI = data;
    node->data->CRC_INDICATION_REL8_TAG = rand() % UINT8_MAX;
    node->data->CRCFLAG = (rand() % 2) ? true : false;
    node->next = NULL;
    return node;
}

// Define the function to add a linked list node
void addNode(HashTable *hashTable, int data, Node *node) {
    // Check if the hash table is full
    if (hashTable->size == INT_MAX) {
        printf("Error: Hash table is full\n");
        return;
    }

    // Add the node to the hash table
    int index = getIndex(hashTable, data);
    Node *head = hashTable->table[index];
    if (head == NULL) {
        head = createNode(data);
        hashTable->table[index] = head;
    } else {
        while (head->next != NULL) {
            head = head->next;
        }
        head->next = createNode(data);
    }
}

// Define the function to get a linked list node
Node *getNode(HashTable *hashTable, int data) {
    // Check if the hash table is empty
    if (hashTable->size == 0) {
        return NULL;
    }

    // Get the index of the RNTI in the hash table
    int index = getIndex(hashTable, data);

    // Get the node from the hash table
    Node *head = hashTable->table[index];
    while (head != NULL) {
        if (head->data->RNTI == data) {
            return head;
        }
        head = head->next;
    }

    // Return NULL if the RNTI is not found in the hash table
    return NULL;
}

// Define the function to create a hash table
HashTable *createHashTable(int size) {
    HashTable *hashTable = malloc(sizeof(HashTable));
    hashTable->size = size;
    hashTable->table = malloc(sizeof(Node *) * size);
    memset(hashTable->table, 0, sizeof(Node *) * size);
    return hashTable;
}

// Define the function to free a hash table
void freeHashTable(HashTable *hashTable) {
    for (int i = 0; i < hashTable->size; i++) {
        Node *head = hashTable->table[i];
        while (head != NULL) {
            Node *next = head->next;
            free(head);
            head = next;
        }
    }
    free(hashTable->table);
    free(hashTable);
}

// Define the function to get the index of a RNTI in the hash table
int getIndex(HashTable *hashTable, int data) {
    return data % hashTable->size;
}
