struct LTE_RRC_Connection_Reconfiguration_array {
    LTE_RRC_Connection_Reconfiguration** messages;
    int size;
    pthread_mutex_t mutex;
};

// Initialize the dynamic array of LTE_RRC_Connection_Reconfiguration messages
void init_LTE_RRC_Connection_Reconfiguration_array(struct LTE_RRC_Connection_Reconfiguration_array* arr) {
    arr->messages = NULL;
    arr->size = 0;
    pthread_mutex_init(&arr->mutex, NULL);
}

// Add a new message to the dynamic array of LTE_RRC_Connection_Reconfiguration messages
void add_LTE_RRC_Connection_Reconfiguration_message(struct LTE_RRC_Connection_Reconfiguration_array* arr, int id, char* data) {
    pthread_mutex_lock(&arr->mutex);
    // Allocate memory for the new message
    LTE_RRC_Connection_Reconfiguration* msg = malloc(sizeof(LTE_RRC_Connection_Reconfiguration));
    if (msg == NULL) {
        pthread_mutex_unlock(&arr->mutex);
        return;
    }
    // Initialize the new message
    msg->id = id;
    msg->data = data;
    // Add the new message to the array
    arr->messages[arr->size++] = msg;
    pthread_mutex_unlock(&arr->mutex);
}

// Remove a message from the dynamic array of LTE_RRC_Connection_Reconfiguration messages
void remove_LTE_RRC_Connection_Reconfiguration_message(struct LTE_RRC_Connection_Reconfiguration_array* arr, int id) {
    pthread_mutex_lock(&arr->mutex);
    // Find the index of the message to be removed
    int i;
    for (i = 0; i < arr->size; i++) {
        if (arr->messages[i]->id == id) {
            break;
        }
    }
    // If the message is found, remove it from the array and free its memory
    if (i < arr->size) {
        LTE_RRC_Connection_Reconfiguration* msg = arr->messages[i];
        for (int j = i; j < arr->size - 1; j++) {
            arr->messages[j] = arr->messages[j + 1];
        }
        arr->size--;
        free(msg);
    }
    pthread_mutex_unlock(&arr->mutex);
}

// Access a message from the dynamic array of LTE_RRC_Connection_Reconfiguration messages
LTE_RRC_Connection_Reconfiguration* get_LTE_RRC_Connection_Reconfiguration_message(struct LTE_RRC_Connection_Reconfiguration_array* arr, int id) {
    pthread_mutex_lock(&arr->mutex);
    // Find the index of the message to be accessed
    int i;
    for (i = 0; i < arr->size; i++) {
        if (arr->messages[i]->id == id) {
            break;
        }
    }
    // If the message is found, return a pointer to it
    LTE_RRC_Connection_Reconfiguration* msg = NULL;
    if (i < arr->size) {
        msg = arr->messages[i];
    }
    pthread_mutex_unlock(&arr->mutex);
    return msg;
}

// Free the memory allocated for the dynamic array of LTE_RRC_Connection_Reconfiguration messages
