namespace DynamicValueGenerator
{
    public class DynamicValueGenerator
    {
        private float _minFloat, _maxFloat;
        private int _minInt, _maxInt;
        private Vector3 _minVector, _maxVector;

        public DynamicValueGenerator(float minFloat = 0.0f, float maxFloat = 1.0f, int minInt = 0, int maxInt = 100, Vector3 minVector = new Vector3(), Vector3 maxVector = new Vector3())
        {
            _minFloat = minFloat;
            _maxFloat = maxFloat;
            _minInt = minInt;
            _maxInt = maxInt;
            _minVector = minVector;
            _maxVector = maxVector;
        }

        public float GenerateRandomFloat()
        {
            return Random.Range(_minFloat, _maxFloat);
        }

        public int GenerateRandomInt()
        {
            return Random.Range(_minInt, _maxInt);
        }

        public Vector3 GenerateRandomVector()
        {
            return new Vector3(Random.Range(_minVector.x, _maxVector.x), Random.Range(_minVector.y, _maxVector.y), Random.Range(_minVector.z, _maxVector.z));
        }

        public override string ToString()
        {
            return $"Min Float: {_minFloat}, Max Float: {_maxFloat}, Min Int: {_minInt}, Max Int: {_maxInt}, Min Vector: {_minVector}, Max Vector: {_maxVector}";
        }
    }
}
