    size_t used; // Amount of memory currently in use
    void **memory; // Array of pointers to allocated memory blocks
};

// Function to allocate memory from the memory pool
void *allocateMemory(struct MemoryPool *pool, size_t size) {
    if (pool->used + size > pool->capacity) {
        return NULL;
    }
    void *memory = pool->memory[pool->used++];
    memset(memory, 0, size);
    return memory;
}

// Function to deallocate memory from the memory pool
void deallocateMemory(struct MemoryPool *pool, void *memory) {
    if (memory == NULL) {
        return;
    }
    int index = -1;
    for (int i = 0; i < pool->used; i++) {
        if (pool->memory[i] == memory) {
            index = i;
            break;
        }
