    time_t Timestamp;
    unsigned long PacketCount;
    double ErrorRate;
} NetworkEntityStats;

// Define the function to initialize and populate the dynamic array of NetworkEntityStats structures
void initAndPopulateNetworkEntityStats(char* csvFilePath, int numEntriesToRead, NetworkEntityStats** statsArray) {
    // Open the CSV file for reading
    FILE* csvFile = fopen(csvFilePath, "r");
    if (csvFile == NULL) {
        printf("Error: Unable to open CSV file %s\n", csvFilePath);
        return;
    }

    // Allocate memory for the dynamic array of NetworkEntityStats structures
    *statsArray = malloc(numEntriesToRead * sizeof(NetworkEntityStats));
    if (*statsArray == NULL) {
        printf("Error: Unable to allocate memory for stats array\n");
        fclose(csvFile);
        return;
    }

    // Initialize the mutex for thread-safe access to the array
    pthread_mutex_t* mutex = malloc(sizeof(pthread_mutex_t));
    if (mutex == NULL) {
        printf("Error: Unable to allocate memory for mutex\n");
        free(*statsArray);
        fclose(csvFile);
        return;
    }
    pthread_mutex_init(mutex, NULL);

    // Read the CSV file and populate the dynamic array of NetworkEntityStats structures
    int numEntriesRead = 0;
    while (numEntriesRead < numEntriesToRead) {
        // Lock the mutex to prevent race conditions and data corruption
        pthread_mutex_lock(mutex);

        // Read a line from the CSV file
        char* line = fgets(csvFile);
        if (line == NULL) {
            printf("Error: Unable to read line from CSV file\n");
            break;
        }

        // Parse the line and populate the NetworkEntityStats structure
        NetworkEntityStats* stats = &(*statsArray)[numEntriesRead];
        char* token = strtok(line, ",");
        if (token == NULL) {
            printf("Error: Unable to parse line from CSV file\n");
            break;
        }
        stats->Timestamp = atol(token);
        token = strtok(NULL, ",");
        if (token == NULL) {
            printf("Error: Unable to parse line from CSV file\n");
            break;
        }
        stats->PacketCount = atol(token);
        token = strtok(NULL, ",");
        if (token == NULL) {
            printf("Error: Unable to parse line from CSV file\n");
            break;
        }
        stats->ErrorRate = atof(token);

        // Filter out duplicate entries based on the combination of Timestamp and PacketCount
        int i;
        for (i = 0; i < numEntriesRead; i++) {
            if ((*statsArray)[i].Timestamp == stats->Timestamp && (*statsArray)[i].PacketCount == stats->PacketCount) {
                break;
            }
        }
        if (i < numEntriesRead) {
            continue;
        }

        // Increment the number of entries read and unlock the mutex
        numEntriesRead++;
        pthread_mutex_unlock(mutex);
    }

    // Close the CSV file
    fclose(csvFile);

    // Free the memory for the mutex
    free(mutex);
}

// Define the function to handle potential errors in file reading, such as malformed lines or missing fields
void handleFileReadingErrors(char* csvFilePath) {
    FILE* csvFile = fopen(csvFilePath, "r");
    if (csvFile == NULL) {
        printf("Error: Unable to open CSV file %s\n", csvFilePath);
        return;
    }

    // Read the first line from the CSV file
    char* line = fgets(csvFile);
    if (line == NULL) {
        printf("Error: Unable to read line from CSV file\n");
        fclose(csvFile);
        return;
    }

    // Check for malformed lines or missing fields
    char* token = strtok(line, ",");
    if (token == NULL) {
        printf("Error: Malformed line in CSV file %s\n", csvFilePath);
        fclose(csvFile);
        return;
    }
    while (token != NULL) {
        token = strtok(NULL, ",");
        if (token == NULL) {
            printf("Error: Missing field in CSV file %s\n", csvFilePath);
            fclose(csvFile);
            return;
        }
    }

    // Close the CSV file
    fclose(csvFile);
}
