// Modular C library for managing a collection of Record structures
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <assert.h>

// Define the Record structure
typedef struct {
    int key;
    int value;
} Record;

// Define the hash table for storing records
static Record* records = NULL;
static size_t record_count = 0;
static size_t record_capacity = 0;

// Function to add a new record to the collection
int add_record(int key, int value) {
    // Check if the hash table is full
    if (record_count == record_capacity) {
        // Double the capacity of the hash table
        record_capacity *= 2;
        records = realloc(records, record_capacity * sizeof(Record));
        assert(records != NULL);
    }

    // Add the new record to the hash table
    records[record_count].key = key;
    records[record_count].value = value;
    record_count++;

    return 0;
}

// Function to update an existing record in the collection
int update_record(int key, int value) {
    // Find the index of the record with the given key
    size_t i = find_index(key);
    if (i == -1) {
        return -1;
    }

    // Update the value of the record at the found index
    records[i].value = value;

    return 0;
}

// Function to retrieve a record from the collection by its key
int get_record(int key, int* value) {
    // Find the index of the record with the given key
    size_t i = find_index(key);
    if (i == -1) {
        return -1;
    }

    // Return the value of the record at the found index
    *value = records[i].value;

    return 0;
}

// Function to find the index of a record in the collection by its key
size_t find_index(int key) {
    for (size_t i = 0; i < record_count; i++) {
        if (records[i].key == key) {
            return i;
        }
    }

    // Return -1 if the record is not found
    return -1;
}

// Function to remove a record from the collection by its key
int remove_record(int key) {
    // Find the index of the record with the given key
    size_t i = find_index(key);
    if (i == -1) {
        return -1;
    }

    // Shift all records after the found index to fill the gap
    for (size_t j = i + 1; j < record_count; j++) {
        records[j - 1] = records[j];
    }

    // Decrement the count of records in the hash table
    record_count--;

    return 0;
}

// Function to clear all records from the collection
void clear_records() {
    free(records);
    records = NULL;
    record_count = 0;
    record_capacity = 0;
}
