#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdbool.h>
#include <pthread.h>

// Define the structure for a user session
typedef struct UserSession {
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    char *buffer;
} UserSession;

// Define the data structure for the list of user sessions
typedef struct UserSessionList {
    UserSession *sessions;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} UserSessionList;

// Initialize a new user session with a unique RNTI and CRC_INDICATION_REL8_TAG
UserSession *new_user_session(int RNTI, int CRC_INDICATION_REL8_TAG) {
    UserSession *session = malloc(sizeof(UserSession));
    if (!session) {
        return NULL;
    }
    session->RNTI = RNTI;
    session->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    session->buffer = malloc(1024); // allocate a buffer of 1024 bytes for temporary storage of user data
    if (!session->buffer) {
        free(session);
        return NULL;
    }
    return session;
}

// Add a new record to the list of user sessions
bool add_user_session(UserSessionList *list, UserSession *session) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= list->capacity) {
        // If the list is full, double its capacity and reallocate memory for the sessions array
        size_t new_capacity = list->capacity * 2;
        UserSession **new_sessions = realloc(list->sessions, sizeof(UserSession *) * new_capacity);
        if (!new_sessions) {
            pthread_mutex_unlock(&list->mutex);
            return false;
        }
        list->sessions = new_sessions;
        list->capacity = new_capacity;
    }
    // Add the new session to the end of the list
    list->sessions[list->count++] = session;
    pthread_mutex_unlock(&list->mutex);
    return true;
}

// Update an existing record in the list of user sessions
bool update_user_session(UserSessionList *list, int RNTI, UserSession *session) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; i++) {
        if (list->sessions[i]->RNTI == RNTI) {
            // Update the existing session with the new values
            list->sessions[i] = session;
            pthread_mutex_unlock(&list->mutex);
            return true;
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return false;
}

// Retrieve the value of a specific record in the list of user sessions by its unique RNTI key
UserSession *get_user_session(UserSessionList *list, int RNTI) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; i++) {
        if (list->sessions[i]->RNTI == RNTI) {
            // Return the existing session with the matching RNTI key
            pthread_mutex_unlock(&list->mutex);
            return list->sessions[i];
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

// Free the memory allocated for a user session
void free_user_session(UserSession *session) {
    if (session) {
        free(session->buffer);
        free(session);
    }
}

// Free the memory allocated for the list of user sessions
void free_user_session_list(UserSessionList *list) {
    if (list) {
        for (size_t i = 0; i < list->count; i++) {
            free_user_session(list->sessions[i]);
        }
        free(list->sessions);
        pthread_mutex_destroy(&list->mutex);
    }
