// Structure to represent a device
typedef struct {
    float power_consumption; // Power consumption in watts
    char identifier[16]; // Unique identifier for the device
} Device;

// Linked list node to store devices
typedef struct Node {
    Device *device;
    struct Node *next;
} Node;

// Function to insert a new device into the linked list
void insert_device(Node **head, const char *identifier, float power_consumption) {
    // Allocate memory for the new node
    Node *new_node = malloc(sizeof(Node));
    if (new_node == NULL) {
        printf("Memory allocation failed\n");
        return;
    }

    // Initialize the new node with the given identifier and power consumption
    strcpy(new_node->device->identifier, identifier);
    new_node->device->power_consumption = power_consumption;

    // Insert the new node at the beginning of the linked list
    new_node->next = *head;
    *head = new_node;
}

// Function to remove a device from the linked list by identifier
void remove_device(Node **head, const char *identifier) {
    // Find the node with the given identifier
    Node *current = *head;
    while (current != NULL && strcmp(current->device->identifier, identifier) != 0) {
        current = current->next;
    }

    // If the node is found, remove it from the linked list
    if (current != NULL) {
        Node *previous = current->prev;
        previous->next = current->next;
        free(current);
    }
}

// Function to update the power consumption value of a specific device
void update_power_consumption(Node **head, const char *identifier, float new_power_consumption) {
    // Find the node with the given identifier
    Node *current = *head;
    while (current != NULL && strcmp(current->device->identifier, identifier) != 0) {
        current = current->next;
    }

    // If the node is found, update its power consumption value
    if (current != NULL) {
        current->device->power_consumption = new_power_consumption;
    }
}

// Function to monitor the total power consumption of all devices and generate alerts if necessary
void monitor_total_power_consumption(Node **head, float threshold) {
    // Calculate the total power consumption of all devices
    float total_power_consumption = 0.0f;
    Node *current = *head;
    while (current != NULL) {
        total_power_consumption += current->device->power_consumption;
        current = current->next;
    }

    // Generate alerts if the total power consumption exceeds the threshold
    if (total_power_consumption > threshold) {
        printf("Total power consumption exceeds threshold: %.2f\n", total_power_consumption);
    }
}

// Function to identify the device with the highest power consumption and allow sorting the devices based on their consumption in ascending order
void sort_devices(Node **head) {
    // Sort the linked list of devices based on their power consumption in ascending order
    Node *current = *head;
    while (current != NULL) {
        Node *next = current->next;
        while (next != NULL && next->device->power_consumption < current->device->power_consumption) {
            swap(current, next);
            next = current->next;
        }
        current = current->next;
    }
}

// Function to find the device with the highest power consumption
Device *find_highest_power_consumption(Node **head) {
    // Find the node with the highest power consumption in the linked list
    Node *current = *head;
    Device *highest_device = NULL;
    while (current != NULL) {
        if (highest_device == NULL || current->device->power_consumption > highest_device->power_consumption) {
            highest_device = current->device;
        }
        current = current->next;
    }

    // Return the device with the highest power consumption
    return highest_device;
}
