    // Check if the message is too long for the allocated buffer
    int messageLength = strlen(message);
    if (messageLength > MAX_MESSAGE_LENGTH) {
        printf("Error: Message length exceeds maximum allowed size\n");
        return;
    }

    // Allocate memory for the NAS message
    ueContext->nasMessage = (char *)malloc(MAX_MESSAGE_LENGTH * sizeof(char));

    // Copy the message into the allocated buffer
    strcpy(ueContext->nasMessage, message);
}

// Function to generate a unique sequence number for each NAS message
