typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the queue to hold the CRC indication data
typedef struct {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int size;
    int front, rear;
    NFAPI_CRC_INDICATION_PDU_T* queue[10000];
} CRC_QUEUE_T;

// Define the memory pool to allocate and release structures efficiently
typedef struct {
    pthread_mutex_t mutex;
    int size;
    NFAPI_CRC_INDICATION_PDU_T* pool[1000];
} CRC_POOL_T;

// Function to create and populate a list of CRC indication structures
void create_crc_indications(int num_threads, int num_operations) {
    // Initialize the queue and memory pool
    CRC_QUEUE_T* crc_queue = (CRC_QUEUE_T*)malloc(sizeof(CRC_QUEUE_T));
    pthread_mutex_init(&crc_queue->mutex, NULL);
    pthread_cond_init(&crc_queue->cond, NULL);
    crc_queue->size = 0;
    crc_queue->front = -1;
    crc_queue->rear = -1;

    CRC_POOL_T* crc_pool = (CRC_POOL_T*)malloc(sizeof(CRC_POOL_T));
    pthread_mutex_init(&crc_pool->mutex, NULL);
    crc_pool->size = 0;

    // Create and populate the CRC indication structures in parallel
    int i;
    for (i = 0; i < num_threads; i++) {
        pthread_t thread;
        pthread_create(&thread, NULL, create_crc_indications_helper, crc_queue);
    }

    // Wait for all threads to finish
    for (i = 0; i < num_threads; i++) {
        pthread_join(thread, NULL);
    }

    // Clean up the queue and memory pool
    pthread_mutex_destroy(&crc_queue->mutex);
    pthread_cond_destroy(&crc_queue->cond);
    free(crc_queue);

    pthread_mutex_destroy(&crc_pool->mutex);
    free(crc_pool);
}

// Helper function for creating and populating CRC indication structures in parallel
void* create_crc_indications_helper(void* arg) {
    // Get the queue and memory pool from the argument
    CRC_QUEUE_T* crc_queue = (CRC_QUEUE_T*)arg;
    CRC_POOL_T* crc_pool = (CRC_POOL_T*)malloc(sizeof(CRC_POOL_T));
    pthread_mutex_init(&crc_pool->mutex, NULL);
    crc_pool->size = 0;

    // Populate the queue and memory pool with CRC indication structures
    int i;
    for (i = 0; i < num_operations; i++) {
        NFAPI_CRC_INDICATION_PDU_T* crc_indication = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pthread_mutex_lock(&crc_pool->mutex);
        if (crc_pool->size < 1000) {
            crc_indication->rx_ue_information = RX_UE_INFORMATION_TAG(rand() % 1000);
            crc_indication->rnti = rand() % 1000;
            crc_indication->crc_indication_rel8.CRCFLAG = rand() % 2;
            crc_pool->pool[crc_pool->size++] = crc_indication;
        } else {
            free(crc_indication);
        }
        pthread_mutex_unlock(&crc_pool->mutex);
    }

    // Add the CRC indication structures to the queue
    pthread_mutex_lock(&crc_queue->mutex);
    while (crc_queue->size < 10000) {
        if (crc_pool->size > 0) {
            crc_queue->queue[crc_queue->rear++] = crc_pool->pool[--crc_pool->size];
            crc_queue->size++;
            pthread_cond_signal(&crc_queue->cond);
        } else {
            break;
        }
    }
    pthread_mutex_unlock(&crc_queue->mutex);

    // Clean up the memory pool
    pthread_mutex_destroy(&crc_pool->mutex);
    free(crc_pool);
}
