// Function to allocate a new LTE_ENB_RRC_API_RX_UE_MSG structure from the memory pool
LTE_ENB_RRC_API_RX_UE_MSG *allocate_memory_pool() {
    // Acquire the semaphore for accessing the memory pool
    sem_wait(&memory_pool_sem);

    // Find a free slot in the memory pool and allocate a new structure
    int i;
    for (i = 0; i < MEMORY_POOL_SIZE; i++) {
        if (memory_pool[i] == NULL) {
            break;
        }
    }
    if (i == MEMORY_POOL_SIZE) {
        // No free slots found, return NULL
        sem_post(&memory_pool_sem);
        return NULL;
    }
    LTE_ENB_RRC_API_RX_UE_MSG *new_structure = malloc(sizeof(LTE_ENB_RRC_API_RX_UE_MSG));
    if (new_structure == NULL) {
        // Memory allocation failed, return NULL
        sem_post(&memory_pool_sem);
        return NULL;
