#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include <errno.h>

// Define the structure to store LTE base station statistics
typedef struct {
    int cell_id;
    int tx_power;
    int rx_quality;
    int scheduling_stats;
} LTE_ENB_STATS_T;

// Define a linked list node to store the LTE base station statistics
typedef struct {
    LTE_ENB_STATS_T stats;
    struct node *next;
} node;

// Define a global variable to store the head of the linked list
node *head = NULL;

// Define a mutex to ensure thread safety in a multi-threaded environment
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize the linked list based on user input N
void init_list(int N) {
    // Check if the input value is valid
    if (N <= 0) {
        printf("Invalid input value: %d\n", N);
        return;
    }

    // Allocate memory for the linked list node
    node *new_node = malloc(sizeof(node));
    if (!new_node) {
        printf("Memory allocation failed: %s\n", strerror(errno));
        return;
    }

    // Initialize the linked list node with the input value N
    new_node->stats.cell_id = N;
    new_node->stats.tx_power = 0;
    new_node->stats.rx_quality = 0;
    new_node->stats.scheduling_stats = 0;
    new_node->next = NULL;

    // Lock the mutex to ensure thread safety
    pthread_mutex_lock(&lock);

    // Check if the linked list is empty
    if (!head) {
        head = new_node;
    } else {
        node *current = head;
        while (current->next) {
            current = current->next;
        }
        current->next = new_node;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&lock);
}

// Function to update the linked list based on external data source updates
void update_list(int N) {
    // Check if the input value is valid
    if (N <= 0) {
        printf("Invalid input value: %d\n", N);
        return;
    }

    // Lock the mutex to ensure thread safety
    pthread_mutex_lock(&lock);

    // Check if the linked list is empty
    if (!head) {
        init_list(N);
    } else {
        node *current = head;
        while (current->next) {
            current = current->next;
        }
        current->stats.cell_id = N;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&lock);
}

// Function to retrieve a specific LTE base station statistics from the linked list
LTE_ENB_STATS_T *get_stats(int cell_id) {
    // Check if the input value is valid
    if (cell_id <= 0) {
        printf("Invalid input value: %d\n", cell_id);
        return NULL;
    }

    // Lock the mutex to ensure thread safety
    pthread_mutex_lock(&lock);

    // Check if the linked list is empty
    if (!head) {
        printf("Linked list is empty\n");
        return NULL;
    } else {
        node *current = head;
        while (current->next) {
            if (current->stats.cell_id == cell_id) {
                // Unlock the mutex
                pthread_mutex_unlock(&lock);
                return &(current->stats);
            }
            current = current->next;
        }
    }

    // Unlock the mutex
    pthread_mutex_unlock(&lock);

    printf("Cell ID %d not found in linked list\n", cell_id);
    return NULL;
}

// Function to free the memory allocated for the linked list
void free_list() {
    // Lock the mutex to ensure thread safety
    pthread_mutex_lock(&lock);

    // Check if the linked list is empty
    if (!head) {
        printf("Linked list is empty\n");
    } else {
        node *current = head;
        while (current->next) {
            current = current->next;
            free(current);
        }
        free(head);
    }

    // Unlock the mutex
    pthread_mutex_unlock(&lock);
}
