        int new_capacity = arr->capacity * 2;
        arr->frames = realloc(arr->frames, new_capacity * sizeof(LTE_DL_FRAMEINFO*));
        arr->capacity = new_capacity;
    }
    arr->frames[arr->num_frames++] = frame;
}

