    size_t count;
} RNTITable;

// Initialize the RNTITable with an initial capacity of 1024 entries
void initialize_rnti_table(RNTITable *table) {
    table->RNTIs = malloc(sizeof(uint16_t) * 1024);
    table->count = 0;
}

// Add a new RNTI to the RNTITable, returning true if successful and false otherwise
bool add_rnti(RNTITable *table, uint16_t rnti) {
    // Check if the RNTI is already in the table
    for (size_t i = 0; i < table->count; i++) {
        if (table->RNTIs[i] == rnti) {
            return false;
        }
    }

    // Add the new RNTI to the end of the table
    table->RNTIs[table->count++] = rnti;

    return true;
}

// Remove an RNTI from the RNTITable, returning true if successful and false otherwise
bool remove_rnti(RNTITable *table, uint16_t rnti) {
    // Check if the RNTI is in the table
    for (size_t i = 0; i < table->count; i++) {
        if (table->RNTIs[i] == rnti) {
            // Shift all subsequent elements to the left
            memmove(&table->RNTIs[i], &table->RNTIs[i + 1], sizeof(uint16_t) * (table->count - i));
            table->count--;
            return true;
        }
    }

    return false;
}

// Initialize a secure PDU list with an initial capacity of 1024 entries
void initialize_network_secure_pdu_list(PDU *list, size_t capacity) {
    // Initialize the RNTITable with an initial capacity of 1024 entries
    initialize_rnti_table(&list->RNTITable);

    // Initialize the PDU list with an initial capacity of 1024 entries
    list->PDUs = malloc(sizeof(PDU) * capacity);
    list->count = 0;
}

// Add a new PDU to the secure PDU list, returning true if successful and false otherwise
bool add_pdu(PDU *list, PDU pdu) {
    // Check if the RNTI is already in the table
    if (!add_rnti(&list->RNTITable, pdu.RNTI)) {
        return false;
    }

    // Add the new PDU to the end of the list
    list->PDUs[list->count++] = pdu;

    return true;
}

// Remove a PDU from the secure PDU list, returning true if successful and false otherwise
bool remove_pdu(PDU *list, uint16_t rnti) {
    // Check if the RNTI is in the table
    for (size_t i = 0; i < list->count; i++) {
        if (list->PDUs[i].RNTI == rnti) {
            // Shift all subsequent elements to the left
            memmove(&list->PDUs[i], &list->PDUs[i + 1], sizeof(PDU) * (list->count - i));
            list->count--;
            return true;
        }
    }

    return false;
}

// Initialize a secure PDU with the provided password and IV length, returning a pointer to the cipher context
AES_KEY *initialize_secure_pdu(PDU *pdu, const char *password, size_t iv_length) {
    // Generate an AES-256-CBC cipher key via the SHA-1 hashing algorithm
    unsigned char key[32];
    SHA1((unsigned char *)password, strlen(password), key);

    // Initialize the cipher with a specified IV length and key size
    AES_KEY *cipher = malloc(sizeof(AES_KEY));
    AES_set_encrypt_key(key, 256, cipher);

    return cipher;
}

// Enable the secure PDU with the provided cipher context and return a pointer to the cipher context
void enable_secure_pdu(PDU *pdu, AES_KEY *cipher) {
    // Set the cipher for the PDU
    pdu->cipher = cipher;
}

// Disable the secure PDU with the provided cipher context and return a pointer to the cipher context
void disable_secure_pdu(PDU *pdu, AES_KEY *cipher) {
    // Set the cipher for the PDU to NULL
    pdu->cipher = NULL;
}

// Cleanup function to disable the secure PDU with the provided cipher context and return a pointer to the cipher context
void cleanup_secure_pdu(PDU *pdu, AES_KEY *cipher) {
    // Disable the secure PDU with the provided cipher context
    disable_secure_pdu(pdu, cipher);

    // Free the cipher context
    free(cipher);
}
