// Define structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int rx_ue_information_tag;
    int rnti;
    int crc_indication_rel8_tag;
} nfapi_crc_indication_pdu_t;

// Define function to generate and populate list of NFAPI_CRC_INDICATION_PDU_T structures
void generate_nfapi_crc_indication_pdu(int num_structures, int offset_size, int key_size) {
    // Allocate memory for the list of structures
    nfapi_crc_indication_pdu_t *list = malloc(num_structures * sizeof(nfapi_crc_indication_pdu_t));
    if (list == NULL) {
        printf("Error: Failed to allocate memory for list of structures\n");
        return;
    }

    // Initialize the list of structures with random values
    srand(time(NULL));
    for (int i = 0; i < num_structures; i++) {
        list[i].rx_ue_information_tag = rand() % 1000;
        list[i].rnti = rand() % 1000;
        list[i].crc_indication_rel8_tag = rand() % 1000;
    }

    // Allocate memory for the offset and key arrays
    int *offset_array = malloc(offset_size * sizeof(int));
    if (offset_array == NULL) {
        printf("Error: Failed to allocate memory for offset array\n");
        return;
    }
    int *key_array = malloc(key_size * sizeof(int));
    if (key_array == NULL) {
        printf("Error: Failed to allocate memory for key array\n");
        return;
    }

    // Initialize the offset and key arrays with random values
    srand(time(NULL));
    for (int i = 0; i < offset_size; i++) {
        offset_array[i] = rand() % 1000;
    }
    for (int i = 0; i < key_size; i++) {
        key_array[i] = rand() % 1000;
    }

    // Dynamically allocate memory for additional structures based on a probability threshold
    int num_additional_structures = 0;
    if (num_structures > 10) {
        num_additional_structures = num_structures / 10;
    }
    nfapi_crc_indication_pdu_t *additional_list = malloc(num_additional_structures * sizeof(nfapi_crc_indication_pdu_t));
    if (additional_list == NULL) {
        printf("Error: Failed to allocate memory for additional list of structures\n");
        return;
    }

    // Initialize the additional structures with random values
    srand(time(NULL));
    for (int i = 0; i < num_additional_structures; i++) {
        additional_list[i].rx_ue_information_tag = rand() % 1000;
        additional_list[i].rnti = rand() % 1000;
        additional_list[i].crc_indication_rel8_tag = rand() % 1000;
    }

    // Merge the list of structures with the additional structures
    for (int i = 0; i < num_additional_structures; i++) {
        list[i + num_structures] = additional_list[i];
    }

    // Free memory for the additional structures
    free(additional_list);
}

// Define function to set environment variables for a web application
void set_environment_variables(char *config_file) {
    // Parse the configuration file and set environment variables as needed
    FILE *fp = fopen(config_file, "r");
    if (fp == NULL) {
        printf("Error: Failed to open configuration file\n");
        return;
    }
    char line[1024];
    while (fgets(line, sizeof(line), fp)) {
        // Skip comments and blank lines
        if (strlen(line) == 0 || line[0] == '#') {
            continue;
        }
        // Set environment variables for the web application
        char *key = strtok(line, "=");
