// Structure to represent a UEContext
typedef struct {
    int UE_ID;
    int PDUSESSION_ID;
    int NAS_MESSAGE_TAG;
} UEContext;

// Function to initialize and manage the dynamic list of UEContext structures
void initUEContextList(UEContext **list) {
    // Allocate memory for the list
    *list = (UEContext *)malloc(sizeof(UEContext));
    if (*list == NULL) {
        printf("Error: Failed to allocate memory for UEContext list\n");
        return;
    }

    // Initialize the list with a single element
    (*list)[0].UE_ID = 0;
    (*list)[0].PDUSESSION_ID = 0;
    (*list)[0].NAS_MESSAGE_TAG = 0;
}

// Function to add a new UEContext to the list, ensuring no two consecutive contexts share the same PDUSESSION_ID
void addUEContext(UEContext **list, int UE_ID, int PDUSESSION_ID, int NAS_MESSAGE_TAG) {
    // Check if the list is full
    if (((*list)[0].UE_ID + 1) == (*list)[0].PDUSESSION_ID) {
        printf("Error: List is full\n");
        return;
    }

    // Add a new element to the list
    (*list)[(*list)[0].UE_ID + 1].UE_ID = UE_ID;
    (*list)[(*list)[0].UE_ID + 1].PDUSESSION_ID = PDUSESSION_ID;
    (*list)[(*list)[0].UE_ID + 1].NAS_MESSAGE_TAG = NAS_MESSAGE_TAG;

    // Update the UE_ID and PDUSESSION_ID of the last element in the list
    (*list)[0].UE_ID++;
    (*list)[0].PDUSESSION_ID++;
}

// Function to remove a UEContext from the list, given its UE_ID
void removeUEContext(UEContext **list, int UE_ID) {
    // Check if the UE_ID is valid
    if (UE_ID < 0 || UE_ID >= (*list)[0].UE_ID) {
        printf("Error: Invalid UE_ID\n");
        return;
    }

    // Remove the element from the list
    for (int i = UE_ID + 1; i < (*list)[0].UE_ID; i++) {
        (*list)[i - 1].UE_ID = (*list)[i].UE_ID;
        (*list)[i - 1].PDUSESSION_ID = (*list)[i].PDUSESSION_ID;
        (*list)[i - 1].NAS_MESSAGE_TAG = (*list)[i].NAS_MESSAGE_TAG;
    }

    // Update the UE_ID and PDUSESSION_ID of the last element in the list
    (*list)[0].UE_ID--;
    (*list)[0].PDUSESSION_ID--;
}

// Function to serialize the list to a binary format for efficient storage or transmission
void serializeList(UEContext **list, char *buffer) {
    // Check if the buffer is large enough to hold the serialized data
    if (strlen(buffer) < (*list)[0].PDUSESSION_ID * sizeof(UEContext)) {
        printf("Error: Buffer is too small\n");
        return;
    }

    // Serialize the list to the buffer
    for (int i = 0; i < (*list)[0].PDUSESSION_ID; i++) {
        memcpy(buffer + i * sizeof(UEContext), &(*list)[i], sizeof(UEContext));
    }
}

// Function to deserialize the list from a binary format, given a buffer
void deserializeList(UEContext **list, char *buffer) {
    // Check if the buffer is large enough to hold the serialized data
    if (strlen(buffer) < (*list)[0].PDUSESSION_ID * sizeof(UEContext)) {
        printf("Error: Buffer is too small\n");
        return;
    }

    // Deserialize the list from the buffer
    for (int i = 0; i < (*list)[0].PDUSESSION_ID; i++) {
        memcpy(&(*list)[i], buffer + i * sizeof(UEContext), sizeof(UEContext));
    }
}
