// Define the structure for LTEPHY_TransportChannelInfo_t
typedef struct {
    int transportChannelId;
    char modulationScheme[10];
    int modulationOrder;
    float codingRate;
} LTEPHY_TransportChannelInfo_t;

// Define the dynamic array for storing LTEPHY_TransportChannelInfo_t structures
typedef struct {
    LTEPHY_TransportChannelInfo_t *array;
    int size;
    int capacity;
} DynamicArray;

// Function to initialize and manage a dynamic array of LTEPHY_TransportChannelInfo_t structures
void initDynamicArray(DynamicArray *array) {
    // Allocate memory for the array
    array->array = (LTEPHY_TransportChannelInfo_t *)malloc(sizeof(LTEPHY_TransportChannelInfo_t) * 10);
    if (!array->array) {
        printf("Error: Failed to allocate memory for dynamic array\n");
        exit(1);
    }
    // Initialize the size and capacity of the array
    array->size = 0;
    array->capacity = 10;
}

// Function to add a new entry to the dynamic array
void addEntryToDynamicArray(DynamicArray *array, int transportChannelId, char modulationScheme[], int modulationOrder, float codingRate) {
    // Check if the array is full and needs to be resized
    if (array->size == array->capacity) {
        // Double the capacity of the array
        array->capacity *= 2;
        // Reallocate memory for the array
        LTEPHY_TransportChannelInfo_t *newArray = (LTEPHY_TransportChannelInfo_t *)realloc(array->array, sizeof(LTEPHY_TransportChannelInfo_t) * array->capacity);
        if (!newArray) {
            printf("Error: Failed to reallocate memory for dynamic array\n");
            exit(1);
        }
        // Update the pointer and size of the array
        array->array = newArray;
    }
    // Add a new entry to the array
    array->array[array->size].transportChannelId = transportChannelId;
    strcpy(array->array[array->size].modulationScheme, modulationScheme);
    array->array[array->size].modulationOrder = modulationOrder;
    array->array[array->size].codingRate = codingRate;
    array->size++;
}

// Function to update an existing entry in the dynamic array
void updateEntryInDynamicArray(DynamicArray *array, int transportChannelId, char modulationScheme[], int modulationOrder, float codingRate) {
    // Find the index of the entry to be updated
    int index = -1;
    for (int i = 0; i < array->size; i++) {
        if (array->array[i].transportChannelId == transportChannelId) {
            index = i;
            break;
        }
    }
    // Check if the entry was found and update it
    if (index != -1) {
        strcpy(array->array[index].modulationScheme, modulationScheme);
        array->array[index].modulationOrder = modulationOrder;
        array->array[index].codingRate = codingRate;
    } else {
        printf("Error: Could not find entry with transport channel ID %d\n", transportChannelId);
    }
}

// Function to iterate over the dynamic array and perform operations on each entry
void iterateOverDynamicArray(DynamicArray *array, void (*operation)(LTEPHY_TransportChannelInfo_t *)) {
    for (int i = 0; i < array->size; i++) {
        operation(&array->array[i]);
    }
}

// Function to calculate the total throughput for all channels in the dynamic array
float calculateTotalThroughput(DynamicArray *array) {
    float totalThroughput = 0.0f;
    iterateOverDynamicArray(array, (LTEPHY_TransportChannelInfo_t *entry) {
        // Calculate the throughput for each channel and add it to the total
        totalThroughput += calculateThroughputForChannel(entry);
    });
    return totalThroughput;
}

// Function to calculate the throughput for a single channel in the dynamic array
float calculateThroughputForChannel(LTEPHY_TransportChannelInfo_t *channel) {
    // Calculate the throughput based on the modulation scheme and coding rate
    float throughput = 0.0f;
    if (strcmp(channel->modulationScheme, "QPSK") == 0) {
        throughput = channel->codingRate * 2;
    } else if (strcmp(channel->modulationScheme, "16QAM") == 0) {
        throughput = channel->codingRate * 4;
    } else if (strcmp(channel->modulationScheme, "64QAM") == 0) {
        throughput = channel->codingRate * 16;
    }
    return throughput;
}

// Function to generate a new file name based on the provided file path and naming rules
char *generateNewFileName(const char *filePath, const char *newExtension) {
    // Check if the file path is valid and has an extension
    if (!filePath || !strchr(filePath, '.')) {
        return NULL;
    }
    // Get the directory and original name from the file path
    const char *directory = dirname(filePath);
    const char *originalName = basename(filePath);
    // Remove the extension from the original name
    size_t len = strlen(originalName);
    if (len > 4 && strcmp(&originalName[len - 4], ".txt") == 0) {
        originalName[len - 4] = '\0';
    }
    // Generate a SHA-256 hash of the original name
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256((unsigned char *)originalName, strlen(originalName), hash);
    // Format the new file name according to the naming rules
    char *newFileName = (char *)malloc(strlen(directory) + 1 + strlen(originalName) + 1 + SHA256_DIGEST_LENGTH * 2 + 10 + strlen(newExtension) + 1);
    if (!newFileName) {
        printf("Error: Failed to allocate memory for new file name\n");
        exit(1);
    }
    sprintf(newFileName, "%s/%s.%s-%010d.%s", directory, originalName, hash, (int)time(NULL), newExtension);
    return newFileName;
}

// Function to validate the file name and ensure it follows the naming rules
bool validateFileName(const char *fileName) {
    // Check if the file name is valid and has an extension
    if (!fileName || !strchr(fileName, '.')) {
        return false;
    }
    // Get the directory and original name from the file name
    const char *directory = dirname(fileName);
    const char *originalName = basename(fileName);
    // Remove the extension from the original name
    size_t len = strlen(originalName);
    if (len > 4 && strcmp(&originalName[len - 4], ".txt") == 0) {
        originalName[len - 4] = '\0';
    }
    // Validate the directory and original name against the naming rules
    if (!directory || !strchr(directory, '/') || strlen(originalName) < 10) {
        return false;
    }
    // Get the hash of the original name and validate it against the naming rules
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256((unsigned char *)originalName, strlen(originalName), hash);
    if (strlen(hash) != 32 || !isalnum(hash[0]) || !isalnum(hash[1]) || !isalnum(hash[2])) {
        return false;
    }
    // Get the timestamp and sequence of digits from the file name
    const char *timestamp = strchr(originalName, '-');
    if (!timestamp) {
        return false;
    }
    int sequenceOfDigits = atoi(timestamp + 1);
    if (sequenceOfDigits < 0 || sequenceOfDigits > 999999999) {
        return false;
    }
    // Get the new extension from the file name and validate it against the naming rules
    const char *newExtension = strrchr(originalName, '.');
    if (!newExtension || !strchr(newExtension + 1, '.')) {
        return false;
    }
    int newExtensionLen = strlen(newExtension);
    for (int i = 0; i < newExtensionLen; i++) {
        if (!isalnum(newExtension[i])) {
            return false;
        }
    }
    // If all validation checks pass, the file name is valid
    return true;
}

// Function to handle edge cases like invalid paths, missing directories, and unsupported file types
void handleEdgeCases(const char *filePath) {
    // Check if the file path is valid and has an extension
    if (!filePath || !strchr(filePath, '.')) {
        printf("Error: Invalid file path provided\n");
        exit(1);
    }
    // Get the directory and original name from the file path
    const char *directory = dirname(filePath);
    const char *originalName = basename(filePath);
    // Remove the extension from the original name
    size_t len = strlen(originalName);
    if (len > 4 && strcmp(&originalName[len - 4], ".txt") == 0) {
        originalName[len - 4] = '\0';
    }
    // Check if the directory exists and is accessible
    struct stat dirStat;
    if (stat(directory, &dirStat) != 0 || !S_ISDIR(dirStat.st_mode)) {
        printf("Error: Invalid directory provided\n");
        exit(1);
    }
    // Check if the file type is supported
    const char *extension = strrchr(originalName, '.');
    if (!extension || !strcmp(extension, ".txt") || !strcmp(extension, ".csv")) {
        printf("Error: Unsupported file type provided\n");
        exit(1);
    }
}
