// Define the function to fetch and process tasks from the API
void fetchAndProcessTasks() {
    // Initialize the cache entries
    CACHE_ENTRY_T cacheEntries[CACHE_SIZE];
    for (int i = 0; i < CACHE_SIZE; i++) {
        cacheEntries[i].taskID = -1;
        cacheEntries[i].timestamp = 0;
        cacheEntries[i].status = 0;
    }

    // Initialize the task metadata array
    TASK_METADATA_T* taskMetadataArray = NULL;
    int numTasks = 0;

