        curl_easy_setopt(curl, CURLOPT_URL, apiEndpoint);
        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        } else {
            // Parse the JSON response from the API
            json_object* jsonResponse = json_tokener_parse(curl_easy_strerror(res));
            if (jsonResponse) {
                // Get the task metadata array from the JSON response
                json_object* tasksJson = json_object_get_object(jsonResponse, "tasks");
                numTasks = json_object_array_length(tasksJson);
                taskMetadataArray = malloc(numTasks * sizeof(TASK_METADATA_T));
                for (int i = 0; i < numTasks; i++) {
                    json_object* taskJson = json_object_array_get_idx(tasksJson, i);
                    taskMetadataArray[i].taskID = json_object_get_int(json_object_get_object(taskJson, "id"));
                    taskMetadataArray[i].priority = json_object_get_int(json_object_get_object(taskJson, "priority"));
                    taskMetadataArray[i].deadline = json_object_get_int(json_object_get_object(taskJson, "deadline"));
                }
            }
        }
        curl_easy_cleanup(curl);
    }

    // Process the tasks in the task metadata array
    for (int i = 0; i < numTasks; i++) {
        TASK_METADATA_T* taskMetadata = &taskMetadataArray[i];
        int taskID = taskMetadata->taskID;
        int priority = taskMetadata->priority;
        int deadline = taskMetadata->deadline;

        // Check if the task is in the cache
        bool foundInCache = false;
        for (int j = 0; j < CACHE_SIZE; j++) {
            if (cacheEntries[j].taskID == taskID) {
                foundInCache = true;
                break;
            }
        }

        // If the task is not in the cache, fetch and process it from the API
        if (!foundInCache) {
            // Fetch the task from the API
            CURL *curl;
            CURLcode res;
            curl_global_init(CURL_GLOBAL_DEFAULT);
            curl = curl_easy_init();
            if (curl) {
                char url[1024];
