                        int crcFlag = json_object_get_int(json_object_get_object(taskJson, "crcFlag"));

                        // Create a new NFAPI_CRC_INDICATION_PDU_T structure for the task
                        NFAPI_CRC_INDICATION_PDU_T* nfapiTask = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
                        nfapiTask->RX_UE_INFORMATION_TAG = 0;
                        nfapiTask->RNTI = taskID;
                        nfapiTask->CRC_INDICATION_REL8_TAG = crcFlag;

                        // Add the task to the cache
                        int oldestCacheEntryIndex = -1;
                        for (int j = 0; j < CACHE_SIZE; j++) {
                            if (cacheEntries[j].timestamp == 0) {
                                oldestCacheEntryIndex = j;
                                break;
                            } else if (cacheEntries[j].timestamp > cacheEntries[oldestCacheEntryIndex].timestamp) {
                                oldestCacheEntryIndex = j;
                            }
                        }
                        if (oldestCacheEntryIndex != -1) {
                            cacheEntries[oldestCacheEntryIndex].taskID = taskID;
                            cacheEntries[oldestCacheEntryIndex].timestamp = time(NULL);
                            cacheEntries[oldestCacheEntryIndex].status = 0;
                        }
                    }
                }
                curl_easy_cleanup(curl);
            }
        }

        // Process the task in the cache
        for (int j = 0; j < CACHE_SIZE; j++) {
            if (cacheEntries[j].taskID == taskID) {
                int status = cacheEntries[j].status;
                if (status == 0) {
