                    double weightedAverage = (priority + deadline) / 2.0;

                    // Append the weighted average as a new attribute in the output
                    json_object* taskJson = json_object_new_int(weightedAverage);
                    json_object_object_add(jsonResponse, "weightedAverage", taskJson);

                    // Update the status of the cache entry
                    cacheEntries[j].status = 1;
                }
            }
        }
    }

