// Define a linked list node to store the NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct Node *next;
} Node;

// Define a global variable to store the head of the linked list
Node *head = NULL;

// Define a function to allocate memory for a new node and initialize it with the given data
Node* create_node(NFAPI_CRC_INDICATION_PDU_T *data) {
    Node *new_node = malloc(sizeof(Node));
    if (new_node == NULL) {
        return NULL;
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

// Define a function to add a node to the linked list
void add_node(Node *new_node) {
    if (head == NULL) {
        head = new_node;
    } else {
        Node *current = head;
        while (current->next != NULL) {
