// Define the record structure
typedef struct {
    int key;
} Record;

// Function to read input from user and validate it
int readInput(char* prompt, int min, int max) {
    int input = 0;
    printf("%s", prompt);
    scanf("%d", &input);
    if (input < min || input > max) {
        printf("Invalid input. Please enter a value between %d and %d.\n", min, max);
        return -1;
    }
    return input;
}

// Function to allocate memory for arrays and initialize them
void initArrays(int* offset_array, int* key_array, Record** record_array, int num_records) {
    // Allocate memory for the offset array
    *offset_array = (int*)malloc(num_records * sizeof(int));
    if (*offset_array == NULL) {
        printf("Error: Failed to allocate memory for offset array.\n");
        exit(1);
    }

    // Initialize the offset array with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        (*offset_array)[i] = rand() % max + min;
    }

    // Allocate memory for the key array
    *key_array = (int*)malloc(num_records * sizeof(int));
    if (*key_array == NULL) {
        printf("Error: Failed to allocate memory for key array.\n");
        exit(1);
    }

    // Initialize the key array with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        (*key_array)[i] = rand() % max + min;
    }

    // Allocate memory for the record array
    *record_array = (Record*)malloc(num_records * sizeof(Record));
    if (*record_array == NULL) {
        printf("Error: Failed to allocate memory for record array.\n");
        exit(1);
    }

    // Initialize the record array with random values within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        (*record_array)[i].key = rand() % max + min;
    }
}

// Function to sort the records based on their keys in ascending order
void sortRecords(Record** record_array, int num_records) {
    // Use a bubble sort algorithm to sort the records based on their keys
    for (int i = 0; i < num_records - 1; i++) {
        for (int j = 0; j < num_records - i - 1; j++) {
            if ((*record_array)[j].key > (*record_array)[j + 1].key) {
                Record temp = (*record_array)[j];
                (*record_array)[j] = (*record_array)[j + 1];
                (*record_array)[j + 1] = temp;
            }
        }
    }
}

// Function to output the sorted records to a file
void outputRecords(Record** record_array, int num_records, char* file_path) {
    // Open the file for writing and validate its existence
    FILE* fp = fopen(file_path, "w");
    if (fp == NULL) {
        printf("Error: Failed to open file %s.\n", file_path);
        exit(1);
    }

    // Write the sorted records to the file
    for (int i = 0; i < num_records; i++) {
        fprintf(fp, "%d\n", (*record_array)[i].key);
    }

    // Close the file and validate its closure
    if (fclose(fp) != 0) {
        printf("Error: Failed to close file %s.\n", file_path);
        exit(1);
    }
}

// Function to handle memory allocation failures and print error messages
void handleMemoryAllocationFailure() {
    printf("Error: Memory allocation failed. Exiting program.\n");
    exit(1);
}

int main() {
    // Declare variables for the arrays and record array
    int* offset_array = NULL;
    int* key_array = NULL;
    Record** record_array = NULL;

    // Read input from user to determine the number of records
    int num_records = readInput("Enter the number of records: ", 1, INT_MAX);
    if (num_records == -1) {
        handleMemoryAllocationFailure();
    }

    // Initialize the arrays and record array
    initArrays(&offset_array, &key_array, &record_array, num_records);

    // Use a loop to set the value of each record's int field to a random value within a specified range
    for (int i = 0; i < num_records; i++) {
        (*record_array)[i].key = rand() % max + min;
    }

    // Sort the records based on their keys in ascending order
    sortRecords(&record_array, num_records);

    // Output the sorted records to a file
    char* file_path = "sorted_records.txt";
    outputRecords(&record_array, num_records, file_path);

    // Free memory allocated for arrays and record array
    free(offset_array);
    free(key_array);
    free(record_array);

    return 0;
}
