cache_t *create_cache() {
    cache_t *cache = malloc(sizeof(cache_t));
    if (!cache) {
        perror("malloc");
        return NULL;
    }
    cache->id = 0;
    cache->num_fields = 0;
    cache->num_messages = 0;
    return cache;
}

void destroy_cache(cache_t *cache) {
    free(cache);
}

bool add_field(cache_t *cache, char *field_name, char *field_value) {
    if (cache->num_fields >= MAX_FIELD_NAMES) {
        return false;
    }
    cache->field_names[cache->num_fields] = field_name;
    cache->field_values[cache->num_fields] = field_value;
    cache->num_fields++;
    return true;
}

bool add_message(cache_t *cache, char *message) {
    if (cache->num_messages >= MAX_MESSAGE_SIZE) {
        return false;
    }
    cache->messages[cache->num_messages] = message;
    cache->num_messages++;
    return true;
}

void update_field(cache_t *cache, int id, char *field_name, char *field_value) {
    for (int i = 0; i < cache->num_fields; i++) {
        if (cache->id == id && strcmp(cache->field_names[i], field_name) == 0) {
            free(cache->field_values[i]);
            cache->field_values[i] = field_value;
            return;
        }
    }
}

void update_message(cache_t *cache, int id, char *message) {
    for (int i = 0; i < cache->num_messages; i++) {
        if (cache->id == id && strcmp(cache->messages[i], message) == 0) {
            free(cache->messages[i]);
            cache->messages[i] = message;
            return;
        }
    }
}

