    for (int i = 0; i < cache->num_messages; i++) {
        if (cache->id == id && strcmp(cache->messages[i], message) == 0) {
            free(cache->messages[i]);
            cache->messages[i] = NULL;
            return;
        }
    }
}

void refresh_dialog_fields(cache_t *cache, int id, char *field_names[]) {
    for (int i = 0; i < cache->num_fields; i++) {
        if (cache->id == id) {
            for (int j = 0; j < MAX_FIELD_NAMES; j++) {
                if (strcmp(cache->field_names[i], field_names[j]) == 0) {
                    send_success_message(parent, "Field updated successfully");
                    update_field(cache, id, field_names[j], cache->field_values[i]);
                }
            }
        }
    }
}

void refresh_dialog_messages(cache_t *cache, int id, char *messages[]) {
    for (int i = 0; i < cache->num_messages; i++) {
        if (cache->id == id) {
            for (int j = 0; j < MAX_MESSAGE_SIZE; j++) {
