void delete_dialog_messages(cache_t *cache, int id, char *messages[]) {
    for (int i = 0; i < cache->num_messages; i++) {
        if (cache->id == id) {
            for (int j = 0; j < MAX_MESSAGE_SIZE; j++) {
                if (strcmp(cache->messages[i], messages[j]) == 0) {
                    send_success_message(parent, "Message deleted successfully");
                    delete_message(cache, id, messages[j]);
                }
            }
        }
    }
}

void handle_request(int socket, cache_t *cache) {
    char request[MAX_MESSAGE_SIZE];
    read(socket, request, MAX_MESSAGE_SIZE);
    if (strcmp(request, "GET") == 0) {
        send_success_message(parent, "Request received");
        refresh_dialog_fields(cache, id, field_names);
        refresh_dialog_messages(cache, id, messages);
    } else if (strcmp(request, "PUT") == 0) {
        char *field_name = get_field_name(request);
        char *field_value = get_field_value(request);
        send_success_message(parent, "Field updated successfully");
        update_field(cache, id, field_name, field_value);
    } else if (strcmp(request, "DELETE") == 0) {
        char *field_name = get_field_name(request);
        send_success_message(parent, "Field deleted successfully");
        delete_field(cache, id, field_name);
    } else if (strcmp(request, "POST") == 0) {
        char *message = get_message(request);
        send_success_message(parent, "Message updated successfully");
        update_message(cache, id, message);
    } else if (strcmp(request, "DELETE") == 0) {
        char *message = get_message(request);
        send_success_message(parent, "Message deleted successfully");
        delete_message(cache, id, message);
    }
}

int main() {
    int socket = create_socket();
    if (socket < 0) {
        perror("create_socket");
        return 1;
    }
    cache_t *cache = create_cache();
    if (!cache) {
        perror("create_cache");
        return 1;
    }
    while (true) {
        handle_request(socket, cache);
    }
    destroy_cache(cache);
    close(socket);
    return 0;
}
