#include <stdio.h>
#include "network_config.h"

void configureNetworkParameters(NetworkConfig_T *configs, size_t num_configs) {
    // Initialize the network configuration array
    for (size_t i = 0; i < num_configs; i++) {
        configs[i].ip_address = NULL;
        configs[i].subnet_mask = NULL;
        configs[i].gateway = NULL;
        configs[i].dns_servers = NULL;
    }

    // Read network configuration from file
    FILE *config_file = fopen("network_config.txt", "r");
    if (config_file == NULL) {
        printf("Error: unable to open network configuration file\n");
        return;
    }

    char line[256];
    while (fgets(line, sizeof(line), config_file)) {
        // Skip comments and empty lines
        if (line[0] == '#' || line[0] == '\n') {
            continue;
        }

        // Parse IP address
        char *token = strtok(line, " ");
        if (token == NULL) {
            printf("Error: unable to parse IP address\n");
            fclose(config_file);
            return;
        }
        configs[i].ip_address = token;

        // Parse subnet mask
        token = strtok(NULL, " ");
        if (token == NULL) {
            printf("Error: unable to parse subnet mask\n");
            fclose(config_file);
            return;
        }
        configs[i].subnet_mask = token;

        // Parse gateway
        token = strtok(NULL, " ");
        if (token == NULL) {
            printf("Error: unable to parse gateway\n");
            fclose(config_file);
            return;
        }
        configs[i].gateway = token;

        // Parse DNS servers
        token = strtok(NULL, " ");
        if (token == NULL) {
            printf("Error: unable to parse DNS servers\n");
            fclose(config_file);
            return;
        }
        configs[i].dns_servers = token;
    }

    // Close the configuration file
    fclose(config_file);
}
