void populateRecords(Record* records, int numRecords, int minValue, int maxValue) {
    // Allocate memory for the array of long offset values and int keys
    long* offsets = (long*)malloc(numRecords * sizeof(long));
    int* keys = (int*)malloc(numRecords * sizeof(int));

