// Define a dynamic array to store the CRC indications
static NFAPI_CRC_INDICATION_PDU_T* crcIndications = NULL;
static size_t numCrcIndications = 0;
static pthread_mutex_t crcIndicationsMutex = PTHREAD_MUTEX_INITIALIZER;

// Function to allocate and initialize a new CRC indication structure
NFAPI_CRC_INDICATION_PDU_T* createCrcIndication(uint16_t RX_UE_INFORMATION_TAG, uint32_t RNTI) {
    NFAPI_CRC_INDICATION_PDU_T* newCrcIndication = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (newCrcIndication == NULL) {
        // Handle allocation failure
        return NULL;
    }
    newCrcIndication->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newCrcIndication->RNTI = RNTI;
    newCrcIndication->CRCFLAG = (uint8_t)rand(); // Randomly set CRCFLAG
    return newCrcIndication;
}

// Function to update an existing CRC indication structure by RNTI
int updateCrcIndication(uint32_t RNTI, NFAPI_CRC_INDICATION_PDU_T* crcIndication) {
    pthread_mutex_lock(&crcIndicationsMutex);
    for (size_t i = 0; i < numCrcIndications; i++) {
        if (crcIndications[i].RNTI == RNTI) {
            // Update the existing CRC indication structure
            crcIndications[i] = *crcIndication;
            pthread_mutex_unlock(&crcIndicationsMutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&crcIndicationsMutex);
    // Handle the case where no matching CRC indication structure was found
    return -1;
}

// Function to remove a CRC indication structure by RNTI
int removeCrcIndication(uint32_t RNTI) {
    pthread_mutex_lock(&crcIndicationsMutex);
    for (size_t i = 0; i < numCrcIndications; i++) {
        if (crcIndications[i].RNTI == RNTI) {
            // Remove the matching CRC indication structure
            free(crcIndications[i]);
            crcIndications[i] = NULL;
            numCrcIndications--;
            pthread_mutex_unlock(&crcIndicationsMutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&crcIndicationsMutex);
    // Handle the case where no matching CRC indication structure was found
    return -1;
}

// Function to add a new CRC indication structure or update an existing one by RNTI
int addOrUpdateCrcIndication(uint32_t RNTI, NFAPI_CRC_INDICATION_PDU_T* crcIndication) {
    pthread_mutex_lock(&crcIndicationsMutex);
    for (size_t i = 0; i < numCrcIndications; i++) {
        if (crcIndications[i].RNTI == RNTI) {
            // Update the existing CRC indication structure
            crcIndications[i] = *crcIndication;
            pthread_mutex_unlock(&crcIndicationsMutex);
            return 0;
        }
    }
    // Add a new CRC indication structure if no matching one was found
    NFAPI_CRC_INDICATION_PDU_T* newCrcIndication = createCrcIndication(crcIndication->RX_UE_INFORMATION_TAG, RNTI);
    if (newCrcIndication == NULL) {
        pthread_mutex_unlock(&crcIndicationsMutex);
        return -1;
    }
    crcIndications = realloc(crcIndications, (numCrcIndications + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (crcIndications == NULL) {
        free(newCrcIndication);
        pthread_mutex_unlock(&crcIndicationsMutex);
        return -1;
    }
    crcIndications[numCrcIndications] = *newCrcIndication;
    numCrcIndications++;
    pthread_mutex_unlock(&crcIndicationsMutex);
    return 0;
}

// Function to retrieve a CRC indication structure by RNTI
NFAPI_CRC_INDICATION_PDU_T* getCrcIndication(uint32_t RNTI) {
    pthread_mutex_lock(&crcIndicationsMutex);
    for (size_t i = 0; i < numCrcIndications; i++) {
        if (crcIndications[i].RNTI == RNTI) {
            // Return the matching CRC indication structure
            pthread_mutex_unlock(&crcIndicationsMutex);
            return &crcIndications[i];
        }
    }
    pthread_mutex_unlock(&crcIndicationsMutex);
    // Handle the case where no matching CRC indication structure was found
    return NULL;
}

// Function to retrieve all CRC indication structures
NFAPI_CRC_INDICATION_PDU_T* getAllCrcIndications() {
    pthread_mutex_lock(&crcIndicationsMutex);
    NFAPI_CRC_INDICATION_PDU_T* allCrcIndications = malloc(numCrcIndications * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (allCrcIndications == NULL) {
        pthread_mutex_unlock(&crcIndicationsMutex);
        return NULL;
    }
    for (size_t i = 0; i < numCrcIndications; i++) {
        allCrcIndications[i] = crcIndications[i];
    }
    pthread_mutex_unlock(&crcIndicationsMutex);
    return allCrcIndications;
}

// Function to clear all CRC indication structures
void clearAllCrcIndications() {
    pthread_mutex_lock(&crcIndicationsMutex);
    for (size_t i = 0; i < numCrcIndications; i++) {
        free(crcIndications[i]);
    }
    free(crcIndications);
    crcIndications = NULL;
    numCrcIndications = 0;
    pthread_mutex_unlock(&crcIndicationsMutex);
}
