#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a struct to represent an element in the array
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdu;
} Element;

// Define a struct to represent the dynamic array
typedef struct {
    Element *elements; // Pointer to the elements in the array
    size_t count; // Number of elements in the array
    size_t capacity; // Maximum number of elements that can be stored in the array
} DynamicArray;

// Define a mutex for synchronizing access to the dynamic array
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new element to the dynamic array
void addElement(DynamicArray *array, NFAPI_CRC_INDICATION_PDU_T pdu) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&mutex);

    // Check if the array is full and needs to be resized
    if (array->count == array->capacity) {
        // Double the capacity of the array
        array->capacity *= 2;

        // Reallocate memory for the elements in the array
        Element *newElements = realloc(array->elements, sizeof(Element) * array->capacity);
        if (newElements == NULL) {
            // Handle error
            pthread_mutex_unlock(&mutex);
            return;
        }

        // Update the elements pointer in the array
        array->elements = newElements;
    }

    // Add the new element to the end of the array
    array->elements[array->count++] = pdu;

    // Release the lock on the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to remove an element from the dynamic array
void removeElement(DynamicArray *array, size_t index) {
    // Acquire the lock on the mutex
    pthread_mutex_lock(&mutex);

    // Check if the index is valid
    if (index >= array->count) {
        // Handle error
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Shift all elements after the specified index to the left by one position
    for (size_t i = index + 1; i < array->count; i++) {
        array->elements[i - 1] = array->elements[i];
    }

    // Decrement the count of elements in the array
    array->count--;

    // Release the lock on the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to retrieve the total count of elements in the dynamic array
size_t getCount(DynamicArray *array) {
    return array->count;
}
```
