// Define the structure for the CRC indication PDU
typedef struct {
    uint16_t rx_ue_information_tag;
    uint32_t rnti;
    uint8_t crc_indication_rel8_tag;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the dynamic array of CRC indication PDUs
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdu;
    size_t capacity;
    size_t count;
} NFAPI_CRC_INDICATION_PDUS;

// Define the mutex for synchronizing access to the dynamic array
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new CRC indication PDU to the dynamic array
void nfapi_crc_indication_pdu_add(NFAPI_CRC_INDICATION_PDUS *pdus, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Acquire the mutex to synchronize access to the dynamic array
    pthread_mutex_lock(&mutex);

    // Check if the dynamic array needs to be resized
    if (pdus->count == pdus->capacity) {
        // Double the capacity of the dynamic array
        size_t new_capacity = pdus->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_pdu = realloc(pdus->pdu, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_pdu == NULL) {
            // Reallocation failed, release the mutex and return
            pthread_mutex_unlock(&mutex);
            return;
        }
        pdus->capacity = new_capacity;
        pdus->pdu = new_pdu;
    }

    // Add the new CRC indication PDU to the dynamic array
    pdus->pdu[pdus->count++] = *pdu;

    // Release the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to remove a CRC indication PDU from the dynamic array
void nfapi_crc_indication_pdu_remove(NFAPI_CRC_INDICATION_PDUS *pdus, size_t index) {
    // Acquire the mutex to synchronize access to the dynamic array
    pthread_mutex_lock(&mutex);

    // Check if the index is valid
    if (index >= pdus->count) {
        // Release the mutex and return
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Remove the CRC indication PDU from the dynamic array
    NFAPI_CRC_INDICATION_PDU_T *pdu = &pdus->pdu[index];
    memmove(pdu, pdu + 1, (pdus->count - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pdus->count--;

    // Release the mutex
    pthread_mutex_unlock(&mutex);
}

// Function to retrieve a CRC indication PDU from the dynamic array by index
NFAPI_CRC_INDICATION_PDU_T *nfapi_crc_indication_pdu_get(NFAPI_CRC_INDICATION_PDUS *pdus, size_t index) {
    // Acquire the mutex to synchronize access to the dynamic array
    pthread_mutex_lock(&mutex);

    // Check if the index is valid
    if (index >= pdus->count) {
        // Release the mutex and return NULL
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    // Return the CRC indication PDU at the specified index
    NFAPI_CRC_INDICATION_PDU_T *pdu = &pdus->pdu[index];

    // Release the mutex
    pthread_mutex_unlock(&mutex);

    return pdu;
}
