#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    RX_UE_INFORMATION_TAG rxUeInformationTag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
    SIB_TAGS *sibTags;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the structure for SIB_TAGS
typedef struct {
    TIMESTAMP timestamp;
    INTEGRITY_CHECK_VALUE integrityCheckValue;
} SIB_TAGS;

// Define the function to initialize and populate an array of NFAPI_CRC_INDICATION_PDU_T structures
void initAndPopulateNfapiCrcIndicationPduArray(int numOfStructures, int maxNumOfSibs) {
    // Allocate memory for the array of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T *nfapiCrcIndicationPduArray = (NFAPI_CRC_INDICATION_PDU_T *)malloc(numOfStructures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!nfapiCrcIndicationPduArray) {
        printf("Error: Failed to allocate memory for the array of NFAPI_CRC_INDICATION_PDU_T structures\n");
        return;
    }

    // Initialize each structure in the array with a valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
    for (int i = 0; i < numOfStructures; i++) {
        nfapiCrcIndicationPduArray[i].rxUeInformationTag = RX_UE_INFORMATION_TAG_VALID;
        nfapiCrcIndicationPduArray[i].rnti = generateRandomRnti();
        nfapiCrcIndicationPduArray[i].crcIndicationRel8Tag.crcflag = generateRandomCrcflag();
    }

    // Populate each structure with a list of up to MAX_NUM_OF_SIBS SIB tags, each tagged with a timestamp and a randomly generated integrity check value
    for (int i = 0; i < numOfStructures; i++) {
        nfapiCrcIndicationPduArray[i].sibTags = (SIB_TAGS *)malloc(maxNumOfSibs * sizeof(SIB_TAGS));
        if (!nfapiCrcIndicationPduArray[i].sibTags) {
            printf("Error: Failed to allocate memory for the list of SIB tags\n");
            return;
        }
        for (int j = 0; j < maxNumOfSibs; j++) {
            nfapiCrcIndicationPduArray[i].sibTags[j].timestamp = generateRandomTimestamp();
            nfapiCrcIndicationPduArray[i].sibTags[j].integrityCheckValue = generateRandomIntegrityCheckValue();
        }
    }
}

// Generate a random RNTI value
RNTI generateRandomRnti() {
    // Use the time as a seed for the random number generator to ensure reproducibility
    srand(time(NULL));
    return (RNTI)rand();
}

// Generate a random CRC flag value
CRC_INDICATION_REL8_TAG generateRandomCrcflag() {
    // Use the time as a seed for the random number generator to ensure reproducibility
    srand(time(NULL));
    return (CRC_INDICATION_REL8_TAG)rand();
}

// Generate a random timestamp value
TIMESTAMP generateRandomTimestamp() {
    // Use the time as a seed for the random number generator to ensure reproducibility
    srand(time(NULL));
    return (TIMESTAMP)rand();
}

// Generate a random integrity check value
INTEGRITY_CHECK_VALUE generateRandomIntegrityCheckValue() {
    // Use the time as a seed for the random number generator to ensure reproducibility
    srand(time(NULL));
    return (INTEGRITY_CHECK_VALUE)rand();
}
