    array->data[array->count].RNTI = RNTI;
    array->data[array->count].CRCFLAG = CRCFLAG;
    // Increment the count of elements in the dynamic array
    array->count++;
    // Unlock the mutex to release thread-safe access to the dynamic array
    pthread_mutex_unlock(&mutex);
