    pthread_mutex_lock(&mutex);
    // Iterate over the elements in the dynamic array
    for (size_t i = 0; i < array->count; i++) {
        if (array->data[i].RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) {
            // Unlock the mutex to release thread-safe access to the dynamic array
            pthread_mutex_unlock(&mutex);
            return &array->data[i];
        }
    }
    // Unlock the mutex to release thread-safe access to the dynamic array
    pthread_mutex_unlock(&mutex);
    return NULL;
}

