NFAPI_CRC_INDICATION_PDU_T* allocate_crc_indication_pdu(int n) {
    // Validate the input parameter 'n'
    if (n < 0) {
        printf("Error: Invalid value for 'n'\n");
        return NULL;
    }

    // Allocate memory for the array of structures
    NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * n);
    if (pdu == NULL) {
        printf("Error: Failed to allocate memory for the array of structures\n");
        return NULL;
    }

    // Initialize each structure with a valid RX_UE_INFORMATION_TAG and RNTI
