        pdu[i].rnti = generate_random_rnti();
    }

    // Populate the CRC_INDICATION_REL8_TAG with a randomly generated CRC flag
    for (int i = 0; i < n; i++) {
        pdu[i].crc_indication_rel8.crc_flag = generate_random_crc_flag();
