LTE_NAS_PDU* init_nas_pdu_list() {
    LTE_NAS_PDU* head = NULL;
    LTE_NAS_PDU* current = NULL;
    LTE_NAS_PDU* previous = NULL;

    // Allocate memory for the first node in the list
    head = (LTE_NAS_PDU*) custom_alloc(sizeof(LTE_NAS_PDU));
    if (!head) {
        return NULL;
    }

    current = head;

    // Initialize the first node in the list
    current->nas_message_type = 0;
    current->nas_message_id = 0;
    current->nas_message = NULL;

    // Allocate memory for the dynamic NAS message body
    current->nas_message = (NAS_MESSAGE*) custom_alloc(sizeof(NAS_MESSAGE));
    if (!current->nas_message) {
        free(head);
        return NULL;
    }

    // Initialize the dynamic NAS message body
    memset(current->nas_message, 0, sizeof(NAS_MESSAGE));

    // Set the head and current pointers to the first node in the list
    head = current;
    current = NULL;

    return head;
}

// Function to insert a new LTE_NAS_PDU structure into the linked list
int insert_nas_pdu(LTE_NAS_PDU* head, NAS_MESSAGE_TYPE nas_message_type, NAS_MESSAGE_ID nas_message_id, void* nas_message) {
    LTE_NAS_PDU* current = NULL;
    LTE_NAS_PDU* previous = NULL;

    // Allocate memory for the new node in the list
    current = (LTE_NAS_PDU*) custom_alloc(sizeof(LTE_NAS_PDU));
    if (!current) {
        return -1;
    }

    // Initialize the new node in the list
    current->nas_message_type = nas_message_type;
    current->nas_message_id = nas_message_id;
    current->nas_message = (NAS_MESSAGE*) custom_alloc(sizeof(NAS_MESSAGE));
    if (!current->nas_message) {
        free(current);
        return -1;
    }

    // Copy the NAS message body into the new node
    memcpy(current->nas_message, nas_message, sizeof(NAS_MESSAGE));

    // Insert the new node into the list
    if (head == NULL) {
        head = current;
    } else {
        previous = head;
        while (previous->next != NULL) {
            previous = previous->next;
        }
        previous->next = current;
    }

    return 0;
}

// Function to delete a LTE_NAS_PDU structure from the linked list
int delete_nas_pdu(LTE_NAS_PDU* head, NAS_MESSAGE_TYPE nas_message_type, NAS_MESSAGE_ID nas_message_id) {
    LTE_NAS_PDU* current = NULL;
    LTE_NAS_PDU* previous = NULL;

    // Find the node to be deleted in the list
    current = head;
    while (current != NULL && current->nas_message_type != nas_message_type || current->nas_message_id != nas_message_id) {
        previous = current;
        current = current->next;
    }

    // If the node is found, delete it from the list
    if (current != NULL) {
        if (previous == NULL) {
            head = current->next;
        } else {
            previous->next = current->next;
        }
        free(current->nas_message);
        free(current);
        return 0;
    }

    // If the node is not found, return an error code
    return -1;
}

// Function to serialize the linked list into a binary file
int serialize_nas_pdu_list(LTE_NAS_PDU* head, const char* filename) {
    FILE* fp = NULL;
    LTE_NAS_PDU* current = NULL;

    // Open the output file for writing
    fp = fopen(filename, "wb");
    if (fp == NULL) {
        return -1;
    }

    // Write the linked list to the output file
    current = head;
    while (current != NULL) {
        fwrite(&current->nas_message_type, sizeof(NAS_MESSAGE_TYPE), 1, fp);
        fwrite(&current->nas_message_id, sizeof(NAS_MESSAGE_ID), 1, fp);
        fwrite(current->nas_message, sizeof(NAS_MESSAGE), 1, fp);
        current = current->next;
    }

    // Close the output file
    fclose(fp);

    return 0;
}

// Function to deserialize the linked list from a binary file
int deserialize_nas_pdu_list(LTE_NAS_PDU* head, const char* filename) {
    FILE* fp = NULL;
    LTE_NAS_PDU* current = NULL;
    LTE_NAS_PDU* previous = NULL;
    size_t read_size = 0;

    // Open the input file for reading
    fp = fopen(filename, "rb");
    if (fp == NULL) {
        return -1;
    }

    // Read the linked list from the input file
    current = head;
    while (current != NULL) {
        read_size = fread(&current->nas_message_type, sizeof(NAS_MESSAGE_TYPE), 1, fp);
        if (read_size == 0) {
            break;
        }
        read_size = fread(&current->nas_message_id, sizeof(NAS_MESSAGE_ID), 1, fp);
        if (read_size == 0) {
            break;
        }
        current->nas_message = (NAS_MESSAGE*) custom_alloc(sizeof(NAS_MESSAGE));
        read_size = fread(current->nas_message, sizeof(NAS_MESSAGE), 1, fp);
