int init_uplink_envelopes(LTE_UPLINK_ENVELOPE_T *envelopes, int num_envelopes) {
    // Initialize RRC connection context for each envelope
    for (int i = 0; i < num_envelopes; i++) {
        envelopes[i].rrc_context.state = RRC_STATE_CONNECTED;
        envelopes[i].rrc_context.configuration = RRC_CONFIGURATION_EUTRA;
    }

    // Initialize PDCP PDU for each envelope
    for (int i = 0; i < num_envelopes; i++) {
        envelopes[i].pdcp_pdu.sequence_number = rand() % 1000;
        envelopes[i].pdcp_pdu.payload = malloc(sizeof(char) * 1024);
        if (envelopes[i].pdcp_pdu.payload == NULL) {
            // Handle memory allocation failure gracefully
            printf("Memory allocation failed for envelope %d\n", i);
            return -1;
        }
    }

    // Calculate DL SINR and BLER values for each envelope based on predefined algorithm
    for (int i = 0; i < num_envelopes; i++) {
        double sinr = calculate_sinr(envelopes[i].tx_frame_info.channel_power, envelopes[i].pdcp_pdu.payload);
        double bler = calculate_bler(sinr, envelopes[i].rrc_context.configuration);
        envelopes[i].dl_sinr = sinr;
        envelopes[i].blr = bler;
    }

    // Log initialization process for debugging purposes
    printf("Initialized %d LTE uplink envelopes\n", num_envelopes);

    return 0;
}

// Define function to calculate DL SINR based on channel power and payload
double calculate_sinr(int channel_power, char *payload) {
