// Define the structure for LTE_NAS_PDU
typedef struct LTE_NAS_PDU {
    int NAS_MESSAGE_TYPE;
    int NAS_MESSAGE_ID;
    char* NAS_MESSAGE;
} LTE_NAS_PDU;

// Define the linked list for storing LTE_NAS_PDU structures
typedef struct LTE_NAS_PDU_LIST {
    LTE_NAS_PDU* head;
    LTE_NAS_PDU* tail;
} LTE_NAS_PDU_LIST;

// Define the function to initialize and serialize the linked list of LTE_NAS_PDU structures
void initializeAndSerializeLTE_NAS_PDUList(int N, LTE_NAS_PDU_LIST* list) {
    // Check if the input N is valid and less than or equal to 1024
    if (N <= 0 || N > 1024) {
        printf("Error: Invalid input N = %d\n", N);
        return;
    }

    // Initialize the linked list with NULL head and tail pointers
    list->head = NULL;
    list->tail = NULL;

    // Dynamically allocate memory for each LTE_NAS_PDU structure based on input N
    for (int i = 0; i < N; i++) {
        LTE_NAS_PDU* pdu = malloc(sizeof(LTE_NAS_PDU));
        if (!pdu) {
            printf("Error: Memory allocation failed\n");
            return;
        }

        // Initialize the NAS_MESSAGE_TYPE, NAS_MESSAGE_ID, and NAS_MESSAGE fields of each structure
        pdu->NAS_MESSAGE_TYPE = i;
        pdu->NAS_MESSAGE_ID = i * 2;
        pdu->NAS_MESSAGE = malloc(sizeof(char) * (i + 1));
        if (!pdu->NAS_MESSAGE) {
            printf("Error: Memory allocation failed\n");
            return;
        }
        strcpy(pdu->NAS_MESSAGE, "Hello World!");

        // Add the new structure to the linked list
        if (list->head == NULL) {
            list->head = pdu;
            list->tail = pdu;
        } else {
            list->tail->next = pdu;
            list->tail = pdu;
        }
    }

    // Serialize the linked list into a binary file for later reuse
    FILE* fp = fopen("LTE_NAS_PDU_LIST.bin", "wb");
    if (!fp) {
        printf("Error: Failed to open file for writing\n");
        return;
    }
    fwrite(list, sizeof(LTE_NAS_PDU_LIST), 1, fp);
    fclose(fp);
}

// Define the function to deserialize the linked list of LTE_NAS_PDU structures from a binary file
void deserializeLTE_NAS_PDUList(LTE_NAS_PDU_LIST* list) {
    // Open the binary file for reading
    FILE* fp = fopen("LTE_NAS_PDU_LIST.bin", "rb");
    if (!fp) {
        printf("Error: Failed to open file for reading\n");
        return;
    }

    // Read the linked list from the binary file and allocate memory for each structure
    while (fread(list, sizeof(LTE_NAS_PDU_LIST), 1, fp)) {
        LTE_NAS_PDU* pdu = malloc(sizeof(LTE_NAS_PDU));
        if (!pdu) {
            printf("Error: Memory allocation failed\n");
            return;
        }

        // Initialize the NAS_MESSAGE_TYPE, NAS_MESSAGE_ID, and NAS_MESSAGE fields of each structure
        pdu->NAS_MESSAGE_TYPE = list->head->NAS_MESSAGE_TYPE;
        pdu->NAS_MESSAGE_ID = list->head->NAS_MESSAGE_ID;
        pdu->NAS_MESSAGE = malloc(sizeof(char) * (list->head->NAS_MESSAGE_LENGTH + 1));
        if (!pdu->NAS_MESSAGE) {
            printf("Error: Memory allocation failed\n");
            return;
        }
        strcpy(pdu->NAS_MESSAGE, list->head->NAS_MESSAGE);

        // Add the new structure to the linked list
        if (list->head == NULL) {
            list->head = pdu;
            list->tail = pdu;
        } else {
            list->tail->next = pdu;
            list->tail = pdu;
        }
    }

    // Close the binary file
    fclose(fp);
}
