class BoostHttpClient : public RestApiServiceInterface {
public:
    BoostHttpClient(io_context& io_ctx) : m_io_ctx(io_ctx) {}
    ~BoostHttpClient() override = default;

    void get(const string& url, const string& payload) override {
        // Create the HTTP GET request
        http::request<http::string_body> req{http::verb::get, url, 11};
        req.set(http::field::host, "localhost");
        req.set(http::field::user_agent, BOOST_BEAST_VERSION_STRING);
        req.set(http::field::content_type, "application/json");
        req.body() = payload;
        req.prepare_payload();

        // Send the HTTP GET request
        http::async_write(m_socket, req, bind(&BoostHttpClient::on_write, this, std::placeholders::_1));
    }

    void post(const string& url, const string& payload) override {
        // Create the HTTP POST request
        http::request<http::string_body> req{http::verb::post, url, 11};
        req.set(http::field::host, "localhost");
        req.set(http::field::user_agent, BOOST_BEAST_VERSION_STRING);
        req.set(http::field::content_type, "application/json");
        req.body() = payload;
        req.prepare_payload();

        // Send the HTTP POST request
        http::async_write(m_socket, req, bind(&BoostHttpClient::on_write, this, std::placeholders::_1));
    }

private:
    void on_write(const error_code& ec) {
        if (ec) {
            BOOST_LOG_TRIVIAL(error) << "Error sending HTTP request: " << ec.message();
            return;
        }

        // Receive the HTTP response
        http::async_read(m_socket, m_buffer, m_response, bind(&BoostHttpClient::on_read, this, std::placeholders::_1));
    }

    void on_read(const error_code& ec) {
        if (ec) {
            BOOST_LOG_TRIVIAL(error) << "Error receiving HTTP response: " << ec.message();
            return;
        }

        // Check the HTTP status code
        if (m_response.result() != http::status::ok) {
            BOOST_LOG_TRIVIAL(error) << "HTTP status code: " << m_response.result_int();
            return;
        }

        // Extract the response payload
        string payload = m_response.body().data();

        // Process the response payload
        // ...
    }

private:
    io_context& m_io_ctx;
    tcp::socket m_socket;
    beast::flat_buffer m_buffer;
    http::response<http::string_body> m_response;
};

