public:
    NetworkManagementDataProcessorWithRetry(const string& url, const string& payload) : m_url(url), m_payload(payload) {}
    ~NetworkManagementDataProcessorWithRetry() = default;

    void process() {
        // Create the Boost HTTP client
        BoostHttpClient http_client(m_io_ctx);

        // Send the HTTP GET request to retrieve the network management data with retry strategy
        sendRequest(http_client, 0);

        // Wait for the HTTP response
        m_io_ctx.run();
    }

private:
    void sendRequest(BoostHttpClient& http_client, int attempt) {
        // Send the HTTP GET request to retrieve the network management data
        http_client.get(m_url, m_payload);

        // Wait for the HTTP response
        m_io_ctx.run();

        // Check if the HTTP response is successful
        if (http_client.m_response.result() != http::status::ok) {
            // Handle failed request
            BOOST_LOG_TRIVIAL(error) << "HTTP status code: " << http_client.m_response.result_int();

            // Check if the attempt is less than the maximum number of retries
            if (attempt < 3) {
                // Increment the attempt count
                attempt++;

                // Sleep for a random amount of time before retrying
                boost::this_thread::sleep(boost::posix_time::milliseconds(rand() % 1000));

                // Retry sending the HTTP GET request
                sendRequest(http_client, attempt);
            } else {
                // Mark the failed request as permanent failure
                BOOST_LOG_TRIVIAL(error) << "Permanent failure: HTTP status code: " << http_client.m_response.result_int();
            }
        }
    }

private:
    io_context m_io_ctx;
    string m_url;
    string m_payload;
