LTE_PHY_RX_FRAME_PDU_T* init_and_populate_array(int num_frames) {
    // Allocate memory for the array of structures
    LTE_PHY_RX_FRAME_PDU_T* pdu_array = (LTE_PHY_RX_FRAME_PDU_T*)malloc(num_frames * sizeof(LTE_PHY_RX_FRAME_PDU_T));
