        pdu_array[i].pucch.tag = "PUCCH";
        pdu_array[i].pdsch.tag = "PDSC";
        pdu_array[i].phich.tag = "PHICH";
        // Compute QCL and SNR values using simulation model
        float qcl = compute_qcl(pdu_array[i]);
        float snr = compute_snr(pdu_array[i]);
        pdu_array[i].qcl = qcl;
        pdu_array[i].snr = snr;
    }

    return pdu_array;
}

// Define function to compute QCL value using simulation model
float compute_qcl(LTE_PHY_RX_FRAME_PDU_T* pdu) {
    // Simulation model for computing QCL
    float qcl = 0.5 * (pdu->pucch.power + pdu->pdsch.power);
    return qcl;
}

// Define function to compute SNR value using simulation model
float compute_snr(LTE_PHY_RX_FRAME_PDU_T* pdu) {
    // Simulation model for computing SNR
    float snr = 10 * log10(pdu->pucch.power / (pdu->pdsch.power + 1e-9));
    return snr;
}
