struct nfapi_crc_indication_pdu_list* create_nfapi_crc_indication_pdu_list() {
    struct nfapi_crc_indication_pdu_list *list = malloc(sizeof(struct nfapi_crc_indication_pdu_list));
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void destroy_nfapi_crc_indication_pdu_list(struct nfapi_crc_indication_pdu_list *list) {
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int append_nfapi_crc_indication_pdu(struct nfapi_crc_indication_pdu_list *list, struct nfapi_crc_indication_pdu *pdu) {
    pthread_mutex_lock(&list->mutex);
    if (list->size >= MAX_LIST_SIZE) {
        // List is full, drop the oldest element
        struct nfapi_crc_indication_pdu *oldest = list->head;
        list->head = list->head->next;
        free(oldest);
    }
    if (list->tail == NULL) {
        // List is empty, set tail to new element
        list->tail = pdu;
    } else {
        // Add new element to end of list
        list->tail->next = pdu;
    }
    list->size++;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

struct nfapi_crc_indication_pdu* get_nfapi_crc_indication_pdu(struct nfapi_crc_indication_pdu_list *list, int index) {
    pthread_mutex_lock(&list->mutex);
    struct nfapi_crc_indication_pdu *current = list->head;
    for (int i = 0; i < index && current != NULL; i++) {
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
    return current;
}

void iterate_nfapi_crc_indication_pdu(struct nfapi_crc_indication_pdu_list *list, void (*callback)(struct nfapi_crc_indication_pdu*)) {
    pthread_mutex_lock(&list->mutex);
    struct nfapi_crc_indication_pdu *current = list->head;
    while (current != NULL) {
        callback(current);
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
}
