} HASH_TABLE;

// Define the function to initialize the hash table
void init_hash_table(HASH_TABLE *ht) {
    ht->size = 0;
    ht->capacity = 1024;
    ht->table = (NFAPI_RX_FRAME_PDU_T **)malloc(sizeof(NFAPI_RX_FRAME_PDU_T *) * ht->capacity);
}

// Define the function to insert a new UE information into the hash table
void insert_ue_info(HASH_TABLE *ht, int RX_UE_INFORMATION_TAG, int RNTI, FRAME_HEADER frame_header) {
    // Check if the hash table is full
    if (ht->size == ht->capacity) {
        // If the hash table is full, double its capacity and rehash all elements
        ht->capacity *= 2;
        NFAPI_RX_FRAME_PDU_T **new_table = (NFAPI_RX_FRAME_PDU_T **)malloc(sizeof(NFAPI_RX_FRAME_PDU_T *) * ht->capacity);
        for (int i = 0; i < ht->size; i++) {
            new_table[i] = ht->table[i];
        }
        free(ht->table);
        ht->table = new_table;
