// Define the data structure for storing validated frames
typedef struct {
    uint64_t timestamp;
    uint8_t frameType;
    uint32_t payloadSize;
    uint8_t *payload;
    uint8_t checksum[SHA256_DIGEST_LENGTH];
} Frame;

// Define the data structure for storing frames in the buffer
typedef struct {
    Frame *frames;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
    semaphore_t semaphore;
} Buffer;

// Define the API contract for the function
void processMediaStreamFrames(Buffer *buffer, Frame *frame) {
    // Acquire a lock on the buffer to prevent concurrent access
    pthread_mutex_lock(&buffer->mutex);

    // Check if the buffer is full and needs to be resized
    if (buffer->count == buffer->capacity) {
        // Resize the buffer by 50%
        buffer->capacity *= 1.5;
        buffer->frames = realloc(buffer->frames, buffer->capacity * sizeof(Frame));
    }

    // Add the new frame to the buffer
    buffer->frames[buffer->count++] = *frame;

    // Release the lock on the buffer
    pthread_mutex_unlock(&buffer->mutex);
}

// Define a method for adding frames to the buffer
void addFrameToBuffer(Buffer *buffer, Frame *frame) {
    processMediaStreamFrames(buffer, frame);
}

// Define a method for retrieving validated frames from the buffer
Frame *getValidatedFrameFromBuffer(Buffer *buffer) {
    // Acquire a lock on the buffer to prevent concurrent access
    pthread_mutex_lock(&buffer->mutex);

    // Check if there are any validated frames in the buffer
    if (buffer->count == 0) {
        // Release the lock on the buffer and return NULL
        pthread_mutex_unlock(&buffer->mutex);
        return NULL;
    }

    // Retrieve the first validated frame from the buffer
    Frame *frame = &buffer->frames[0];

    // Remove the retrieved frame from the buffer
    memmove(buffer->frames, buffer->frames + 1, (buffer->count - 1) * sizeof(Frame));
    buffer->count--;

    // Release the lock on the buffer
    pthread_mutex_unlock(&buffer->mutex);

    return frame;
}

// Define a method for clearing the buffer of all frames
void clearBuffer(Buffer *buffer) {
    // Acquire a lock on the buffer to prevent concurrent access
    pthread_mutex_lock(&buffer->mutex);

    // Clear the buffer by setting its count to 0
    buffer->count = 0;

    // Release the lock on the buffer
    pthread_mutex_unlock(&buffer->mutex);
}
