#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a structure to represent an LTE UE Context
typedef struct {
    int ue_id;
    char downlink_channel[16];
    char uplink_channel[16];
    bool connection_health;
} lte_ue_context_t;

// Define a linked list node to store UE Contexts
typedef struct {
    lte_ue_context_t *data;
    struct node *next;
} node_t;

// Define a global variable to store the head of the linked list
node_t *head = NULL;

// Define a mutex for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void init_lte_ue_context(int ue_id, char *downlink_channel, char *uplink_channel) {
    // Allocate memory for the UE Context structure
    lte_ue_context_t *ue_context = malloc(sizeof(lte_ue_context_t));
    if (ue_context == NULL) {
        // Handle memory allocation failure gracefully
        return;
    }

    // Initialize the UE Context structure
    ue_context->ue_id = ue_id;
    strcpy(ue_context->downlink_channel, downlink_channel);
    strcpy(ue_context->uplink_channel, uplink_channel);
    ue_context->connection_health = true;

    // Acquire the lock to prevent race conditions
    pthread_mutex_lock(&lock);

    // Add the UE Context to the linked list
    node_t *new_node = malloc(sizeof(node_t));
    new_node->data = ue_context;
    new_node->next = head;
    head = new_node;

    // Release the lock
    pthread_mutex_unlock(&lock);
}

void remove_lte_ue_context(int ue_id) {
    // Acquire the lock to prevent race conditions
    pthread_mutex_lock(&lock);

    // Find the node containing the UE Context with the specified ID
    node_t *node = head;
    while (node != NULL && node->data->ue_id != ue_id) {
        node = node->next;
    }

    // If the node is found, remove it from the linked list
    if (node != NULL) {
        // Update the head pointer if necessary
        if (head == node) {
            head = node->next;
        }

        // Free the memory allocated for the UE Context structure
        free(node->data);

        // Free the memory allocated for the node
        free(node);
    }

    // Release the lock
    pthread_mutex_unlock(&lock);
}

void update_lte_ue_context(int ue_id, char *downlink_channel, char *uplink_channel) {
    // Acquire the lock to prevent race conditions
    pthread_mutex_lock(&lock);

    // Find the node containing the UE Context with the specified ID
    node_t *node = head;
    while (node != NULL && node->data->ue_id != ue_id) {
        node = node->next;
    }

    // If the node is found, update the UE Context structure
    if (node != NULL) {
        strcpy(node->data->downlink_channel, downlink_channel);
        strcpy(node->data->uplink_channel, uplink_channel);
    }

    // Release the lock
    pthread_mutex_unlock(&lock);
}

void get_lte_ue_context(int ue_id) {
    // Acquire the lock to prevent race conditions
    pthread_mutex_lock(&lock);

    // Find the node containing the UE Context with the specified ID
    node_t *node = head;
    while (node != NULL && node->data->ue_id != ue_id) {
        node = node->next;
    }

    // If the node is found, return a copy of the UE Context structure
    if (node != NULL) {
        lte_ue_context_t *ue_context = malloc(sizeof(lte_ue_context_t));
        memcpy(ue_context, node->data, sizeof(lte_ue_context_t));
        free(node);
    }

    // Release the lock
    pthread_mutex_unlock(&lock);
}
```
