#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <assert.h>

// Custom memory allocator for the configuration list
void* custom_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        printf("Error: Out of memory\n");
        exit(1);
    }
    return ptr;
}

// Custom memory deallocator for the configuration list
void custom_free(void* ptr) {
    free(ptr);
}

// Structure to represent a network configuration setting
typedef struct NetworkConfig {
    int id;
    char* mode;
    void* params;
} NetworkConfig;

// Structure to represent the dynamic list of network configurations
typedef struct ConfigList {
    NetworkConfig** configs;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} ConfigList;

// Initialize a new configuration list with an initial capacity
void init_config_list(ConfigList* list, size_t capacity) {
    list->capacity = capacity;
    list->count = 0;
    list->configs = (NetworkConfig**)custom_malloc(sizeof(NetworkConfig*) * capacity);
    pthread_mutex_init(&list->mutex, NULL);
}

// Add a new configuration to the list
void add_config(ConfigList* list, NetworkConfig* config) {
    // Acquire lock on mutex
    pthread_mutex_lock(&list->mutex);

    // Check if the list is full
    if (list->count == list->capacity) {
        // Double the capacity of the list
        size_t new_capacity = list->capacity * 2;
        NetworkConfig** new_configs = (NetworkConfig**)custom_malloc(sizeof(NetworkConfig*) * new_capacity);
        memcpy(new_configs, list->configs, sizeof(NetworkConfig*) * list->count);
        custom_free(list->configs);
        list->configs = new_configs;
        list->capacity = new_capacity;
    }

    // Add the configuration to the list
    list->configs[list->count++] = config;

    // Release lock on mutex
    pthread_mutex_unlock(&list->mutex);
}

// Remove a configuration from the list by its ID
void remove_config(ConfigList* list, int id) {
    // Acquire lock on mutex
    pthread_mutex_lock(&list->mutex);

    // Find the index of the configuration to be removed
    size_t i;
    for (i = 0; i < list->count; i++) {
        if (list->configs[i]->id == id) {
            break;
        }
    }

    // Check if the configuration was found
    if (i == list->count) {
        printf("Error: Configuration with ID %d not found\n", id);
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    // Remove the configuration from the list
    NetworkConfig* config = list->configs[i];
    memmove(list->configs + i, list->configs + i + 1, sizeof(NetworkConfig*) * (list->count - i - 1));
    list->count--;

    // Release lock on mutex
    pthread_mutex_unlock(&list->mutex);
}

// Get a configuration from the list by its ID
NetworkConfig* get_config(ConfigList* list, int id) {
    // Acquire lock on mutex
    pthread_mutex_lock(&list->mutex);

    // Find the index of the configuration to be retrieved
    size_t i;
    for (i = 0; i < list->count; i++) {
        if (list->configs[i]->id == id) {
            break;
        }
    }

    // Check if the configuration was found
    if (i == list->count) {
        printf("Error: Configuration with ID %d not found\n", id);
        pthread_mutex_unlock(&list->mutex);
        return NULL;
    }

    // Retrieve the configuration from the list
    NetworkConfig* config = list->configs[i];

    // Release lock on mutex
    pthread_mutex_unlock(&list->mutex);

    return config;
}

// Serialize a configuration list to a file
void serialize_config_list(ConfigList* list, FILE* fp) {
    // Acquire lock on mutex
    pthread_mutex_lock(&list->mutex);

    // Write the number of configurations in the list to the file
    fwrite(&list->count, sizeof(size_t), 1, fp);

    // Write each configuration in the list to the file
    for (size_t i = 0; i < list->count; i++) {
        NetworkConfig* config = list->configs[i];
        fwrite(&config->id, sizeof(int), 1, fp);
        fwrite(config->mode, strlen(config->mode) + 1, 1, fp);
        fwrite(config->params, sizeof(void*), 1, fp);
    }

    // Release lock on mutex
    pthread_mutex_unlock(&list->mutex);
}

// Deserialize a configuration list from a file
void deserialize_config_list(ConfigList* list, FILE* fp) {
    // Acquire lock on mutex
    pthread_mutex_lock(&list->mutex);

    // Read the number of configurations in the list from the file
    size_t count;
    fread(&count, sizeof(size_t), 1, fp);

    // Initialize the configuration list with the read capacity
    init_config_list(list, count);

    // Read each configuration from the file and add it to the list
    for (size_t i = 0; i < count; i++) {
        NetworkConfig* config = (NetworkConfig*)custom_malloc(sizeof(NetworkConfig));
        fread(&config->id, sizeof(int), 1, fp);
        config->mode = (char*)custom_malloc(strlen(config->mode) + 1);
        fread(config->mode, strlen(config->mode) + 1, 1, fp);
        config->params = (void*)custom_malloc(sizeof(void*));
        fread(config->params, sizeof(void*), 1, fp);
        add_config(list, config);
    }

    // Release lock on mutex
    pthread_mutex_unlock(&list->mutex);
}

// Clean up unused configurations in the list to free up resources and reduce overhead
void cleanup_config_list(ConfigList* list) {
    // Acquire lock on mutex
    pthread_mutex_lock(&list->mutex);

    // Iterate over each configuration in the list and check if it is unused
    for (size_t i = 0; i < list->count; i++) {
        NetworkConfig* config = list->configs[i];
        if (!config->id) {
            // Remove the unused configuration from the list
            remove_config(list, config->id);
        }
    }

    // Release lock on mutex
    pthread_mutex_unlock(&list->mutex);
}
