// Custom hash function for the key-value pair
unsigned int custom_hash(const char* key) {
    unsigned int hash = 0;
    for (int i = 0; i < strlen(key); i++) {
        hash += key[i];
    }
    return hash % 1000000007; // Use a prime number as the modulus to ensure uniqueness
}

// Data structure for storing LTEPHYLayerConfig records
typedef struct LTEPHYLayerConfig {
    int antenna_count;
    int modulation_scheme;
    int transmission_power;
} LTEPHYLayerConfig;

// Custom hash table data structure
typedef struct HashTable {
    LTEPHYLayerConfig** records; // Array of pointers to LTEPHYLayerConfig structures
    unsigned int size; // Size of the hash table
    pthread_mutex_t mutex; // Mutex for synchronizing access to the hash table
} HashTable;

// Function to initialize a new hash table with a given size
HashTable* init_hash_table(unsigned int size) {
    HashTable* ht = (HashTable*)malloc(sizeof(HashTable));
    ht->records = (LTEPHYLayerConfig**)calloc(size, sizeof(LTEPHYLayerConfig*));
    ht->size = size;
    pthread_mutex_init(&ht->mutex, NULL);
    return ht;
}

// Function to insert a new record into the hash table
void insert_record(HashTable* ht, const char* key, LTEPHYLayerConfig* value) {
    pthread_mutex_lock(&ht->mutex);
    unsigned int index = custom_hash(key) % ht->size;
    while (ht->records[index] != NULL && strcmp(key, ht->records[index]->key) != 0) {
        index++;
        if (index == ht->size) {
            index = 0;
        }
    }
    if (ht->records[index] == NULL) {
        ht->records[index] = value;
    } else {
        // Rehash the record to a new index
        LTEPHYLayerConfig* new_value = (LTEPHYLayerConfig*)malloc(sizeof(LTEPHYLayerConfig));
        memcpy(new_value, value, sizeof(LTEPHYLayerConfig));
        ht->records[index] = new_value;
    }
    pthread_mutex_unlock(&ht->mutex);
}

// Function to look up a record in the hash table by key
LTEPHYLayerConfig* lookup_record(HashTable* ht, const char* key) {
    pthread_mutex_lock(&ht->mutex);
    unsigned int index = custom_hash(key) % ht->size;
    while (ht->records[index] != NULL && strcmp(key, ht->records[index]->key) != 0) {
        index++;
        if (index == ht->size) {
            index = 0;
        }
    }
    LTEPHYLayerConfig* value = ht->records[index];
    pthread_mutex_unlock(&ht->mutex);
    return value;
}

// Function to delete a record from the hash table by key
void delete_record(HashTable* ht, const char* key) {
    pthread_mutex_lock(&ht->mutex);
    unsigned int index = custom_hash(key) % ht->size;
    while (ht->records[index] != NULL && strcmp(key, ht->records[index]->key) != 0) {
        index++;
        if (index == ht->size) {
            index = 0;
        }
    }
    if (ht->records[index] != NULL) {
        free(ht->records[index]);
        ht->records[index] = NULL;
    }
    pthread_mutex_unlock(&ht->mutex);
}

// Function to read configurations from a binary file and populate the hash table
void populate_configurations(HashTable* ht, const char* filename) {
    FILE* fp = fopen(filename, "rb");
    if (fp == NULL) {
        perror("Error opening file");
        return;
    }
    LTEPHYLayerConfig config;
    while (fread(&config, sizeof(LTEPHYLayerConfig), 1, fp) == 1) {
        // Validate the configuration to ensure it meets industry standards
        if (config.antenna_count < MIN_ANTENNA_COUNT || config.modulation_scheme != MODEM_QPSK) {
            continue;
        }
        // Generate a random value within a given range for each record
        int random_value = rand() % MAX_TRANSMISSION_POWER + MIN_TRANSMISSION_POWER;
        config.transmission_power = random_value;
        // Insert the record into the hash table
        insert_record(ht, config.key, &config);
    }
    fclose(fp);
}

// Function to export the current set of configurations to a CSV file
void export_configurations(HashTable* ht, const char* filename) {
    FILE* fp = fopen(filename, "w");
    if (fp == NULL) {
        perror("Error opening file");
        return;
    }
    // Write the header row to the CSV file
    fprintf(fp, "key,antenna_count,modulation_scheme,transmission_power\n");
    pthread_mutex_lock(&ht->mutex);
    for (int i = 0; i < ht->size; i++) {
        LTEPHYLayerConfig* config = ht->records[i];
        if (config != NULL) {
            fprintf(fp, "%s,%d,%d,%d\n", config->key, config->antenna_count, config->modulation_scheme, config->transmission_power);
        }
    }
    pthread_mutex_unlock(&ht->mutex);
    fclose(fp);
}

// Function to handle memory allocation failures gracefully
void handle_memory_allocation_failure() {
    // Fall back to default configurations if memory allocation fails
    printf("Memory allocation failed. Using default configurations.\n");
}

// Function to filter configurations based on criteria such as minimum number of antennas or specific modulation scheme
void filter_configurations(HashTable* ht) {
    pthread_mutex_lock(&ht->mutex);
    for (int i = 0; i < ht->size; i++) {
        LTEPHYLayerConfig* config = ht->records[i];
        if (config != NULL && config->antenna_count < MIN_ANTENNA_COUNT || config->modulation_scheme != MODEM_QPSK) {
            delete_record(ht, config->key);
        }
    }
    pthread_mutex_unlock(&ht->mutex);
}

// Function to validate configurations to ensure they meet specific industry standards for LTE networks
void validate_configurations(HashTable* ht) {
    pthread_mutex_lock(&ht->mutex);
    for (int i = 0; i < ht->size; i++) {
        LTEPHYLayerConfig* config = ht->records[i];
        if (config != NULL && config->antenna_count < MIN_ANTENNA_COUNT || config->modulation_scheme != MODEM_QPSK) {
            delete_record(ht, config->key);
        }
    }
    pthread_mutex_unlock(&ht->mutex);
}

