    // Initialize the offset array
    Offset* offsets = allocate_offset(MAX_MEMORY);
    for (int i = 0; i < MAX_MEMORY / sizeof(Offset); i++) {
        offsets[i].offset = rand() % MEMORY_ALLOCATION_LIMIT;
    }

    // Initialize the key array
    Key* keys = allocate_key(MAX_MEMORY);
    for (int i = 0; i < MAX_MEMORY / sizeof(Key); i++) {
        keys[i].key = rand() % MEMORY_ALLOCATION_LIMIT;
    }

    // Initialize the record array
    Record* records = allocate_record(MAX_MEMORY);
    for (int i = 0; i < MAX_MEMORY / sizeof(Record); i++) {
        records[i].value = rand() % MEMORY_ALLOCATION_LIMIT;
        records[i].offset_ptr = &offsets[i];
        records[i].key_ptr = &keys[i];
    }

    // Initialize the metadata array
    Metadata* metadatas = allocate_metadata(MAX_MEMORY);
    for (int i = 0; i < MAX_MEMORY / sizeof(Metadata); i++) {
        metadatas[i].last_accessed = time(NULL);
        metadatas[i].update_count = 0;
    }
}

// Define the cleanup function
void cleanup_data_structures() {
    // Deallocate the offset array
    deallocate_offset(offsets);

    // Deallocate the key array
    deallocate_key(keys);

    // Deallocate the record array
    deallocate_record(records);

    // Deallocate the metadata array
    deallocate_metadata(metadatas);
}
