// Function to initialize and sort the arrays
void init_and_sort(Record* records, int num_records) {
    // Allocate memory for the two arrays
    long* offsets = malloc(num_records * sizeof(long));
    int* keys = malloc(num_records * sizeof(int));

    // Initialize the arrays with unique values
    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand() % 1000000;
        keys[i] = rand() % 1000000;
    }

    // Sort the arrays using a stable sorting algorithm
    qsort(offsets, num_records, sizeof(long), compare_offsets);
    qsort(keys, num_records, sizeof(int), compare_keys);

    // Initialize the record structures with the sorted values
    for (int i = 0; i < num_records; i++) {
        records[i].offset = offsets[i];
        records[i].key = keys[i];
    }

    // Free the memory allocated for the arrays
    free(offsets);
    free(keys);
}

// Function to compare two long values
int compare_offsets(const void* a, const void* b) {
    long x = *(long*)a;
    long y = *(long*)b;
    if (x < y) return -1;
    else if (x > y) return 1;
    else return 0;
}

// Function to compare two int values
int compare_keys(const void* a, const void* b) {
    int x = *(int*)a;
