        if (total_valid_allocations < new_N) {
            printf("Warning: %d out of %d memory allocations failed\n", new_N - total_valid_allocations, new_N);
        }

        // Update the total number of validly allocated structures and return a pointer to the newly allocated memory
        total_allocated = new_N;
        return new_ue_contexts;
