    // Calculate the network priority level based on the weighted average of the CELL_ID and RRC_UE_CONTEXT_TAG
    int network_priority = (weight_cell_id * cell_id + weight_RRC_UE_CONTEXT_TAG * RRC_UE_CONTEXT_TAG) / (weight_cell_id + weight_RRC_UE_CONTEXT_TAG);

