        insertion_sort(&identifier_map, &new_map_entry);
        pthread_mutex_unlock(&identifier_map_lock);

        // Populate the structure with the generated values
        array[i].rx_ue_information_tag = rx_ue_information_tag;
        array[i].rnti = rnti;
        array[i].crc_indication_rel8_tag = crc_indication_rel8_tag;
    }

    // Free the hash map memory
    free(identifier_map);

    return array;
}

// Define the function for comparing identifiers in the hash map
int compare_identifiers(const void* a, const void* b) {
    IDENTIFIER_MAP* map_a = (IDENTIFIER_MAP*)a;
    IDENTIFIER_MAP* map_b = (IDENTIFIER_MAP*)b;
    return map_a->key - map_b->key;
}

// Define the function for inserting a new entry into the hash map
void insertion_sort(IDENTIFIER_MAP** identifier_map, IDENTIFIER_MAP* new_entry) {
    int i = 0;
    while (i < 10000 && (*identifier_map)[i].key <= new_entry->key) {
        i++;
    }
    memmove(&(*identifier_map)[i + 1], &(*identifier_map)[i], sizeof(IDENTIFIER_MAP) * (10000 - i));
    (*identifier_map)[i] = *new_entry;
}
