#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdbool.h>
#include <assert.h>

// Define the maximum number of RNTIs to support
#define MAX_RNTIS 1024

// Define the structure for a CRC indication PDU
typedef struct {
    uint8_t rx_ue_information_tag;
    uint16_t rnti;
    uint8_t crc_indication_rel8_tag;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the structure for a NAS PDU
typedef struct {
    uint8_t nas_message_type;
    uint16_t nas_message_id;
    char *nas_message;
} LTE_NAS_PDU;

// Define the linked list node for the CRC indication PDUs
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdu;
    struct Node *next;
} NFAPI_CRC_INDICATION_LIST_NODE_T;

// Define the linked list for the CRC indication PDUs
typedef struct {
    NFAPI_CRC_INDICATION_LIST_NODE_T *head;
    NFAPI_CRC_INDICATION_LIST_NODE_T *tail;
} NFAPI_CRC_INDICATION_LIST_T;

// Define the function to populate and serialize the CRC indication list
void populateAndSerializeNFAPI_CRC_INDICATION_LIST(uint16_t n) {
    // Check if the provided N exceeds the maximum limit of 1024
    if (n > MAX_RNTIS) {
        printf("Error: Provided N exceeds the maximum limit of 1024\n");
        return;
    }

    // Initialize the linked list for the CRC indication PDUs
    NFAPI_CRC_INDICATION_LIST_T *list = calloc(1, sizeof(NFAPI_CRC_INDICATION_LIST_T));
    if (!list) {
        printf("Error: Failed to allocate memory for the CRC indication list\n");
        return;
    }

    // Dynamically allocate memory for the linked list nodes
    NFAPI_CRC_INDICATION_LIST_NODE_T *node = calloc(n, sizeof(NFAPI_CRC_INDICATION_LIST_NODE_T));
    if (!node) {
        printf("Error: Failed to allocate memory for the CRC indication list nodes\n");
        free(list);
        return;
    }

    // Populate the linked list with random values for RX UE information and CRC indication
    for (uint16_t i = 0; i < n; i++) {
        node[i].pdu = calloc(1, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!node[i].pdu) {
            printf("Error: Failed to allocate memory for the CRC indication PDU\n");
            free(list);
            free(node);
            return;
        }
        node[i].pdu->rx_ue_information_tag = rand() % 256;
        node[i].pdu->rnti = rand() % MAX_RNTIS;
        node[i].pdu->crc_indication_rel8_tag = rand() % 256;
        node[i].pdu->crcflag = (rand() % 2) ? true : false;
    }

    // Insert the linked list nodes into the linked list
    for (uint16_t i = 0; i < n; i++) {
        if (!list->head) {
            list->head = node + i;
            list->tail = node + i;
        } else {
            list->tail->next = node + i;
            list->tail = node + i;
        }
    }

    // Serialize the linked list into a binary file
    FILE *file = fopen("crc_indication_list.bin", "wb");
    if (!file) {
        printf("Error: Failed to open the CRC indication list file for writing\n");
        free(list);
        free(node);
        return;
    }
    fwrite(list, sizeof(NFAPI_CRC_INDICATION_LIST_T), 1, file);
    fclose(file);

    // Free the memory allocated for the linked list nodes and the linked list itself
    free(node);
    free(list);
}

// Define the function to deserialize the CRC indication list from a binary file
void deserializeNFAPI_CRC_INDICATION_LIST(char *filename) {
    // Open the binary file for reading
    FILE *file = fopen(filename, "rb");
    if (!file) {
        printf("Error: Failed to open the CRC indication list file for reading\n");
        return;
    }

    // Allocate memory for the linked list and its nodes
    NFAPI_CRC_INDICATION_LIST_T *list = calloc(1, sizeof(NFAPI_CRC_INDICATION_LIST_T));
    if (!list) {
        printf("Error: Failed to allocate memory for the CRC indication list\n");
        fclose(file);
        return;
    }
    NFAPI_CRC_INDICATION_LIST_NODE_T *node = calloc(1, sizeof(NFAPI_CRC_INDICATION_LIST_NODE_T));
    if (!node) {
        printf("Error: Failed to allocate memory for the CRC indication list nodes\n");
        free(list);
        fclose(file);
        return;
    }

    // Read the linked list from the binary file
    size_t bytes_read = fread(list, sizeof(NFAPI_CRC_INDICATION_LIST_T), 1, file);
    if (bytes_read != 1) {
        printf("Error: Failed to read the CRC indication list from the binary file\n");
        free(node);
        free(list);
        fclose(file);
        return;
    }

    // Deserialize the linked list into a linked list of NAS PDUs
    for (NFAPI_CRC_INDICATION_LIST_NODE_T *current = list->head; current != NULL; current = current->next) {
        LTE_NAS_PDU *nas_pdu = calloc(1, sizeof(LTE_NAS_PDU));
        if (!nas_pdu) {
            printf("Error: Failed to allocate memory for the NAS PDU\n");
            free(node);
            free(list);
            fclose(file);
            return;
        }
        nas_pdu->nas_message_type = current->pdu->rx_ue_information_tag;
        nas_pdu->nas_message_id = current->pdu->rnti;
        nas_pdu->nas_message = calloc(1, sizeof(char) * 256);
        if (!nas_pdu->nas_message) {
            printf("Error: Failed to allocate memory for the NAS message\n");
            free(nas_pdu);
            free(node);
            free(list);
            fclose(file);
            return;
        }
        strcpy(nas_pdu->nas_message, "NAS message");
    }

    // Free the memory allocated for the linked list and its nodes
    free(node);
    free(list);
    fclose(file);
}

// Define the function to calculate CQI and RSRP for each frame index
void calculateCQIRSRP(uint16_t n) {
    // Check if the provided N exceeds the maximum limit of 1024
    if (n > MAX_RNTIS) {
        printf("Error: Provided N exceeds the maximum limit of 1024\n");
        return;
    }

    // Initialize the linked list for the CRC indication PDUs
    NFAPI_CRC_INDICATION_LIST_T *list = calloc(1, sizeof(NFAPI_CRC_INDICATION_LIST_T));
    if (!list) {
        printf("Error: Failed to allocate memory for the CRC indication list\n");
        return;
    }

    // Dynamically allocate memory for the linked list nodes
    NFAPI_CRC_INDICATION_LIST_NODE_T *node = calloc(n, sizeof(NFAPI_CRC_INDICATION_LIST_NODE_T));
    if (!node) {
        printf("Error: Failed to allocate memory for the CRC indication list nodes\n");
        free(list);
        return;
    }

