// Define a struct to represent the JSON object
struct token_info {
    char *access_token;
    int expires_in;
    char *token_type;
    char *refresh_token;
    char **scopes;
};

// Define a function to validate the JSON object
bool validate_token(const char *json) {
    // Parse the JSON string into a struct
    json_object *obj = json_tokener_parse(json);
    if (!obj) {
        return false;
    }

    // Check that the token_type is 'Bearer'
    const char *token_type = json_object_get_string(json_object_object_get(obj, "token_type"));
    if (strcmp(token_type, "Bearer") != 0) {
        return false;
    }

    // Check that the expires_in field is a positive integer
    int expires_in = json_object_get_int(json_object_object_get(obj, "expires_in"));
    if (expires_in <= 0) {
        return false;
    }

    // Check that the access_token consists solely of valid ASCII characters
    const char *access_token = json_object_get_string(json_object_object_get(obj, "access_token"));
    if (!is_valid_ascii(access_token)) {
        return false;
    }

    // Check that the refresh_token has a length greater than 16 characters (if present)
    const char *refresh_token = json_object_get_string(json_object_object_get(obj, "refresh_token"));
    if (refresh_token && strlen(refresh_token) <= 16) {
        return false;
    }

    // Check that the scopes field contains a list of valid strings representing permissions (if present)
    const char *scopes = json_object_get_string(json_object_object_get(obj, "scopes"));
    if (scopes && !is_valid_scope(scopes)) {
        return false;
    }

    // If all checks pass, the token is valid
    return true;
}

// Define a function to check that a string consists solely of valid ASCII characters
bool is_valid_ascii(const char *str) {
    for (int i = 0; i < strlen(str); i++) {
        if (!isascii(str[i])) {
            return false;
        }
    }
    return true;
}

// Define a function to check that a string represents a valid scope
bool is_valid_scope(const char *str) {
    // Split the string into an array of scopes
    const char **scopes = strsplit(str, ",");

    // Check each scope for validity
    for (int i = 0; i < strlen(scopes); i++) {
        if (!is_valid_scope_string(scopes[i])) {
            return false;
        }
    }

    // If all scopes are valid, the string is valid
    return true;
}

// Define a function to check that a string represents a valid scope string
bool is_valid_scope_string(const char *str) {
    // Check that the string has a maximum length of 32 characters
    if (strlen(str) > 32) {
        return false;
    }

    // Check that the string only contains valid ASCII characters
    for (int i = 0; i < strlen(str); i++) {
        if (!isascii(str[i])) {
            return false;
        }
    }

    // If all checks pass, the string is valid
    return true;
}

// Define a function to split a string into an array of strings based on a delimiter
const char **strsplit(const char *str, const char *delim) {
    int count = 0;
    for (int i = 0; i < strlen(str); i++) {
        if (str[i] == delim[0]) {
            count++;
        }
    }

    // Allocate memory for the array of strings
    const char **arr = malloc((count + 1) * sizeof(char*));
    if (!arr) {
        return NULL;
    }

    // Split the string into an array of strings
    int start = 0, end = 0;
    for (int i = 0; i < strlen(str); i++) {
        if (str[i] == delim[0]) {
            arr[end++] = strndup(str + start, i - start);
            start = i + 1;
        }
    }
    arr[end] = NULL;

    return arr;
}
