['```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

// Define the structure to store PDU information
typedef struct {
    uint32_t UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} PDU;

// Define the hash table to track RNTIs
typedef struct {
    uint16_t RNTI;
    int count;
} RNTIHashTable;

// Define the list of PDUs
typedef struct {
    PDU *pdu;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} PDUList;

// Function to initialize the PDU list
void initialize_pdu_list(PDUList *list, size_t max_entries, bool enable_logging) {
    // Allocate memory for the list and its elements
    list->capacity = max_entries;
    list->size = 0;
    list->pdu = (PDU *)malloc(sizeof(PDU) * list->capacity);
    memset(list->pdu, 0, sizeof(PDU) * list->capacity);

    // Initialize the hash table for RNTIs
    list->rnti_hash_table = (RNTIHashTable *)malloc(sizeof(RNTIHashTable) * list->capacity);
    memset(list->rnti_hash_table, 0, sizeof(RNTIHashTable) * list->capacity);

    // Initialize the mutex for thread-safe access
    pthread_mutex_init(&list->mutex, NULL);

    if (enable_logging) {
        printf("Initializing PDU list with capacity %zu\n", list->capacity);
    }
}

// Function to add a new PDU to the list
void add_pdu(PDUList *list, uint32_t UE_INFORMATION_TAG, uint16_t RNTI, uint8_t CRC_INDICATION_REL8_TAG) {
    // Acquire the mutex for thread-safe access
    pthread_mutex_lock(&list->mutex);

    // Check if the list needs to be resized
    if (list->size == list->capacity) {
        // Reallocate memory for the list and its elements
        list->capacity *= 2;
        list->pdu = (PDU *)realloc(list->pdu, sizeof(PDU) * list->capacity);
        memset(list->pdu + list->size, 0, sizeof(PDU) * (list->capacity - list->size));

        // Reallocate memory for the hash table
        list->rnti_hash_table = (RNTIHashTable *)realloc(list->rnti_hash_table, sizeof(RNTIHashTable) * list->capacity);
        memset(list->rnti_hash_table + list->size, 0, sizeof(RNTIHashTable) * (list->capacity - list->size));

        if (enable_logging) {
            printf("Resizing PDU list to capacity %zu\n", list->capacity);
        }
    }

    // Add the new PDU to the list
    list->pdu[list->size].UE_INFORMATION_TAG = UE_INFORMATION_TAG;
    list->pdu[list->size].RNTI = RNTI;
    list->pdu[list->size].CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    list->rnti_hash_table[list->size].RNTI = RNTI;
    list->rnti_hash_table[list->size].count++;
    list->size++;

    // Release the mutex for thread-safe access
    pthread_mutex_unlock(&list->mutex);
}

// Function to remove a PDU from the list
void remove_pdu(PDUList *list, uint16_t RNTI) {
    // Acquire the mutex for thread-safe access
    pthread_mutex_lock(&list->mutex);

    // Find the index of the PDU to be removed
    size_t i;
    for (i = 0; i < list->size; i++) {
        if (list->pdu[i].RNTI == RNTI) {
            break;
        }
    }

    // Check if the PDU was found
    if (i < list->size) {
        // Remove the PDU from the list
        memmove(list->pdu + i, list->pdu + i + 1, sizeof(PDU) * (list->size - i));
        list->size--;

        // Update the hash table
        list->rnti_hash_table[i].count--;
    } else {
        if (enable_logging) {
            printf("RNTI %u not found in PDU list\n", RNTI);
        }
    }

    // Release the mutex for thread-safe access
    pthread_mutex_unlock(&list->mutex);
}

// Function to get a PDU from the list by its RNTI
PDU *get_pdu(PDUList *list, uint16_t RNTI) {
    // Acquire the mutex for thread-safe access
    pthread_mutex_lock(&list->mutex);

    // Find the index of the PDU with the given RNTI
    size_t i;
    for (i = 0; i < list->size; i++) {
        if (list->pdu[i].RNTI == RNTI) {
            break;
        }
    }

    // Check if the PDU was found
    if (i < list->size) {
        // Return a pointer to the PDU
        PDU *pdu = &list->pdu[i];
        pthread_mutex_unlock(&list->mutex);
        return pdu;
    } else {
        if (enable_logging) {
            printf("RNTI %u not found in PDU list\n", RNTI);
        }
        pthread_mutex_unlock(&list->mutex);
        return NULL;
    }
}

// Function to free all allocated memory for the list
void free_pdu_list(PDUList *list) {
    // Acquire the mutex for thread-safe access
    pthread_mutex_lock(&list->mutex);

    // Free the memory for the list and its elements
    free(list->pdu);
    list->pdu = NULL;
    list->size = 0;
    list->capacity = 0;

    // Free the memory for the hash table
    free(list->rnti_hash_table);
    list->rnti_hash_table = NULL;

    // Release the mutex for thread-safe access
    pthread_mutex_unlock(&list->mutex);
}
