using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using Newtonsoft.Json;

public class TransactionProcessor
{
    private readonly IDataWarehouse _dataWarehouse;
    private readonly Dictionary<string, List<Transaction>> _transactions = new Dictionary<string, List<Transaction>>();

    public TransactionProcessor(IDataWarehouse dataWarehouse)
    {
        _dataWarehouse = dataWarehouse;
    }

    public async Task ProcessTransactionsAsync(IEnumerable<Transaction> transactions)
    {
        foreach (var transaction in transactions)
        {
            if (!_transactions.ContainsKey(transaction.UserId))
            {
                _transactions[transaction.UserId] = new List<Transaction>();
            }

            _transactions[transaction.UserId].Add(transaction);
        }

        await Task.WhenAll(_transactions.Values.Select(async transactions =>
        {
            var userTransactions = transactions.OrderByDescending(t => t.Timestamp).Take(10);
            var summaryReport = new TransactionSummaryReport();

            foreach (var transaction in userTransactions)
            {
                summaryReport.TotalAmount += transaction.Amount;
                summaryReport.Count++;
            }

            await _dataWarehouse.UpdateTransactionSummaryAsync(summaryReport);
        }));
    }
}

public class Transaction
{
    public string UserId { get; set; }
    public decimal Amount { get; set; }
    public DateTime Timestamp { get; set; }
}

public class TransactionSummaryReport
{
    public int Count { get; set; }
    public decimal TotalAmount { get; set; }
}
```
