};

// Define a function to create and populate the linked list of LTE_PHY_RRC_MESSAGE_T structures
void createAndPopulateLinkedList(struct LinkedList **list, int numElements) {
    // Allocate memory for the linked list
    *list = (struct LinkedList *)malloc(sizeof(struct LinkedList));
    (*list)->head = NULL;
    (*list)->tail = NULL;

    // Populate the linked list with LTE_PHY_RRC_MESSAGE_T structures
    for (int i = 0; i < numElements; i++) {
        struct Node *newNode = (struct Node *)malloc(sizeof(struct Node));
        newNode->data = (LTE_PHY_RRC_MESSAGE_T *)malloc(sizeof(LTE_PHY_RRC_MESSAGE_T));
        newNode->next = NULL;

        // Set the CELL_ID, RRC_MESSAGE_TYPE, and SEQUENCE_NUMBER for each structure
        newNode->data->CELL_ID = i + 1;
        newNode->data->RRC_MESSAGE_TYPE = i % 2 == 0 ? LTE_PHY_RRC_MESSAGE_TYPE_DL_CCCH : LTE_PHY_RRC_MESSAGE_TYPE_UL_CCCH;
        newNode->data->SEQUENCE_NUMBER = i + 1;

        // Add the node to the linked list
        if ((*list)->head == NULL) {
            (*list)->head = newNode;
            (*list)->tail = newNode;
        } else {
            (*list)->tail->next = newNode;
            (*list)->tail = newNode;
        }
    }
}

// Define a function to add a new element to the linked list
