    // Allocate memory for the node
    struct Node *newNode = (struct Node *)malloc(sizeof(struct Node));
    newNode->data = element;
    newNode->next = NULL;

    // Add the node to the linked list
    if (list->head == NULL) {
        list->head = newNode;
        list->tail = newNode;
    } else {
        list->tail->next = newNode;
        list->tail = newNode;
    }
}

// Define a function to remove an element from the linked list by CELL_ID
void removeElementFromLinkedListByCELL_ID(struct LinkedList *list, int cellId) {
    // Find the node with the matching CELL_ID
    struct Node *currentNode = list->head;
    while (currentNode != NULL && currentNode->data->CELL_ID != cellId) {
        currentNode = currentNode->next;
    }

    // Remove the node from the linked list
    if (currentNode != NULL) {
        struct Node *previousNode = currentNode->prev;
        if (previousNode == NULL) {
            list->head = currentNode->next;
        } else {
            previousNode->next = currentNode->next;
        }
        free(currentNode);
    }
}

// Define a function to iterate over the linked list and print all elements
void iterateOverLinkedListAndPrintElements(struct LinkedList *list) {
    // Iterate over the linked list and print each element
    struct Node *currentNode = list->head;
    while (currentNode != NULL) {
        printf("CELL_ID: %d, RRC_MESSAGE_TYPE: %d, SEQUENCE_NUMBER: %d\n", currentNode->data->CELL_ID, currentNode->data->RRC_MESSAGE_TYPE, currentNode->data->SEQUENCE_NUMBER);
        currentNode = currentNode->next;
    }
}
