use std::time::Instant;
use std::process::Command;
use std::fs::File;
use std::io::Write;
use std::path::PathBuf;

fn compile_project(project: &str, compiler: &str) -> Result<(), String> {
    let start = Instant::now();
    let mut process = Command::new("cargo")
        .arg("build")
        .arg("--release")
        .arg("-Z")
        .arg(format!("unstable-options={}", compiler))
        .spawn()?;

    let status = process.wait()?;
    if !status.success() {
        return Err(String::from("Compilation failed"));
    }

    let end = Instant::now();
    let duration = end - start;
    let memory_usage = get_memory_usage(&process);
    let error_details = get_error_details(&project, &compiler);

    send_metrics(duration, memory_usage, error_details);

    Ok(())
}

fn get_memory_usage(process: &mut std::process::Child) -> u64 {
    let mut file = File::open("/proc/self/statm").unwrap();
    let mut buffer = String::new();
    file.read_to_string(&mut buffer).unwrap();
    let parts: Vec<&str> = buffer.split(' ').collect();
    parts[1].parse().unwrap() * 4096
}

fn get_error_details(project: &str, compiler: &str) -> String {
    let mut error_file = PathBuf::from("target/debug/");
    error_file.push(format!("{}-{}.log", project, compiler));
    if !error_file.exists() {
        return String::new();
    }

    let mut file = File::open(&error_file).unwrap();
    let mut buffer = String::new();
    file.read_to_string(&mut buffer).unwrap();
    buffer
}

fn send_metrics(duration: Duration, memory_usage: u64, error_details: &str) {
    // Implement your own metrics sending logic here
}
