#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>

// Custom allocator that uses a fixed-size block pool with dynamic resizing
void* nas_alloc(size_t size) {
    // Allocate memory from the block pool
    void* mem = malloc(size);
    if (mem == NULL) {
        // Handle memory allocation failure gracefully
        printf("Memory allocation failed\n");
        return NULL;
    }
    return mem;
}

void nas_free(void* ptr) {
    free(ptr);
}

// Linked list node structure for managing LTE_NAS_PDU elements
typedef struct LTE_NAS_PDU_node {
    struct LTE_NAS_PDU_node* next;
    struct LTE_NAS_PDU_node* prev;
    NAS_MESSAGE_TYPE type;
    NAS_MESSAGE_ID id;
    void* message; // dynamically allocated NAS message body
} LTE_NAS_PDU_node;

// Linked list structure for managing a collection of LTE_NAS_PDU elements
typedef struct LTE_NAS_PDU_list {
    LTE_NAS_PDU_node* head;
    LTE_NAS_PDU_node* tail;
} LTE_NAS_PDU_list;

// Initialize a new linked list structure
void nas_list_init(LTE_NAS_PDU_list* list) {
    list->head = NULL;
    list->tail = NULL;
}

// Insert a new LTE_NAS_PDU element into the linked list
void nas_list_insert(LTE_NAS_PDU_list* list, NAS_MESSAGE_TYPE type, NAS_MESSAGE_ID id, void* message) {
    // Allocate memory for the new node
    LTE_NAS_PDU_node* new_node = nas_alloc(sizeof(LTE_NAS_PDU_node));
    if (new_node == NULL) {
        // Handle memory allocation failure gracefully
        printf("Memory allocation failed\n");
        return;
    }

    // Initialize the new node with the given parameters
    new_node->type = type;
    new_node->id = id;
    new_node->message = message;

    // Insert the new node into the linked list
    if (list->head == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        new_node->prev = list->tail;
        list->tail = new_node;
    }
}

// Delete a LTE_NAS_PDU element from the linked list
void nas_list_delete(LTE_NAS_PDU_list* list, NAS_MESSAGE_TYPE type, NAS_MESSAGE_ID id) {
    // Find the node to be deleted
    LTE_NAS_PDU_node* node = list->head;
    while (node != NULL && node->type != type || node->id != id) {
        node = node->next;
    }

    if (node == NULL) {
        // Handle deletion failure gracefully
        printf("Node not found\n");
        return;
    }

    // Remove the node from the linked list
    if (node->prev != NULL) {
        node->prev->next = node->next;
    } else {
        list->head = node->next;
    }
    if (node->next != NULL) {
        node->next->prev = node->prev;
    } else {
        list->tail = node->prev;
    }

    // Free the memory allocated for the node
    nas_free(node);
}

// Serialize a linked list of LTE_NAS_PDU elements into a binary format
void nas_list_serialize(LTE_NAS_PDU_list* list, void* buffer) {
    // Calculate the total size of the serialized data
    size_t size = 0;
    LTE_NAS_PDU_node* node = list->head;
    while (node != NULL) {
        size += sizeof(NAS_MESSAGE_TYPE) + sizeof(NAS_MESSAGE_ID) + strlen((char*)node->message);
        node = node->next;
    }

    // Write the serialized data to the buffer
    char* ptr = (char*)buffer;
    node = list->head;
    while (node != NULL) {
        memcpy(ptr, &node->type, sizeof(NAS_MESSAGE_TYPE));
        ptr += sizeof(NAS_MESSAGE_TYPE);
        memcpy(ptr, &node->id, sizeof(NAS_MESSAGE_ID));
        ptr += sizeof(NAS_MESSAGE_ID);
        memcpy(ptr, node->message, strlen((char*)node->message));
        ptr += strlen((char*)node->message);
        node = node->next;
    }
}

// Deserialize a linked list of LTE_NAS_PDU elements from a binary format
void nas_list_deserialize(LTE_NAS_PDU_list* list, void* buffer) {
    // Calculate the total size of the serialized data
    size_t size = 0;
    LTE_NAS_PDU_node* node = list->head;
    while (node != NULL) {
        size += sizeof(NAS_MESSAGE_TYPE) + sizeof(NAS_MESSAGE_ID) + strlen((char*)node->message);
        node = node->next;
    }

    // Read the serialized data from the buffer
    char* ptr = (char*)buffer;
    while (ptr < (char*)buffer + size) {
        NAS_MESSAGE_TYPE type;
        memcpy(&type, ptr, sizeof(NAS_MESSAGE_TYPE));
        ptr += sizeof(NAS_MESSAGE_TYPE);
        NAS_MESSAGE_ID id;
        memcpy(&id, ptr, sizeof(NAS_MESSAGE_ID));
        ptr += sizeof(NAS_MESSAGE_ID);
        void* message = nas_alloc(strlen((char*)ptr) + 1);
        if (message == NULL) {
            // Handle memory allocation failure gracefully
            printf("Memory allocation failed\n");
            return;
        }
        memcpy(message, ptr, strlen((char*)ptr) + 1);
        nas_list_insert(list, type, id, message);
        ptr += strlen((char*)ptr) + 1;
    }
}
```
This code implements a custom allocator that uses a fixed-size block pool with dynamic resizing to manage memory allocation for the linked list structure. The `nas_alloc` function allocates memory from the block pool, and the `nas_free` function frees the allocated memory. The `nas_list_init` function initializes a new linked list structure, the `nas_list_insert` function inserts a new LTE_NAS_PDU element into the linked list, and the `nas_list_delete` function deletes a LTE_NAS_PDU element from the linked list. The `nas_list_serialize` function serializes a linked list of LTE_NAS_PDU elements into a binary format, and the `nas_list_deserialize` function deserializes a linked list of LTE_NAS_PDU elements from a binary format.

