#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include <assert.h>

// Define a struct to represent a GTP_U entity
typedef struct {
    int id;
    char* name;
} GTP_U;

// Define a struct to represent the dynamic list of GTP_U entities
typedef struct {
    GTP_U** entities;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} GTP_UList;

// Initialize a new GTP_UList with an initial capacity of 10
GTP_UList* gtp_u_list_init(size_t capacity) {
    GTP_UList* list = malloc(sizeof(GTP_UList));
    assert(list != NULL);
    list->entities = malloc(capacity * sizeof(GTP_U*));
    assert(list->entities != NULL);
    list->capacity = capacity;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

// Add a new GTP_U entity to the list
void gtp_u_list_add(GTP_UList* list, int id, char* name) {
    pthread_mutex_lock(&list->mutex);
    if (list->count == list->capacity) {
        // Double the capacity of the list if it's full
        size_t new_capacity = list->capacity * 2;
        GTP_U** new_entities = realloc(list->entities, new_capacity * sizeof(GTP_U*));
        assert(new_entities != NULL);
        list->entities = new_entities;
        list->capacity = new_capacity;
    }
    GTP_U* entity = malloc(sizeof(GTP_U));
    assert(entity != NULL);
    entity->id = id;
    entity->name = name;
    list->entities[list->count++] = entity;
    pthread_mutex_unlock(&list->mutex);
}

// Remove a GTP_U entity from the list by its ID
void gtp_u_list_remove(GTP_UList* list, int id) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; i++) {
        if (list->entities[i]->id == id) {
            free(list->entities[i]);
            memmove(&list->entities[i], &list->entities[i + 1], (list->count - i - 1) * sizeof(GTP_U*));
            list->count--;
            break;
        }
    }
    pthread_mutex_unlock(&list->mutex);
}

// Retrieve a GTP_U entity from the list by its ID
GTP_U* gtp_u_list_get(GTP_UList* list, int id) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; i++) {
        if (list->entities[i]->id == id) {
            GTP_U* entity = list->entities[i];
            pthread_mutex_unlock(&list->mutex);
            return entity;
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

// Free the memory used by the GTP_UList
void gtp_u_list_free(GTP_UList* list) {
    for (size_t i = 0; i < list->count; i++) {
        free(list->entities[i]);
    }
    pthread_mutex_destroy(&list->mutex);
    free(list->entities);
    free(list);
}
```
