#include <stdlib.h>

struct node {
    struct link *links;
};

struct link {
    struct node *node;
    struct link *next;
};

int populateGraph(int numNodes, int numLinks) {
    struct node *nodeArray = malloc(numNodes * sizeof(struct node));
    if (nodeArray == NULL) {
        return -1; // Memory allocation failed
    }

    struct link *linkArray = malloc(numLinks * sizeof(struct link));
    if (linkArray == NULL) {
        free(nodeArray);
        return -2; // Memory allocation failed
    }

    for (int i = 0; i < numNodes; i++) {
        struct node *node = &nodeArray[i];
        node->links = malloc(5);
        if (node->links == NULL) {
            free(linkArray);
            free(nodeArray);
            return -3; // Memory allocation failed
        }

        for (int j = 0; j < 5; j++) {
            struct link *link = &linkArray[j];
            link->node = node;
            link->next = NULL;
        }
    }

    return numNodes;
}

void cleanupGraph(struct node *nodeArray, int numNodes) {
    for (int i = 0; i < numNodes; i++) {
        struct node *node = &nodeArray[i];
        free(node->links);
    }
    free(nodeArray);
}
