#include <string>

using namespace std;
using namespace boost::asio;
using namespace YAML;

struct NetworkSettings {
  string hostname;
  int port;
  bool use_ssl;
};

struct ApplicationParameters {
  string app_id;
  string app_secret;
};

struct ExternalServiceURLs {
  string url1;
  string url2;
};

struct Configuration {
  NetworkSettings network_settings;
  ApplicationParameters application_parameters;
  ExternalServiceURLs external_service_urls;
};

void parseYAMLConfig(const string& filename, Configuration& config) {
  YAML::Node node = LoadFile(filename);
  if (node["network_settings"]) {
    NetworkSettings network_settings;
    network_settings.hostname = node["network_settings"]["hostname"].as<string>();
    network_settings.port = node["network_settings"]["port"].as<int>();
    network_settings.use_ssl = node["network_settings"]["use_ssl"].as<bool>();
    config.network_settings = network_settings;
  } else {
    throw runtime_error("Missing required field: network_settings");
  }

  if (node["application_parameters"]) {
    ApplicationParameters application_parameters;
    application_parameters.app_id = node["application_parameters"]["app_id"].as<string>();
    application_parameters.app_secret = node["application_parameters"]["app_secret"].as<string>();
    config.application_parameters = application_parameters;
  } else {
    throw runtime_error("Missing required field: application_parameters");
  }

  if (node["external_service_urls"]) {
    ExternalServiceURLs external_service_urls;
    external_service_urls.url1 = node["external_service_urls"]["url1"].as<string>();
    external_service_urls.url2 = node["external_service_urls"]["url2"].as<string>();
    config.external_service_urls = external_service_urls;
  } else {
    throw runtime_error("Missing required field: external_service_urls");
  }
}

void validateConfiguration(const Configuration& config) {
  if (config.network_settings.hostname.empty()) {
    throw runtime_error("Missing required field: network_settings.hostname");
  }

  if (config.network_settings.port <= 0) {
    throw runtime_error("Invalid value for network_settings.port");
  }

  if (!config.application_parameters.app_id.empty() && !config.application_parameters.app_secret.empty()) {
    throw runtime_error("Missing required field: application_parameters.app_id or application_parameters.app_secret");
