// Define a hash table to map frame numbers to their corresponding statistics
typedef struct FrameStatisticsHashTable {
    int size;
    FrameStatistics** buckets;
} FrameStatisticsHashTable;

// Initialize the hash table with a given size
void init_hash_table(FrameStatisticsHashTable* table, int size) {
    table->size = size;
    table->buckets = (FrameStatistics**)malloc(sizeof(FrameStatistics*) * size);
    memset(table->buckets, 0, sizeof(FrameStatistics*) * size);
}

// Add a new measurement report to the hash table
void add_report(FrameStatisticsHashTable* table, MeasurementReport report) {
    int index = report.frame_number % table->size;
    FrameStatistics* stats = (FrameStatistics*)malloc(sizeof(FrameStatistics));
    memset(stats, 0, sizeof(FrameStatistics));
    stats->frame_number = report.frame_number;
    stats->average_rssi = report.average_rssi;
    stats->average_snr = report.average_snr;
    table->buckets[index] = stats;
}

// Update an existing measurement report in the hash table
void update_report(FrameStatisticsHashTable* table, MeasurementReport report) {
    int index = report.frame_number % table->size;
    FrameStatistics* stats = table->buckets[index];
    if (stats != NULL) {
        stats->average_rssi += report.average_rssi;
        stats->average_snr += report.average_snr;
        stats->frame_number++;
    } else {
        add_report(table, report);
    }
}

// Retrieve the statistics for a specific time frame
FrameStatistics* get_statistics(FrameStatisticsHashTable* table, int frame_number) {
    int index = frame_number % table->size;
    FrameStatistics* stats = table->buckets[index];
    if (stats != NULL && stats->frame_number == frame_number) {
        return stats;
    } else {
        return NULL;
    }
}

// Provide an overview of aggregated statistics across all reports
void get_overview(FrameStatisticsHashTable* table, int* total_frames, double* average_rssi, double* average_snr) {
    *total_frames = 0;
    *average_rssi = 0.0;
    *average_snr = 0.0;
    for (int i = 0; i < table->size; i++) {
        FrameStatistics* stats = table->buckets[i];
        if (stats != NULL) {
            *total_frames += stats->frame_number;
            *average_rssi += stats->average_rssi;
            *average_snr += stats->average_snr;
        }
    }
    *average_rssi /= (double)*total_frames;
    *average_snr /= (double)*total_frames;
}

// Periodically clean up unused resources to prevent memory leaks
void cleanup(FrameStatisticsHashTable* table) {
    for (int i = 0; i < table->size; i++) {
        FrameStatistics* stats = table->buckets[i];
        if (stats != NULL && stats->frame_number == 0) {
            free(stats);
            table->buckets[i] = NULL;
        }
    }
}
