    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the list of NFAPI_CRC_INDICATION_PDU_T structures
static NFAPI_CRC_INDICATION_PDU_T *list = NULL;

// Define the mutex for thread-safe operations
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Define the maximum size of the list
#define MAX_LIST_SIZE 1024

// Function to add a new structure to the list
void add_structure(NFAPI_CRC_INDICATION_PDU_T *new_struct) {
    // Acquire the mutex for thread-safe operations
    pthread_mutex_lock(&mutex);

    // Check if the list is full
    if (list == NULL || list->count >= MAX_LIST_SIZE) {
        // If the list is full, trim the least recently used entry
        trim_lru();
    }

    // Add the new structure to the end of the list
    NFAPI_CRC_INDICATION_PDU_T *new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    memcpy(new_node, new_struct, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list == NULL) {
        list = new_node;
    } else {
        NFAPI_CRC_INDICATION_PDU_T *last_node = list;
        while (last_node->next != NULL) {
            last_node = last_node->next;
        }
        last_node->next = new_node;
    }

    // Increment the count of unique RNTI values
    if (new_struct->RNTI != 0) {
        int *count = get_rnti_count(new_struct->RNTI);
        (*count)++;
    }

    // Release the mutex for thread-safe operations
    pthread_mutex_unlock(&mutex);
}

// Function to retrieve the count of unique RNTI values in the list
int get_rnti_count(int rnti) {
    int count = 0;
    // Acquire the mutex for thread-safe operations
    pthread_mutex_lock(&mutex);

    NFAPI_CRC_INDICATION_PDU_T *node = list;
    while (node != NULL) {
        if (node->RNTI == rnti) {
            count++;
        }
        node = node->next;
    }

    // Release the mutex for thread-safe operations
    pthread_mutex_unlock(&mutex);

    return count;
}

// Function to trim the least recently used entry from the list
void trim_lru() {
    // Acquire the mutex for thread-safe operations
    pthread_mutex_lock(&mutex);

    NFAPI_CRC_INDICATION_PDU_T *node = list;
    while (node->next != NULL) {
        node = node->next;
    }
    free(node);
    node->next = NULL;

    // Release the mutex for thread-safe operations
    pthread_mutex_unlock(&mutex);
}

// Function to reset the list to an empty state, preserving thread safety during the operation
void reset() {
    // Acquire the mutex for thread-safe operations
    pthread_mutex_lock(&mutex);

    NFAPI_CRC_INDICATION_PDU_T *node = list;
    while (node != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *next_node = node->next;
        free(node);
        node = next_node;
    }
    list = NULL;

    // Release the mutex for thread-safe operations
    pthread_mutex_unlock(&mutex);
}
