    // Lock the mutex to prevent concurrent access to the traffic flow stats array
    pthread_mutex_lock(&traffic_flow_stats_mutex);

    // Check if the interface is already in the array
    for (int i = 0; i < num_interfaces; i++) {
        if (traffic_flow_stats[i].ifindex == ifindex) {
            pthread_mutex_unlock(&traffic_flow_stats_mutex);
            return; // Interface already exists, do nothing
        }
    }

    // Allocate memory for the new interface in the traffic flow stats array
    TrafficFlowStats *new_interface = malloc(sizeof(TrafficFlowStats));
    if (new_interface == NULL) {
        perror("malloc");
        exit(1);
    }

    // Initialize the new interface's statistics to zero
    memset(new_interface, 0, sizeof(TrafficFlowStats));
    new_interface->ifindex = ifindex;

    // Add the new interface to the end of the array
    traffic_flow_stats[num_interfaces++] = *new_interface;

    // Unlock the mutex and return
    pthread_mutex_unlock(&traffic_flow_stats_mutex);
}

// Function to update the traffic flow statistics for a given interface
void update_interface(int ifindex) {
    // Lock the mutex to prevent concurrent access to the traffic flow stats array
    pthread_mutex_lock(&traffic_flow_stats_mutex);

    // Find the interface in the array and update its statistics
    for (int i = 0; i < num_interfaces; i++) {
        if (traffic_flow_stats[i].ifindex == ifindex) {
            traffic_flow_stats[i].bytes_transmitted += bytes_transmitted;
            traffic_flow_stats[i].bytes_received += bytes_received;
            traffic_flow_stats[i].packet_loss_rate = packet_loss_rate;
            traffic_flow_stats[i].latency_statistics = latency_statistics;
