    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&traffic_flow_stats_mutex);
}

// Function to retrieve the most recent traffic flow statistics for a given interface
TrafficFlowStats *get_interface(int ifindex) {
    // Lock the mutex to prevent concurrent access to the traffic flow stats array
    pthread_mutex_lock(&traffic_flow_stats_mutex);

    // Find the interface in the array and return its statistics
    for (int i = 0; i < num_interfaces; i++) {
        if (traffic_flow_stats[i].ifindex == ifindex) {
            TrafficFlowStats *interface_stats = &traffic_flow_stats[i];
            pthread_mutex_unlock(&traffic_flow_stats_mutex);
            return interface_stats; // Return a copy of the interface's statistics
        }
    }

    // If the interface is not found, return NULL
    pthread_mutex_unlock(&traffic_flow_stats_mutex);
    return NULL;
}

// Function to handle network interface disconnections and reconnections gracefully
void handle_interface_disconnection(int ifindex) {
    // Lock the mutex to prevent concurrent access to the traffic flow stats array
    pthread_mutex_lock(&traffic_flow_stats_mutex);

    // Find the interface in the array and remove it from the array
    for (int i = 0; i < num_interfaces; i++) {
        if (traffic_flow_stats[i].ifindex == ifindex) {
            free(traffic_flow_stats[i]); // Free the memory allocated for the interface's statistics
            traffic_flow_stats[i] = traffic_flow_stats[--num_interfaces]; // Shift the remaining interfaces to fill the gap
