    // Start a thread to handle retrieval of traffic flow statistics for each interface and return the most recent statistics
    pthread_t interface_stats_retrieval_thread;
    if (pthread_create(&interface_stats_retrieval_thread, NULL, &get_interface, NULL) != 0) {
        perror("pthread_create");
        exit(1);
    }

    // Start a thread to handle addition of new interfaces to the traffic flow stats array
    pthread_t interface_addition_thread;
    if (pthread_create(&interface_addition_thread, NULL, &add_interface, NULL) != 0) {
        perror("pthread_create");
        exit(1);
    }

    // Join all threads to ensure proper termination of the program
    pthread_join(background_task_thread, NULL);
    pthread_join(external_data_source_thread, NULL);
    pthread_join(interface_disconnection_thread, NULL);
    pthread_join(interface_reconnection_thread, NULL);
    pthread_join(historical_data_management_thread, NULL);
    pthread_join(real_time_traffic_stats_thread, NULL);
    pthread_join(interface_stats_retrieval_thread, NULL);
    pthread_join(interface_addition_thread, NULL);

    // Free the memory allocated for the traffic flow stats array and return
    free(traffic_flow_stats);
    return 0;
}
