// Define the data structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the data structure for the list of NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *list;
    size_t size;
} NFAPI_CRC_INDICATION_LIST_T;

// Define the data structure for the statistics on successful and failed attempts to add RNTIs
typedef struct {
    uint32_t num_successful_additions;
    uint32_t num_failed_additions;
} NFAPI_CRC_INDICATION_STATS_T;

// Define the data structure for the synchronization strategy
typedef enum {
    LOCK,
    LOCKFREE
} SYNCHRONIZATION_STRATEGY_T;

// Define the data structure for the logging mechanism
typedef struct {
    FILE *logfile;
    bool enabled;
} LOGGING_MECHANISM_T;

// Define the function to dynamically generate and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
void generate_crc_indication_list(NFAPI_CRC_INDICATION_LIST_T *list, size_t num_elements, SYNCHRONIZATION_STRATEGY_T strategy) {
    // Initialize the list and statistics
    list->size = 0;
    NFAPI_CRC_INDICATION_STATS_T stats = {0};

    // Define the random seed for generating RNTIs
    srand(time(NULL));

    // Iterate over the number of elements to generate
    for (size_t i = 0; i < num_elements; i++) {
        // Generate a new RNTI value
        uint32_t rnti = rand() % 1000000000 + 1;

        // Check if the RNTI already exists in the list
        bool duplicate = false;
        for (size_t j = 0; j < list->size; j++) {
            if (list->list[j].RNTI == rnti) {
                duplicate = true;
                break;
            }
        }

        // If the RNTI is not a duplicate, add it to the list and increment the statistics
        if (!duplicate) {
            NFAPI_CRC_INDICATION_PDU_T pdu = {0};
            pdu.RX_UE_INFORMATION_TAG = 1;
            pdu.RNTI = rnti;
            pdu.CRC_INDICATION_REL8_TAG = 2;
            pdu.CRCFLAG = rand() % 2 == 0 ? true : false;
            list->list[list->size++] = pdu;
            stats.num_successful_additions++;
        } else {
            stats.num_failed_additions++;
        }
    }

    // Log the statistics and return the list
    if (strategy == LOCK) {
        pthread_mutex_lock(&list->mutex);
        log_statistics(stats, list->size);
        pthread_mutex_unlock(&list->mutex);
    } else if (strategy == LOCKFREE) {
        log_statistics(stats, list->size);
    }
    return list;
}

// Define the function to check the integrity of the final list
void verify_crc_indication_list(NFAPI_CRC_INDICATION_LIST_T *list) {
    // Iterate over the list and check the consistency of the CRC flags with respect to the UE information tags and RNTIs
    for (size_t i = 0; i < list->size; i++) {
        if (list->list[i].CRC_INDICATION_REL8_TAG != 2) {
            printf("Error: CRC flag is not consistent with UE information tag and RNTI\n");
        }
    }
}

// Define the function to log the statistics and errors encountered during the operation
void log_statistics(NFAPI_CRC_INDICATION_STATS_T stats, size_t list_size) {
    // Log the statistics and return the list
    printf("Successful additions: %d\n", stats.num_successful_additions);
    printf("Failed additions: %d\n", stats.num_failed_additions);
}

// Define the function to handle potential memory leaks and ensure all resources are properly released
void cleanup(NFAPI_CRC_INDICATION_LIST_T *list) {
    // Release the list of NFAPI_CRC_INDICATION_PDU_T structures
    free(list->list);
}
