    if (fp == NULL) {
        perror("Error opening configuration file");
        return -1;
    }

    // Read the version header from the file
    char version_header[256];
    if (fread(version_header, sizeof(char), 256, fp) != 256) {
        perror("Error reading version header");
        return -1;
    }

    // Determine the version of the configuration structure to use based on the version header
    int version = atoi(version_header);
    if (version < 0 || version > MAX_NUM_CONFIGS) {
        perror("Invalid version number");
        return -1;
    }

    // Allocate memory for the array of configurations
    configs = MEMORY_MANAGEMENT_STRATEGY(sizeof(LTEPHYLayerConfig) * MAX_NUM_CONFIGS);
