        // Validate the configuration before adding it to the array
        if (!validate_configuration(&configs[i])) {
            perror("Invalid configuration");
            return -1;
        }

        // Add the configuration to the array
        i++;
    }

    // Close the file and return the number of configurations read
    fclose(fp);
    return i;
}

// Define the function to validate a single configuration
bool validate_configuration(const LTEPHYLayerConfig* config) {
    // Validate the bandwidth, number of antennas, and modulation scheme
    if (config->bandwidth < 0 || config->num_antennas < 0 || strlen(config->modulation_scheme) == 0) {
        return false;
    }

    // Validate the modulation scheme based on industry standards for LTE networks
    if (strcmp(config->modulation_scheme, "QPSK") != 0 && strcmp(config->modulation_scheme, "16QAM") != 0) {
        return false;
    }

    // Return true if the configuration is valid
    return true;
}

