void cache_item(resource_cache_t *cache, item_metadata_t *item) {
    if (cache->count == MAX_ITEMS) {
        // evict oldest item from cache
        // ...
    }
    cache->items[cache->count++] = item;
}

void* load_resource(void *args) {
    resource_bundle_t *bundle = (resource_bundle_t *)args;
    int count = 0;
    while (true) {
        item_metadata_t *item = malloc(sizeof(item_metadata_t));
        if (read_item(bundle, item) == -1) {
            free(item);
            break;
        }
        cache_item(&cache, item);
        count++;
    }
    return (void *)count;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <resource file path>\n", argv[0]);
        exit(EXIT_FAILURE);
    }
    resource_bundle_t bundle;
    load_resource_bundle(argv[1], &bundle);
    pthread_t thread;
    pthread_create(&thread, NULL, load_resource, (void *)&bundle);
    int count = 0;
    while (true) {
        item_metadata_t *item = malloc(sizeof(item_metadata_t));
        if (read_item(&bundle, item) == -1) {
            free(item);
            break;
        }
        cache_item(&cache, item);
        count++;
    }
    pthread_join(thread, NULL);
    close_resource_bundle(&bundle);
    return 0;
}
