#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <chrono>
#include <future>
#include <vector>
#include <unordered_map>
#include <string>
#include <sstream>
#include <iomanip>
#include <cstdlib>
#include <ctime>

// Define the external service interface
class ExternalServiceInterface {
public:
    virtual ~ExternalServiceInterface() {}
    virtual std::string makeRequest(const std::string& request) = 0;
};

// Define a test double for the external service interface
class TestDouble : public ExternalServiceInterface {
public:
    std::string makeRequest(const std::string& request) override {
        // Simulate slow response time
        std::this_thread::sleep_for(std::chrono::milliseconds(500));
        return "Test Double Response";
    }
};

// Define the client class
class Client {
public:
    Client(const std::string& name, const int& requestLimit, const int& timeout) :
            m_name(name), m_requestLimit(requestLimit), m_timeout(timeout) {}

    // Make a request to the external service
    void makeRequest(const std::string& request) {
        // Check if the request limit has been reached
        if (m_requests.size() >= m_requestLimit) {
            return;
        }

        // Create a new task and add it to the work queue
        auto task = std::make_shared<Task>(request);
        m_workQueue.push(task);

        // Start the worker thread if necessary
        if (m_workerThreads.size() < m_maxWorkerThreads) {
            startWorkerThread();
        }
    }

    // Get the number of requests made so far
    int getRequestCount() const { return m_requests.size(); }

    // Get the number of successful requests
    int getSuccessfulRequestCount() const { return m_successfulRequests; }

    // Get the number of failed requests
    int getFailedRequestCount() const { return m_failedRequests; }

    // Get the average latency for all successful requests
    double getAverageLatency() const { return m_averageLatency; }

    // Get the maximum latency for any successful request
    int getMaximumLatency() const { return m_maximumLatency; }

private:
    struct Task {
        std::string request;
        std::chrono::time_point<std::chrono::steady_clock> startTime;
        std::future<std::string> future;
    };

    // Start a new worker thread
    void startWorkerThread() {
        m_workerThreads.emplace_back(new std::thread([this] {
            while (true) {
                Task task;
                {
                    std::unique_lock<std::mutex> lock(m_workQueueMutex);
                    m_workQueueConditionVariable.wait(lock, [this] { return !m_workQueue.empty() || m_shutdown; });
                    if (m_shutdown) {
                        break;
                    }
                    task = m_workQueue.front();
                    m_workQueue.pop();
                }

                // Make the request to the external service
                std::string response;
                try {
                    response = m_externalService->makeRequest(task.request);
                    task.future.set_value(response);
                } catch (const std::exception& e) {
                    task.future.set_exception(std::current_exception());
                }
            }
        }));
    }

    // Stop all worker threads
    void stopWorkerThreads() {
        m_shutdown = true;
        for (auto& thread : m_workerThreads) {
            if (thread->joinable()) {
                thread->join();
            }
        }
    }

    // The name of the client
    std::string m_name;

    // The maximum number of requests to make concurrently
    int m_requestLimit;

    // The timeout for each request in milliseconds
    int m_timeout;

    // The external service interface
    ExternalServiceInterface* m_externalService;

    // The worker threads
    std::vector<std::shared_ptr<std::thread>> m_workerThreads;

    // The maximum number of worker threads to create
    int m_maxWorkerThreads = 10;

    // The work queue for tasks
    std::queue<Task> m_workQueue;

    // The mutex and condition variable for the work queue
    std::mutex m_workQueueMutex;
    std::condition_variable m_workQueueConditionVariable;

    // The shutdown flag
    bool m_shutdown = false;

    // The number of requests made so far
    int m_requests = 0;

    // The number of successful requests
    int m_successfulRequests = 0;

    // The number of failed requests
    int m_failedRequests = 0;

    // The average latency for all successful requests
    double m_averageLatency = 0.0;

    // The maximum latency for any successful request
    int m_maximumLatency = 0;
};

int main() {
    // Create a client with the given name, request limit, and timeout
    Client client("MyClient", 200, 4000);

    // Set the external service interface to use
    client.m_externalService = new TestDouble();

    // Start the worker threads
    client.startWorkerThreads();

    // Make a request to the external service
    client.makeRequest("My Request");

    // Wait for the response
    std::future<std::string> future = client.m_workQueue.front().future;
    std::string response = future.get();

    // Print the response
    std::cout << "Response: " << response << std::endl;

    // Stop the worker threads
    client.stopWorkerThreads();

    return 0;
}']

