void init_frame(NFAPI_RX_FRAME_PDU_T *pdu, int size) {
    pthread_mutex_lock(&mutex);
    frame_info_t *new_frame = malloc(sizeof(frame_info_t));
    new_frame->pdu = pdu;
    new_frame->size = size;
    frames = realloc(frames, (num_frames + 1) * sizeof(frame_info_t));
    frames[num_frames++] = new_frame;
    pthread_mutex_unlock(&mutex);
}

void populate_frame(NFAPI_RX_FRAME_PDU_T *pdu, int size) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_frames; i++) {
        if (frames[i]->pdu == pdu) {
            frames[i]->size = size;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void destroy_frame(NFAPI_RX_FRAME_PDU_T *pdu) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_frames; i++) {
        if (frames[i]->pdu == pdu) {
            free(frames[i]);
            frames[i] = NULL;
            break;
        }
