// Define a function to retrieve user data from a dynamic storage mechanism, e.g., a JSON file
void loadUsers(User **users, int *num_users) {
    // Implement retrieval logic here, e.g., reading the users array from a JSON file
    printf("Loaded %d users\n", *num_users);
}

int main() {
    User **users = NULL;
    int num_users = 0;
    Request request;
    while (true) {
        // Read the next request from stdin or a file
        scanf("%d %s %s %s %s", &request.id, request.name, request.email, request.password, request.sub_action);
        if (strcmp(request.sub_action, "quit") == 0) {
