// Define the structure for LTE_PHY_RACH_CONFIG_DULR
typedef struct {
    int ue_id;
    int preamble_seq;
    long start_time;
} LTE_PHY_RACH_CONFIG_DULR;

// Define the structure for LTEPHYLayerConfig
typedef struct {
    int bandwidth;
    int num_antennas;
    char* modulation_scheme;
} LTEPHYLayerConfig;

// Define the function to initialize and populate the dynamic array of LTE_PHY_RACH_CONFIG_DULR structures
void init_rach_config(LTE_PHY_RACH_CONFIG_DULR** rach_config, int num_ues) {
    // Allocate memory for the dynamic array of LTE_PHY_RACH_CONFIG_DULR structures
    *rach_config = (LTE_PHY_RACH_CONFIG_DULR*)malloc(num_ues * sizeof(LTE_PHY_RACH_CONFIG_DULR));

    // Initialize the dynamic array of LTE_PHY_RACH_CONFIG_DULR structures with default values
    for (int i = 0; i < num_ues; i++) {
        (*rach_config)[i].ue_id = -1;
        (*rach_config)[i].preamble_seq = -1;
        (*rach_config)[i].start_time = -1;
    }
}

// Define the function to initialize and populate the dynamic array of LTEPHYLayerConfig structures
void init_phy_layer_config(LTEPHYLayerConfig** phy_layer_config, int num_ues) {
    // Allocate memory for the dynamic array of LTEPHYLayerConfig structures
    *phy_layer_config = (LTEPHYLayerConfig*)malloc(num_ues * sizeof(LTEPHYLayerConfig));

    // Initialize the dynamic array of LTEPHYLayerConfig structures with default values
    for (int i = 0; i < num_ues; i++) {
        (*phy_layer_config)[i].bandwidth = -1;
        (*phy_layer_config)[i].num_antennas = -1;
        (*phy_layer_config)[i].modulation_scheme = NULL;
    }
}

// Define the function to read configurations from a binary file and populate the dynamic arrays of LTE_PHY_RACH_CONFIG_DULR and LTEPHYLayerConfig structures
void read_configs(LTE_PHY_RACH_CONFIG_DULR** rach_config, LTEPHYLayerConfig** phy_layer_config, int num_ues) {
    // Open the binary file for reading
    FILE* fp = fopen("config.bin", "rb");
    if (fp == NULL) {
        perror("Error opening config file");
        exit(1);
    }

    // Read the configurations from the binary file and populate the dynamic arrays of LTE_PHY_RACH_CONFIG_DULR and LTEPHYLayerConfig structures
    for (int i = 0; i < num_ues; i++) {
        // Read the UE ID, preamble sequence, and start time from the binary file
        fread(&(*rach_config)[i].ue_id, sizeof(int), 1, fp);
        fread(&(*rach_config)[i].preamble_seq, sizeof(int), 1, fp);
        fread(&(*rach_config)[i].start_time, sizeof(long), 1, fp);

