void initUeContexts(int numUes, int numCcs, UEContextInfo **ueContexts) {
    // Allocate memory for the array of UE context information structures
    *ueContexts = (UEContextInfo *)malloc(numUes * sizeof(UEContextInfo));
    if (*ueContexts == NULL) {
        printf("Error: Failed to allocate memory for UE contexts\n");
        return;
    }

    // Initialize the array of UE context information structures
    for (int i = 0; i < numUes; i++) {
        (*ueContexts)[i].ueId = i + 1;
        (*ueContexts)[i].rnti = i + 1;
        (*ueContexts)[i].sfn = 0;
        (*ueContexts)[i].ccConfig.numCcs = numCcs;
    }

    // Populate the array of UE context information structures with valid CC configurations
    for (int i = 0; i < numUes; i++) {
        for (int j = 0; j < numCcs; j++) {
            (*ueContexts)[i].ccConfig.cc[j] = j + 1;
        }
    }
}

