// Define the structure for an NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the structure for a list of NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
} NFAPI_CRC_INDICATION_LIST_T;

// Define the structure for a list of RNTIs to process concurrently
typedef struct {
    uint16_t *RNTIs;
    size_t size;
} RNTI_LIST_T;

// Define the function to manage the dynamic list of NFAPI_CRC_INDICATION_PDU_T structures
void manage_crc_indication_list(NFAPI_CRC_INDICATION_LIST_T *list, RNTI_LIST_T *rnti_list) {
    // Lock the list to prevent concurrent access from multiple threads
    pthread_mutex_lock(&list->mutex);

    // Iterate over the RNTIs in the rnti_list and insert/delete/retrieve corresponding elements in the list
    for (size_t i = 0; i < rnti_list->size; i++) {
        uint16_t rnti = rnti_list->RNTIs[i];

        // Check if an element with the given RNTI already exists in the list
        bool found = false;
        for (size_t j = 0; j < list->size; j++) {
            if (list->data[j].RNTI == rnti) {
                found = true;
                break;
            }
        }

        // If an element with the given RNTI does not exist, insert a new one
        if (!found) {
            NFAPI_CRC_INDICATION_PDU_T *new_element = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            new_element->RX_UE_INFORMATION_TAG = 0;
            new_element->RNTI = rnti;
            new_element->CRCFLAG = rand() % 256;
            list->data = realloc(list->data, (list->size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            list->data[list->size++] = *new_element;
        }
    }

    // Unlock the list to allow concurrent access from multiple threads
    pthread_mutex_unlock(&list->mutex);
}

// Define the function to retrieve the number of processed and unprocessed elements in the list
void get_crc_indication_count(NFAPI_CRC_INDICATION_LIST_T *list, size_t *processed_count, size_t *unprocessed_count) {
    // Lock the list to prevent concurrent access from multiple threads
    pthread_mutex_lock(&list->mutex);

    // Iterate over the elements in the list and count the number of processed and unprocessed elements
    for (size_t i = 0; i < list->size; i++) {
        if (list->data[i].CRCFLAG == 1) {
            (*processed_count)++;
        } else {
            (*unprocessed_count)++;
        }
    }

    // Unlock the list to allow concurrent access from multiple threads
    pthread_mutex_unlock(&list->mutex);
}
