// Define the structure to store PHY layer statistics
typedef struct {
    int TX_POWER;
    float BER;
    float RSSI;
    float SNR;
    float FER;
} PHY_LAYER_STATS;

// Define the threshold for BER values that exceed this value will be stored in a thread-safe data structure
#define BER_THRESHOLD 0.1

// Define the function to dynamically allocate memory for an array of PHY_LAYER_STATS structures based on user input M
void *allocate_phy_layer_stats(int M) {
    // Allocate memory for the array of PHY_LAYER_STATS structures
    PHY_LAYER_STATS *stats = (PHY_LAYER_STATS *)malloc(M * sizeof(PHY_LAYER_STATS));
    if (!stats) {
        // Handle allocation failure
        printf("Error: Failed to allocate memory for PHY layer statistics\n");
        return NULL;
    }

    // Initialize the array of PHY_LAYER_STATS structures
    for (int i = 0; i < M; i++) {
        stats[i].TX_POWER = 0;
        stats[i].BER = 0.0f;
        stats[i].RSSI = 0.0f;
        stats[i].SNR = 0.0f;
        stats[i].FER = 0.0f;
    }

    // Create a thread-safe data structure to store the indices of BER values exceeding the threshold
    pthread_mutex_t *mutex = (pthread_mutex_t *)malloc(sizeof(pthread_mutex_t));
    if (!mutex) {
        // Handle allocation failure
        printf("Error: Failed to allocate memory for mutex\n");
        free(stats);
        return NULL;
    }
    pthread_mutex_init(mutex, NULL);

    // Define a function to update the statistics and store the indices of BER values exceeding the threshold in the thread-safe data structure
    void update_phy_layer_stats(PHY_LAYER_STATS *stats, int M) {
        for (int i = 0; i < M; i++) {
            // Update the statistics
            stats[i].TX_POWER++;
            stats[i].BER += 0.1f;
            stats[i].RSSI += 0.1f;
            stats[i].SNR += 0.1f;
            stats[i].FER += 0.1f;

            // Check if the BER value exceeds the threshold
            if (stats[i].BER > BER_THRESHOLD) {
                // Store the index of the BER value in the thread-safe data structure
                pthread_mutex_lock(mutex);
                int *indices = (int *)malloc(sizeof(int));
                indices[0] = i;
                pthread_mutex_unlock(mutex);
            }
        }
    }

    // Define a function to flush the statistics and thread-safe data structure to a remote server for analysis
    void flush_phy_layer_stats(PHY_LAYER_STATS *stats, int M) {
        // Flush the statistics to a remote server
        printf("Flushing PHY layer statistics to remote server\n");

        // Flush the thread-safe data structure to a remote server for analysis
        pthread_mutex_lock(mutex);
        int *indices = (int *)malloc(sizeof(int));
        indices[0] = 0;
