void manage_UE_sessions(int num_cells, int num_ues) {
    // Initialize the linked list and hash table for storing UE contexts
    node *head = NULL;
    hash_table *htable = (hash_table *)malloc(sizeof(hash_table));
    htable->size = 1024;
    htable->table = (UE_CONTEXT **)malloc(htable->size * sizeof(UE_CONTEXT *));

    // Generate unique UE IDs and cell IDs for each session
    int *ue_ids = (int *)malloc(num_ues * sizeof(int));
    int *cell_ids = (int *)malloc(num_cells * sizeof(int));
    for (int i = 0; i < num_ues; i++) {
        ue_ids[i] = i + 1;
    }
    for (int i = 0; i < num_cells; i++) {
        cell_ids[i] = i + 1;
    }

    // Generate random channel quality indicators for each session
    float *channel_quality_indicators = (float *)malloc(num_ues * sizeof(float));
    srand(time(NULL));
    for (int i = 0; i < num_ues; i++) {
        channel_quality_indicators[i] = rand() % 100 / 10.0;
    }

    // Populate the linked list and hash table with UE contexts
    for (int i = 0; i < num_ues; i++) {
        UE_CONTEXT *ue_context = (UE_CONTEXT *)malloc(sizeof(UE_CONTEXT));
        ue_context->UE_ID = ue_ids[i];
        ue_context->CELL_ID = cell_ids[i % num_cells];
        ue_context->CHANNEL_QUALITY_INDICATOR = channel_quality_indicators[i];
        node *new_node = (node *)malloc(sizeof(node));
        new_node->data = ue_context;
        new_node->next = head;
        head = new_node;
        htable->table[ue_ids[i] % htable->size] = ue_context;
    }

    // Handle dynamic changes in UE sessions
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    while (1) {
        // Acquire the lock on the linked list and hash table
        pthread_mutex_lock(&mutex);

        // Check for inactive sessions and prune them periodically
        node *current = head;
        while (current != NULL) {
            if (current->data->UE_ID % 100 == 0) {
                UE_CONTEXT *ue_context = current->data;
                node *next = current->next;
                free(current);
                head = next;
                htable->table[ue_context->UE_ID % htable->size] = NULL;
            } else {
                current = current->next;
            }
        }

        // Release the lock on the linked list and hash table
        pthread_mutex_unlock(&mutex);

        // Sleep for a short period to avoid busy waiting
        sleep(1);
    }
}
