#include <arpa/inet.h>
#include <resolv.h>

#define MAX_LIST_SIZE 1000
#define DNS_BUFFER_SIZE 256
#define DNS_QUERY_LIMIT 10
#define DNS_RETRY_DELAY 1000 // in milliseconds

typedef struct NFAPI_CRC_INDICATION_PDU {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
