typedef struct DNS_RESOLVER {
    char *hostname;
    int port;
    int sockfd;
    struct addrinfo *addr_info;
    struct addrinfo *current_addr;
} DNS_RESOLVER_T;

// Thread-safe DNS resolution function
int dns_resolve(const char *hostname, size_t buffer_size) {
    // Check input parameters
    if (hostname == NULL || buffer_size <= 0) {
        return -1;
    }

    // Create a new DNS resolver object
    DNS_RESOLVER_T *resolver = malloc(sizeof(DNS_RESOLVER_T));
    if (resolver == NULL) {
        return -2;
    }

    // Initialize the resolver object
    resolver->hostname = strdup(hostname);
    resolver->port = 53;
    resolver->sockfd = -1;
    resolver->addr_info = NULL;
    resolver->current_addr = NULL;

    // Perform DNS resolution
    int ret = getaddrinfo(resolver->hostname, NULL, &resolver->addr_info);
    if (ret != 0) {
        free(resolver);
        return -3;
    }

    // Iterate through the address information and find a suitable IP address
    struct addrinfo *current = resolver->addr_info;
    while (current != NULL) {
        if (current->ai_family == AF_INET || current->ai_family == AF_INET6) {
            // Create a new socket and connect to the DNS server
            resolver->sockfd = socket(current->ai_family, SOCK_DGRAM, 0);
            if (resolver->sockfd < 0) {
                continue;
            }

            ret = connect(resolver->sockfd, current->ai_addr, current->ai_addrlen);
            if (ret != 0) {
                close(resolver->sockfd);
                resolver->sockfd = -1;
                continue;
            }

            // Send a DNS query to the server
            char *query = "QUERY";
            ret = sendto(resolver->sockfd, query, strlen(query), 0, current->ai_addr, current->ai_addrlen);
            if (ret < 0) {
                close(resolver->sockfd);
                resolver->sockfd = -1;
                continue;
            }

            // Receive the DNS response from the server
            char buffer[DNS_BUFFER_SIZE];
            ret = recvfrom(resolver->sockfd, buffer, DNS_BUFFER_SIZE, 0, NULL, NULL);
            if (ret < 0) {
                close(resolver->sockfd);
                resolver->sockfd = -1;
                continue;
            }

            // Parse the DNS response and extract the IP address
            struct sockaddr_in *addr = (struct sockaddr_in *)current->ai_addr;
            char *ip_address = inet_ntoa(addr->sin_addr);
            if (ip_address == NULL) {
                close(resolver->sockfd);
                resolver->sockfd = -1;
                continue;
            }

            // Copy the IP address to the output buffer and return success
            strncpy(buffer, ip_address, buffer_size);
            freeaddrinfo(resolver->addr_info);
            free(resolver->hostname);
            free(resolver);
            return 0;
        }

        current = current->ai_next;
    }

    // If no suitable IP address was found, return an error code
    freeaddrinfo(resolver->addr_info);
    free(resolver->hostname);
    free(resolver);
    return -4;
}

// Thread-safe DNS resolver with rate limiting and exponential backoff
int dns_resolve_with_rate_limiting(const char *hostname, size_t buffer_size) {
    // Check input parameters
    if (hostname == NULL || buffer_size <= 0) {
        return -1;
    }

    // Create a new DNS resolver object
    DNS_RESOLVER_T *resolver = malloc(sizeof(DNS_RESOLVER_T));
    if (resolver == NULL) {
        return -2;
    }

    // Initialize the resolver object
    resolver->hostname = strdup(hostname);
    resolver->port = 53;
    resolver->sockfd = -1;
    resolver->addr_info = NULL;
    resolver->current_addr = NULL;

    // Perform DNS resolution with rate limiting and exponential backoff
    int ret = getaddrinfo(resolver->hostname, NULL, &resolver->addr_info);
    if (ret != 0) {
        free(resolver->hostname);
        free(resolver);
        return -3;
    }

    struct addrinfo *current = resolver->addr_info;
    while (current != NULL) {
        if (current->ai_family == AF_INET || current->ai_family == AF_INET6) {
            // Create a new socket and connect to the DNS server
            resolver->sockfd = socket(current->ai_family, SOCK_DGRAM, 0);
            if (resolver->sockfd < 0) {
                continue;
            }

            ret = connect(resolver->sockfd, current->ai_addr, current->ai_addrlen);
            if (ret != 0) {
                close(resolver->sockfd);
                resolver->sockfd = -1;
                continue;
            }

            // Send a DNS query to the server with rate limiting and exponential backoff
            char *query = "QUERY";
            int attempt = 0;
            while (attempt < DNS_QUERY_LIMIT) {
                ret = sendto(resolver->sockfd, query, strlen(query), 0, current->ai_addr, current->ai_addrlen);
                if (ret >= 0) {
                    break;
                } else {
                    attempt++;
                    usleep(DNS_RETRY_DELAY * attempt);
                }
            }

            // Receive the DNS response from the server
            char buffer[DNS_BUFFER_SIZE];
            ret = recvfrom(resolver->sockfd, buffer, DNS_BUFFER_SIZE, 0, NULL, NULL);
            if (ret < 0) {
                close(resolver->sockfd);
                resolver->sockfd = -1;
                continue;
            }

            // Parse the DNS response and extract the IP address
            struct sockaddr_in *addr = (struct sockaddr_in *)current->ai_addr;
            char *ip_address = inet_ntoa(addr->sin_addr);
            if (ip_address == NULL) {
                close(resolver->sockfd);
                resolver->sockfd = -1;
                continue;
            }

            // Copy the IP address to the output buffer and return success
            strncpy(buffer, ip_address, buffer_size);
            freeaddrinfo(resolver->addr_info);
            free(resolver->hostname);
            free(resolver);
            return 0;
        }

        current = current->ai_next;
    }

    // If no suitable IP address was found, return an error code
    freeaddrinfo(resolver->addr_info);
    free(resolver->hostname);
    free(resolver);
    return -4;
}

