// Define the structure for a DataPacket
typedef struct {
    time_t timestamp;
    char* sourceAddress;
    char* destinationAddress;
    int payloadLength;
} DataPacket;

// Define the dynamic array of DataPackets
DataPacket** dataPackets = NULL;
int numDataPackets = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize and populate the dynamic array of DataPackets
void initAndPopulateDataPackets(int maxNumDataPackets, int retentionPeriod) {
    // Allocate memory for the dynamic array of DataPackets
    dataPackets = (DataPacket**)malloc(maxNumDataPackets * sizeof(DataPacket*));
    if (!dataPackets) {
        perror("Failed to allocate memory for data packets");
        return;
    }

    // Initialize the dynamic array of DataPackets
    memset(dataPackets, 0, maxNumDataPackets * sizeof(DataPacket*));

    // Set the maximum number of data packets and retention period
    numDataPackets = maxNumDataPackets;
    retentionPeriod = retentionPeriod;

    // Start a thread to clear old data packets periodically
    pthread_t threadId;
    if (pthread_create(&threadId, NULL, clearOldDataPackets, NULL) != 0) {
        perror("Failed to create thread for clearing old data packets");
        return;
    }
}

// Function to insert a new DataPacket into the dynamic array of DataPackets
void insertDataPacket(DataPacket* packet) {
    // Acquire the mutex lock
    pthread_mutex_lock(&mutex);

    // Check if the dynamic array is full and needs to be resized
    if (numDataPackets == maxNumDataPackets) {
        // Resize the dynamic array of DataPackets
        dataPackets = (DataPacket**)realloc(dataPackets, 2 * maxNumDataPackets * sizeof(DataPacket*));
        if (!dataPackets) {
            perror("Failed to resize memory for data packets");
            return;
        }
        // Update the maximum number of data packets
        numDataPackets = 2 * maxNumDataPackets;
    }

    // Insert the new DataPacket into the dynamic array of DataPackets
    dataPackets[numDataPackets - 1] = packet;

    // Release the mutex lock
    pthread_mutex_unlock(&mutex);
}

// Function to clear old data packets periodically
void* clearOldDataPackets(void* arg) {
    while (true) {
        // Acquire the mutex lock
        pthread_mutex_lock(&mutex);

        // Check if there are any old data packets that need to be cleared
        for (int i = 0; i < numDataPackets; i++) {
            DataPacket* packet = dataPackets[i];
            if (packet->timestamp + retentionPeriod <= time(NULL)) {
                // Clear the old data packet
                free(packet);
                dataPackets[i] = NULL;
            }
        }

        // Release the mutex lock
        pthread_mutex_unlock(&mutex);

        // Sleep for a short period of time before checking again
        sleep(10);
    }
}
```
