#include <stdbool.h>
#include <pthread.h>

// Define the structure for holding RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
typedef struct {
    uint16_t rx_ue_information_tag;
    uint16_t rnti;
    uint8_t crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a hash table for storing the RNTI values
static pthread_mutex_t *rnti_hash = NULL;

// Function to dynamically populate a list of NFAPI_CRC_INDICATION_PDU_T structures
void populate_crc_indication_pdu_list(int n, NFAPI_CRC_INDICATION_PDU_T **pdu_list) {
    // Initialize the hash table if it hasn't been initialized yet
    if (rnti_hash == NULL) {
        rnti_hash = calloc(1024, sizeof(pthread_mutex_t));
        for (int i = 0; i < 1024; i++) {
            pthread_mutex_init(&rnti_hash[i], NULL);
        }
    }

    // Generate a random RNTI value for each structure
    uint16_t rnti = rand() % 65536;

    // Lock the hash table to prevent concurrent access
    pthread_mutex_lock(&rnti_hash[rnti % 1024]);

    // Check if the RNTI value is already in use
    while (rnti_hash[rnti % 1024] != NULL) {
        rnti = rand() % 65536;
    }

    // Set the CRCFLAG to a random value
    uint8_t crcflag = rand() % 2;

    // Create a new structure and populate it with the RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
    NFAPI_CRC_INDICATION_PDU_T *pdu = calloc(1, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pdu->rx_ue_information_tag = rand() % 65536;
    pdu->rnti = rnti;
    pdu->crc_indication_rel8_tag = crcflag;

    // Add the structure to the list
    *pdu_list = realloc(*pdu_list, (n + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    (*pdu_list)[n] = pdu;

    // Unlock the hash table
    pthread_mutex_unlock(&rnti_hash[rnti % 1024]);
}

// Function to handle potential errors gracefully
void error_handler(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
    exit(EXIT_FAILURE);
}
