sem_t crc_indication_sem;

// Function to allocate memory for the collection of CRC indications
void allocate_crc_indications() {
    // Allocate memory for the collection of CRC indications
    crc_indications = (NFAPI_CRC_INDICATION_PDU_T *)malloc(NUM_STRUCTURES * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_indications) {
        printf("Error: Failed to allocate memory for CRC indications\n");
        exit(1);
    }
}

// Function to free the memory allocated for the collection of CRC indications
void free_crc_indications() {
    // Free the memory allocated for the collection of CRC indications
    if (crc_indications) {
        free(crc_indications);
        crc_indications = NULL;
    }
}

// Function to generate a new CRC indication structure
