    // Initialize the fields of the new CRC indication structure
    new_crc_indication->rx_ue_information_tag = 0;
    new_crc_indication->rnti = 0;
    new_crc_indication->crc_indication_rel8_tag = 0;
    new_crc_indication->crcflag = false;

