}

// Function to add a new CRC indication structure to the collection
void add_crc_indication(NFAPI_CRC_INDICATION_PDU_T *new_crc_indication) {
    // Acquire the semaphore for controlling concurrent access
    if (sem_wait(&crc_indication_sem)) {
        printf("Error: Failed to acquire semaphore\n");
        exit(1);
    }

    // Check if the collection is empty
    if (!crc_indications) {
        allocate_crc_indications();
    }

    // Add the new CRC indication structure to the end of the collection
    crc_indications[NUM_STRUCTURES - 1] = *new_crc_indication;

    // Release the semaphore for controlling concurrent access
    if (sem_post(&crc_indication_sem)) {
        printf("Error: Failed to release semaphore\n");
        exit(1);
    }
}

// Function to remove a CRC indication structure from the collection
void remove_crc_indication(NFAPI_CRC_INDICATION_PDU_T *crc_indication) {
    // Acquire the semaphore for controlling concurrent access
    if (sem_wait(&crc_indication_sem)) {
        printf("Error: Failed to acquire semaphore\n");
        exit(1);
    }

    // Check if the collection is empty
    if (!crc_indications) {
        free_crc_indications();
    }

    // Find the index of the CRC indication structure to remove
    int index = -1;
    for (int i = 0; i < NUM_STRUCTURES; i++) {
        if (crc_indications[i].rx_ue_information_tag == crc_indication->rx_ue_information_tag &&
            crc_indications[i].rnti == crc_indication->rnti) {
            index = i;
            break;
        }
    }

    // Remove the CRC indication structure from the collection
