        crc_indications[NUM_STRUCTURES - 1].rx_ue_information_tag = 0;
        crc_indications[NUM_STRUCTURES - 1].rnti = 0;
        crc_indications[NUM_STRUCTURES - 1].crc_indication_rel8_tag = 0;
        crc_indications[NUM_STRUCTURES - 1].crcflag = false;
    }

    // Release the semaphore for controlling concurrent access
    if (sem_post(&crc_indication_sem)) {
        printf("Error: Failed to release semaphore\n");
        exit(1);
    }
}

// Function to retrieve a CRC indication structure from the collection
NFAPI_CRC_INDICATION_PDU_T *get_crc_indication(uint16_t rx_ue_information_tag, uint32_t rnti) {
    // Acquire the semaphore for controlling concurrent access
    if (sem_wait(&crc_indication_sem)) {
        printf("Error: Failed to acquire semaphore\n");
        exit(1);
    }

    // Check if the collection is empty
    if (!crc_indications) {
        free_crc_indications();
    }

    // Find the index of the CRC indication structure to retrieve
    int index = -1;
    for (int i = 0; i < NUM_STRUCTURES; i++) {
        if (crc_indications[i].rx_ue_information_tag == rx_ue_information_tag &&
            crc_indications[i].rnti == rnti) {
            index = i;
            break;
        }
    }

    // Retrieve the CRC indication structure from the collection
    NFAPI_CRC_INDICATION_PDU_T *crc_indication = NULL;
    if (index != -1) {
        crc_indication = &crc_indications[index];
    }

    // Release the semaphore for controlling concurrent access
    if (sem_post(&crc_indication_sem)) {
        printf("Error: Failed to release semaphore\n");
        exit(1);
    }

    return crc_indication;
}
```
