    TAI_LIST_T* list = malloc(sizeof(TAI_LIST_T));
    list->size = 0;
    list->capacity = 16;
    list->tais = malloc(list->capacity * sizeof(TAI_INFO_T));

    // Populate the list of TAIs using the populate_tai_list function
    populate_tai_list(list);

    // Print the list of TAIs to the console
    for (int i = 0; i < list->size; i++) {
        printf("TAI: %s, CGI: %s, Last Update: %s\n", list->tais[i].tai, list->tais[i].cgi, ctime(&list->tais[i].last_update));
    }

    // Free the memory allocated for the list and its elements
    free(list);

    return 0;
}
