// Function to dynamically create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu(uint16_t num_pdus) {
    // Check if the pool has enough memory blocks available for allocation
    if (num_pdus > POOL_SIZE) {
        printf("Error: Not enough memory in pool to allocate %d PDUs\n", num_pdus);
        return NULL;
    }

    // Allocate memory for the list of structures
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_pdus);
    if (!pdu_list) {
        printf("Error: Failed to allocate memory for PDU list\n");
        return NULL;
    }

    // Initialize the structures in the list
    for (int i = 0; i < num_pdus; i++) {
        pdu_list[i].rx_ue_information_tag = rand() % 65535;
        pdu_list[i].rnti = rand() % 4294967295;
        pdu_list[i].crc_indication_rel8_tag = rand() % 255;
        pdu_list[i].crcflag = (rand() % 2) ? true : false;
    }

    // Return the list of structures
    return pdu_list;
}

// Function to validate each PDU in the list
bool validate_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Check if the RX_UE_INFORMATION_TAG is valid
    if (pdu->rx_ue_information_tag > 65535) {
        printf("Error: Invalid RX_UE_INFORMATION_TAG\n");
        return false;
    }

    // Check if the RNTI is valid
    if (pdu->rnti > 4294967295) {
        printf("Error: Invalid RNTI\n");
        return false;
    }

    // Check if the CRC_INDICATION_REL8_TAG is valid
    if (pdu->crc_indication_rel8_tag > 255) {
        printf("Error: Invalid CRC_INDICATION_REL8_TAG\n");
        return false;
    }

    // Check if the CRCFLAG is valid
    if (pdu->crcflag != true && pdu->crcflag != false) {
        printf("Error: Invalid CRCFLAG\n");
        return false;
    }

    // Return true if all validation checks pass
    return true;
}

// Function to discard a PDU that fails validation
void discard_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    free(pdu);
}

// Main function to demonstrate the use of the create_crc_indication_pdu() and validate_pdu() functions
