    // Create a list of 1000 PDUs using the create_crc_indication_pdu() function
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = create_crc_indication_pdu(1000);

    // Validate each PDU in the list using the validate_pdu() function
    for (int i = 0; i < 1000; i++) {
        if (!validate_pdu(&pdu_list[i])) {
            discard_pdu(&pdu_list[i]);
        }
    }

