void init_LTE_PHY_RX_FRAME_PDU_dyn(int num_ues, LTE_PHY_RX_FRAME_PDU_T* pdu) {
    // Allocate memory for the RNTI and CQI values for each UE dynamically
    int* rnti = malloc(num_ues * sizeof(int));
    int* cqi = malloc(num_ues * sizeof(int));

    // Initialize the RNTI and CQI values for each UE using dynamic memory allocation
