    // Initialize the RSRP values for each UE using dynamic memory allocation
    for (int i = 0; i < num_ues; i++) {
        rsrp[i] = calculate_rsrp(i);
    }

    // Copy the RNTI, CQI, and RSRP values from the temporary buffers to the final buffer
    for (int i = 0; i < num_ues; i++) {
        pdu[i].RNTI = rnti[i];
        pdu[i].CQI = cqi[i];
        pdu[i].RSRP = rsrp[i];
    }

