    LTEUEContext **pools = malloc(num_pools * sizeof(LTEUEContext *));
    for (int i = 0; i < num_pools; i++) {
        pools[i] = malloc(pool_size * sizeof(LTEUEContext));
    }

    // Validate each measurement report and discard failing reports
