NFAPI_CRC_INDICATION_PDU_LIST* nfapi_crc_indication_pdu_list_init(size_t initial_capacity) {
    NFAPI_CRC_INDICATION_PDU_LIST* list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_LIST));
    if (!list) {
        return NULL;
    }
    list->data = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!list->data) {
        free(list);
        return NULL;
    }
    list->capacity = initial_capacity;
    list->size = 0;
    return list;
}

// Add a new element to the list, growing the capacity if necessary
bool nfapi_crc_indication_pdu_list_add(NFAPI_CRC_INDICATION_PDU_LIST* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
