    if (index >= list->size) {
        return false;
    }
    // Remove the element from the list
    NFAPI_CRC_INDICATION_PDU_T* pdu = list->data[index];
    memmove(list->data + index, list->data + index + 1, (list->size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    list->size--;
    // Shrink the capacity if necessary
    if (list->size == list->capacity / 2 && list->capacity > 1) {
        size_t new_capacity = list->capacity / 2;
        NFAPI_CRC_INDICATION_PDU_T** new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        if (!new_data) {
            return false;
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }
    return true;
}

// Free the memory allocated for the list
void nfapi_crc_indication_pdu_list_free(NFAPI_CRC_INDICATION_PDU_LIST* list) {
    free(list->data);
    free(list);
