// Thread-safe function to add a new element to the list, growing the capacity if necessary
bool nfapi_crc_indication_pdu_list_add_threadsafe(NFAPI_CRC_INDICATION_PDU_LIST* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&list->mutex);
    bool result = nfapi_crc_indication_pdu_list_add(list, pdu);
