// Thread-safe function to remove an element from the list, shrinking the capacity if necessary
bool nfapi_crc_indication_pdu_list_remove_threadsafe(NFAPI_CRC_INDICATION_PDU_LIST* list, size_t index) {
    // Lock the mutex to prevent concurrent access
