public:
    ServerConnection(const string& host, const int port) : service(), socket(service), request_buffer(), response_buffer() {
        tcp::resolver resolver(service);
        auto endpoint_iterator = resolver.resolve(host, to_string(port));
        boost::asio::connect(socket, endpoint_iterator);
        connected = true;
    }

    ~ServerConnection() {
