Pokemon* get_pokemon_list(int num_pokemon) {
    // Allocate memory for the array of Pokemon objects
    Pokemon* pokemon_list = (Pokemon*)malloc(num_pokemon * sizeof(Pokemon));

    // Initialize each Pokemon object in the list
    for (int i = 0; i < num_pokemon; i++) {
        pokemon_list[i].id = i + 1;
        pokemon_list[i].name = "Pikachu";
        pokemon_list[i].type = "Electric";
        pokemon_list[i].weaknesses[0] = "Ground";
        pokemon_list[i].weaknesses[1] = "Flying";
    }

    // Return the list of Pokemon objects
    return pokemon_list;
}

// Define a function to calculate the weighted average of weaknesses for each Pokemon object
float get_weakness_average(Pokemon* pokemon) {
    float total = 0.0f;
    int num_weaknesses = sizeof(pokemon->weaknesses) / sizeof(char*);

    // Calculate the weighted average of weaknesses for each Pokemon object
    for (int i = 0; i < num_weaknesses; i++) {
        total += pokemon->weaknesses[i];
    }

    return total / num_weaknesses;
}

// Define a function to generate and populate an array of 'record' structures
void generate_records(Pokemon* pokemon_list, int num_pokemon) {
    // Allocate memory for the array of records
    Record* record_list = (Record*)malloc(num_pokemon * sizeof(Record));

    // Initialize each record in the list with the weighted average of weaknesses for each Pokemon object
    for (int i = 0; i < num_pokemon; i++) {
        record_list[i].id = pokemon_list[i].id;
        record_list[i].name = pokemon_list[i].name;
        record_list[i].type = pokemon_list[i].type;
        record_list[i].weakness_average = get_weakness_average(&pokemon_list[i]);
    }

    // Free the memory allocated for the Pokemon objects
    free(pokemon_list);
}

// Define a function to return a string representing the weaknesses of each Pokemon object
char* get_weaknesses(Pokemon* pokemon) {
    char* weaknesses = (char*)malloc(1024 * sizeof(char));
    int num_weaknesses = sizeof(pokemon->weaknesses) / sizeof(char*);

    // Concatenate the weaknesses for each Pokemon object into a single string
    for (int i = 0; i < num_weaknesses; i++) {
        strcat(weaknesses, pokemon->weaknesses[i]);
        if (i != num_weaknesses - 1) {
            strcat(weaknesses, ", ");
        }
    }

    return weaknesses;
}
