#include <stdlib.h>
#include <string.h>
#include <stdio.h>

// Define the structure for a Network Device Interface (NDI) Packet Data Unit (PDU)
typedef struct {
    uint32_t ueContextId; // Valid User Equipment (UE) Context ID
    int8_t mimoAntennaCount; // Number of MIMO antennas
    float mimoAntennaGains[MAX_MIMO_ANTENNA_COUNT]; // Array of MIMO antenna gains
} ndiPdu_t;

// Define the dynamic array for storing NDI PDUs
typedef struct {
    ndiPdu_t *pduArray; // Pointer to an array of NDI PDUs
    size_t pduCount; // Number of NDI PDUs in the array
} ndiPduArray_t;

// Function to initialize and configure a dynamic array of NDI PDUs
void initNdiPduArray(ndiPduArray_t *pduArray, size_t pduCount) {
    // Validate input parameters
    if (pduCount == 0 || pduArray == NULL) {
        printf("Error: Invalid input parameters for NDI PDU array initialization\n");
        return;
    }

    // Allocate memory for the NDI PDUs
    pduArray->pduArray = (ndiPdu_t *)malloc(sizeof(ndiPdu_t) * pduCount);
    if (pduArray->pduArray == NULL) {
        printf("Error: Failed to allocate memory for NDI PDU array\n");
        return;
    }

    // Initialize the NDI PDUs with default values
    for (size_t i = 0; i < pduCount; i++) {
        pduArray->pduArray[i].ueContextId = 0;
        pduArray->pduArray[i].mimoAntennaCount = 1;
        pduArray->pduArray[i].mimoAntennaGains[0] = 1.0f;
    }

    // Set the number of NDI PDUs in the array
    pduArray->pduCount = pduCount;
}

// Function to add a new NDI PDU to the dynamic array
void addNdiPdu(ndiPduArray_t *pduArray, uint32_t ueContextId, int8_t mimoAntennaCount, float *mimoAntennaGains) {
    // Validate input parameters
    if (pduArray == NULL || ueContextId == 0 || mimoAntennaCount < 1 || mimoAntennaGains == NULL) {
        printf("Error: Invalid input parameters for adding NDI PDU\n");
        return;
    }

    // Check if the array is full
    if (pduArray->pduCount >= pduArray->size) {
        printf("Error: NDI PDU array is full, cannot add new PDU\n");
        return;
    }

    // Add the new NDI PDU to the array
    pduArray->pduArray[pduArray->pduCount].ueContextId = ueContextId;
    pduArray->pduArray[pduArray->pduCount].mimoAntennaCount = mimoAntennaCount;
    for (int8_t i = 0; i < mimoAntennaCount; i++) {
        pduArray->pduArray[pduArray->pduCount].mimoAntennaGains[i] = mimoAntennaGains[i];
    }

    // Increment the number of NDI PDUs in the array
    pduArray->pduCount++;
}

// Function to remove an existing NDI PDU from the dynamic array
void removeNdiPdu(ndiPduArray_t *pduArray, uint32_t ueContextId) {
    // Validate input parameters
    if (pduArray == NULL || ueContextId == 0) {
        printf("Error: Invalid input parameters for removing NDI PDU\n");
        return;
    }

    // Find the index of the NDI PDU to remove
    size_t pduIndex = findNdiPdu(pduArray, ueContextId);
    if (pduIndex == SIZE_MAX) {
        printf("Error: Could not find NDI PDU with UE Context ID %u\n", ueContextId);
        return;
    }

    // Remove the NDI PDU from the array
    for (size_t i = pduIndex + 1; i < pduArray->pduCount; i++) {
        pduArray->pduArray[i - 1] = pduArray->pduArray[i];
    }
    pduArray->pduCount--;
}

// Function to find an existing NDI PDU in the dynamic array by its UE Context ID
size_t findNdiPdu(ndiPduArray_t *pduArray, uint32_t ueContextId) {
    // Validate input parameters
    if (pduArray == NULL || ueContextId == 0) {
        printf("Error: Invalid input parameters for finding NDI PDU\n");
        return SIZE_MAX;
    }

    // Iterate over the NDI PDUs in the array and find the one with the matching UE Context ID
    for (size_t i = 0; i < pduArray->pduCount; i++) {
        if (pduArray->pduArray[i].ueContextId == ueContextId) {
            return i;
        }
    }

    // Return SIZE_MAX if the NDI PDU was not found in the array
    return SIZE_MAX;
}

// Function to update an existing NDI PDU in the dynamic array with new MIMO antenna parameters
void updateNdiPdu(ndiPduArray_t *pduArray, uint32_t ueContextId, int8_t mimoAntennaCount, float *mimoAntennaGains) {
    // Validate input parameters
    if (pduArray == NULL || ueContextId == 0 || mimoAntennaCount < 1 || mimoAntennaGains == NULL) {
        printf("Error: Invalid input parameters for updating NDI PDU\n");
        return;
    }

    // Find the index of the NDI PDU to update
    size_t pduIndex = findNdiPdu(pduArray, ueContextId);
    if (pduIndex == SIZE_MAX) {
        printf("Error: Could not find NDI PDU with UE Context ID %u\n", ueContextId);
        return;
    }

    // Update the MIMO antenna parameters of the NDI PDU
    pduArray->pduArray[pduIndex].mimoAntennaCount = mimoAntennaCount;
    for (int8_t i = 0; i < mimoAntennaCount; i++) {
        pduArray->pduArray[pduIndex].mimoAntennaGains[i] = mimoAntennaGains[i];
    }
}

// Function to print the contents of a dynamic array of NDI PDUs
void printNdiPduArray(ndiPduArray_t *pduArray) {
    // Validate input parameters
    if (pduArray == NULL || pduArray->pduCount == 0) {
        printf("Error: Invalid input parameters for printing NDI PDU array\n");
        return;
    }

    // Print the contents of the NDI PDUs in the array
    for (size_t i = 0; i < pduArray->pduCount; i++) {
        printf("NDI PDU %zu: UE Context ID = %u, MIMO Antenna Count = %d\n", i, pduArray->pduArray[i].ueContextId, pduArray->pduArray[i].mimoAntennaCount);
        for (int8_t j = 0; j < pduArray->pduArray[i].mimoAntennaCount; j++) {
            printf("    MIMO Antenna %d: Gain = %.2f\n", j, pduArray->pduArray[i].mimoAntennaGains[j]);
        }
    }
}
```
