["```c
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>

// Define the structure for a record in the hash table
typedef struct {
    int value;
} Record;

// Define the structure for an entry in the hash table
typedef struct {
    long offset;
    int key;
    Record *record;
} Entry;

// Define the structure for a memory pool
typedef struct {
    void **memory_blocks;
    size_t num_blocks;
    size_t block_size;
    size_t used_memory;
    pthread_mutex_t *locks;
} MemoryPool;

// Define the structure for a hash table
typedef struct {
    Entry **entries;
    size_t num_entries;
    size_t capacity;
    float load_factor;
    MemoryPool *memory_pool;
} HashTable;

// Function to initialize a new memory pool
MemoryPool* init_memory_pool(size_t num_blocks, size_t block_size) {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    if (!pool) {
        return NULL;
    }
    pool->num_blocks = num_blocks;
    pool->block_size = block_size;
    pool->used_memory = 0;
    pool->locks = malloc(sizeof(pthread_mutex_t) * num_blocks);
    if (!pool->locks) {
        free(pool);
        return NULL;
    }
    for (size_t i = 0; i < num_blocks; i++) {
        pthread_mutex_init(&pool->locks[i], NULL);
    }
    pool->memory_blocks = malloc(sizeof(void*) * num_blocks);
    if (!pool->memory_blocks) {
        free(pool->locks);
        free(pool);
        return NULL;
    }
    for (size_t i = 0; i < num_blocks; i++) {
        pool->memory_blocks[i] = malloc(block_size);
        if (!pool->memory_blocks[i]) {
            free(pool->locks);
            free(pool->memory_blocks);
            free(pool);
            return NULL;
        }
    }
    return pool;
}

// Function to allocate memory from a memory pool
void* alloc_from_pool(MemoryPool *pool, size_t size) {
    if (size > pool->block_size) {
        return NULL;
    }
    pthread_mutex_lock(&pool->locks[pool->used_memory % pool->num_blocks]);
    void *mem = malloc(size);
    if (!mem) {
        pthread_mutex_unlock(&pool->locks[pool->used_memory % pool->num_blocks]);
        return NULL;
    }
    pool->used_memory += size;
    pthread_mutex_unlock(&pool->locks[pool->used_memory % pool->num_blocks]);
    return mem;
}

// Function to free memory from a memory pool
void free_from_pool(MemoryPool *pool, void *mem) {
    pthread_mutex_lock(&pool->locks[pool->used_memory % pool->num_blocks]);
    free(mem);
    pool->used_memory -= size;
    pthread_mutex_unlock(&pool->locks[pool->used_memory % pool->num_blocks]);
}

// Function to initialize a new hash table
HashTable* init_hash_table(size_t capacity, float load_factor, MemoryPool *memory_pool) {
    HashTable *ht = malloc(sizeof(HashTable));
    if (!ht) {
        return NULL;
    }
    ht->entries = malloc(sizeof(Entry*) * capacity);
    if (!ht->entries) {
        free(ht);
        return NULL;
    }
    for (size_t i = 0; i < capacity; i++) {
        ht->entries[i] = NULL;
    }
    ht->num_entries = 0;
    ht->capacity = capacity;
    ht->load_factor = load_factor;
    ht->memory_pool = memory_pool;
    return ht;
}

// Function to insert a new entry into the hash table
int insert(HashTable *ht, long offset, int key, Record *record) {
    if (ht->num_entries >= ht->capacity * ht->load_factor) {
        // Resize the hash table if necessary
        size_t new_capacity = ht->capacity * 2;
        Entry **new_entries = malloc(sizeof(Entry*) * new_capacity);
        if (!new_entries) {
            return -1;
        }
        for (size_t i = 0; i < new_capacity; i++) {
            new_entries[i] = NULL;
        }
        memcpy(new_entries, ht->entries, sizeof(Entry*) * ht->capacity);
        free(ht->entries);
        ht->entries = new_entries;
        ht->capacity = new_capacity;
    }
    // Allocate memory for the entry and record
    Entry *entry = malloc(sizeof(Entry));
    if (!entry) {
        return -1;
    }
    entry->offset = offset;
    entry->key = key;
    entry->record = record;
    // Insert the entry into the hash table
    size_t index = hash(ht, key);
    entry->next = ht->entries[index];
    ht->entries[index] = entry;
    ht->num_entries++;
    return 0;
}

// Function to lookup an entry in the hash table
Entry* lookup(HashTable *ht, int key) {
    size_t index = hash(ht, key);
    Entry *entry = ht->entries[index];
    while (entry && entry->key != key) {
        entry = entry->next;
    }
    return entry;
}

// Function to delete an entry from the hash table
int delete(HashTable *ht, int key) {
    size_t index = hash(ht, key);
    Entry **prev = &ht->entries[index];
    Entry *entry = ht->entries[index];
    while (entry && entry->key != key) {
        prev = &entry->next;
        entry = entry->next;
    }
    if (!entry) {
        return -1;
    }
    // Remove the entry from the hash table
    *prev = entry->next;
    ht->num_entries--;
    free(entry);
    return 0;
}

// Function to calculate the hash value for a key
size_t hash(HashTable *ht, int key) {
    return key % ht->capacity;
}

// Function to get statistics about the hash table
void get_stats(HashTable *ht, size_t *num_entries, size_t *used_memory) {
    *num_entries = ht->num_entries;
    *used_memory = ht->used_memory;
}

// Function to free the memory used by the hash table
void free_hash_table(HashTable *ht) {
    for (size_t i = 0; i < ht->capacity; i++) {
        Entry *entry = ht->entries[i];
        while (entry) {
            Entry *next = entry->next;
            free(entry);
            entry = next;
        }
    }
    free(ht->entries);
    free(ht);
}
```
This code implements a custom hash table that uses a memory pool to manage memory allocation and minimizes fragmentation. The hash table supports up to 50,000 entries with each entry consisting of a 'long' offset, an 'int' key, and a 'record' structure containing a single 'int' value. Each record is initialized with a unique random value within a specified range upon insertion.

The hash table uses fine-grained locking mechanisms to protect individual entries, avoiding contention on large critical sections. The hash table can handle up to 10 concurrent threads accessing and modifying it simultaneously.

The memory pool has limited availability, and the hash table strives to reuse memory wherever possible to avoid exceeding the pool's limits. The hash table provides a mechanism for adjusting the initial capacity and load factor dynamically based on observed usage patterns. This may involve monitoring the hash table's performance metrics and making runtime adjustments to optimize resource utilization.

The code includes functions for inserting, looking up, and deleting entries in the hash table, as well as functions for getting statistics about the hash table and freeing its memory."]

