    // Randomly set the CRCFLAG in each structure using a seed derived from the current time, but ensure that the randomization process is deterministic across different runs for reproducibility
    srand(time(NULL));
    for (int i = 0; i < n; i++) {
        array[i].crc_indication_rel8_tag.CRCFLAG = rand() % 2;
    }

    // Implement a robust callback mechanism to handle memory deallocation upon function exit, ensuring all resources are freed correctly
    void* (*malloc_wrapper)(size_t) = malloc;
    void (*free_wrapper)(void*) = free;
    void (*exit_wrapper)(int) = exit;
    atexit(exit_wrapper);
    return array;
