// Define the custom UUID function to generate unique RX_UE_INFORMATION_TAG values
RX_UE_INFORMATION_TAG generate_uuid() {
    // Generate a random number between 0 and 2^32-1
    unsigned int rand_num = rand();

    // Convert the random number to a string of hexadecimal digits
    char* hex_str = (char*)malloc(sizeof(char) * 8);
    sprintf(hex_str, "%08x", rand_num);

    // Create a new RX_UE_INFORMATION_TAG structure with the generated UUID
    RX_UE_INFORMATION_TAG uuid;
    memcpy(&uuid.uuid, hex_str, 8);

    // Free the memory allocated for the hexadecimal string
    free(hex_str);

    return uuid;
}

// Define the function to get an available RNTI identifier from a provided list of identifiers
RNTI get_available_rnti(int* rnti_list, int size) {
    // Generate a random number between 0 and the size of the RNTI list
    unsigned int rand_num = rand() % size;

    // Check if the randomly generated RNTI is already in use
    while (rnti_list[rand_num] != -1) {
        rand_num = rand() % size;
    }

    return rnti_list[rand_num];
}
