}

// Add a new PDU to the list, growing the list if necessary
void add_pdu(pdu_list_t* list, int ue_context_id, float mimo_params[4], long timestamp, char status) {
    // Check if the list needs to be grown
    if (list->size == list->capacity) {
        list->capacity *= 2;
        list->pdu_list = (pdu_t*)realloc(list->pdu_list, sizeof(pdu_t) * list->capacity);
    }

    // Add the new PDU to the list
    list->pdu_list[list->size].ue_context_id = ue_context_id;
    memcpy(list->pdu_list[list->size].mimo_params, mimo_params, sizeof(float) * 4);
    list->pdu_list[list->size].timestamp = timestamp;
    list->pdu_list[list->size].status = status;
    list->size++;
}

// Remove a PDU from the list by index
void remove_pdu(pdu_list_t* list, int index) {
    // Check if the index is valid
    assert(index >= 0 && index < list->size);

    // Shift all subsequent PDUs to fill the gap
    for (int i = index + 1; i < list->size; i++) {
        memcpy(&list->pdu_list[i - 1], &list->pdu_list[i], sizeof(pdu_t));
    }

    // Decrement the size of the list
    list->size--;
}

// Update a PDU in the list by index, growing the list if necessary
void update_pdu(pdu_list_t* list, int index, int ue_context_id, float mimo_params[4], long timestamp, char status) {
    // Check if the index is valid
    assert(index >= 0 && index < list->size);

    // Update the PDU fields
    list->pdu_list[index].ue_context_id = ue_context_id;
    memcpy(list->pdu_list[index].mimo_params, mimo_params, sizeof(float) * 4);
    list->pdu_list[index].timestamp = timestamp;
    list->pdu_list[index].status = status;
}

// Filter the PDUs in the list based on a given criteria
void filter_pdus(pdu_list_t* list, int (*filter)(const pdu_t*)) {
    // Create a new list to hold the filtered PDUs
    pdu_list_t filtered;
    init_pdu_list(&filtered, list->size);

    // Iterate over the PDUs in the original list and filter them based on the given criteria
    for (int i = 0; i < list->size; i++) {
        if (filter(&list->pdu_list[i])) {
            add_pdu(&filtered, list->pdu_list[i].ue_context_id, list->pdu_list[i].mimo_params, list->pdu_list[i].timestamp, list->pdu_list[i].status);
        }
    }

    // Replace the original list with the filtered one
    free(list->pdu_list);
    *list = filtered;
}

// Free the memory used by the PDU list
void free_pdu_list(pdu_list_t* list) {
    free(list->pdu_list);
}
```
This code defines a `pdu_t` structure to hold the data for each PDU, and a `pdu_list_t` structure to hold a list of PDUs. The `init_pdu_list()` function initializes a new list with a given capacity, the `add_pdu()` function adds a new PDU to the list, the `remove_pdu()` function removes a PDU from the list by index, and the `update_pdu()` function updates a PDU in the list by index. The `filter_pdus()` function filters the PDUs in the list based on a given criteria, and the `free_pdu_list()` function frees the memory used by the list.

The code also includes some error handling and validation to ensure that invalid configurations are not allowed and informative error messages are provided when necessary. For example, the `add_pdu()` function checks if the list needs to be grown before adding a new PDU, and the `update_pdu()` function checks if the index is valid before updating a PDU.

