// Define the structure for each record in the list
typedef struct {
    long offset;
    int key;
    int value;
} Record;

// Define a dynamic array to store the records
struct DynamicArray {
    size_t capacity; // maximum number of elements in the array
    size_t count; // current number of elements in the array
    Record* data; // pointer to the array of records
};

// Initialize the dynamic array with a specified capacity and random values within a range
void initDynamicArray(struct DynamicArray* arr, size_t capacity, int minValue, int maxValue) {
    arr->capacity = capacity;
    arr->count = 0;
    arr->data = (Record*)malloc(sizeof(Record) * capacity);
    for (size_t i = 0; i < capacity; i++) {
        arr->data[i].offset = rand() % (maxValue - minValue + 1) + minValue;
        arr->data[i].key = rand() % (maxValue - minValue + 1) + minValue;
        arr->data[i].value = rand() % (maxValue - minValue + 1) + minValue;
    }
}

// Add a new record to the dynamic array with a specified key and value
void addRecord(struct DynamicArray* arr, int key, int value) {
    if (arr->count == arr->capacity) {
        // resize the array if it is full
        arr->capacity *= 2;
        arr->data = (Record*)realloc(arr->data, sizeof(Record) * arr->capacity);
    }
    arr->data[arr->count].offset = rand() % (maxValue - minValue + 1) + minValue;
    arr->data[arr->count].key = key;
    arr->data[arr->count].value = value;
    arr->count++;
}

// Remove a record from the dynamic array with a specified key
void removeRecord(struct DynamicArray* arr, int key) {
    for (size_t i = 0; i < arr->count; i++) {
        if (arr->data[i].key == key) {
            // move the last element to the current position and reduce the count by one
            arr->data[i] = arr->data[arr->count - 1];
            arr->count--;
            break;
        }
    }
}

// Serialize the dynamic array to a binary file
void serialize(struct DynamicArray* arr, const char* filename) {
    FILE* fp = fopen(filename, "wb");
    if (fp == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return;
    }
    // write the number of records in the array
    size_t count = arr->count;
    fwrite(&count, sizeof(size_t), 1, fp);
    // write each record in the array
    for (size_t i = 0; i < arr->count; i++) {
        Record* rec = &arr->data[i];
        fwrite(rec, sizeof(Record), 1, fp);
    }
    fclose(fp);
}

// Deserialize the dynamic array from a binary file
void deserialize(struct DynamicArray* arr, const char* filename) {
    FILE* fp = fopen(filename, "rb");
    if (fp == NULL) {
        printf("Error: unable to open file %s\n", filename);
        return;
    }
    // read the number of records in the array
    size_t count;
    fread(&count, sizeof(size_t), 1, fp);
    arr->capacity = count;
    arr->data = (Record*)malloc(sizeof(Record) * count);
    for (size_t i = 0; i < count; i++) {
        Record* rec = &arr->data[i];
        fread(rec, sizeof(Record), 1, fp);
    }
    arr->count = count;
    fclose(fp);
}
