// Define the allowed extensions for the new file name
const char *allowed_extensions[] = {"jpg", "png", "pdf"};

// Define the maximum length of the sequence of digits in the new file name
#define MAX_SEQUENCE_LENGTH 8

// Define the directory where the original file is located
const char *original_directory = "/path/to/original/file";

// Define the function to generate a unique file name
void generateDynamicFileName(char *original_filename, char *new_filename) {
    // Get the current Unix timestamp
    time_t timestamp = time(NULL);

    // Generate a random hash for the new file name
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256((unsigned char *)original_filename, strlen(original_filename), hash);

    // Get the directory where the original file is located
    const char *directory = dirname(original_filename);

    // Generate a sequence of digits based on the first 10 characters of the original file name
    int sequence = rand() % (pow(10, MAX_SEQUENCE_LENGTH) - 1) + 1;

    // Get the extension of the original file
    const char *extension = strrchr(original_filename, '.');

    // Check if the extension is valid
    if (!extension || !strcmp(extension, ".") || !strcmp(extension, "..")) {
        printf("Invalid extension for file %s\n", original_filename);
        return;
    }

    // Check if the extension is allowed
    int i;
    for (i = 0; i < sizeof(allowed_extensions) / sizeof(char *); i++) {
        if (!strcmp(extension, allowed_extensions[i])) {
            break;
        }
    }
    if (i == sizeof(allowed_extensions) / sizeof(char *)) {
        printf("Extension %s is not allowed\n", extension);
        return;
    }

    // Generate the new file name
    sprintf(new_filename, "%s/%s.%08x.%lu-%d.%s", directory, basename(original_filename), hash, timestamp, sequence, extension + 1);
}
