void add_NFAPI_CRC_INDICATION_PDU_T_to_array(NFAPI_CRC_INDICATION_PDU_T_array* arr, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&arr->mutex);
    if (arr->size == arr->capacity) {
        // Resize the array if it is full
        int new_capacity = arr->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_elements = (NFAPI_CRC_INDICATION_PDU_T*)realloc(arr->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
        if (new_elements == NULL) {
            // Handle allocation failure
            pthread_mutex_unlock(&arr->mutex);
            return;
        }
        arr->elements = new_elements;
        arr->capacity = new_capacity;
