} STATISTICS;

// Define the function for creating and populating a list of NFAPI_CRC_INDICATION_PDU_T structures
void create_and_populate_list(int N, RNTI_HASH_TABLE *rnti_hash_table, RNTI_CACHE *rnti_cache, STATISTICS *stats) {
    // Initialize the hash table and caching mechanism
    rnti_hash_table->size = 0;
    rnti_hash_table->load_factor = 0.75;
    rnti_hash_table->table = NULL;
    rnti_cache->capacity = N;
    rnti_cache->size = 0;
    rnti_cache->rnti_cache = (uint32_t *)malloc(sizeof(uint32_t) * N);

    // Populate the list of NFAPI_CRC_INDICATION_PDU_T structures
    for (int i = 0; i < N; i++) {
        // Generate a random RNTI value
        uint32_t rnti = rand() % 1000000000 + 1;

        // Check if the RNTI is already in the hash table or cache
        bool found = false;
        for (int j = 0; j < rnti_hash_table->size; j++) {
            if (rnti == rnti_hash_table->table[j]->RNTI) {
                found = true;
                break;
            }
        }
        for (int j = 0; j < rnti_cache->size; j++) {
            if (rnti == rnti_cache->rnti_cache[j]) {
                found = true;
                break;
            }
        }

        // If the RNTI is not already in the hash table or cache, add it to both data structures
        if (!found) {
            NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pdu->RX_UE_INFORMATION_TAG = rand() % 10000 + 1;
            pdu->RNTI = rnti;
            pdu->CRC_INDICATION_REL8_TAG = rand() % 10000 + 1;
            pdu->CRCFLAG = (rand() % 2 == 0) ? true : false;

            // Add the RNTI to the hash table and cache
            rnti_hash_table->size++;
            rnti_cache->size++;
            if (rnti_hash_table->size > rnti_hash_table->load_factor * rnti_hash_table->capacity) {
                // Resize the hash table if necessary
                int new_capacity = rnti_hash_table->capacity * 2;
                NFAPI_CRC_INDICATION_PDU_T **new_table = (NFAPI_CRC_INDICATION_PDU_T **)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T *) * new_capacity);
                memcpy(new_table, rnti_hash_table->table, sizeof(NFAPI_CRC_INDICATION_PDU_T *) * rnti_hash_table->size);
                free(rnti_hash_table->table);
                rnti_hash_table->table = new_table;
            }
            if (rnti_cache->size > rnti_cache->capacity) {
                // Resize the cache if necessary
                int new_capacity = rnti_cache->capacity * 2;
                uint32_t *new_rnti_cache = (uint32_t *)malloc(sizeof(uint32_t) * new_capacity);
                memcpy(new_rnti_cache, rnti_cache->rnti_cache, sizeof(uint32_t) * rnti_cache->size);
                free(rnti_cache->rnti_cache);
                rnti_cache->rnti_cache = new_rnti_cache;
            }
            rnti_hash_table->table[rnti_hash_table->size - 1] = pdu;
            rnti_cache->rnti_cache[rnti_cache->size - 1] = rnti;

            // Increment the statistics
            stats->num_successful_additions++;
        } else {
            // If the RNTI is already in the hash table or cache, increment the statistics
            stats->num_failed_additions++;
        }
    }
}

// Define the function for looking up an RNTI value in the list of NFAPI_CRC_INDICATION_PDU_T structures
void lookup_rnti(uint32_t rnti, RNTI_HASH_TABLE *rnti_hash_table, RNTI_CACHE *rnti_cache, STATISTICS *stats) {
    // Check if the RNTI is in the cache first
