    for (int i = 0; i < rnti_cache->size; i++) {
        if (rnti == rnti_cache->rnti_cache[i]) {
            found = true;
            break;
        }
    }

    // If the RNTI is not in the cache, check if it's in the hash table
    if (!found) {
        for (int i = 0; i < rnti_hash_table->size; i++) {
            if (rnti == rnti_hash_table->table[i]->RNTI) {
                found = true;
                break;
            }
        }
    }

