} NFAPI_CRC_INDICATION_PDU_T;

// Define the data structure to store RNTIs
typedef struct {
    pthread_mutex_t mutex;
    uint32_t *RNTIs;
    size_t count;
} RNTI_SET;

// Function to dynamically generate and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* generate_crc_indication_pdu(size_t num_elements) {
    // Allocate memory for the list of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T *list = malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list == NULL) {
        printf("Error: Failed to allocate memory for the list of NFAPI_CRC_INDICATION_PDU_T structures\n");
        return NULL;
    }

    // Initialize the RNTI set data structure
    RNTI_SET *rnti_set = malloc(sizeof(RNTI_SET));
    if (rnti_set == NULL) {
        printf("Error: Failed to allocate memory for the RNTI set data structure\n");
        free(list);
        return NULL;
    }
    rnti_set->mutex = PTHREAD_MUTEX_INITIALIZER;
    rnti_set->RNTIs = malloc(num_elements * sizeof(uint32_t));
    if (rnti_set->RNTIs == NULL) {
        printf("Error: Failed to allocate memory for the RNTI set\n");
        free(list);
        free(rnti_set);
        return NULL;
    }
    rnti_set->count = 0;

    // Populate the list of NFAPI_CRC_INDICATION_PDU_T structures with random RNTIs and CRCFLAG values
    for (size_t i = 0; i < num_elements; i++) {
        // Generate a random RNTI value
        uint32_t rnti = rand() % 1000000000 + 1;

        // Check if the RNTI is already in the set
        bool found = false;
        pthread_mutex_lock(&rnti_set->mutex);
        for (size_t j = 0; j < rnti_set->count; j++) {
            if (rnti == rnti_set->RNTIs[j]) {
                found = true;
                break;
            }
        }
        pthread_mutex_unlock(&rnti_set->mutex);

        // If the RNTI is not in the set, add it and set the CRCFLAG value
        if (!found) {
            list[i].RX_UE_INFORMATION_TAG = 0x1;
            list[i].RNTI = rnti;
            list[i].CRC_INDICATION_REL8_TAG = 0x2;
            list[i].CRCFLAG = rand() % 2 == 0 ? true : false;

            // Add the RNTI to the set
            pthread_mutex_lock(&rnti_set->mutex);
            rnti_set->RNTIs[rnti_set->count++] = rnti;
            pthread_mutex_unlock(&rnti_set->mutex);
        } else {
            // If the RNTI is already in the set, generate a new random value and try again
            i--;
