    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    size_t capacity;
} NFAPI_CRC_INDICATION_LIST_T;

// Define a function for dynamically creating and populating the list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_LIST_T *create_crc_indication_list(NFAPI_CRC_INDICATION_CONFIG_T config) {
    // Allocate memory for the list and initialize its size and capacity to 0
    NFAPI_CRC_INDICATION_LIST_T *list = malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    list->size = 0;
    list->capacity = 0;

    // Set the range and maximum size limits from the configuration module
    int rnti_range_min = config.rnti_range_min;
    int rnti_range_max = config.rnti_range_max;
    int max_size = config.max_size;

    // Loop until the maximum size is reached or all RNTIs have been used
    while (list->size < max_size && rnti_range_min <= rnti_range_max) {
        // Generate a random RNTI within the specified range
        int rnti = rand() % (rnti_range_max - rnti_range_min + 1) + rnti_range_min;

        // Create a new NFAPI_CRC_INDICATION_PDU_T structure with the random RNTI and a randomly set CRCFLAG
        NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        pdu->rx_ue_information.rnti = rnti;
        pdu->crc_indication_rel8.CRCFLAG = rand() % 2;

        // Add the new structure to the list, checking for duplicates and exceeding the maximum size
        if (list->size == 0 || list->data[list->size - 1].rx_ue_information.rnti != rnti) {
            list->data = realloc(list->data, (list->size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            list->data[list->size++] = *pdu;
        } else {
            free(pdu);
        }
    }

    // Return the populated list of NFAPI_CRC_INDICATION_PDU_T structures
    return list;
}

// Define a function for inserting a new structure into the list, handling concurrent access from multiple threads
void insert_crc_indication(NFAPI_CRC_INDICATION_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Acquire a lock on the list to prevent concurrent modifications
    pthread_mutex_lock(&list->mutex);

    // Check if the list is full and needs to be resized
    if (list->size == list->capacity) {
        // Double the capacity of the list to accommodate new elements
        list->capacity *= 2;
        list->data = realloc(list->data, list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    // Add the new structure to the end of the list
    list->data[list->size++] = *pdu;

    // Release the lock on the list
    pthread_mutex_unlock(&list->mutex);
}

// Define a function for deleting a structure from the list, handling concurrent access from multiple threads
void delete_crc_indication(NFAPI_CRC_INDICATION_LIST_T *list, int index) {
    // Acquire a lock on the list to prevent concurrent modifications
    pthread_mutex_lock(&list->mutex);

    // Check if the index is valid and the list is not empty
    if (index >= 0 && index < list->size) {
        // Remove the structure at the specified index from the list
        NFAPI_CRC_INDICATION_PDU_T *pdu = &list->data[index];
        memmove(list->data + index, list->data + index + 1, (list->size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        list->size--;

        // Free the memory allocated for the structure
        free(pdu);
    }

    // Release the lock on the list
    pthread_mutex_unlock(&list->mutex);
