void init_worker_threads(int num_workers, int initial_num_threads) {
    // Initialize the array of worker data structures
    worker_data_t *workers = (worker_data_t *)malloc(sizeof(worker_data_t) * num_workers);
    if (!workers) {
        printf("Error: Failed to allocate memory for worker data structures\n");
        return;
    }

    // Initialize the number of active threads
    int num_active_threads = initial_num_threads;

    // Loop through each worker thread and initialize it
    for (int i = 0; i < num_workers; i++) {
        workers[i].running = true;
        workers[i].stats = NULL;
        pthread_create(&workers[i].thread, NULL, worker_thread, &workers[i]);
    }

    // Loop until all threads are running and the workload is evenly distributed
    while (num_active_threads < num_workers) {
        // Check if any thread has finished its work
        for (int i = 0; i < num_workers; i++) {
            if (!workers[i].running) {
                num_active_threads--;
                break;
            }
        }

        // If the workload is not evenly distributed, adjust the number of active threads
        if (num_active_threads < num_workers) {
            int new_num_active_threads = num_active_threads + 1;
            for (int i = 0; i < new_num_active_threads; i++) {
                workers[i].running = true;
