    uint16_t ue_id;
    rrc_state_t rrc_state;
    struct sib_tag* sibs[MAX_NUM_OF_SIBS];
} lte_rrc_uecontext;

// Function to initialize an UE context
lte_rrc_uecontext* init_ue_context(uint16_t ue_id, rrc_state_t rrc_state) {
    // Allocate memory for the UE context structure
    lte_rrc_uecontext* ue_context = malloc(sizeof(lte_rrc_uecontext));
    if (ue_context == NULL) {
        return NULL;
    }

    // Initialize the UE ID and RRC state
    ue_context->ue_id = ue_id;
    ue_context->rrc_state = rrc_state;

    // Initialize the SIB list
    for (int i = 0; i < MAX_NUM_OF_SIBS; i++) {
        sib_tag* sib = malloc(sizeof(sib_tag));
        if (sib == NULL) {
            free(ue_context);
            return NULL;
        }
        sib->timestamp = 0;
        sib->integrity_check_value = 0;
        sib->prev = NULL;
        sib->next = NULL;
        ue_context->sibs[i] = sib;
    }

    return ue_context;
}

// Function to update the RRC state of an UE context
void update_rrc_state(lte_rrc_uecontext* ue_context, rrc_state_t new_state) {
    // Update the RRC state
    ue_context->rrc_state = new_state;
}

// Function to retrieve the SIB list for a given UE context
sib_tag* get_sib_list(lte_rrc_uecontext* ue_context) {
    return ue_context->sibs[0];
}
