    uint8_t crc_indication_rel8_tag;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu(char* input_string, int size_limit) {
    // Initialize the list of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * size_limit);
    if (pdu_list == NULL) {
        return NULL;
    }

    // Initialize the counter for the number of elements in the list
    int num_elements = 0;

    // Iterate over each character in the input string
    for (int i = 0; i < strlen(input_string); i++) {
        // Check if the current character is a valid RX_UE_INFORMATION_TAG
        if (input_string[i] == 'R') {
            // Generate a random RNTI value
            uint32_t rnti = rand() % 1000;

            // Check if the RNTI value is unique and not already in use
            bool unique = true;
            for (int j = 0; j < num_elements; j++) {
                if (pdu_list[j].rnti == rnti) {
                    unique = false;
                    break;
                }
            }

            // If the RNTI value is unique, add it to the list of NFAPI_CRC_INDICATION_PDU_T structures
            if (unique) {
                pdu_list[num_elements].rx_ue_information_tag = 'R';
                pdu_list[num_elements].rnti = rnti;
                pdu_list[num_elements].crc_indication_rel8_tag = rand() % 256;
                pdu_list[num_elements].crcflag = (rand() % 2) == 0;
                num_elements++;
            }
        }
    }

    // Return the list of NFAPI_CRC_INDICATION_PDU_T structures
    return pdu_list;
}
