NFAPI_CRC_INDICATION_PDU_T* allocate_crc_indication_pdu(int n) {
    // Validate that all RNTI values are unique within the list before population
    if (n <= 0 || n > MAX_RNTI_VALUE) {
        printf("Invalid input size: %d\n", n);
        return NULL;
    }

    // Allocate memory for the list of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    // Initialize the RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG for each structure
    for (int i = 0; i < n; i++) {
        pdu_list[i].rx_ue_information_tag = RX_UE_INFORMATION_TAG_INIT;
        pdu_list[i].rnti = generate_random_rnti();
        pdu_list[i].crc_indication_rel8_tag = CRC_INDICATION_REL8_TAG_INIT;
    }

    // Set the CRCFLAG for each structure to a randomly set value
    for (int i = 0; i < n; i++) {
        pdu_list[i].crc_indication_rel8_tag.crcflag = generate_random_crcflag();
    }

    // Return the list of NFAPI_CRC_INDICATION_PDU_T structures
    return pdu_list;
}

// Define the function to free memory for a list of NFAPI_CRC_INDICATION_PDU_T structures
void free_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu_list) {
    // Validate that the input is not NULL
    if (!pdu_list) {
        printf("Invalid input: NULL\n");
        return;
    }

    // Free the memory for the list of NFAPI_CRC_INDICATION_PDU_T structures
    free(pdu_list);
}

// Define the function to generate a random RNTI value
RNTI generate_random_rnti() {
    // Generate a random RNTI value between 0 and MAX_RNTI_VALUE
    return (RNTI)rand() % MAX_RNTI_VALUE;
}

// Define the function to generate a random CRCFLAG value
CRCFLAG generate_random_crcflag() {
    // Generate a random CRCFLAG value between 0 and MAX_CRC_FLAG_VALUE
    return (CRCFLAG)rand() % MAX_CRC_FLAG_VALUE;
}
