// Initialize the array with N elements, each element is a pointer to an NFAPI_CRC_INDICATION_PDU_T structure
void initialize_crc_indication_array(size_t n) {
    // Check if the array has already been initialized
    if (crc_indication_array != NULL) {
        return;
    }

    // Allocate memory for the array
    crc_indication_array = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (crc_indication_array == NULL) {
        fprintf(stderr, "Failed to allocate memory for CRC indication array\n");
        return;
    }

    // Initialize each element in the array with a valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
    for (size_t i = 0; i < n; ++i) {
        crc_indication_array[i].RX_UE_INFORMATION_TAG = i + 1;
        crc_indication_array[i].RNTI = rand();
        crc_indication_array[i].CRC_INDICATION_REL8_TAG = rand() % 256;
    }

    // Set the size of the array to N
    crc_indication_array_size = n;
