// Add a new element to the end of the array, initializing it with a valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
void add_crc_indication(NFAPI_CRC_INDICATION_PDU_T *new_element) {
    // Check if the array has already been initialized
    if (crc_indication_array == NULL) {
        fprintf(stderr, "Cannot add element to uninitialized CRC indication array\n");
        return;
    }

    // Lock the mutex to prevent race conditions during array manipulation
    pthread_mutex_lock(&crc_indication_array_lock);

    // Allocate memory for the new element
    NFAPI_CRC_INDICATION_PDU_T *new_element = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_element == NULL) {
        fprintf(stderr, "Failed to allocate memory for new CRC indication element\n");
        pthread_mutex_unlock(&crc_indication_array_lock);
