    }

    // Initialize the new element with a valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
    new_element->RX_UE_INFORMATION_TAG = crc_indication_array_size + 1;
    new_element->RNTI = rand();
    new_element->CRC_INDICATION_REL8_TAG = rand() % 256;

    // Add the new element to the end of the array
    crc_indication_array[crc_indication_array_size++] = new_element;

    // Unlock the mutex
    pthread_mutex_unlock(&crc_indication_array_lock);
}

// Remove an element from the array, freeing its memory
void remove_crc_indication(size_t index) {
    // Check if the array has already been initialized
    if (crc_indication_array == NULL) {
        fprintf(stderr, "Cannot remove element from uninitialized CRC indication array\n");
        return;
    }

    // Lock the mutex to prevent race conditions during array manipulation
    pthread_mutex_lock(&crc_indication_array_lock);

    // Free the memory of the element being removed
    free(crc_indication_array[index]);

    // Shift all elements after the removed element to fill the gap
