#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <stdbool.h>
#include <pthread.h>

// Define the structure for LTE UE Context Information
typedef struct {
    int ue_id;
    int serving_cell_id;
    struct rrc_message *rrc_messages;
} lte_ue_context_info;

// Define the linked list node for RRC messages
typedef struct rrc_message_node {
    struct rrc_message *rrc_message;
    struct rrc_message_node *next;
} rrc_message_node;

// Define the function to manage the dynamic list of LTE UE Context Information structures
void manage_lte_ue_context(lte_ue_context_info **list, int ue_id, int serving_cell_id, struct rrc_message *rrc_messages) {
    // Check if the UE ID and serving cell ID fall within predefined valid ranges
    if (ue_id < 0 || ue_id > 65535 || serving_cell_id < 0 || serving_cell_id > 255) {
        printf("Invalid UE ID or serving cell ID\n");
        return;
    }

    // Check if the RRC messages are correctly initialized
    if (rrc_messages == NULL) {
        printf("RRC messages not initialized\n");
        return;
    }

    // Create a new node for the RRC message
    rrc_message_node *new_node = malloc(sizeof(rrc_message_node));
    new_node->rrc_message = rrc_messages;
    new_node->next = NULL;

    // Lock the list to prevent race conditions
    pthread_mutex_lock(&list_mutex);

    // Check if the UE ID already exists in the list
    bool ue_id_exists = false;
    for (lte_ue_context_info *current = *list; current != NULL; current = current->next) {
        if (current->ue_id == ue_id) {
            ue_id_exists = true;
            break;
        }
    }

    // If the UE ID already exists, update the serving cell ID and RRC messages
    if (ue_id_exists) {
        for (lte_ue_context_info *current = *list; current != NULL; current = current->next) {
            if (current->ue_id == ue_id) {
                current->serving_cell_id = serving_cell_id;
                current->rrc_messages = new_node;
                break;
            }
        }
    } else { // If the UE ID does not exist, create a new node for it
        lte_ue_context_info *new_ue = malloc(sizeof(lte_ue_context_info));
        new_ue->ue_id = ue_id;
        new_ue->serving_cell_id = serving_cell_id;
        new_ue->rrc_messages = new_node;
        new_node->next = *list;
        *list = new_ue;
    }

    // Unlock the list to allow other threads to access it
    pthread_mutex_unlock(&list_mutex);
}

// Define the function to serialize the dynamic list of LTE UE Context Information structures
void serialize_lte_ue_context(lte_ue_context_info *list) {
    // Check if the list is empty
    if (list == NULL) {
        return;
    }

    // Lock the list to prevent race conditions
    pthread_mutex_lock(&list_mutex);

    // Create a new node for the serialized data
    lte_ue_context_info *serialized = malloc(sizeof(lte_ue_context_info));
    serialized->ue_id = list->ue_id;
    serialized->serving_cell_id = list->serving_cell_id;
    serialized->rrc_messages = list->rrc_messages;

    // Serialize the RRC messages in the linked list
    rrc_message_node *current = list->rrc_messages;
    while (current != NULL) {
        current->rrc_message->serialize();
        current = current->next;
    }

    // Unlock the list to allow other threads to access it
    pthread_mutex_unlock(&list_mutex);
}

// Define the function to deserialize the dynamic list of LTE UE Context Information structures
void deserialize_lte_ue_context(lte_ue_context_info *serialized) {
    // Check if the serialized data is empty
    if (serialized == NULL) {
        return;
    }

    // Lock the list to prevent race conditions
    pthread_mutex_lock(&list_mutex);

    // Create a new node for the deserialized data
    lte_ue_context_info *deserialized = malloc(sizeof(lte_ue_context_info));
    deserialized->ue_id = serialized->ue_id;
    deserialized->serving_cell_id = serialized->serving_cell_id;
    deserialized->rrc_messages = serialized->rrc_messages;

    // Deserialize the RRC messages in the linked list
    rrc_message_node *current = deserialized->rrc_messages;
    while (current != NULL) {
        current->rrc_message->deserialize();
        current = current->next;
    }

    // Unlock the list to allow other threads to access it
    pthread_mutex_unlock(&list_mutex);
}
