    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the list structure for managing the NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *entries;
    size_t num_entries;
} NFAPI_CRC_INDICATION_LIST_T;

// Define the error codes for the list operations
#define LIST_SUCCESS 0
#define LIST_DUPLICATE_RNTI -1
#define LIST_INVALID_RNTI -2
#define LIST_MEMORY_ERROR -3

// Initialize and allocate memory for the list
void nfapi_crc_indication_list_init(NFAPI_CRC_INDICATION_LIST_T *list) {
    list->entries = NULL;
    list->num_entries = 0;
}

// Add a new entry to the list, ensuring that each RNTI is unique within the list
int nfapi_crc_indication_list_add(NFAPI_CRC_INDICATION_LIST_T *list, uint32_t rnti) {
    // Check if the RNTI is already in the list
    for (size_t i = 0; i < list->num_entries; i++) {
        if (list->entries[i].RNTI == rnti) {
            return LIST_DUPLICATE_RNTI;
        }
    }

    // Allocate memory for the new entry
    NFAPI_CRC_INDICATION_PDU_T *new_entry = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_entry == NULL) {
        return LIST_MEMORY_ERROR;
    }

    // Initialize the new entry with the given RNTI and a randomly set CRCFLAG
    new_entry->RX_UE_INFORMATION_TAG = 0;
    new_entry->RNTI = rnti;
    new_entry->CRCFLAG = rand() % 256;

    // Add the new entry to the list
    list->entries = realloc(list->entries, (list->num_entries + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list->entries == NULL) {
        free(new_entry);
        return LIST_MEMORY_ERROR;
    }
    list->entries[list->num_entries++] = *new_entry;

    return LIST_SUCCESS;
}

// Remove an entry from the list based on a specified RNTI, maintaining the integrity of the list
int nfapi_crc_indication_list_remove(NFAPI_CRC_INDICATION_LIST_T *list, uint32_t rnti) {
    // Find the entry with the given RNTI in the list
    for (size_t i = 0; i < list->num_entries; i++) {
        if (list->entries[i].RNTI == rnti) {
            // Remove the entry from the list by shifting all subsequent entries one position to the left
            for (size_t j = i; j < list->num_entries - 1; j++) {
                list->entries[j] = list->entries[j + 1];
            }
            list->num_entries--;
            return LIST_SUCCESS;
        }
    }

    // If the RNTI is not found in the list, return an error code
    return LIST_INVALID_RNTI;
}

// Update the CRCFLAG of an entry given its RNTI. Consider the impact on performance and cache locality when implementing this operation.
int nfapi_crc_indication_list_update(NFAPI_CRC_INDICATION_LIST_T *list, uint32_t rnti) {
    // Find the entry with the given RNTI in the list
    for (size_t i = 0; i < list->num_entries; i++) {
        if (list->entries[i].RNTI == rnti) {
            // Update the CRCFLAG of the entry
            list->entries[i].CRCFLAG = rand() % 256;
            return LIST_SUCCESS;
        }
    }

    // If the RNTI is not found in the list, return an error code
    return LIST_INVALID_RNTI;
}

// Retrieve the total number of entries in the list. Ensure that this operation is fast even under heavy load.
size_t nfapi_crc_indication_list_get_num_entries(NFAPI_CRC_INDICATION_LIST_T *list) {
    return list->num_entries;
}

// Return an error code if a duplicate RNTI is encountered during addition or if an invalid RNTI is provided for removal or update. Design the error handling to minimize performance impact during normal operations.
int nfapi_crc_indication_list_check_duplicate(NFAPI_CRC_INDICATION_LIST_T *list, uint32_t rnti) {
    // Check if the RNTI is already in the list
    for (size_t i = 0; i < list->num_entries; i++) {
        if (list->entries[i].RNTI == rnti) {
            return LIST_DUPLICATE_RNTI;
        }
    }

    // If the RNTI is not found in the list, return success
    return LIST_SUCCESS;
