#include <stdlib.h>
#include <stdio.h>
#include <time.h>

// Define a structure for a record
typedef struct {
    int value;
} Record;

// Define a function to dynamically allocate an array of records
Record* allocate_records(int num_records, int range) {
    // Validate the input parameters
    if (num_records <= 0 || range <= 0) {
        fprintf(stderr, "Invalid input parameters\n");
        return NULL;
    }

    // Allocate memory for the array of records
    Record* records = malloc(sizeof(Record) * num_records);
    if (records == NULL) {
        fprintf(stderr, "Failed to allocate memory\n");
        return NULL;
    }

    // Initialize each record with a random value within the specified range
    for (int i = 0; i < num_records; i++) {
        records[i].value = rand() % range + 1;
    }

    return records;
}
