// Define a structure for the CRC indication PDU
typedef struct {
    uint16_t rx_ue_information_tag;
    uint32_t rnti;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a function to create and populate a list of CRC indication PDUs
NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu_list(int num_pdus) {
    // Validate the input parameter
    if (num_pdus <= 0) {
        fprintf(stderr, "Invalid input parameter\n");
        return NULL;
    }

    // Allocate memory for the list of CRC indication PDUs
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_pdus);
    if (pdu_list == NULL) {
        fprintf(stderr, "Failed to allocate memory\n");
        return NULL;
    }

    // Initialize each CRC indication PDU with a valid RX UE information tag and RNTI value
    for (int i = 0; i < num_pdus; i++) {
        pdu_list[i].rx_ue_information_tag = rand() % 10 + 1;
        pdu_list[i].rnti = rand() % 1000000 + 1;
    }

    return pdu_list;
}
