    int id;
    int value;
} Record;

// Define the function to serialize and deserialize data for interoperability with other systems
void serializeAndDeserializeData(Record *records, int N) {
    // Check that N is between 1 and 1000
    if (N < 1 || N > 1000) {
        printf("Error: Invalid input value for N\n");
        return;
    }

    // Allocate memory for the list of records
    Record *records = malloc(N * sizeof(Record));
    if (records == NULL) {
        printf("Error: Failed to allocate memory for the list of records\n");
        return;
    }

    // Populate the list of records with random values within the specified range
    for (int i = 0; i < N; i++) {
        records[i].id = i + 1;
        records[i].value = rand() % (maxValue - minValue) + minValue;
    }

    // Serialize the data to a file
    FILE *file = fopen("data.bin", "wb");
    if (file == NULL) {
        printf("Error: Failed to open file for writing\n");
        return;
    }
    fwrite(records, sizeof(Record), N, file);
    fclose(file);

    // Deserialize the data from a file
    FILE *file = fopen("data.bin", "rb");
    if (file == NULL) {
        printf("Error: Failed to open file for reading\n");
        return;
    }
    Record *records = malloc(N * sizeof(Record));
    if (records == NULL) {
        printf("Error: Failed to allocate memory for the list of records\n");
        return;
    }
    fread(records, sizeof(Record), N, file);
    fclose(file);
}
```
