// Define the structure for holding UE information
typedef struct {
    int ue_id;
    char* imsi;
    char* msisdn;
} NFAPI_UE_INFO_T;

// Define the structure for holding CRC indication PDUs
typedef struct {
    int pdu_type;
    int pdu_length;
    void* pdu_data;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a dynamic array to hold the CRC indication PDUs
typedef struct {
    int size;
    int capacity;
    NFAPI_CRC_INDICATION_PDU_T* pdu_array;
} NFAPI_CRC_INDICATION_PDUS_T;

// Function to initialize and populate the dynamic array of CRC indication PDUs
NFAPI_CRC_INDICATION_PDUS_T* nfapi_crc_indication_pdu_init(int num_pdus) {
    // Allocate memory for the dynamic array
    NFAPI_CRC_INDICATION_PDUS_T* pdu_array = malloc(sizeof(NFAPI_CRC_INDICATION_PDUS_T));
    if (!pdu_array) {
        return NULL;
    }

    // Initialize the size and capacity of the dynamic array
    pdu_array->size = 0;
    pdu_array->capacity = num_pdus;

    // Allocate memory for the PDU data
    pdu_array->pdu_array = malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_array->pdu_array) {
        free(pdu_array);
        return NULL;
    }

    // Initialize the PDU data to default values
    for (int i = 0; i < num_pdus; i++) {
        pdu_array->pdu_array[i].pdu_type = -1;
        pdu_array->pdu_array[i].pdu_length = 0;
        pdu_array->pdu_array[i].pdu_data = NULL;
    }

    return pdu_array;
}

// Function to add a new CRC indication PDU to the dynamic array
int nfapi_crc_indication_pdu_add(NFAPI_CRC_INDICATION_PDUS_T* pdu_array, int pdu_type, void* pdu_data) {
    // Check if the dynamic array is full
    if (pdu_array->size == pdu_array->capacity) {
        return -1;
    }

    // Add the new PDU to the end of the dynamic array
    int index = pdu_array->size++;
    pdu_array->pdu_array[index].pdu_type = pdu_type;
    pdu_array->pdu_array[index].pdu_length = 0;
    pdu_array->pdu_array[index].pdu_data = pdu_data;

    return index;
}

// Function to remove a CRC indication PDU from the dynamic array
int nfapi_crc_indication_pdu_remove(NFAPI_CRC_INDICATION_PDUS_T* pdu_array, int index) {
    // Check if the index is valid
    if (index < 0 || index >= pdu_array->size) {
        return -1;
    }

    // Remove the PDU from the dynamic array
    for (int i = index; i < pdu_array->size - 1; i++) {
        pdu_array->pdu_array[i] = pdu_array->pdu_array[i + 1];
    }
    pdu_array->size--;

    return 0;
}

// Function to validate the integrity of a CRC indication PDU
int nfapi_crc_indication_pdu_validate(NFAPI_CRC_INDICATION_PDUS_T* pdu_array, int index) {
    // Check if the index is valid
    if (index < 0 || index >= pdu_array->size) {
        return -1;
    }

    // Validate the PDU data
    NFAPI_CRC_INDICATION_PDU_T* pdu = &pdu_array->pdu_array[index];
    if (pdu->pdu_type != 0 || pdu->pdu_length == 0) {
        return -1;
    }

    // Validate the PDU data further based on the type of PDU
    switch (pdu->pdu_type) {
        case NFAPI_CRC_INDICATION_PDU_TYPE_UE_INFO:
            if (!pdu->pdu_data || pdu->pdu_length < sizeof(NFAPI_UE_INFO_T)) {
                return -1;
            }
            break;
        default:
            return -1;
    }

    return 0;
}

// Function to free the memory allocated for the dynamic array of CRC indication PDUs
void nfapi_crc_indication_pdu_free(NFAPI_CRC_INDICATION_PDUS_T* pdu_array) {
    // Free the memory allocated for the PDU data
    free(pdu_array->pdu_array);

    // Free the memory allocated for the dynamic array itself
    free(pdu_array);
}
