// Define the struct node
struct node {
    int key;
    char *str;
    struct node *next;
};

// Function to dynamically allocate memory for and initialize three arrays: one for storing double precision floating-point numbers, another for char strings (up to 256 characters), and a third for struct node pointers. Each struct node contains an integer key and a pointer to the next node in a singly linked list.
void init_arrays(int num_nodes, int *key_range, int max_num_nodes) {
    // Allocate memory for the double precision floating-point numbers array
    double *doubles = (double *)malloc(sizeof(double) * num_nodes);
    if (!doubles) {
        printf("Error: Failed to allocate memory for doubles\n");
        return;
    }

    // Initialize the doubles array with random values within the given range
    srand(time(NULL));
    for (int i = 0; i < num_nodes; i++) {
        doubles[i] = rand() % key_range[1] + key_range[0];
    }

    // Allocate memory for the char strings array
    char **strings = (char **)malloc(sizeof(char *) * num_nodes);
    if (!strings) {
        printf("Error: Failed to allocate memory for strings\n");
        free(doubles);
        return;
    }

    // Initialize the strings array with randomly generated ASCII strings
    for (int i = 0; i < num_nodes; i++) {
        strings[i] = (char *)malloc(sizeof(char) * 256);
        if (!strings[i]) {
            printf("Error: Failed to allocate memory for string %d\n", i);
            free(doubles);
            free(strings);
            return;
        }
        for (int j = 0; j < 256; j++) {
            strings[i][j] = rand() % 128 + 32;
        }
    }

    // Allocate memory for the struct node pointers array
    struct node **nodes = (struct node **)malloc(sizeof(struct node *) * num_nodes);
    if (!nodes) {
        printf("Error: Failed to allocate memory for nodes\n");
        free(doubles);
        free(strings);
        return;
    }

    // Initialize the struct node pointers array with random values within the given range
    srand(time(NULL));
    for (int i = 0; i < num_nodes; i++) {
        nodes[i] = (struct node *)malloc(sizeof(struct node));
        if (!nodes[i]) {
            printf("Error: Failed to allocate memory for node %d\n", i);
            free(doubles);
            free(strings);
            free(nodes);
            return;
        }
        nodes[i]->key = rand() % key_range[1] + key_range[0];
        nodes[i]->str = strings[i];
        nodes[i]->next = NULL;
    }

    // Initialize the linked list head pointer and insert specified number of nodes into this list
    struct node *head = NULL;
    for (int i = 0; i < num_nodes; i++) {
        if (head == NULL) {
            head = nodes[i];
        } else {
            nodes[i]->next = head;
            head = nodes[i];
        }
    }
}
```
