struct MemoryPool* mempool = NULL;
size_t num_created = 0;
size_t num_discarded = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to create a new NFAPI_CRC_INDICATION_PDU_T structure
NFAPI_CRC_INDICATION_PDU_T* create_crc_indication(void) {
    // Allocate memory for the structure from the custom memory pool
    struct MemoryPool* mem = mempool;
    if (mem == NULL || mem->size == 0) {
        return NULL;
    }

    // Populate the structure with random data
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)mem->data;
    pdu->RX_UE_INFORMATION_TAG = rand() % 65536;
    pdu->RNTI = rand() % 4294967296;
    pdu->CRC_INDICATION_REL8_TAG = rand() % 256;
    pdu->CRCFLAG = (rand() % 2) == 0;

    // Update the memory pool and statistics tracking variables
    mempool = mem->next;
    num_created++;

    return pdu;
}

// Function to validate a NFAPI_CRC_INDICATION_PDU_T structure
bool validate_crc_indication(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Calculate the checksum for the structure
    uint32_t checksum = 0;
    for (int i = 0; i < sizeof(pdu); i++) {
        checksum += ((uint8_t*)pdu)[i];
    }

    // Compare the calculated checksum with the stored value
    if (checksum == pdu->CRC_INDICATION_REL8_TAG) {
        return true;
    } else {
        num_discarded++;
        return false;
    }
}

// Function to manage a pool of NFAPI_CRC_INDICATION_PDU_T structures
void manage_crc_indications(NFAPI_CRC_INDICATION_PDU_T* pdu, size_t num) {
