// Function to insert a new packet into the array
void insert_packet(int sequence_number, long timestamp, bool loss) {
    // Lock the mutex before modifying the array
    pthread_mutex_lock(&mutex);

    // Allocate memory for the new packet statistics structure
    TX_PACKET_STATS *new_packet = malloc(sizeof(TX_PACKET_STATS));
    if (new_packet == NULL) {
        perror("malloc");
        exit(1);
    }

    // Initialize the new packet statistics structure
    new_packet->sequence_number = sequence_number;
    new_packet->timestamp = timestamp;
    new_packet->loss = loss;

    // Insert the new packet into the array
    if (num_packets == 0) {
        packet_stats = malloc(sizeof(TX_PACKET_STATS));
        if (packet_stats == NULL) {
            perror("malloc");
            exit(1);
        }
        packet_stats[0] = *new_packet;
    } else {
        // Reallocate memory for the array to accommodate the new packet
        TX_PACKET_STATS *tmp = realloc(packet_stats, (num_packets + 1) * sizeof(TX_PACKET_STATS));
        if (tmp == NULL) {
            perror("realloc");
            exit(1);
        }
        packet_stats = tmp;
        packet_stats[num_packets] = *new_packet;
