    // If the packet is found, delete it from the array
    if (i < num_packets) {
        // Reallocate memory for the array to remove the deleted packet
        TX_PACKET_STATS *tmp = realloc(packet_stats, (num_packets - 1) * sizeof(TX_PACKET_STATS));
        if (tmp == NULL) {
            perror("realloc");
            exit(1);
        }
        packet_stats = tmp;

        // Shift the remaining packets to fill the gap
        for (size_t j = i; j < num_packets - 1; j++) {
            packet_stats[j] = packet_stats[j + 1];
        }

        // Decrement the number of packets in the array
        num_packets--;
    }

    // Unlock the mutex after modifying the array
    pthread_mutex_unlock(&mutex);
}

