        printf("RX_UE_INFORMATION_TAG: %d\n", currentNode->data->rxUeInformationTag);
        printf("RNTI: %d\n", currentNode->data->rnti);
        printf("CRC_INDICATION_REL8_TAG: %d\n", currentNode->data->crcIndicationRel8Tag.CRCFLAG);
        currentNode = currentNode->next;
    }

    // Unlock the linked list to allow other threads to access it
    pthread_mutex_unlock(&linkedListMutex);
}
