// Define the structure for an NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int rnti;
    int crc_indication_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a linked list node for the NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct Node *next;
} Node;

// Define a global variable to keep track of the head node of the linked list
Node *head = NULL;

// Define a function to initialize and manage the linked list
void init_list(int N) {
    // Check if the input is within a realistic operational range
    if (N < 0 || N > 1000000) {
        printf("Error: Invalid input for number of structures to create\n");
        return;
    }

    // Allocate memory for the linked list nodes
    Node *node = malloc(sizeof(Node));
    if (node == NULL) {
        printf("Error: Failed to allocate memory for linked list node\n");
        return;
    }

    // Initialize the head node of the linked list
    head = node;
    head->data = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (head->data == NULL) {
        printf("Error: Failed to allocate memory for linked list data\n");
        return;
    }

    // Initialize the next pointer of the head node to NULL
    head->next = NULL;

    // Dynamically resize the linked list as needed
    int i = 0;
    while (i < N) {
        Node *new_node = malloc(sizeof(Node));
        if (new_node == NULL) {
            printf("Error: Failed to allocate memory for new linked list node\n");
            return;
        }

        // Add the new node to the end of the linked list
        Node *current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
        new_node->data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_node->data == NULL) {
            printf("Error: Failed to allocate memory for linked list data\n");
            return;
        }
        new_node->next = NULL;

        i++;
    }
}

// Define a function to add a new node to the linked list
void add_node(int rnti, int crc_indication_tag) {
    // Check if the input is within a realistic operational range
    if (rnti < 0 || rnti > 65535 || crc_indication_tag < 0 || crc_indication_tag > 255) {
        printf("Error: Invalid input for RNTI or CRC indication tag\n");
        return;
    }

    // Allocate memory for the new node
    Node *new_node = malloc(sizeof(Node));
    if (new_node == NULL) {
        printf("Error: Failed to allocate memory for new linked list node\n");
        return;
    }

    // Add the new node to the end of the linked list
    Node *current = head;
    while (current->next != NULL) {
        current = current->next;
    }
    current->next = new_node;
    new_node->data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_node->data == NULL) {
        printf("Error: Failed to allocate memory for linked list data\n");
        return;
    }
    new_node->next = NULL;

    // Set the RNTI and CRC indication tag of the new node
    new_node->data->rnti = rnti;
    new_node->data->crc_indication_tag = crc_indication_tag;
}

// Define a function to remove a node from the linked list
void remove_node(int index) {
    // Check if the input is within a realistic operational range
    if (index < 0 || index >= N) {
        printf("Error: Invalid input for index\n");
        return;
    }

    // Find the node to be removed
    Node *current = head;
    int i = 0;
    while (i < index) {
        current = current->next;
        i++;
    }

    // Remove the node from the linked list
    if (current == head) {
        head = head->next;
    } else {
        Node *previous = current->prev;
        previous->next = current->next;
    }

    // Free the memory of the removed node
    free(current);
}

// Define a function to update the RNTI and CRC indication tag of a node in the linked list
void update_node(int index, int rnti, int crc_indication_tag) {
    // Check if the input is within a realistic operational range
    if (index < 0 || index >= N || rnti < 0 || rnti > 65535 || crc_indication_tag < 0 || crc_indication_tag > 255) {
        printf("Error: Invalid input for index, RNTI, or CRC indication tag\n");
        return;
    }

    // Find the node to be updated
    Node *current = head;
    int i = 0;
    while (i < index) {
        current = current->next;
        i++;
    }

    // Update the RNTI and CRC indication tag of the node
    current->data->rnti = rnti;
    current->data->crc_indication_tag = crc_indication_tag;
}

// Define a function to print the linked list
void print_list() {
    // Print the RNTI and CRC indication tag of each node in the linked list
    Node *current = head;
    while (current != NULL) {
        printf("RNTI: %d, CRC indication tag: %d\n", current->data->rnti, current->data->crc_indication_tag);
        current = current->next;
    }
}
