#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

// Define the maximum size of the linked list
#define MAX_LIST_SIZE 1024

// Define the structure for a MAC frame PDU
typedef struct {
    // The MAC header
    uint8_t macHeader[6];
    // The preamble
    uint8_t preamble[8];
    // The MAC payload
    uint8_t* macPayload;
} MAC_FRAME_PDU_T;

// Define the linked list node structure
typedef struct {
    // The next node in the linked list
    struct Node* next;
    // The previous node in the linked list
    struct Node* prev;
    // The MAC frame PDU data
    MAC_FRAME_PDU_T* pduData;
} Node;

// Define the linked list structure
typedef struct {
    // The head of the linked list
    Node* head;
    // The tail of the linked list
    Node* tail;
    // The number of nodes in the linked list
    size_t numNodes;
} LinkedList;

// Define the function to add a new node to the linked list
void addNode(LinkedList* list, MAC_FRAME_PDU_T* pduData) {
    // Create a new node for the PDU data
    Node* newNode = malloc(sizeof(Node));
    if (newNode == NULL) {
        printf("Error: Failed to allocate memory for new node\n");
        return;
    }

    // Set the next and previous pointers of the new node to NULL
    newNode->next = NULL;
    newNode->prev = NULL;

    // Set the PDU data pointer of the new node
    newNode->pduData = pduData;

    // If the linked list is empty, set the head and tail pointers to the new node
    if (list->head == NULL) {
        list->head = newNode;
        list->tail = newNode;
    } else {
        // Otherwise, add the new node to the end of the linked list
        list->tail->next = newNode;
        newNode->prev = list->tail;
        list->tail = newNode;
    }

    // Increment the number of nodes in the linked list
    list->numNodes++;
}

// Define the function to remove a node from the linked list
void removeNode(LinkedList* list, Node* node) {
    // If the node is the head of the linked list, set the new head to the next node
    if (node == list->head) {
        list->head = node->next;
    }

    // If the node is the tail of the linked list, set the new tail to the previous node
    if (node == list->tail) {
        list->tail = node->prev;
    }

    // Remove the node from the linked list by setting its next and previous pointers to NULL
    node->next = NULL;
    node->prev = NULL;

    // Decrement the number of nodes in the linked list
    list->numNodes--;
}

// Define the function to update a node in the linked list
void updateNode(LinkedList* list, Node* node, MAC_FRAME_PDU_T* pduData) {
    // If the node is not found in the linked list, return
    if (node == NULL) {
        return;
    }

    // Update the PDU data pointer of the node
    node->pduData = pduData;
}

// Define the function to remove the oldest entry from the linked list if the maximum size is exceeded
void removeOldestEntry(LinkedList* list) {
    // If the linked list is not full, return
    if (list->numNodes < MAX_LIST_SIZE) {
        return;
    }

    // Remove the oldest entry from the linked list by removing its node
    removeNode(list, list->head);
}

// Define the function to iterate over the nodes in the linked list
void iterateOverNodes(LinkedList* list, void (*callback)(MAC_FRAME_PDU_T*)) {
    // If the linked list is empty, return
    if (list->head == NULL) {
        return;
    }

    // Iterate over the nodes in the linked list and call the callback function for each node
    Node* currentNode = list->head;
    while (currentNode != NULL) {
        callback(currentNode->pduData);
        currentNode = currentNode->next;
    }
}

// Define the function to print the linked list
void printLinkedList(LinkedList* list) {
    // If the linked list is empty, return
    if (list->head == NULL) {
        return;
    }

    // Print the PDU data of each node in the linked list
    Node* currentNode = list->head;
    while (currentNode != NULL) {
        printf("PDU Data: ");
        for (int i = 0; i < currentNode->pduData->macHeader[5]; i++) {
            printf("%02x ", currentNode->pduData->macPayload[i]);
        }
        printf("\n");
        currentNode = currentNode->next;
    }
}
