// Define a structure to represent a state in the FSA
typedef struct State {
    int id;
    struct Transition *transitions;
    int ref_count;
} State;

// Define a structure to represent a transition in the FSA
typedef struct Transition {
    int next_state;
    int weight;
} Transition;

// Define a structure to represent the FSA
typedef struct FSA {
    int num_states;
    State *states;
} FSA;

void initialize_fsa(FSA *fsa, int num_states, int range) {
    // Validate that the FSA is correctly initialized
    if (fsa == NULL || num_states <= 0 || range < 0) {
        printf("Error: Invalid input parameters\n");
        return;
    }

    // Allocate memory for the state list
    fsa->states = malloc(sizeof(State) * num_states);
    if (fsa->states == NULL) {
        printf("Error: Failed to allocate memory for state list\n");
        return;
    }

    // Initialize each state in the list
    for (int i = 0; i < num_states; i++) {
        fsa->states[i].id = i;
        fsa->states[i].transitions = NULL;
        fsa->states[i].ref_count = 0;
    }

    // Initialize the number of states in the FSA
    fsa->num_states = num_states;
}

void add_transition(FSA *fsa, int state_id, int next_state_id, int weight) {
    // Validate that the input parameters are valid
    if (fsa == NULL || state_id < 0 || next_state_id < 0 || weight < 0) {
        printf("Error: Invalid input parameters\n");
        return;
    }

    // Check if the state exists in the FSA
    if (state_id >= fsa->num_states || next_state_id >= fsa->num_states) {
        printf("Error: State does not exist in the FSA\n");
        return;
    }

    // Allocate memory for the transition
    Transition *transition = malloc(sizeof(Transition));
    if (transition == NULL) {
        printf("Error: Failed to allocate memory for transition\n");
        return;
    }

    // Initialize the transition
    transition->next_state = next_state_id;
    transition->weight = weight;

    // Add the transition to the state's list of outgoing transitions
    State *state = &fsa->states[state_id];
    Transition *last_transition = state->transitions;
    while (last_transition != NULL && last_transition->next != NULL) {
        last_transition = last_transition->next;
    }
    if (last_transition == NULL) {
        state->transitions = transition;
    } else {
        last_transition->next = transition;
    }
}

void simulate_fsa(FSA *fsa, int num_transitions) {
    // Validate that the input parameters are valid
    if (fsa == NULL || num_transitions <= 0) {
        printf("Error: Invalid input parameters\n");
        return;
    }

    // Initialize a counter for the number of transitions processed
    int total_transitions = 0;

    // Simulate the FSA's behavior by processing up to the specified number of transitions
    while (total_transitions < num_transitions) {
        // Choose a random state from the FSA
        State *state = &fsa->states[rand() % fsa->num_states];

        // Increment the reference count for the chosen state
        state->ref_count++;

        // Process all outgoing transitions from the chosen state
        Transition *transition = state->transitions;
        while (transition != NULL) {
            // Choose a random next state from the transition's list of possible next states
            int next_state_id = rand() % fsa->num_states;

            // Increment the reference count for the chosen next state
            State *next_state = &fsa->states[next_state_id];
            next_state->ref_count++;

            // Decrement the reference count for the chosen state
            state->ref_count--;

            // Update the 'next' pointer of the last transition in the list to point to the newly created state list
            Transition *last_transition = transition;
            while (last_transition != NULL && last_transition->next != NULL) {
                last_transition = last_transition->next;
            }
            if (last_transition == NULL) {
                transition->next = next_state;
            } else {
                last_transition->next = next_state;
            }

            // Update the total number of transitions processed
            total_transitions++;
        }
    }
}

void free_fsa(FSA *fsa) {
    // Validate that the FSA is correctly initialized
    if (fsa == NULL || fsa->states == NULL) {
        printf("Error: Invalid input parameters\n");
        return;
    }

    // Free all memory allocated for the state list and the FSA
    free(fsa->states);
    free(fsa);
}
