    long* arr = malloc(size * sizeof(long));
    if (arr == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for long array\n");
        exit(1);
    }
    return arr;
}

// Function to dynamically allocate memory for an array of int integers
