    int* arr = malloc(size * sizeof(int));
    if (arr == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for int array\n");
        exit(1);
    }
    return arr;
}

// Function to dynamically allocate memory for an array of record structures
Record* allocate_record_array(int size) {
    Record* arr = malloc(size * sizeof(Record));
    if (arr == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for record array\n");
        exit(1);
    }
    return arr;
}

// Function to initialize the record structures with random values within a specified range
void init_records(Record* records, int size, int min, int max) {
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        records[i].value = rand() % (max - min + 1) + min;
    }
}

// Function to sort the record structures based on their corresponding key values in ascending order
void sort_records(Record* records, int size) {
    for (int i = 0; i < size - 1; i++) {
        for (int j = 0; j < size - i - 1; j++) {
            if (records[j].value > records[j + 1].value) {
                Record temp = records[j];
                records[j] = records[j + 1];
                records[j + 1] = temp;
            }
        }
    }
}

// Function to free the memory allocated for the arrays of long integers, int integers, and record structures
void free_memory(long* offsets, int* keys, Record* records) {
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    // Get user input for the size of the arrays
    int size;
    printf("Enter the size of the array: ");
    scanf("%d", &size);

    // Check if the user input is valid
    if (size <= 0) {
        fprintf(stderr, "Error: Invalid input. Size must be a positive integer.\n");
        exit(1);
    }

    // Dynamically allocate memory for the arrays of long integers and int integers
    long* offsets = allocate_long_array(size);
    int* keys = allocate_int_array(size);

    // Initialize the record structures with random values within a specified range
    Record* records = allocate_record_array(size);
    init_records(records, size, 1, 100);

    // Sort the record structures based on their corresponding key values in ascending order
    sort_records(records, size);

    // Print the sorted records
    printf("Sorted records:\n");
    for (int i = 0; i < size; i++) {
        printf("%d: %d\n", i + 1, records[i].value);
    }

    // Free the memory allocated for the arrays of long integers, int integers, and record structures
    free_memory(offsets, keys, records);

    return 0;
}
