#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

// Define a structure for storing record metadata
typedef struct {
    int key;
    long offset;
    time_t creation_timestamp;
    time_t last_accessed_timestamp;
} Record;

// Define a function to allocate and initialize memory for the arrays
void init_arrays(int num_records, int max_key, long max_offset) {
    // Allocate memory for the offset array
    long *offsets = malloc(num_records * sizeof(long));
    if (offsets == NULL) {
        printf("Error: Failed to allocate memory for offsets\n");
        exit(1);
    }

    // Allocate memory for the key array
    int *keys = malloc(num_records * sizeof(int));
    if (keys == NULL) {
        printf("Error: Failed to allocate memory for keys\n");
        free(offsets);
        exit(1);
    }

    // Allocate memory for the record array
    Record *records = malloc(num_records * sizeof(Record));
    if (records == NULL) {
        printf("Error: Failed to allocate memory for records\n");
        free(offsets);
        free(keys);
        exit(1);
    }

    // Initialize the offset and key arrays
    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand() % max_offset;
        keys[i] = rand() % max_key;
    }

    // Initialize the record array
    for (int i = 0; i < num_records; i++) {
        records[i].key = keys[i];
        records[i].offset = offsets[i];
        records[i].creation_timestamp = time(NULL);
        records[i].last_accessed_timestamp = 0;
    }

    // Log memory usage and access patterns to a file for debugging purposes
    FILE *log_file = fopen("memory_usage.log", "a");
    if (log_file == NULL) {
        printf("Error: Failed to open log file\n");
        free(offsets);
        free(keys);
        free(records);
        exit(1);
    }
    fprintf(log_file, "Memory usage: %lu bytes\n", (num_records * sizeof(long)) + (num_records * sizeof(int)) + (num_records * sizeof(Record)));
    fclose(log_file);
}

// Define a function to deallocate memory for the arrays
void free_arrays() {
    // Deallocate memory for the offset array
    free(offsets);

    // Deallocate memory for the key array
    free(keys);

    // Deallocate memory for the record array
    free(records);
}

// Define a function to add a new record to the arrays
void add_record(int key, long offset) {
    // Check if the maximum number of records has been reached
    if (num_records == max_records) {
        printf("Error: Maximum number of records has been reached\n");
        return;
    }

    // Allocate memory for a new record
    Record *new_record = malloc(sizeof(Record));
    if (new_record == NULL) {
        printf("Error: Failed to allocate memory for new record\n");
        return;
    }

    // Initialize the new record
    new_record->key = key;
    new_record->offset = offset;
    new_record->creation_timestamp = time(NULL);
    new_record->last_accessed_timestamp = 0;

    // Add the new record to the arrays
    offsets[num_records] = offset;
    keys[num_records] = key;
    records[num_records++] = new_record;

    // Log memory usage and access patterns to a file for debugging purposes
    FILE *log_file = fopen("memory_usage.log", "a");
    if (log_file == NULL) {
        printf("Error: Failed to open log file\n");
        free(new_record);
        return;
    }
    fprintf(log_file, "Memory usage: %lu bytes\n", (num_records * sizeof(long)) + (num_records * sizeof(int)) + (num_records * sizeof(Record)));
    fclose(log_file);
}

// Define a function to retrieve a record from the arrays based on its key
void get_record(int key) {
    // Check if the key is valid
    if (key < 0 || key >= max_key) {
        printf("Error: Invalid key\n");
        return;
    }

    // Search for the record with the specified key
    int i = 0;
    while (i < num_records && keys[i] != key) {
        i++;
    }

    // Check if the record was found
    if (i == num_records) {
        printf("Error: Record not found\n");
        return;
    }

    // Update the last accessed timestamp for the record
    records[i]->last_accessed_timestamp = time(NULL);
}

// Define a function to retrieve all records from the arrays based on their creation timestamps
void get_records() {
    // Sort the records by creation timestamp in ascending order
    qsort(records, num_records, sizeof(Record), compare_creation_timestamps);

    // Print the records to standard output
    for (int i = 0; i < num_records; i++) {
        printf("Key: %d\nOffset: %ld\nCreation timestamp: %s", records[i]->key, records[i]->offset, ctime(&(records[i]->creation_timestamp)));
    }
}

// Define a function to compare the creation timestamps of two records
int compare_creation_timestamps(const void *a, const void *b) {
    Record *record1 = (Record *)a;
    Record *record2 = (Record *)b;
    return record1->creation_timestamp - record2->creation_timestamp;
}
