// Define the function implementations for the service
void init_encryption_key(encryption_key_t *key) {
    // Initialize the encryption key with a random value
    RAND_bytes(key->key, 32);
}

int encrypt_data(unsigned char *data, size_t data_len, encryption_key_t *key) {
    // Encrypt the data using AES-256-CBC
    EVP_CIPHER_CTX *ctx;
    int len;

    if (!(ctx = EVP_CIPHER_CTX_new())) {
        log_message(NULL, LOG_LEVEL_ERROR, "Failed to create encryption context");
        return -1;
    }

    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key->key, key->iv) <= 0) {
        log_message(NULL, LOG_LEVEL_ERROR, "Failed to initialize encryption");
        return -1;
    }

    if (EVP_EncryptUpdate(ctx, data, &len, data, data_len) <= 0) {
        log_message(NULL, LOG_LEVEL_ERROR, "Failed to encrypt data");
        return -1;
    }

    EVP_CIPHER_CTX_free(ctx);

    return len;
}

int decrypt_data(unsigned char *data, size_t data_len, encryption_key_t *key) {
    // Decrypt the data using AES-256-CBC
    EVP_CIPHER_CTX *ctx;
    int len;

    if (!(ctx = EVP_CIPHER_CTX_new())) {
        log_message(NULL, LOG_LEVEL_ERROR, "Failed to create decryption context");
        return -1;
    }

    if (EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key->key, key->iv) <= 0) {
        log_message(NULL, LOG_LEVEL_ERROR, "Failed to initialize decryption");
        return -1;
    }

    if (EVP_DecryptUpdate(ctx, data, &len, data, data_len) <= 0) {
        log_message(NULL, LOG_LEVEL_ERROR, "Failed to decrypt data");
        return -1;
    }

    EVP_CIPHER_CTX_free(ctx);

    return len;
}

