    if (level <= config->log_level) {
        va_list args;
        va_start(args, format);
        vfprintf(config->log_file, format, args);
        va_end(args);
    }
}

int check_rate_limit(rate_limiting_state_t *state) {
    // Check if the rate limit has been exceeded
    unsigned long long current_time = get_current_time();
    if (current_time - state->last_request_time < 60000) {
        return 1;
    } else {
        state->last_request_time = current_time;
        state->request_count = 0;
        return 0;
    }
}

void update_rate_limit(rate_limiting_state_t *state) {
