    memcpy(state->old_key, state->new_key, 32);
    RAND_bytes(state->new_key, 32);
}

int handle_nfapi_crc_indication_pdu(nfapi_crc_indication_pdu_t *pdu, encryption_key_t *key) {
    // Handle an NFAPI CRC indication PDU
    int len;

    if (check_rate_limit(&state->rate_limiting_state)) {
        log_message(NULL, LOG_LEVEL_WARNING, "Rate limit exceeded");
        return -1;
    }

    update_rate_limit(&state->rate_limiting_state);

    if (pdu->rx_ue_information_tag[0] == 0) {
        // Encrypt the data using AES-256-CBC
        EVP_CIPHER_CTX *ctx;

        if (!(ctx = EVP_CIPHER_CTX_new())) {
            log_message(NULL, LOG_LEVEL_ERROR, "Failed to create encryption context");
            return -1;
        }

        if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key->key, key->iv) <= 0) {
            log_message(NULL, LOG_LEVEL_ERROR, "Failed to initialize encryption");
            return -1;
        }

        if (EVP_EncryptUpdate(ctx, pdu->crc_indication_rel8_tag, &len, pdu->crc_indication_rel8_tag, 32) <= 0) {
            log_message(NULL, LOG_LEVEL_ERROR, "Failed to encrypt data");
            return -1;
        }

        EVP_CIPHER_CTX_free(ctx);
    } else if (pdu->rx_ue_information_tag[0] == 1) {
        // Encrypt the data using AES-128-CBC
        EVP_CIPHER_CTX *ctx;

        if (!(ctx = EVP_CIPHER_CTX_new())) {
            log_message(NULL, LOG_LEVEL_ERROR, "Failed to create encryption context");
            return -1;
        }

        if (EVP_EncryptInit_ex(ctx, EVP_aes_128_cbc(), NULL, key->key, key->iv) <= 0) {
            log_message(NULL, LOG_LEVEL_ERROR, "Failed to initialize encryption");
            return -1;
        }

        if (EVP_EncryptUpdate(ctx, pdu->crc_indication_rel8_tag, &len, pdu->crc_indication_rel8_tag, 32) <= 0) {
            log_message(NULL, LOG_LEVEL_ERROR, "Failed to encrypt data");
            return -1;
        }

        EVP_CIPHER_CTX_free(ctx);
    } else if (pdu->rx_ue_information_tag[0] == 2) {
        // Encrypt the data using ChaCha20-Poly1305
        EVP_CIPHER_CTX *ctx;

        if (!(ctx = EVP_CIPHER_CTX_new())) {
            log_message(NULL, LOG_LEVEL_ERROR, "Failed to create encryption context");
            return -1;
        }

        if (EVP_EncryptInit_ex(ctx, EVP_chacha20_poly1305(), NULL, key->key, key->iv) <= 0) {
            log_message(NULL, LOG_LEVEL_ERROR, "Failed to initialize encryption");
            return -1;
        }

        if (EVP_EncryptUpdate(ctx, pdu->crc_indication_rel8_tag, &len, pdu->crc_indication_rel8_tag, 32) <= 0) {
            log_message(NULL, LOG_LEVEL_ERROR, "Failed to encrypt data");
            return -1;
        }

        EVP_CIPHER_CTX_free(ctx);
    } else {
        // Unknown RX UE information tag
        log_message(NULL, LOG_LEVEL_WARNING, "Unknown RX UE information tag");
        return -1;
    }

    return len;
}

void init_network_adaptation_state(network_adaptation_state_t *state) {
    // Initialize the network adaptation state with default values
    state->last_request_time = 0;
    state->request_count = 0;
}

void adapt_to_network_changes(network_adaptation_state_t *state) {
    // Adapt to changes in the underlying network architecture and data flow patterns
    if (state->last_request_time == 0) {
        // No previous requests, initialize the state
        init_network_adaptation_state(state);
    } else {
        // Update the state based on the current request count
        unsigned long long current_time = get_current_time();
        if (current_time - state->last_request_time < 60000) {
            // No changes in the network, update the state
            state->request_count++;
        } else {
            // Changes in the network, reset the state
            init_network_adaptation_state(state);
        }
    }
}
