// Function to add a new message
void add_message(int sender_id, int recipient_id) {
    // Check if the array is full
    if (num_messages == max_messages) {
        // If so, double the size of the array
        Message* temp = realloc(messages, 2 * max_messages * sizeof(Message));
        if (temp != NULL) {
            messages = temp;
            max_messages *= 2;
        } else {
            // If reallocation fails, print an error message and exit
            printf("Error: unable to allocate memory for new messages\n");
            exit(1);
        }
    }

    // Add the new message to the array
    Message* new_message = &messages[num_messages++];
    new_message->sender_id = sender_id;
    new_message->recipient_id = recipient_id;
    new_message->timestamp = time(NULL);
}

// Function to remove expired messages based on a configurable threshold
void remove_expired_messages(int threshold) {
    // Iterate through the array of messages and remove any that are older than the threshold
    for (size_t i = 0; i < num_messages; ++i) {
        if (difftime(time(NULL), messages[i].timestamp) > threshold) {
            // If the message is expired, move the last message to its position and decrement the size of the array
            Message* temp = &messages[i];
            memcpy(&messages[i], &messages[num_messages - 1], sizeof(Message));
            --num_messages;
        }
    }
}

