// Structure to store traffic flow statistics
typedef struct TrafficFlowStats {
    int flow_id;
    long packet_count;
    long byte_count;
    time_t timestamp;
} TrafficFlowStats;

// Function to initialize the list with a specified number of entries
void init_list(TrafficFlowStats **list, int num_entries) {
    // Allocate memory for the list and its elements
    *list = (TrafficFlowStats *)malloc(sizeof(TrafficFlowStats) * num_entries);

    // Initialize each element with random data
    for (int i = 0; i < num_entries; i++) {
        (*list)[i].flow_id = rand() % 100000;
        (*list)[i].packet_count = rand() % 100000;
        (*list)[i].byte_count = rand() % 100000;
        (*list)[i].timestamp = time(NULL);
    }
}

// Function to add a new entry to the list
void add_entry(TrafficFlowStats **list, int num_entries) {
    // Check if the list is full
    if (num_entries == 0) {
        return;
    }

    // Allocate memory for the new element
    TrafficFlowStats *new_element = (TrafficFlowStats *)malloc(sizeof(TrafficFlowStats));

    // Generate random data for the new element
    new_element->flow_id = rand() % 100000;
    new_element->packet_count = rand() % 100000;
    new_element->byte_count = rand() % 100000;
    new_element->timestamp = time(NULL);

    // Add the new element to the list
    (*list)[num_entries - 1] = *new_element;
}

// Function to update an existing entry in the list
void update_entry(TrafficFlowStats **list, int num_entries, int flow_id) {
    // Check if the list is empty or the flow ID does not exist
    if (num_entries == 0 || !flow_exists(list, num_entries, flow_id)) {
        return;
    }

    // Find the index of the element with the specified flow ID
    int index = find_index(list, num_entries, flow_id);

    // Update the packet and byte counts for the element
    (*list)[index].packet_count += rand() % 100000;
    (*list)[index].byte_count += rand() % 100000;
}

// Function to retrieve statistics for a specific flow ID
void get_stats(TrafficFlowStats **list, int num_entries, int flow_id) {
    // Check if the list is empty or the flow ID does not exist
    if (num_entries == 0 || !flow_exists(list, num_entries, flow_id)) {
        return;
    }

    // Find the index of the element with the specified flow ID
    int index = find_index(list, num_entries, flow_id);

    // Print the statistics for the element
    printf("Flow ID: %d\n", (*list)[index].flow_id);
    printf("Packet Count: %ld\n", (*list)[index].packet_count);
    printf("Byte Count: %ld\n", (*list)[index].byte_count);
    printf("Timestamp: %s\n", ctime(&(*list)[index].timestamp));
}

// Function to check if a flow ID exists in the list
int flow_exists(TrafficFlowStats **list, int num_entries, int flow_id) {
    // Check if the list is empty or the flow ID does not exist
    if (num_entries == 0 || !flow_exists(list, num_entries, flow_id)) {
        return 0;
    }

    // Find the index of the element with the specified flow ID
    int index = find_index(list, num_entries, flow_id);

    // Return 1 if the element is found, otherwise return 0
    return (index != -1) ? 1 : 0;
}

// Function to find the index of an element with a specified flow ID in the list
int find_index(TrafficFlowStats **list, int num_entries, int flow_id) {
    // Iterate through the list and compare each element's flow ID with the specified flow ID
    for (int i = 0; i < num_entries; i++) {
        if ((*list)[i].flow_id == flow_id) {
            return i;
        }
    }

    // Return -1 if the element is not found in the list
    return -1;
}
