// Function to generate random numbers within a given range
int rand_range(int min, int max) {
    return min + (rand() % (max - min + 1));
}

// Function to generate unique keys
key_t gen_unique_key(void) {
    static int last_key = 0;
    key_t new_key;
    do {
        new_key = rand_range(0, 9999);
    } while (new_key == last_key);
    last_key = new_key;
    return new_key;
}

// Function to populate the two-dimensional array with records
void populate_records(struct record_t **records, int num_records) {
    // Allocate memory for the two-dimensional array
    *records = (struct record_t *)malloc(num_records * sizeof(**records));
    if (*records == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for records\n");
        exit(1);
    }

    // Initialize the two-dimensional array with random values
    for (int i = 0; i < num_records; i++) {
        (*records)[i].key = gen_unique_key();
        (*records)[i].offset = rand_range(-1000000, 1000000);
    }
}

// Function to free the memory allocated for the two-dimensional array
void free_records(struct record_t **records) {
    if (*records != NULL) {
        free(*records);
        *records = NULL;
    }
}

