        // Increment the size of the NAS message buffer based on the current load and available system resources
        nasMessageBufferSize += strlen(nasMessage);
    }

    // Set the size of the NAS message buffer for each UE context based on the current load and available system resources
    for (int i = 0; i < numUEs; i++) {
        ueContexts[i].nasMessageSize = nasMessageBufferSize;
    }
}

