            ue_context.nas_sap = prev_ue_context.nas_sap;
        } else {
            // If no previous UE context exists, use a default NAS SAP
            ue_context.nas_sap = "127.0.0.1".to_string();
        }
    }

    // Create a new directory for the UE context
    let mut directory_path = PathBuf::new();
    directory_path.push("ue_contexts");
    directory_path.push(imsi);
