    // Set the environment variable to the path of the UE context directory
    let mut env_var = String::new();
    env_var.push_str("UE_CONTEXT_DIR=");
    env_var.push_str(&directory_path.to_string_lossy());
    if let Ok(env_var) = env::set_var(env_var) {
        println!("Set environment variable: {}", env_var);
