        // If the environment variable is already set, use the existing value
        if let Some(existing_value) = env::var("UE_CONTEXT_DIR") {
            directory_path = PathBuf::from(existing_value);
        }
    }

    // Create a new NAS message buffer and add it to the UE context
    ue_context.nas_message = create_nas_message_buffer();

    // Return the initialized UE context
    ue_context
}

