// Define a hash table to manage LCID and PDUSessionID values
#define HASH_TABLE_SIZE 50000
static MAC_PDU_T* lcid_hash[HASH_TABLE_SIZE];

// Initialize the hash table with random data
void init_lcid_hash() {
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        lcid_hash[i] = NULL;
    }
}

// Add a new entry to the hash table, ensuring uniqueness
void add_lcid_entry(MAC_PDU_T* pdu) {
    int LCID = pdu->LCID;
    int PDUSessionID = pdu->PDUSessionID;

    // Check if the entry already exists in the hash table
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        if (lcid_hash[i] != NULL && lcid_hash[i]->LCID == LCID) {
            return; // Duplicate entry, do nothing
        }
    }

    // Add the new entry to the hash table
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        if (lcid_hash[i] == NULL) {
            lcid_hash[i] = pdu;
            break;
        }
    }
}

// Remove an entry from the hash table
void remove_lcid_entry(int LCID, int PDUSessionID) {
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        if (lcid_hash[i] != NULL && lcid_hash[i]->LCID == LCID && lcid_hash[i]->PDUSessionID == PDUSessionID) {
            lcid_hash[i] = NULL;
            break;
        }
    }
}

// Generate a random number within the hash table size
