    for (int i = 0; i < num_pdus; i++) {
        int LCID = generate_random_index();
        while (LCID == -1) {
            LCID = generate_random_index();
        }

        int PDUSessionID = generate_random_index();
        while (PDUSessionID == -1) {
            PDUSessionID = generate_random_index();
        }

        MAC_PDU_T* pdu = malloc(sizeof(MAC_PDU_T));
        pdu->LCID = LCID;
        pdu->SRC_LCID = LCID;
        pdu->PDUSessionID = PDUSessionID;

        add_lcid_entry(pdu);
