    // Add the new entry to the hash table
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        if (lcid_hash[i] == NULL) {
            lcid_hash[i] = pdu;
            break;
        }
    }
}

// Remove an entry from the list of MAC PDUs
