    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        if (lcid_hash[i] != NULL && lcid_hash[i]->LCID == LCID && lcid_hash[i]->PDUSessionID == PDUSessionID) {
            lcid_hash[i] = NULL;
            break;
        }
    }
}

// Update the list of MAC PDUs with new data from an external source
void update_mac_pdus(MAC_PDU_T* pdus, int num_pdus) {
    // Remove any existing entries in the hash table
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        if (lcid_hash[i] != NULL) {
            remove_mac_pdu(lcid_hash[i]->LCID, lcid_hash[i]->PDUSessionID);
        }
    }

    // Add the new entries to the hash table
    for (int i = 0; i < num_pdus; i++) {
        add_mac_pdu(pdus + i);
    }
}

// Free the memory allocated for the list of MAC PDUs
void free_mac_pdus() {
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        if (lcid_hash[i] != NULL) {
            free(lcid_hash[i]);
        }
    }
}
