// Custom allocator for managing memory pool
struct MemoryPool {
    void* buffer;
    size_t capacity;
    size_t used;
};

// NFAPI_CRC_INDICATION_PDU_T structure definition
typedef struct {
    uint32_t crc_indication_pdu_id;
    uint8_t* payload;
