// Function to initialize memory pool
void initMemoryPool(struct MemoryPool* pool, size_t capacity) {
    pool->buffer = malloc(capacity);
    if (pool->buffer == NULL) {
        printf("Error: Failed to allocate memory for memory pool\n");
        exit(1);
    }
    pool->capacity = capacity;
    pool->used = 0;
}

// Function to allocate memory from memory pool
void* allocMemory(struct MemoryPool* pool, size_t size) {
    if (pool->used + size > pool->capacity) {
        printf("Error: Out of memory in memory pool\n");
        exit(1);
    }
    void* ptr = pool->buffer + pool->used;
    pool->used += size;
    return ptr;
}

// Function to free memory from memory pool
void freeMemory(struct MemoryPool* pool, void* ptr) {
    if (ptr < pool->buffer || ptr >= pool->buffer + pool->capacity) {
        printf("Error: Invalid pointer passed to freeMemory\n");
        exit(1);
    }
    size_t offset = ptr - pool->buffer;
    pool->used -= offset;
}

