// Define the interface for the third-party API
class ThirdPartyAPI {
public:
    virtual bool findVmUuidFromMetadataIp(const string& metadataIp) = 0;
};

// Implement the third-party API using Boost.Beast
class ThirdPartyAPIImpl : public ThirdPartyAPI {
private:
    io_context ctx_;
    tcp::resolver resolver_;
    tcp::socket socket_;

public:
    ThirdPartyAPIImpl(io_context& ctx) : ctx_(ctx), resolver_(ctx), socket_(ctx) {}

    bool findVmUuidFromMetadataIp(const string& metadataIp) override {
        // Connect to the third-party API using Boost.Beast
        auto result = resolver_.resolve("api.example.com", "80");
        socket_.connect(*result);

        // Send a request to the third-party API
        string request = "GET /vm/uuid?metadata_ip=" + metadataIp;
        write(request, socket_);

        // Read the response from the third-party API
        string response;
        read(response, socket_);

        // Parse the JSON response and extract the VM UUID
        auto json = boost::json::parse(response);
        return json["vm"]["uuid"].as<string>();
    }
};

