        // Start the HTTP server
        acceptor_.listen();
        doAccept();
    }

private:
    void doAccept() {
        // Accept a new connection
        acceptor_.async_accept(socket_, [this](const error_code& ec) {
            if (!ec) {
                // Handle the incoming request
                handleRequest(socket_);
            }

            // Accept another connection
            doAccept();
        });
    }

    void handleRequest(tcp::socket& socket) {
        // Read the incoming request
        string request;
        read(request, socket);

        // Handle the request and send a response
        string response = "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\n\r\n";
        write(response, socket);
    }
};

// Define a class to handle proxy sessions
class ProxySession {
private:
    io_context ctx_;
    tcp::socket socket_;
    ThirdPartyAPI* api_;

public:
    ProxySession(io_context& ctx, const string& address, uint16_t port) : ctx_(ctx), socket_(ctx), api_(new ThirdPartyAPIImpl(ctx)) {}

    void start() {
        // Start the proxy session
        doRead();
    }

private:
    void doRead() {
        // Read data from the client
        async_read(socket_, boost::asio::buffer(request_), [this](const error_code& ec, size_t bytesTransferred) {
            if (!ec) {
                // Handle the incoming request
                handleRequest();
            }

            // Read another chunk of data from the client
            doRead();
        });
    }

    void handleRequest() {
        // Parse the incoming request and extract the VM UUID
        auto json = boost::json::parse(request_);
        string vmUuid = json["vm"]["uuid"].as<string>();

        // Use the third-party API to find the VM UUID in the metadata IP
        string metadataIp = json["metadata"]["ip"].as<string>();
        bool found = api_->findVmUuidFromMetadataIp(metadataIp);

        // Send a response back to the client
        string response = "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\n\r\n";
        if (found) {
            response += "{\"vm\": {\"uuid\": \"" + vmUuid + "\"}}";
        } else {
            response += "{\"error\": \"VM not found\"}";
        }
        write(response, socket_);
    }
};

