// Define a class to handle caching
class Cache {
private:
    map<string, string> cache_;
    mutex mtx_;

public:
    void add(const string& key, const string& value) {
        lock_guard<mutex> lck(mtx_);
        cache_.insert({key, value});
    }

    bool contains(const string& key) {
        lock_guard<mutex> lck(mtx_);
        return cache_.find(key) != cache_.end();
    }

    string get(const string& key) {
        lock_guard<mutex> lck(mtx_);
        return cache_[key];
    }
};

// Define a class to handle rate limiting
class RateLimiter {
private:
    mutex mtx_;
    condition_variable cv_;
    uint64_t requests_;
    uint64_t maxRequests_;
    chrono::time_point<chrono::system_clock> lastRequestTime_;

public:
    RateLimiter(uint64_t maxRequests) : mtx_(mtx_), cv_(cv_), requests_(0), maxRequests_(maxRequests), lastRequestTime_(chrono::system_clock::now()) {}

    void increment() {
        lock_guard<mutex> lck(mtx_);
        ++requests_;
        if (requests_ > maxRequests_) {
            cv_.wait_until(lastRequestTime_ + chrono::seconds(1));
        }
        lastRequestTime_ = chrono::system_clock::now();
    }
};

// Define a class to handle concurrent requests
class ConcurrentRequestHandler {
private:
    io_context ctx_;
    tcp::acceptor acceptor_;
    vector<thread> threads_;
    ThirdPartyAPI* api_;
    Cache cache_;
    RateLimiter rateLimiter_;

public:
    ConcurrentRequestHandler(io_context& ctx, const string& address, uint16_t port) : ctx_(ctx), acceptor_(ctx, tcp::endpoint(address, port)), threads_(vector<thread>()), api_(new ThirdPartyAPIImpl(ctx)), cache_(Cache()), rateLimiter_(RateLimiter(10)) {}

    void start() {
        // Start the concurrent request handler
        doAccept();
    }

private:
    void doAccept() {
        // Accept a new connection
        acceptor_.async_accept(socket_, [this](const error_code& ec) {
            if (!ec) {
                // Handle the incoming request
                handleRequest(socket_);
            }

            // Accept another connection
            doAccept();
        });
    }

    void handleRequest(tcp::socket& socket) {
        // Read the incoming request
        string request;
        read(request, socket);

        // Handle the request and send a response
        string response = "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\n\r\n";
        if (rateLimiter_.increment()) {
            // Use the cache to check if the VM UUID is already in the cache
            string vmUuid = cache_.get(request);
            if (!vmUuid.empty()) {
                response += "{\"vm\": {\"uuid\": \"" + vmUuid + "\"}}";
            } else {
                // Use the third-party API to find the VM UUID in the metadata IP
                auto json = boost::json::parse(request);
                string metadataIp = json["metadata"]["ip"].as<string>();
                bool found = api_->findVmUuidFromMetadataIp(metadataIp);
                if (found) {
                    vmUuid = json["vm"]["uuid"].as<string>();
                    cache_.add(request, vmUuid);
                    response += "{\"vm\": {\"uuid\": \"" + vmUuid + "\"}}";
                } else {
                    response += "{\"error\": \"VM not found\"}";
                }
            }
        } else {
            response += "{\"error\": \"Rate limit exceeded\"}";
        }
        write(response, socket);
    }
};

// Define a class to handle the main application logic
class Application {
private:
    io_context ctx_;
