    }

    // Initialize the fields of the new UE context structure
    new_ue_context->UE_ID = UE_ID;
    new_ue_context->CELL_ID = CELL_ID;
    update_phy_layer_status(new_ue_context, CELL_ID);

    // Add the new UE context to the dynamic list
    if (!ue_contexts) {
        ue_contexts = new_ue_context;
    } else {
        UE_CONTEXT_INFO *current_ue_context = ue_contexts;
        while (current_ue_context->next) {
            current_ue_context = current_ue_context->next;
        }
        current_ue_context->next = new_ue_context;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&ue_contexts_mutex);
}

// Define a function to remove an existing UE context from the dynamic list
void remove_ue_context(int UE_ID) {
    // Lock the mutex to synchronize access to the dynamic list
    pthread_mutex_lock(&ue_contexts_mutex);

    // Find the UE context with the specified UE ID in the dynamic list
    UE_CONTEXT_INFO *current_ue_context = ue_contexts;
    while (current_ue_context && current_ue_context->UE_ID != UE_ID) {
        current_ue_context = current_ue_context->next;
    }

    // If the UE context is found, remove it from the dynamic list
    if (current_ue_context) {
        if (current_ue_context == ue_contexts) {
            ue_contexts = current_ue_context->next;
        } else {
            UE_CONTEXT_INFO *previous_ue_context = ue_contexts;
            while (previous_ue_context->next != current_ue_context) {
                previous_ue_context = previous_ue_context->next;
            }
            previous_ue_context->next = current_ue_context->next;
        }

        // Free the memory allocated for the UE context structure
        free(current_ue_context);
    }

    // Unlock the mutex
    pthread_mutex_unlock(&ue_contexts_mutex);
}

// Define a function to sort the dynamic list of UE contexts based on their cell ID
void sort_ue_contexts(int cell_id) {
    // Lock the mutex to synchronize access to the dynamic list
    pthread_mutex_lock(&ue_contexts_mutex);

    // Sort the dynamic list of UE contexts based on their cell ID
    UE_CONTEXT_INFO *current_ue_context = ue_contexts;
    while (current_ue_context) {
        if (current_ue_context->CELL_ID == cell_id) {
            break;
        }
        current_ue_context = current_ue_context->next;
    }

    // If the UE context is found, sort the dynamic list based on its PHY layer status
    if (current_ue_context) {
        UE_CONTEXT_INFO *previous_ue_context = NULL;
        while (current_ue_context) {
            if (previous_ue_context && previous_ue_context->PHY_LAYER_STATUS > current_ue_context->PHY_LAYER_STATUS) {
                break;
            }
            previous_ue_context = current_ue_context;
            current_ue_context = current_ue_context->next;
        }

        // If the UE context is not found, sort the dynamic list based on its PHY layer status
        if (!current_ue_context) {
            previous_ue_context = NULL;
            while (previous_ue_context && previous_ue_context->next) {
                current_ue_context = previous_ue_context->next;
                if (current_ue_context->PHY_LAYER_STATUS > previous_ue_context->PHY_LAYER_STATUS) {
                    break;
                }
                previous_ue_context = current_ue_context;
            }
        }

        // If the UE context is found or not found, sort the dynamic list based on its PHY layer status
        if (previous_ue_context) {
            previous_ue_context->next = NULL;
            while (current_ue_context) {
                UE_CONTEXT_INFO *next_ue_context = current_ue_context->next;
                current_ue_context->next = previous_ue_context;
                previous_ue_context = current_ue_context;
                current_ue_context = next_ue_context;
            }
        }
    }

    // Unlock the mutex
    pthread_mutex_unlock(&ue_contexts_mutex);
}

// Define a function to update the PHY layer status of all UE contexts in the dynamic list
void update_phy_layer_statuses() {
    // Lock the mutex to synchronize access to the dynamic list
    pthread_mutex_lock(&ue_contexts_mutex);

    // Update the PHY layer status of all UE contexts in the dynamic list
    UE_CONTEXT_INFO *current_ue_context = ue_contexts;
    while (current_ue_context) {
        update_phy_layer_status(current_ue_context, current_ue_context->CELL_ID);
        current_ue_context = current_ue_context->next;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&ue_contexts_mutex);
}
