void add_to_list(NFAPI_CRC_INDICATION_LIST_T *list, int rx_ue_information_tag, int rnti, int crc_indication_rel8_tag, int crcflag) {
    // Acquire the lock for thread-safe operations
    pthread_mutex_lock(&list_lock);

    // Check if the list is full and needs to be resized
    if (list->size == list->capacity) {
        // Double the capacity of the list
        list->capacity *= 2;
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
