#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Define the structure for an NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the list of structures for managing CRC indications
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdu;
    size_t count;
} CRC_INDICATION_LIST_T;

// Define the function to manage the dynamic list of structures
void manage_crc_indications(CRC_INDICATION_LIST_T *list, uint32_t rnti) {
    // Initialize a random seed for generating unique CRCFLAG values
    srand(time(NULL));

    // Validate that the RNTI is within a valid range
    if (rnti < 0 || rnti > 65535) {
        printf("Invalid RNTI value: %u\n", rnti);
        return;
    }

    // Lock the list to prevent concurrent access from multiple threads
    pthread_mutex_lock(&list->mutex);

    // Check if the list is full and needs to be reallocated
    if (list->count == 10000) {
        NFAPI_CRC_INDICATION_PDU_T *new_pdu = realloc(list->pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T) * list->count * 2);
        if (new_pdu == NULL) {
            printf("Failed to allocate memory for CRC indications\n");
            pthread_mutex_unlock(&list->mutex);
            return;
        }
        list->pdu = new_pdu;
    }

    // Add a new structure to the list and update the count
    NFAPI_CRC_INDICATION_PDU_T *new_pdu = &list->pdu[list->count];
    new_pdu->RX_UE_INFORMATION_TAG = 0;
    new_pdu->RNTI = rnti;
    new_pdu->CRCFLAG = rand() % 256;
    list->count++;

    // Update the total count of processed CRC indications
    pthread_mutex_unlock(&list->mutex);
}

// Define a mechanism to periodically prune the list of structures to maintain memory efficiency
void prune_crc_indications(CRC_INDICATION_LIST_T *list) {
    // Lock the list to prevent concurrent access from multiple threads
    pthread_mutex_lock(&list->mutex);

    // Check if the list needs to be pruned
    if (list->count > 1000000) {
        NFAPI_CRC_INDICATION_PDU_T *new_pdu = realloc(list->pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T) * list->count / 2);
