void manage_array(NFAPI_CRC_INDICATION_PDU_T** arr, int size) {
    // Check if the input array is NULL or empty
    if (arr == NULL || size <= 0) {
        return;
    }

    // Initialize a temporary array to store the new elements
    NFAPI_CRC_INDICATION_PDU_T* temp = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * size);
    if (temp == NULL) {
        printf("Failed to allocate memory for temporary array\n");
        return;
    }

    // Copy the elements from the input array to the temporary array
    memcpy(temp, arr, sizeof(NFAPI_CRC_INDICATION_PDU_T) * size);

    // Free the original array and replace it with the new one
    free(arr);
    arr = temp;

    // Initialize a memory pool manager to recycle unused structures
    struct MemoryPoolManager {
        NFAPI_CRC_INDICATION_PDU_T* pool;
        int size;
        int used;
    } mempool;
    mempool.pool = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * size);
    if (mempool.pool == NULL) {
        printf("Failed to allocate memory for memory pool\n");
        return;
    }
    mempool.size = size;
    mempool.used = 0;

    // Define a function to recycle unused structures in the memory pool
    void recycle(NFAPI_CRC_INDICATION_PDU_T* pdu) {
        if (pdu == NULL) {
            return;
        }
        mempool.used--;
        free(pdu);
    }

    // Define a function to allocate new structures in the memory pool
    NFAPI_CRC_INDICATION_PDU_T* alloc() {
        if (mempool.used == mempool.size) {
            return NULL;
        }
        mempool.used++;
        return &mempool.pool[mempool.used - 1];
    }

    // Define a function to add new elements to the array
    void add(NFAPI_CRC_INDICATION_PDU_T* pdu) {
        if (pdu == NULL) {
            return;
        }
        NFAPI_CRC_INDICATION_PDU_T* temp = alloc();
        if (temp == NULL) {
            printf("Failed to allocate memory for new element\n");
            return;
        }
        memcpy(temp, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        arr[size] = temp;
    }

