        if (index < 0 || index >= size) {
            return;
        }
        NFAPI_CRC_INDICATION_PDU_T* temp = arr[index];
        recycle(temp);
        memmove(&arr[index], &arr[index + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (size - index));
