sem_t crc_indication_lock;

// Define the function to populate the dynamic collection of NFAPI_CRC_INDICATION_PDU_T structures
void populate_crc_indication_pdu_list(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    // Lock the collection to prevent concurrent access
    sem_wait(&crc_indication_lock);

    // Allocate memory for a new NFAPI_CRC_INDICATION_PDU_T structure
    NFAPI_CRC_INDICATION_PDU_T *new_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_pdu == NULL) {
