        return;
    }

    // Initialize the new structure with the given values
    new_pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_pdu->RNTI = RNTI;
    new_pdu->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    new_pdu->CRCFLAG = rand() % 2; // Set CRCFLAG to a random value

    // Add the new structure to the end of the collection
    if (crc_indication_pdu_list == NULL) {
        crc_indication_pdu_list = new_pdu;
    } else {
        NFAPI_CRC_INDICATION_PDU_T *current_pdu = crc_indication_pdu_list;
        while (current_pdu->next != NULL) {
            current_pdu = current_pdu->next;
        }
        current_pdu->next = new_pdu;
    }

    // Unlock the collection to allow other threads to access it
    sem_post(&crc_indication_lock);
}

// Define the function to update the center frequency value in the dynamic collection of NFAPI_CRC_INDICATION_PDU_T structures
void update_center_frequency(int new_center_frequency) {
    // Lock the collection to prevent concurrent access
    sem_wait(&crc_indication_lock);

    // Update the center frequency value in each structure
    NFAPI_CRC_INDICATION_PDU_T *current_pdu = crc_indication_pdu_list;
    while (current_pdu != NULL) {
        current_pdu->center_frequency = new_center_frequency;
        current_pdu = current_pdu->next;
    }

    // Unlock the collection to allow other threads to access it
    sem_post(&crc_indication_lock);
}

// Define the function to handle incoming telemetry updates and update the dynamic collection of NFAPI_CRC_INDICATION_PDU_T structures accordingly
void handle_telemetry_update(int new_center_frequency) {
    // Lock the collection to prevent concurrent access
    sem_wait(&crc_indication_lock);

    // Update the center frequency value in each structure
