    // Acquire lock on mutex to ensure thread-safe access to collection
    pthread_mutex_lock(&collection->mutex);

    // Allocate memory for new report and initialize fields
    nr_ue_measurement_report_t *new_report = malloc(sizeof(nr_ue_measurement_report_t));
    new_report->measurement_report_tag = measurement_report_tag;
    new_report->rnti = rnti;
    new_report->center_frequency_tag = center_frequency_tag;
    new_report->measurement_quality = 0.0f;

    // Add new report to collection and update number of reports
    collection->reports = realloc(collection->reports, (collection->num_reports + 1) * sizeof(nr_ue_measurement_report_t));
    collection->reports[collection->num_reports] = *new_report;
    collection->num_reports++;

    // Release lock on mutex
    pthread_mutex_unlock(&collection->mutex);

    return new_report;
}

// Define function to remove a NR UE Measurement Report from the collection
void remove_report(nr_ue_measurement_report_collection_t *collection, int index) {
    // Acquire lock on mutex to ensure thread-safe access to collection
    pthread_mutex_lock(&collection->mutex);

    // Remove report from collection and update number of reports
    nr_ue_measurement_report_t *removed_report = &collection->reports[index];
    for (int i = index; i < collection->num_reports - 1; i++) {
        collection->reports[i] = collection->reports[i + 1];
    }
    collection->num_reports--;

    // Free memory for removed report
    free(removed_report);

    // Release lock on mutex
    pthread_mutex_unlock(&collection->mutex);
}

