    // Acquire lock on mutex to ensure thread-safe access to collection
    pthread_mutex_lock(&collection->mutex);

    // Update measurement quality for report at given index
    collection->reports[index].measurement_quality = measurement_quality;

    // Release lock on mutex
    pthread_mutex_unlock(&collection->mutex);
}

// Define function to retrieve a NR UE Measurement Report from the collection
nr_ue_measurement_report_t *get_report(nr_ue_measurement_report_collection_t *collection, int index) {
    // Acquire lock on mutex to ensure thread-safe access to collection
    pthread_mutex_lock(&collection->mutex);

    // Return report at given index
    nr_ue_measurement_report_t *report = &collection->reports[index];

    // Release lock on mutex
    pthread_mutex_unlock(&collection->mutex);

    return report;
}

// Define function to retrieve all NR UE Measurement Reports from the collection
nr_ue_measurement_report_t **get_all_reports(nr_ue_measurement_report_collection_t *collection) {
    // Acquire lock on mutex to ensure thread-safe access to collection
    pthread_mutex_lock(&collection->mutex);

    // Allocate memory for array of reports and copy all reports from collection
    nr_ue_measurement_report_t **reports = malloc(sizeof(nr_ue_measurement_report_t *) * collection->num_reports);
    for (int i = 0; i < collection->num_reports; i++) {
        reports[i] = &collection->reports[i];
    }

    // Release lock on mutex
    pthread_mutex_unlock(&collection->mutex);

    return reports;
}

// Define function to clear all NR UE Measurement Reports from the collection
void clear_all_reports(nr_ue_measurement_report_collection_t *collection) {
    // Acquire lock on mutex to ensure thread-safe access to collection
    pthread_mutex_lock(&collection->mutex);

    // Free memory for all reports in collection and set number of reports to 0
    free(collection->reports);
    collection->num_reports = 0;

    // Release lock on mutex
    pthread_mutex_unlock(&collection->mutex);
}
