        UEContext *new_ue_contexts = realloc(ue_contexts, sizeof(UEContext) * ue_contexts_capacity);
        if (!new_ue_contexts) {
            // Handle memory allocation error
            return;
        }
        ue_contexts = new_ue_contexts;
    }

    // Add the new UE context to the array
    UEContext *ue_context = &ue_contexts[ue_contexts_count++];
    ue_context->UE_ID = UE_ID;
    ue_context->srs_config = srs_config;
    ue_context->measurement_reports = NULL;
}

// Function to remove a UE context
void remove_ue_context(int UE_ID) {
    // Find the index of the UE context to be removed
    size_t i = 0;
    while (i < ue_contexts_count && ue_contexts[i].UE_ID != UE_ID) {
        i++;
    }

    // Check if the UE context was found
    if (i == ue_contexts_count) {
        return;
    }

    // Remove the UE context from the array
    memmove(&ue_contexts[i], &ue_contexts[i + 1], sizeof(UEContext) * (ue_contexts_count - i - 1));
    ue_contexts_count--;
}

// Function to iterate over all UE contexts
void iterate_ue_contexts(void (*callback)(int, SRS_CONFIG_RRC)) {
    for (size_t i = 0; i < ue_contexts_count; i++) {
        callback(ue_contexts[i].UE_ID, ue_contexts[i].srs_config);
    }
}

// Function to add a measurement report for a UE context
void add_measurement_report(int UE_ID, double cell_rsrp, double cell_rsrq, long timestamp) {
    // Find the index of the UE context
    size_t i = 0;
    while (i < ue_contexts_count && ue_contexts[i].UE_ID != UE_ID) {
        i++;
    }

    // Check if the UE context was found
    if (i == ue_contexts_count) {
        return;
    }

    // Add the measurement report to the list of reports for the UE context
    MeasurementReport *measurement_report = malloc(sizeof(MeasurementReport));
    if (!measurement_report) {
        // Handle memory allocation error
        return;
    }
    measurement_report->cell_rsrp = cell_rsrp;
    measurement_report->cell_rsrq = cell_rsrq;
    measurement_report->timestamp = timestamp;
    measurement_report->next = ue_contexts[i].measurement_reports;
    ue_contexts[i].measurement_reports = measurement_report;
}

// Function to remove a measurement report for a UE context
void remove_measurement_report(int UE_ID, long timestamp) {
    // Find the index of the UE context
    size_t i = 0;
    while (i < ue_contexts_count && ue_contexts[i].UE_ID != UE_ID) {
        i++;
    }

    // Check if the UE context was found
    if (i == ue_contexts_count) {
        return;
    }

    // Find the index of the measurement report to be removed
    MeasurementReport *measurement_report = ue_contexts[i].measurement_reports;
    size_t j = 0;
    while (j < ue_contexts[i].measurement_reports_count && measurement_report->timestamp != timestamp) {
        measurement_report = measurement_report->next;
        j++;
    }

    // Check if the measurement report was found
    if (j == ue_contexts[i].measurement_reports_count) {
        return;
    }

    // Remove the measurement report from the list of reports for the UE context
    MeasurementReport *prev = measurement_report->next;
    free(measurement_report);
    ue_contexts[i].measurement_reports = prev;
}
