// Define the structure to hold the frame data
typedef struct NFhabi_TxFrameBuffer {
    int frameID;
    long timestamp;
    int txPowerLevel;
    int priority;
} NFhabi_TxFrameBuffer;

// Define the collection of frames
static NFhabi_TxFrameBuffer *frames = NULL;

// Define the number of frames in the collection
static size_t numFrames = 0;

// Define the lock for protecting the collection
static pthread_mutex_t frameLock = PTHREAD_MUTEX_INITIALIZER;

// Define the semaphore for signaling new frames
static sem_t newFrameSem;

// Initialize the module
void NFhabi_Init() {
    // Allocate memory for the collection of frames
    numFrames = 100;
    frames = (NFhabi_TxFrameBuffer *)malloc(numFrames * sizeof(NFhabi_TxFrameBuffer));

    // Initialize the lock and semaphore
    pthread_mutex_init(&frameLock, NULL);
    sem_init(&newFrameSem, 0, 0);
}

// Add a new frame to the collection
void NFhabi_AddFrame(int frameID, long timestamp, int txPowerLevel, int priority) {
    // Acquire the lock
    pthread_mutex_lock(&frameLock);

    // Check if the collection is full
    if (numFrames == 0) {
        // Reallocate memory for the collection
        numFrames *= 2;
        frames = (NFhabi_TxFrameBuffer *)realloc(frames, numFrames * sizeof(NFhabi_TxFrameBuffer));
    }

    // Add the new frame to the collection
    frames[numFrames - 1].frameID = frameID;
    frames[numFrames - 1].timestamp = timestamp;
    frames[numFrames - 1].txPowerLevel = txPowerLevel;
    frames[numFrames - 1].priority = priority;

    // Release the lock
    pthread_mutex_unlock(&frameLock);

    // Signal the new frame semaphore
    sem_post(&newFrameSem);
}

// Get the next frame from the collection
NFhabi_TxFrameBuffer NFhabi_GetNextFrame() {
    // Acquire the lock
    pthread_mutex_lock(&frameLock);

    // Check if there are any frames in the collection
    if (numFrames == 0) {
        // Release the lock and return NULL
        pthread_mutex_unlock(&frameLock);
        return NULL;
    }

    // Get the next frame from the collection
    NFhabi_TxFrameBuffer frame = frames[0];

    // Shift all the frames down by one position
    for (size_t i = 1; i < numFrames; i++) {
        frames[i - 1] = frames[i];
    }

    // Decrement the number of frames in the collection
    numFrames--;

    // Release the lock
    pthread_mutex_unlock(&frameLock);

    return frame;
}

// Integrate with an external scheduling service
void NFhabi_IntegrateWithSchedulingService(int (*schedulingCallback)(NFhabi_TxFrameBuffer *)) {
    // Create a new thread for the scheduling callback
    pthread_t schedulingThread;
    pthread_create(&schedulingThread, NULL, schedulingCallback, NULL);
}

// Callback function for the scheduling service
void NFhabi_SchedulingCallback(NFhabi_TxFrameBuffer *frame) {
    // Acquire the lock
    pthread_mutex_lock(&frameLock);

    // Check if there is space in the collection for the new frame
    if (numFrames == 0) {
        // Reallocate memory for the collection
        numFrames *= 2;
        frames = (NFhabi_TxFrameBuffer *)realloc(frames, numFrames * sizeof(NFhabi_TxFrameBuffer));
    }

    // Add the new frame to the collection
    frames[numFrames - 1].frameID = frame->frameID;
    frames[numFrames - 1].timestamp = frame->timestamp;
    frames[numFrames - 1].txPowerLevel = frame->txPowerLevel;
    frames[numFrames - 1].priority = frame->priority;

    // Release the lock
    pthread_mutex_unlock(&frameLock);
}
