// Define the allowed extensions for the new file name
const char* allowed_extensions[] = {"jpg", "png", "gif"};

// Function to generate a unique file name based on the original file path
char* generateDynamicFileName(const char* original_file_path) {
  // Get the directory and base name of the original file
  const char* directory = dirname(original_file_path);
  const char* base_name = basename(original_file_path);

  // Generate a SHA-256 hash of the original file name
  unsigned char hash[SHA256_DIGEST_LENGTH];
  SHA256((unsigned char*)base_name, strlen(base_name), hash);

  // Get the current Unix timestamp
  time_t timestamp = time(NULL);

  // Generate a sequence of digits based on the first 10 characters of the original file name
  int sequence = atoi(base_name + 10);

  // Check if the sequence is greater than 99999999, and if so, reset it to 0
  if (sequence > 99999999) {
    sequence = 0;
  }

  // Increment the sequence by 1
  sequence++;

  // Generate a new file name based on the directory, base name, hash, timestamp, and sequence
  char* new_file_name = (char*)malloc(strlen(directory) + strlen(base_name) + SHA256_DIGEST_LENGTH * 2 + 10 + 1);
  sprintf(new_file_name, "%s/%s.%s.%lu-%d.%s", directory, base_name, hash, timestamp, sequence, allowed_extensions[rand() % (sizeof(allowed_extensions) / sizeof(char*))]);

  // Check if the new file name already exists in the specified directory
  struct stat st;
  if (stat(new_file_name, &st) == 0) {
    // If the new file name already exists, generate a new sequence and try again
    sequence++;
    sprintf(new_file_name, "%s/%s.%s.%lu-%d.%s", directory, base_name, hash, timestamp, sequence, allowed_extensions[rand() % (sizeof(allowed_extensions) / sizeof(char*))]);
  }

  // Return the generated file name
  return new_file_name;
}
