const char* directory = "/path/to/directory";

// Define the function to generate a unique file name
void generateDynamicFileName(char* original_file_name, char* new_file_name) {
    // Get the current Unix timestamp
    time_t timestamp = time(NULL);

    // Generate a random hash of the original file name
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256((unsigned char*)original_file_name, strlen(original_file_name), hash);

    // Generate a sequence of digits based on the first 10 alphanumeric characters of the original file name
    int sequence = 0;
    for (int i = 0; i < 10; i++) {
        if (isalnum(original_file_name[i])) {
            sequence = sequence * 10 + (original_file_name[i] - '0');
        } else {
            break;
        }
    }

    // Ensure the sequence does not exceed 8 digits
    if (sequence > MAX_SEQUENCE_LENGTH) {
        sequence = MAX_SEQUENCE_LENGTH;
    }

    // Generate the new file name
    sprintf(new_file_name, "%s/%s.%06x.%ld-%08d.%s", directory, original_file_name, hash, timestamp, sequence, allowed_extensions[rand() % 4]);
}
