        fprintf(stderr, "Invalid input parameters\n");
        return;
    }

    // Get the list of files in the directory
    num_files = getFileList(directory, &files);
    if (num_files == 0) {
        fprintf(stderr, "No files found in directory\n");
        freeFileList(&files);
        return;
    }

    // Calculate the hash of the directory's contents
    for (i = 0; i < num_files; i++) {
        hash += files[i].filesize;
    }
    hash = SHA256(hash, sizeof(hash), &extension);

    // Generate the backup filename
    snprintf(backup_filename, MAX_FILENAME_LEN, "%s-%ld-%08d-%s.%s", directory, timestamp, sequence++, extension, ALLOWED_EXTENSIONS);

    // Compress and upload the files to the remote storage service
    for (i = 0; i < num_files; i++) {
