        // Upload the file to the remote storage service
        uploadFile(remote_storage, compressed_filename, compressed_size);

        // Free resources
        free(compressed_filename);
    }

    // Free resources
    freeFileList(&files);
}

int getFileList(const char *directory, file_info_t **files) {
    DIR *dir = opendir(directory);
    struct dirent *entry;
    int num_files = 0;

    if (dir == NULL) {
        return -1;
    }

    while ((entry = readdir(dir)) != NULL) {
        char filename[MAX_FILENAME_LEN];
        size_t filesize = 0;

        // Skip hidden files and directories
        if (entry->d_name[0] == '.') {
            continue;
        }

        snprintf(filename, MAX_FILENAME_LEN, "%s/%s", directory, entry->d_name);
        filesize = getFileSize(filename);

        // Add the file to the list
        (*files)[num_files].filename = strdup(filename);
        (*files)[num_files].filesize = filesize;
        num_files++;
    }

    closedir(dir);
    return num_files;
}

void freeFileList(file_info_t **files) {
    int i;

    for (i = 0; i < (*files)->num_files; i++) {
        free((*files)[i].filename);
    }
    free(*files);
}

char *compressFile(const char *filename) {
    FILE *file = fopen(filename, "rb");
    gzFile gzfile = gzdopen(fileno(file), "wb");
    char *compressed_filename = NULL;
    size_t compressed_size = 0;

    if (gzfile == NULL) {
        fprintf(stderr, "Error opening file for compression\n");
        return NULL;
    }

    // Compress the file
    gzwrite(gzfile, filename, strlen(filename));
    compressed_size = ftell(file);

    // Close the files
    fclose(file);
    gzclose(gzfile);

    // Generate a unique filename for the compressed file
    snprintf(compressed_filename, MAX_FILENAME_LEN, "%s.gz", filename);

    return compressed_filename;
}

