    // Initialize a mutex to protect the allocation function from concurrent access
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Allocate memory for the array of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* pduArray = (NFAPI_CRC_INDICATION_PDU_T*)malloc(numElements * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Initialize the mutex for thread safety
    pthread_mutex_init(&mutex, NULL);

    // Lock the mutex to prevent concurrent access to the allocation function
    pthread_mutex_lock(&mutex);

    // Iterate over each element in the array and initialize its fields
    for (int i = 0; i < numElements; i++) {
        // Initialize the RX_UE_INFORMATION_TAG field
        pduArray[i].rxUeInformation.tag = RX_UE_INFORMATION_TAG;

