        pduArray[i].crcIndicationRel8.tag = CRC_INDICATION_REL8_TAG;
        pduArray[i].crcIndicationRel8.crcflag = (CRCFLAG)rand();
    }

    // Unlock the mutex to allow other threads to access the allocation function
    pthread_mutex_unlock(&mutex);

    // Verify the integrity of the allocated data by checking that all fields are correctly initialized
    for (int i = 0; i < numElements; i++) {
        if (pduArray[i].rxUeInformation.tag != RX_UE_INFORMATION_TAG || pduArray[i].rnti == 0 || pduArray[i].crcIndicationRel8.tag != CRC_INDICATION_REL8_TAG) {
            // If any field is not correctly initialized, free the allocated memory and return NULL
