    if (strcmp(channel->modulation, "QPSK") == 0) {
        throughput = channel->modulationOrder * channel->codingRate;
    } else if (strcmp(channel->modulation, "16QAM") == 0) {
        throughput = channel->modulationOrder * channel->codingRate / log2f(16);
