            fprintf(stderr, "Payload exceeds maximum size: %d\n", pdu_list[i].rx_ue_information.length);
            free(pdu_list);
            return NULL;
        }
    }

    // Allocate memory for the slabs and populate them with PDUs
    MEMORY_POOL* mempool = malloc(sizeof(MEMORY_POOL));
    if (!mempool) {
        perror("malloc");
        free(pdu_list);
        return NULL;
    }
    mempool->total_size = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    mempool->free_size = mempool->total_size;
    mempool->used_size = 0;
    mempool->slab_count = 0;
    mempool->large_slab_count = 0;
    for (int i = 0; i < N; i++) {
        if (pdu_list[i].rx_ue_information.length <= SLAB_SIZE) {
            // Allocate a small slab for the PDU
            mempool->slabs[mempool->slab_count] = malloc(SLAB_SIZE);
            if (!mempool->slabs[mempool->slab_count]) {
                perror("malloc");
                free(pdu_list);
                return NULL;
            }
            memcpy(mempool->slabs[mempool->slab_count], &pdu_list[i], SLAB_SIZE);
            mempool->slab_count++;
        } else {
            // Allocate a large slab for the PDU
            mempool->large_slab_count++;
            size_t large_slab_size = pdu_list[i].rx_ue_information.length;
            mempool->slabs[mempool->slab_count] = malloc(large_slab_size);
            if (!mempool->slabs[mempool->slab_count]) {
                perror("malloc");
                free(pdu_list);
                return NULL;
            }
            memcpy(mempool->slabs[mempool->slab_count], &pdu_list[i], large_slab_size);
            mempool->slab_count++;
        }
    }

    // Return the list of PDUs and the memory pool
    return pdu_list;
}

// Define the function for reclaiming unused PDUs in the memory pool
void reclaim_unused_pdus(MEMORY_POOL* mempool) {
    // Lock the mutex to protect concurrent access to the memory pool
    pthread_mutex_lock(&mempool_mutex);

    // Iterate over the slabs in the memory pool and reclaim any unused PDUs
    for (int i = 0; i < mempool->slab_count; i++) {
        if (mempool->slabs[i]->rx_ue_information.length == 0) {
            free(mempool->slabs[i]);
            mempool->slab_count--;
        }
    }

    // Unlock the mutex to allow other threads to access the memory pool
    pthread_mutex_unlock(&mempool_mutex);
}

// Define the function for monitoring the health of the memory pool
void monitor_memory_pool(MEMORY_POOL* mempool) {
    // Lock the mutex to protect concurrent access to the memory pool
    pthread_mutex_lock(&mempool_mutex);

    // Calculate the free and used sizes of the memory pool
    size_t free_size = 0;
    size_t used_size = 0;
    for (int i = 0; i < mempool->slab_count; i++) {
        free_size += mempool->slabs[i]->rx_ue_information.length;
        used_size += SLAB_SIZE;
    }

    // Calculate the slab usage rates and log them to a file
    float slab_usage_rate = (float)used_size / (float)mempool->total_size;
    fprintf(stderr, "Slab usage rate: %f\n", slab_usage_rate);

    // Unlock the mutex to allow other threads to access the memory pool
    pthread_mutex_unlock(&mempool_mutex);
}
