// Define the structure to hold the frame setup information
typedef struct LTE_DL_FRAME_SETUP {
    DL_FRAME_TRANSPORT_CONTEXT transport_context;
    CELL_ID cell_id;
    int num_channels;
    PHY_TRANSPORT_CHANNEL *channels;
} LTE_DL_FRAME_SETUP;

// Define the function to initialize the frames
void initialize_frames(LTE_DL_FRAME_SETUP **frames, int num_frames) {
    // Allocate memory for the frame setup structures
    *frames = (LTE_DL_FRAME_SETUP *)malloc(num_frames * sizeof(LTE_DL_FRAME_SETUP));
    if (*frames == NULL) {
        printf("Error: Failed to allocate memory for frames\n");
        return;
    }

    // Initialize the frame setup structures
    for (int i = 0; i < num_frames; i++) {
        (*frames)[i].transport_context = DL_FRAME_TRANSPORT_CONTEXT();
        (*frames)[i].cell_id = CELL_ID();
        (*frames)[i].num_channels = 0;
        (*frames)[i].channels = NULL;
    }
}

// Define the function to add a channel to a frame
void add_channel(LTE_DL_FRAME_SETUP *frame, PHY_TRANSPORT_CHANNEL *channel) {
    // Check if there is enough memory for another channel
    if (frame->num_channels >= MAX_NUM_CHANNELS) {
        printf("Error: Maximum number of channels reached\n");
        return;
    }

    // Allocate memory for the new channel
    frame->channels = (PHY_TRANSPORT_CHANNEL *)realloc(frame->channels, (frame->num_channels + 1) * sizeof(PHY_TRANSPORT_CHANNEL));
    if (frame->channels == NULL) {
        printf("Error: Failed to allocate memory for new channel\n");
        return;
    }

    // Add the new channel to the frame
    frame->channels[frame->num_channels] = *channel;
    frame->num_channels++;
}

// Define the function to remove a channel from a frame
void remove_channel(LTE_DL_FRAME_SETUP *frame, int channel_index) {
    // Check if the channel index is valid
    if (channel_index >= frame->num_channels || channel_index < 0) {
        printf("Error: Invalid channel index\n");
        return;
    }

    // Remove the channel from the frame
    for (int i = channel_index; i < frame->num_channels - 1; i++) {
        frame->channels[i] = frame->channels[i + 1];
    }
    frame->num_channels--;
}

// Define the function to deallocate memory for a frame
void deallocate_frame(LTE_DL_FRAME_SETUP *frame) {
    // Check if the frame is valid
    if (frame == NULL) {
        printf("Error: Invalid frame\n");
        return;
    }

    // Deallocate memory for the channels
    free(frame->channels);
    frame->channels = NULL;

    // Deallocate memory for the frame setup structure
    free(frame);
}
