void calc_stats(float* data, int num_data, float* mean, float* stddev) {
    // Calculate the sum of the data points
    double sum = 0;
    for (int i = 0; i < num_data; i++) {
        sum += data[i];
    }

    // Calculate the mean
    *mean = sum / num_data;

    // Calculate the variance
    double var = 0;
    for (int i = 0; i < num_data; i++) {
        var += pow(data[i] - *mean, 2);
    }

    // Calculate the standard deviation
    *stddev = sqrt(var / num_data);
