NFAPI_CRC_INDICATION_PDU_T* allocate_crc_indication_pdu(int n) {
    // Check if the input is valid
    if (n <= 0) {
        fprintf(stderr, "Invalid input: %d\n", n);
        return NULL;
    }

    // Allocate memory for the array of CRC indication PDUs
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        fprintf(stderr, "Failed to allocate memory for CRC indication PDUs\n");
        return NULL;
    }

    // Initialize the array of CRC indication PDUs
    for (int i = 0; i < n; i++) {
        pdu[i].rx_ue_information_tag = 0;
        pdu[i].rnti = 0;
        pdu[i].crc_indication_rel8_tag = false;
    }

    // Allocate memory for the secondary array to track indices of CRCFLAG values set to true
    bool* crcflag_indices = (bool*)malloc(n * sizeof(bool));
    if (!crcflag_indices) {
        fprintf(stderr, "Failed to allocate memory for CRCFLAG indices\n");
        free(pdu);
        return NULL;
    }

    // Initialize the secondary array of CRCFLAG indices
    for (int i = 0; i < n; i++) {
        crcflag_indices[i] = false;
    }

    // Set a random value for each CRCFLAG index
    srand(time(NULL));
    for (int i = 0; i < n; i++) {
        int random_index = rand() % n;
        crcflag_indices[random_index] = true;
    }

    // Set the CRCFLAG value for each CRC indication PDU based on the secondary array
    for (int i = 0; i < n; i++) {
        if (crcflag_indices[i]) {
            pdu[i].crc_indication_rel8_tag = true;
        } else {
            pdu[i].crc_indication_rel8_tag = false;
        }
    }

    // Free the secondary array of CRCFLAG indices
    free(crcflag_indices);

    return pdu;
}
