}

// Define the function to handle thread safety and minimal lock contention during concurrent access from multiple threads
pthread_mutex_t config_lock = PTHREAD_MUTEX_INITIALIZER;
int load_configurations_threadsafe(const char* filename) {
    // Lock the mutex before accessing the configuration array
    pthread_mutex_lock(&config_lock);

    // Load the configurations from the file
    int num_configs = load_configurations(filename);
    if (num_configs < 0) {
        perror("Failed to load configurations");
        return -1;
    }

    // Unlock the mutex after accessing the configuration array
    pthread_mutex_unlock(&config_lock);

    // Return the number of configurations loaded
    return num_configs;
}

// Define the function to handle thread safety and minimal lock contention during concurrent access from multiple threads
int validate_configuration_threadsafe(LTEPHYLayerConfig* config) {
    // Lock the mutex before accessing the configuration array
    pthread_mutex_lock(&config_lock);

    // Validate the configuration
    int valid = validate_configuration(config);
    if (!valid) {
        perror("Failed to validate configuration");
        return -1;
    }

    // Unlock the mutex after accessing the configuration array
    pthread_mutex_unlock(&config_lock);

    // Return 1 if the configuration is valid, 0 otherwise
    return valid;
}
