#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define a struct to represent an LTE_UPLINK NAS Transport PDU
typedef struct {
    uint32_t id; // Unique identifier for the PDU
    NAS_HEADER header; // Header containing information about the PDU
    NAS_MESSAGE message; // Message contained in the PDU
} LTE_UPLINK_PDU;

// Define a struct to represent a dynamic list of LTE_UPLINK NAS Transport PDUs
typedef struct {
    LTE_UPLINK_PDU* pdu_list; // Array of pointers to the PDUs in the list
    size_t num_pdus; // Number of PDUs in the list
} LTE_UPLINK_PDU_LIST;

// Function to allocate memory for a new PDU and add it to the list
void add_pdu(LTE_UPLINK_PDU_LIST* list, NAS_HEADER header, NAS_MESSAGE message) {
    // Allocate memory for the new PDU
    LTE_UPLINK_PDU* pdu = malloc(sizeof(LTE_UPLINK_PDU));
    if (pdu == NULL) {
        return;
    }

    // Initialize the new PDU with the given header and message
    pdu->header = header;
    pdu->message = message;

    // Generate a unique identifier for the PDU
    pdu->id = generate_unique_id();

    // Add the new PDU to the list
    list->pdu_list[list->num_pdus++] = pdu;
}

// Function to remove a PDU from the list by its unique identifier
void remove_pdu(LTE_UPLINK_PDU_LIST* list, uint32_t id) {
    // Find the index of the PDU with the given ID in the list
    size_t i;
    for (i = 0; i < list->num_pdus; i++) {
        if (list->pdu_list[i]->id == id) {
            break;
        }
    }

    // If the PDU was found, remove it from the list and free its memory
    if (i < list->num_pdus) {
        LTE_UPLINK_PDU* pdu = list->pdu_list[i];
        memmove(&list->pdu_list[i], &list->pdu_list[i + 1], sizeof(LTE_UPLINK_PDU*) * (list->num_pdus - i - 1));
        free(pdu);
        list->num_pdus--;
    }
}

// Function to update the NAS_HEADER of all PDUs in the list with the current timestamp
void update_headers(LTE_UPLINK_PDU_LIST* list) {
    // Get the current time as a timestamp
    time_t now = time(NULL);

    // Update the NAS_HEADER of each PDU in the list with the current timestamp
    for (size_t i = 0; i < list->num_pdus; i++) {
        LTE_UPLINK_PDU* pdu = list->pdu_list[i];
        pdu->header.timestamp = now;
    }
}

// Function to generate a unique identifier for a new PDU
uint32_t generate_unique_id() {
    // Generate a random number as the unique identifier
    uint32_t id = rand();

    // If the generated ID is already in use, try again until a unique ID is found
    while (is_id_in_use(id)) {
        id = rand();
    }

    return id;
