// Define a struct to represent a TCP connection
typedef struct {
    int id;
    time_t last_active;
    char* packets; // list of associated packets
} tcp_connection_t;

// Define a linked list to store all active connections
struct connection_list {
    tcp_connection_t* head;
    tcp_connection_t* tail;
};

// Function to add a new TCP connection to the list
void add_connection(struct connection_list* list, int id) {
    // Allocate memory for the new connection
    tcp_connection_t* new_conn = malloc(sizeof(tcp_connection_t));
    if (!new_conn) {
        printf("Error: failed to allocate memory for new connection\n");
        return;
    }

    // Initialize the new connection's metadata
    new_conn->id = id;
    new_conn->last_active = time(NULL);
    new_conn->packets = NULL;

    // Add the new connection to the end of the list
    if (list->tail) {
        list->tail->next = new_conn;
        list->tail = new_conn;
    } else {
        list->head = new_conn;
        list->tail = new_conn;
    }
}

// Function to remove a TCP connection from the list by its ID
void remove_connection(struct connection_list* list, int id) {
    // Find the connection with the specified ID
    tcp_connection_t* conn = list->head;
    while (conn && conn->id != id) {
        conn = conn->next;
    }

    // If the connection was found, remove it from the list
    if (conn) {
        // Update the previous and next connections' pointers
        tcp_connection_t* prev = conn->prev;
        tcp_connection_t* next = conn->next;
        if (prev) {
            prev->next = next;
        } else {
            list->head = next;
        }
        if (next) {
            next->prev = prev;
        } else {
            list->tail = prev;
        }

        // Free the connection's memory
        free(conn);
    }
}

// Function to update the last active time for all connections in the list
void update_connections(struct connection_list* list) {
    // Iterate over all connections and update their last active time
    tcp_connection_t* conn = list->head;
    while (conn) {
        conn->last_active = time(NULL);
        conn = conn->next;
    }
}

// Function to retrieve the number of active connections in the list
int get_num_connections(struct connection_list* list) {
    int count = 0;
    tcp_connection_t* conn = list->head;
    while (conn) {
        count++;
        conn = conn->next;
    }
    return count;
}

// Function to retrieve the ID of a connection at a specified index in the list
int get_connection_id(struct connection_list* list, int index) {
    tcp_connection_t* conn = list->head;
    while (conn && index-- > 0) {
        conn = conn->next;
    }
    return conn ? conn->id : -1;
}

// Function to retrieve the last active time of a connection by its ID
time_t get_connection_last_active(struct connection_list* list, int id) {
    tcp_connection_t* conn = list->head;
    while (conn && conn->id != id) {
        conn = conn->next;
    }
    return conn ? conn->last_active : -1;
}

// Function to retrieve the list of associated packets for a connection by its ID
char* get_connection_packets(struct connection_list* list, int id) {
    tcp_connection_t* conn = list->head;
    while (conn && conn->id != id) {
        conn = conn->next;
    }
    return conn ? conn->packets : NULL;
}
```
This code defines a struct to represent a TCP connection, and a linked list to store all active connections. The `add_connection` function adds a new connection to the end of the list, while the `remove_connection` function removes a connection from the list by its ID. The `update_connections` function updates the last active time for all connections in the list, and the `get_num_connections`, `get_connection_id`, `get_connection_last_active`, and `get_connection_packets` functions provide access to the metadata of each connection.

The code also includes a few trade-offs between efficiency, usability, maintainability, and scalability. For example, it uses a linked list instead of a hash map for managing connections, which can be more efficient in terms of insertion/deletion overhead but may have slower access time. It also includes a mechanism to handle irregular packet arrival patterns by updating the last active time of each connection as soon as a new packet arrives, even if the update takes some time due to external data retrieval delays.

Overall, this code is designed to efficiently manage a large number of TCP connections while minimizing latency and resource consumption, while also supporting high-traffic scenarios with irregular packet arrival patterns.']

