// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the function to dynamically generate and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* generate_crc_indication_pdu(uint16_t num_elements) {
    // Allocate memory for the list of structures
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        printf("Error: Failed to allocate memory for the list of CRC indication PDUs\n");
        return NULL;
    }

    // Initialize the RX_UE_INFORMATION_TAG and CRCFLAG fields for each structure in the list
    for (uint16_t i = 0; i < num_elements; i++) {
        pdu_list[i].RX_UE_INFORMATION_TAG = i + 1; // Initialize RX_UE_INFORMATION_TAG to a unique value
        pdu_list[i].CRCFLAG = rand() % 256; // Set CRCFLAG to a random value between 0 and 255
    }

    // Generate a valid RNTI for each structure in the list
    uint32_t rnti_min = 1; // Minimum valid RNTI value
    uint32_t rnti_max = 65535; // Maximum valid RNTI value
    for (uint16_t i = 0; i < num_elements; i++) {
        pdu_list[i].RNTI = rand() % (rnti_max - rnti_min + 1) + rnti_min; // Generate a random RNTI value within the valid range
    }

    // Ensure that no two structures in the list share the same RNTI value
    for (uint16_t i = 0; i < num_elements - 1; i++) {
        for (uint16_t j = i + 1; j < num_elements; j++) {
            if (pdu_list[i].RNTI == pdu_list[j].RNTI) {
                // If two structures share the same RNTI value, regenerate the RNTI for one of them
                pdu_list[i].RNTI = rand() % (rnti_max - rnti_min + 1) + rnti_min;
            }
        }
    }

    return pdu_list;
}

// Define a function to serialize the list of NFAPI_CRC_INDICATION_PDU_T structures into a buffer for transmission or storage
void serialize_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* pdu_list, uint16_t num_elements, char* buffer) {
    // Calculate the total size of the serialized data
    uint32_t total_size = 0;
    for (uint16_t i = 0; i < num_elements; i++) {
        total_size += sizeof(pdu_list[i].RX_UE_INFORMATION_TAG) + sizeof(pdu_list[i].RNTI) + sizeof(pdu_list[i].CRCFLAG);
    }

    // Allocate memory for the serialized data
    char* serialized_data = (char*)malloc(total_size);
    if (!serialized_data) {
        printf("Error: Failed to allocate memory for the serialized CRC indication PDUs\n");
        return;
    }

    // Serialize each structure in the list into the buffer
    uint32_t offset = 0;
    for (uint16_t i = 0; i < num_elements; i++) {
        memcpy(serialized_data + offset, &pdu_list[i].RX_UE_INFORMATION_TAG, sizeof(pdu_list[i].RX_UE_INFORMATION_TAG));
        offset += sizeof(pdu_list[i].RX_UE_INFORMATION_TAG);
        memcpy(serialized_data + offset, &pdu_list[i].RNTI, sizeof(pdu_list[i].RNTI));
        offset += sizeof(pdu_list[i].RNTI);
        memcpy(serialized_data + offset, &pdu_list[i].CRCFLAG, sizeof(pdu_list[i].CRCFLAG));
        offset += sizeof(pdu_list[i].CRCFLAG);
    }

    // Copy the serialized data into the buffer
    memcpy(buffer, serialized_data, total_size);

    // Free the memory allocated for the serialized data
    free(serialized_data);
